window.SWMN_DATA=window.SWMN_DATA||{};window.SWMN_DATA["k1v2"]=[{"id":"k1v2-b01","courseId":"k1v2","order":1,"title":"Chào bạn!","titleZh":"你好！","vocab":[{"stt":1,"hanzi":"你","pinyin":"nǐ","hanviet":"Nễ","pos":"Đại từ","meaning":"bạn, anh, chị, em (ngôi thứ 2 số ít)","comps":"你好 (chào bạn)","example":{"zh":"你好！很高兴认识你。","py":"Nǐ hǎo! Hěn gāoxìng rènshi nǐ.","vi":"Chào bạn! Rất vui được quen biết bạn."}},{"stt":2,"hanzi":"好","pinyin":"hǎo","hanviet":"Hảo","pos":"Tính từ","meaning":"tốt, khỏe, hay, đẹp","comps":"很好 (rất tốt), 好人 (người tốt)","example":{"zh":"今天天气很好。","py":"Jīntiān tiānqì hěn hǎo.","vi":"Hôm nay thời tiết rất đẹp."}},{"stt":3,"hanzi":"您","pinyin":"nín","hanviet":"Nhẫm","pos":"Đại từ","meaning":"ông, bà, ngài (ngôi thứ 2, trang trọng)","comps":"您好 (chào ngài)","example":{"zh":"老师，您好！","py":"Lǎoshī, nín hǎo!","vi":"Chào thầy/cô ạ!"}},{"stt":4,"hanzi":"你们","pinyin":"nǐmen","hanviet":"Nễ môn","pos":"Đại từ","meaning":"các bạn, các anh chị (ngôi 2 số nhiều)","comps":"你们好 (chào các bạn)","example":{"zh":"你们去哪里？","py":"Nǐmen qù nǎlǐ?","vi":"Các bạn đi đâu vậy?"}},{"stt":5,"hanzi":"对不起","pinyin":"duìbuqi","hanviet":"Đối bất khởi","pos":"Động từ","meaning":"xin lỗi","comps":"对不起大家 (xin lỗi mọi người)","example":{"zh":"对不起，我迟到了。","py":"Duìbuqi, wǒ chídào le.","vi":"Xin lỗi, tôi đến muộn rồi."}},{"stt":6,"hanzi":"没关系","pinyin":"méi guānxi","hanviet":"Một quan hệ","pos":"Cụm từ","meaning":"không sao đâu, không có gì","comps":"没什么关系 (không có vấn đề gì cả)","example":{"zh":"A: 对不起。 B: 没关系。","py":"A: Duìbuqi. B: Méi guānxi.","vi":"A: Xin lỗi. B: Không sao đâu."}}],"hanzi":[{"char":"你","pinyin":"nǐ","hanviet":"Nễ","chars":["你"],"story":"Chữ 你 gồm bộ Nhân đứng (亻- người) bên trái và chữ Nhĩ (尔) bên phải. Ý nói một \"người\" đang đứng đối diện để trò chuyện với bạn."},{"char":"好","pinyin":"hǎo","hanviet":"Hảo","chars":["好"],"story":"Gồm bộ Nữ (女 - phụ nữ) và bộ Tử (子 - con trai). Người xưa quan niệm người phụ nữ sinh được con trai là một điều vô cùng \"tốt đẹp\" (好)."},{"char":"您","pinyin":"nín","hanviet":"Nhẫm","chars":["您"],"story":"Phía trên là chữ 你 (bạn), phía dưới là bộ Tâm (心 - trái tim). Để người đối diện ở trong tim mình, thể hiện sự kính trọng tuyệt đối."},{"char":"你们","pinyin":"nǐmen","hanviet":"Nễ môn","chars":["你","们"],"story":"Chữ 们 (men) là hậu tố chỉ số nhiều cho người. Thêm 们 vào sau 你 (nǐ) sẽ biến \"bạn\" thành \"các bạn\"."},{"char":"对不起","pinyin":"duìbuqi","hanviet":"Đối bất khởi","chars":["对","不","起"],"story":"Một cụm từ cố định biểu thị sự hối lỗi, cảm thấy \"không xứng đáng, không thể đối mặt\" (đối bất khởi) với người khác."},{"char":"没关系","pinyin":"méi guānxi","hanviet":"Một quan hệ","chars":["没","关","系"],"story":"没 (không có), 关系 (quan hệ/vấn đề). Lắp lại nghĩa là \"không có vấn đề gì đâu\", dùng để đáp lại lời xin lỗi một cách lịch sự."}],"grammar":[{"title":"Biến điệu thanh 3 (第三声变调)","formula":"Thanh 3 + <span>Thanh 3</span> ➡ Thanh 2 + <span>Thanh 3</span>","summary":"Trong tiếng Trung, khi hai âm tiết mang thanh 3 đứng liền kề nhau, âm tiết thứ nhất sẽ tự động chuyển cách đọc thành thanh 2. (Ghi chú: Khi viết pinyin chuẩn vẫn giữ nguyên thanh 3, nhưng lúc đọc phải đọc thành thanh 2. Ở ví dụ dưới đây, Pinyin được viết theo \"cách đọc\" để bạn dễ luyện tập).","note":"<strong>Lưu ý:</strong> Quy tắc này chỉ áp dụng cho phát âm, không thay đổi cách viết Pinyin trên giấy tờ chính thức.","examples":[{"zh":"你好","py":"ní hǎo","vi":"chào bạn (nǐ + hǎo)"},{"zh":"可以","py":"ké yǐ","vi":"có thể (kě + yǐ)"},{"zh":"辅导","py":"fú dǎo","vi":"phụ đạo (fǔ + dǎo)"},{"zh":"口语","py":"kóu yǔ","vi":"khẩu ngữ (kǒu + yǔ)"},{"zh":"语法","py":"yú fǎ","vi":"ngữ pháp (yǔ + fǎ)"},{"zh":"了解","py":"liáo jiě","vi":"hiểu rõ (liǎo + jiě)"},{"zh":"友好","py":"yóu hǎo","vi":"hữu nghị (yǒu + hǎo)"},{"zh":"手表","py":"shóu biǎo","vi":"đồng hồ đeo tay (shǒu + biǎo)"}]},{"title":"Cấu trúc chào hỏi cơ bản","formula":"Người được chào + <span>好</span>","summary":"Để chào hỏi một ai đó, người Trung Quốc sử dụng cấu trúc ghép trực tiếp Đại từ nhân xưng hoặc Danh từ chỉ người với tính từ \"好\" (hǎo).","note":"<strong>Lưu ý:</strong> \"你好\" chỉ dùng cho quan hệ ngang hàng. Với người lớn tuổi, cấp trên, giáo viên, bắt buộc dùng \"您好\" hoặc \"Chức danh + 好\".","examples":[{"zh":"你好","py":"Nǐ hǎo","vi":"Chào bạn (Dùng chung cho bạn bè)"},{"zh":"您好","py":"Nín hǎo","vi":"Chào ngài (Trang trọng)"},{"zh":"你们好","py":"Nǐmen hǎo","vi":"Chào các bạn (Số nhiều)"},{"zh":"老师好","py":"Lǎoshī hǎo","vi":"Em chào thầy/cô"},{"zh":"爸爸好","py":"Bàba hǎo","vi":"Con chào bố"},{"zh":"妈妈好","py":"Māma hǎo","vi":"Con chào mẹ"},{"zh":"爷爷好","py":"Yéye hǎo","vi":"Cháu chào ông"},{"zh":"奶奶好","py":"Nǎinai hǎo","vi":"Cháu chào bà"}]}],"text":{"title":"课文 · Bài khoá","blocks":[{"titleZh":"在路上","titleVi":"Trên đường","icon":"👋","lines":[{"speaker":"A","zh":"你好！","py":"Nǐ hǎo!","vi":"Chào bạn!"},{"speaker":"B","zh":"你好！","py":"Nǐ hǎo!","vi":"Chào bạn!"}]},{"titleZh":"在公司","titleVi":"Tại công ty","icon":"🤝","lines":[{"speaker":"A","zh":"您好！","py":"Nín hǎo!","vi":"Chào giám đốc/ông!"},{"speaker":"B","zh":"你们好！","py":"Nǐmen hǎo!","vi":"Chào các bạn!"}]},{"titleZh":"在学校","titleVi":"Tại trường học","icon":"🙇","lines":[{"speaker":"A","zh":"对不起！","py":"Duìbuqi!","vi":"Xin lỗi! (Vô tình va trúng)"},{"speaker":"B","zh":"没关系！","py":"Méi guānxi!","vi":"Không sao đâu!"}]}]},"extra":[{"label":"Mục tiêu","html":"<h2 class=\"section-title\">Mục tiêu bài học</h2>\n  <p class=\"section-sub\">Những kiến thức cốt lõi bạn cần nắm vững sau khi hoàn thành Bài 1.</p>\n  <div class=\"goal-grid\">\n    <div class=\"goal-item\">\n      <div class=\"num\">01</div>\n      <h4>Giao tiếp</h4>\n      <ul>\n        <li>Chào hỏi thông thường với bạn bè, đồng nghiệp.</li>\n        <li>Chào hỏi trang trọng với người lớn tuổi, cấp trên.</li>\n        <li>Nói lời xin lỗi và đáp lại lời xin lỗi một cách lịch sự.</li>\n      </ul>\n    </div>\n    <div class=\"goal-item\">\n      <div class=\"num\">02</div>\n      <h4>Từ vựng</h4>\n      <ul>\n        <li>Đại từ nhân xưng: <b>你, 您, 你们</b></li>\n        <li>Tính từ tốt/khỏe: <b>好</b></li>\n        <li>Cụm từ giao tiếp: <b>对不起, 没关系</b></li>\n      </ul>\n    </div>\n    <div class=\"goal-item\">\n      <div class=\"num\">03</div>\n      <h4>Phát âm & Chữ viết</h4>\n      <ul>\n        <li>Nhận diện 4 thanh điệu cơ bản trong Tiếng Trung.</li>\n        <li>Nắm vững quy tắc biến điệu khi 2 thanh 3 đi liền nhau.</li>\n        <li>Biết 5 nét chữ Hán cơ bản (Ngang, Sổ, Phẩy, Chấm, Mác).</li>\n      </ul>\n    </div>\n  </div>"},{"label":"Phát âm & Chữ Hán","html":"<h2 class=\"section-title\">Nhập môn Phát âm & Chữ Hán</h2>\n  <p class=\"section-sub\">Kiến thức nền tảng quan trọng nhất khi bắt đầu học tiếng Trung: Thanh điệu và Các nét chữ cơ bản.</p>\n\n  <div class=\"card\">\n    <h3>1. Bốn Thanh Điệu (四声)</h3>\n    <p>Tiếng Trung có 4 thanh điệu cơ bản. Thanh điệu khác nhau sẽ tạo ra nghĩa hoàn toàn khác nhau. Hãy tưởng tượng thanh điệu như một bản nhạc 5 quãng.</p>\n    \n    <div class=\"goal-grid\" style=\"grid-template-columns: repeat(4, 1fr); margin-top: 16px;\">\n      <div class=\"goal-item\" style=\"padding: 18px; text-align: center;\">\n        <div class=\"num\" style=\"font-size: 2rem;\">Thanh 1</div>\n        <h4 style=\"color: var(--burgundy); font-family: 'Be Vietnam Pro', sans-serif;\">mā (mẹ)</h4>\n        <p style=\"font-size: 0.9rem;\">Đọc cao và đều (5-5). Giống đọc nốt Sol.</p>\n      </div>\n      <div class=\"goal-item\" style=\"padding: 18px; text-align: center;\">\n        <div class=\"num\" style=\"font-size: 2rem;\">Thanh 2</div>\n        <h4 style=\"color: var(--burgundy); font-family: 'Be Vietnam Pro', sans-serif;\">má (cây gai)</h4>\n        <p style=\"font-size: 0.9rem;\">Đọc từ vừa lên cao (3-5). Giống dấu sắc.</p>\n      </div>\n      <div class=\"goal-item\" style=\"padding: 18px; text-align: center;\">\n        <div class=\"num\" style=\"font-size: 2rem;\">Thanh 3</div>\n        <h4 style=\"color: var(--burgundy); font-family: 'Be Vietnam Pro', sans-serif;\">mǎ (con ngựa)</h4>\n        <p style=\"font-size: 0.9rem;\">Xuống thấp rồi lên cao (2-1-4). Giống dấu hỏi.</p>\n      </div>\n      <div class=\"goal-item\" style=\"padding: 18px; text-align: center;\">\n        <div class=\"num\" style=\"font-size: 2rem;\">Thanh 4</div>\n        <h4 style=\"color: var(--burgundy); font-family: 'Be Vietnam Pro', sans-serif;\">mà (mắng)</h4>\n        <p style=\"font-size: 0.9rem;\">Đọc từ cao rớt mạnh xuống (5-1). Dứt khoát.</p>\n      </div>\n    </div>\n\n    <div class=\"tip-card\">\n      <h5>💡 Mẹo luyện thanh 4</h5>\n      <p>Người Việt hay đọc nhầm thanh 4 thành dấu huyền hoặc dấu sắc. Hãy tưởng tượng bạn đang bực mình cãi lại: \"Không!\" một cách rất mạnh và dứt khoát. Đó chính là âm hưởng của thanh 4.</p>\n    </div>\n  </div>\n\n  <div class=\"card\">\n    <h3>2. Các Nét Chữ Hán Cơ Bản</h3>\n    <p>Chữ Hán được cấu tạo từ các nét. Bài 1 giới thiệu 5 nét cơ bản nhất. Hãy xem các chữ số cũng được tạo từ các nét này.</p>\n    \n    <div class=\"syn-grid\">\n      <div class=\"syn-card theme-burgundy\" style=\"margin-bottom: 0;\">\n        <table class=\"syn-table\">\n          <tr><th>Tên nét</th><th>Hướng viết</th><th>Ví dụ</th></tr>\n          <tr><td>Ngang (héng)</td><td>Trái → Phải</td><td><b class=\"zh\" style=\"color:var(--burgundy);font-size:1.2rem\">一</b> (yī - một)</td></tr>\n          <tr><td>Sổ (shù)</td><td>Trên ↓ Dưới</td><td><b class=\"zh\" style=\"color:var(--burgundy);font-size:1.2rem\">十</b> (shí - mười)</td></tr>\n          <tr><td>Phẩy (piě)</td><td>Trên phải ↙ Dưới trái</td><td><b class=\"zh\" style=\"color:var(--burgundy);font-size:1.2rem\">八</b> (bā - tám)</td></tr>\n          <tr><td>Chấm (diǎn)</td><td>Chấm nhẹ từ trên xuống</td><td><b class=\"zh\" style=\"color:var(--burgundy);font-size:1.2rem\">六</b> (liù - sáu)</td></tr>\n          <tr><td>Mác (nà)</td><td>Trên trái ↘ Dưới phải</td><td><b class=\"zh\" style=\"color:var(--burgundy);font-size:1.2rem\">大</b> (dà - to, lớn)</td></tr>\n        </table>\n      </div>\n      <div class=\"syn-card theme-gold\" style=\"margin-bottom: 0;\">\n        <div class=\"syn-icon\">✍️</div>\n        <h4 style=\"font-family:'Quicksand',serif;font-size:1.2rem;font-weight:700\">Quy tắc vàng khi viết chữ:</h4>\n        <ul style=\"margin-top: 10px;\">\n          <li>Từ trái sang phải (ví dụ chữ 川).</li>\n          <li>Từ trên xuống dưới (ví dụ chữ 三).</li>\n          <li>Ngang trước, sổ sau (ví dụ chữ 十).</li>\n          <li>Phẩy trước, mác sau (ví dụ chữ 八).</li>\n        </ul>\n      </div>\n    </div>\n  </div>"},{"label":"Lỗi sai","html":"<h2 class=\"section-title\">Lỗi sai thường gặp</h2>\n  <p class=\"section-sub\">Những lỗi người Việt hay mắc phải nhất khi học Bài 1.</p>\n  <div class=\"error-grid\">\n    <!-- Lỗi 1 -->\n    <div class=\"error-box\">\n      <div class=\"err-head wrong\">Lỗi 1 · Quên biến điệu thanh 3</div>\n      <div class=\"err-body\">\n        <p style=\"margin-bottom:12px\">Lỗi kinh điển nhất là đọc \"nǐ hǎo\" thành hai dấu hỏi dời rạc. Khi hai thanh 3 đứng cạnh nhau, từ đầu tiên phải chuyển thành thanh 2.</p>\n        <p class=\"strike zh\">nǐ hǎo (nỉ hảo)</p>\n      </div>\n      <div class=\"err-head correct\">Cách sửa</div>\n      <div class=\"err-body\">\n        <p class=\"correct-text zh\">ní hǎo</p>\n        <p style=\"font-size:.88rem;color:var(--muted);margin-top:6px\">Đọc \"nǐ\" giống như thêm dấu sắc: \"ní hǎo\".</p>\n      </div>\n    </div>\n    <!-- Lỗi 2 -->\n    <div class=\"error-box\">\n      <div class=\"err-head wrong\">Lỗi 2 · Dùng sai \"你\" và \"您\"</div>\n      <div class=\"err-body\">\n        <p style=\"margin-bottom:12px\">Học viên thường dùng \"你好\" (Nǐ hǎo) để chào mọi đối tượng, kể cả giáo viên lớn tuổi hay giám đốc, điều này bị coi là thiếu tôn trọng.</p>\n        <p class=\"strike zh\">老师，你好！ (Lǎoshī, nǐ hǎo!)</p>\n      </div>\n      <div class=\"err-head correct\">Cách sửa</div>\n      <div class=\"err-body\">\n        <p class=\"correct-text zh\">老师，您好！ (Lǎoshī, nín hǎo!)</p>\n        <p style=\"font-size:.88rem;color:var(--muted);margin-top:6px\">Luôn dùng \"您\" (Nín - ngài, ông, bà, thầy, cô) cho người bề trên.</p>\n      </div>\n    </div>\n    <!-- Lỗi 3 -->\n    <div class=\"error-box\">\n      <div class=\"err-head wrong\">Lỗi 3 · Đọc thanh 4 thành dấu huyền</div>\n      <div class=\"err-body\">\n        <p style=\"margin-bottom:12px\">Từ \"对不起\" (duìbuqi - xin lỗi), người Việt rất hay đọc \"duì\" thành \"dùi\" (dấu huyền) hoặc \"dúi\" (dấu sắc). Thanh 4 cần đọc mạnh và rớt âm nhanh.</p>\n        <p class=\"strike zh\">Dùi-bu-qỉ / Dúi-bu-qỉ</p>\n      </div>\n      <div class=\"err-head correct\">Cách sửa</div>\n      <div class=\"err-body\">\n        <p class=\"correct-text zh\">Duì-bu-qi (Đọc mạnh chữ \"Duì\" từ trên cao xuống)</p>\n        <p style=\"font-size:.88rem;color:var(--muted);margin-top:6px\">Hãy dứt khoát như khi bạn nói \"Không!\".</p>\n      </div>\n    </div>\n  </div>"},{"label":"Tổng hợp","html":"<h2 class=\"section-title\">Tổng hợp kiến thức</h2>\n  <p class=\"section-sub\">Sơ đồ cốt lõi giúp tóm tắt toàn bộ bài học số 1.</p>\n\n  <div class=\"syn-grid\">\n    <!-- Khối 1: Cấu trúc -->\n    <div class=\"syn-card theme-burgundy\">\n      <div class=\"syn-icon\">👋</div>\n      <h3>Cấu trúc chào hỏi</h3>\n      <table class=\"syn-table\">\n        <tr><th>Loại</th><th>Cấu trúc</th></tr>\n        <tr><td>Bình thường</td><td>你 + 好 (Nǐ hǎo)</td></tr>\n        <tr><td>Trang trọng</td><td>您 + 好 (Nín hǎo)</td></tr>\n        <tr><td>Số nhiều</td><td>你们 + 好 (Nǐmen hǎo)</td></tr>\n      </table>\n      <div class=\"syn-mnemonic\">Mẹo: Chỉ cần ghép <strong>Đại từ nhân xưng + 好</strong> là tạo thành câu chào.</div>\n    </div>\n\n    <!-- Khối 2: Sơ đồ chuỗi (Flow) -->\n    <div class=\"syn-card theme-gold\">\n      <div class=\"syn-icon\">🤝</div>\n      <h3>Phản xạ giao tiếp</h3>\n      <div class=\"syn-flow\">\n        <div class=\"step\"><span class=\"syn-keyhz\">对不起</span><br><small>Xin lỗi</small></div>\n        <span class=\"arrow\">→</span>\n        <div class=\"step\"><span class=\"syn-keyhz\">没关系</span><br><small>Không sao</small></div>\n      </div>\n      <div class=\"syn-mnemonic\">Nhớ theo cặp: Hễ ai nói <strong>Duìbuqi</strong> thì phản xạ ngay là <strong>Méi guānxi</strong>.</div>\n    </div>\n\n    <!-- Khối 3: Bảng 5 Câu Thần Chú -->\n    <div class=\"syn-card theme-ink\" style=\"grid-column: 1 / -1;\">\n      <div class=\"syn-icon\">⚡</div>\n      <h3>Câu thần chú 5 mẫu</h3>\n      <table class=\"syn-table\">\n        <tr><th>Mẫu</th><th>Tình huống</th></tr>\n        <tr><td><span class=\"syn-keyhz\">你好！ (Nǐ hǎo)</span></td><td>Chào bạn bè, đồng nghiệp cùng trang lứa.</td></tr>\n        <tr><td><span class=\"syn-keyhz\">您好！ (Nín hǎo)</span></td><td>Chào giám đốc, thầy cô giáo, người lớn tuổi hơn mình.</td></tr>\n        <tr><td><span class=\"syn-keyhz\">你们好！ (Nǐmen hǎo)</span></td><td>Chào một nhóm người (từ 2 người trở lên).</td></tr>\n        <tr><td><span class=\"syn-keyhz\">对不起。 (Duìbuqi)</span></td><td>Khi bạn làm sai điều gì đó, lỡ đạp trúng chân ai đó.</td></tr>\n        <tr><td><span class=\"syn-keyhz\">没关系。 (Méi guānxi)</span></td><td>Khi có người nói xin lỗi bạn và bạn muốn tha thứ cho họ.</td></tr>\n      </table>\n      <div class=\"syn-mnemonic\"><strong>Thuộc lòng 5 mẫu câu này là bạn đã hoàn thành xuất sắc Bài 01.</strong></div>\n    </div>\n  </div>"}],"cssId":"c0c50c6d8"},{"id":"k1v2-b02","courseId":"k1v2","order":2,"title":"Cảm ơn bạn!","titleZh":"谢谢你！","vocab":[{"stt":1,"hanzi":"谢谢","pinyin":"xièxie","hanviet":"Tạ tạ","pos":"Động từ","meaning":"cảm ơn","comps":"谢谢你 (cảm ơn bạn), 谢谢大家 (cảm ơn mọi người)","example":{"zh":"谢谢你的帮助。","py":"Xièxie nǐ de bāngzhù.","vi":"Cảm ơn sự giúp đỡ của bạn."}},{"stt":2,"hanzi":"不","pinyin":"bù","hanviet":"Bất","pos":"Phó từ","meaning":"không, đừng","comps":"不是 (không phải), 不好 (không tốt)","example":{"zh":"我不去。","py":"Wǒ bù qù.","vi":"Tôi không đi."}},{"stt":3,"hanzi":"不客气","pinyin":"bú kèqi","hanviet":"Bất khách khí","pos":"Cụm từ","meaning":"đừng khách sáo, không có gì","comps":"对人不客气 (thiếu lịch sự với người khác)","example":{"zh":"A: 谢谢。 B: 不客气。","py":"A: Xièxie. B: Bú kèqi.","vi":"A: Cảm ơn. B: Đừng khách sáo."}},{"stt":4,"hanzi":"客气","pinyin":"kèqi","hanviet":"Khách khí","pos":"Tính từ","meaning":"khách sáo, lịch sự","comps":"太客气 (quá khách sáo)","example":{"zh":"你太客气了。","py":"Nǐ tài kèqi le.","vi":"Bạn quá khách sáo rồi."}},{"stt":5,"hanzi":"再见","pinyin":"zàijiàn","hanviet":"Tái kiến","pos":"Động từ","meaning":"tạm biệt, hẹn gặp lại","comps":"明天再见 (ngày mai gặp lại)","example":{"zh":"老师，再见！","py":"Lǎoshī, zàijiàn!","vi":"Thầy/cô, tạm biệt ạ!"}},{"stt":6,"hanzi":"见","pinyin":"jiàn","hanviet":"Kiến","pos":"Động từ","meaning":"gặp, nhìn thấy","comps":"见面 (gặp mặt), 看见 (nhìn thấy)","example":{"zh":"很高兴见到你。","py":"Hěn gāoxìng jiàndào nǐ.","vi":"Rất vui được gặp bạn."}}],"hanzi":[{"char":"谢谢","pinyin":"xièxie","hanviet":"Tạ tạ","chars":["谢","谢"],"story":"Chữ 谢 (xiè) gồm bộ Ngôn (讠- lời nói), chữ Thân (身 - cơ thể) và chữ Thốn (寸 - luật lệ/chừng mực). Khi cảm ơn, ta dùng \"lời nói\" chân thành, \"cơ thể\" cúi xuống theo đúng \"chừng mực, phép tắc\". Chữ thứ hai đọc thanh nhẹ."},{"char":"不","pinyin":"bù","hanviet":"Bất","chars":["不"],"story":"Hình ảnh một rễ cây đâm sâu xuống đất (hoặc một con chim bay vút lên trời không quay đầu lại), mang ý nghĩa phủ định một cách tuyệt đối: \"Không\"."},{"char":"不客气","pinyin":"bú kèqi","hanviet":"Bất khách khí","chars":["不","客","气"],"story":"客 (khách), 气 (khí/thái độ). \"客气\" là thái độ giữ kẽ của người làm khách. Lắp chữ \"不\" vào thành \"不客气\" ý bảo: Chúng ta là người nhà, đừng làm khách, đừng giữ kẽ."},{"char":"客气","pinyin":"kèqi","hanviet":"Khách khí","chars":["客","气"],"story":"Chữ 客 (khách) có bộ Miên (宀 - mái nhà), nghĩa là người từ nơi khác đến nhà mình. Dưới mái nhà, đối đãi với khách phải có sự tôn trọng (\"Khí\" - 气)."},{"char":"再见","pinyin":"zàijiàn","hanviet":"Tái kiến","chars":["再","见"],"story":"再 (zài) là \"lại/một lần nữa\", 见 (jiàn) là \"gặp/nhìn thấy\". \"再见\" không chỉ là chia tay mà mang hy vọng tốt đẹp: \"Hẹn một ngày lại được nhìn thấy nhau\"."},{"char":"见","pinyin":"jiàn","hanviet":"Kiến","chars":["见"],"story":"Nhìn chữ 见 (jiàn), phần trên là bộ Mục (目 - con mắt), phần dưới là bộ Nhân (儿 - người đang đi). Thể hiện một người đang mở to mắt để nhìn, để gặp gỡ."}],"grammar":[{"title":"Biến điệu của chữ \"不\" (bù)","formula":"不 (bù) + <span>Thanh 4</span> ➡ 不 (bú) + <span>Thanh 4</span>","summary":"Chữ \"不\" (bù) bình thường mang thanh 4 (đọc mạnh từ trên xuống). Tuy nhiên, khi âm tiết đứng ngay sau nó cũng mang thanh 4, chữ \"不\" bắt buộc phải đọc thành thanh 2 (bú) để việc phát âm được mượt mà hơn.","note":"<strong>Lưu ý:</strong> Khi đứng trước thanh 1, thanh 2, thanh 3, chữ \"不\" vẫn giữ nguyên cách đọc là thanh 4 (bù). Ví dụ: bù hǎo (không tốt), bù mǎi (không mua).","examples":[{"zh":"不谢","py":"bú xiè","vi":"không có gì (bù + xiè)"},{"zh":"不客气","py":"bú kè qi","vi":"đừng khách sáo (bù + kè)"},{"zh":"不是","py":"bú shì","vi":"không phải (bù + shì)"},{"zh":"不去","py":"bú qù","vi":"không đi (bù + qù)"},{"zh":"不看","py":"bú kàn","vi":"không nhìn/xem (bù + kàn)"},{"zh":"不卖","py":"bú mài","vi":"không bán (bù + mài)"},{"zh":"不做","py":"bú zuò","vi":"không làm (bù + zuò)"},{"zh":"不要","py":"bú yào","vi":"không cần/không muốn (bù + yào)"}]},{"title":"Viết giản lược Pinyin (省写)","formula":"Thanh mẫu + <span>iou / uei / uen</span> ➡ <span>iu / ui / un</span>","summary":"Trong hệ thống phiên âm Pinyin, có 3 vần (vận mẫu) đặc biệt. Khi chúng được ghép với phụ âm (thanh mẫu) ở phía trước, âm ở giữa sẽ bị lược bỏ khi viết (nhưng khi đọc vẫn phải đọc lướt qua âm đó).","note":"<strong>Lưu ý:</strong> Nhớ khẩu quyết: iou thành iu (như tiếng kêu cứu), uei thành ui (như xui xẻo), uen thành un (như mùa xuân). Dấu thanh điệu luôn đánh ở chữ cái cuối cùng của phần giản lược (ví dụ: niú, guì, lùn).","examples":[{"zh":"六 (l + iou)","py":"liù","vi":"số sáu"},{"zh":"九 (j + iou)","py":"jiǔ","vi":"số chín"},{"zh":"休 (x + iou)","py":"xiū","vi":"nghỉ ngơi (xiūxi)"},{"zh":"对 (d + uei)","py":"duì","vi":"đúng, đối (duìbuqi)"},{"zh":"贵 (g + uei)","py":"guì","vi":"đắt, quý"},{"zh":"会 (h + uei)","py":"huì","vi":"biết, sẽ"},{"zh":"春 (ch + uen)","py":"chūn","vi":"mùa xuân"},{"zh":"论 (l + uen)","py":"lùn","vi":"thảo luận"}]}],"text":{"title":"课文 · Bài khoá","blocks":[{"titleZh":"在学校","titleVi":"Tại trường học","icon":"🏫","lines":[{"speaker":"A","zh":"谢谢！","py":"Xièxie!","vi":"Cảm ơn bạn! (Nhận cuốn sách)"},{"speaker":"B","zh":"不谢！","py":"Bú xiè!","vi":"Không có gì!"}]},{"titleZh":"在公司","titleVi":"Tại công ty","icon":"🏢","lines":[{"speaker":"A","zh":"谢谢你！","py":"Xièxie nǐ!","vi":"Cảm ơn anh! (Được rót trà)"},{"speaker":"B","zh":"不客气！","py":"Bú kèqi!","vi":"Đừng khách sáo!"}]},{"titleZh":"在路上","titleVi":"Trên đường phố","icon":"👋","lines":[{"speaker":"A","zh":"再见！","py":"Zàijiàn!","vi":"Tạm biệt nhé!"},{"speaker":"B","zh":"再见！","py":"Zàijiàn!","vi":"Tạm biệt!"}]}]},"extra":[{"label":"Mục tiêu","html":"<h2 class=\"section-title\">Mục tiêu bài học</h2>\n  <p class=\"section-sub\">Những kiến thức cốt lõi bạn cần nắm vững sau khi hoàn thành Bài 2.</p>\n  <div class=\"goal-grid\">\n    <div class=\"goal-item\">\n      <div class=\"num\">01</div>\n      <h4>Giao tiếp</h4>\n      <ul>\n        <li>Nói lời cảm ơn người khác đúng cách.</li>\n        <li>Đáp lại lời cảm ơn lịch sự (Không có gì, đừng khách sáo).</li>\n        <li>Chào tạm biệt khi ra về.</li>\n      </ul>\n    </div>\n    <div class=\"goal-item\">\n      <div class=\"num\">02</div>\n      <h4>Từ vựng</h4>\n      <ul>\n        <li>Động từ cảm ơn: <b>谢谢</b></li>\n        <li>Cụm từ đáp lại: <b>不客气, 不谢</b></li>\n        <li>Động từ tạm biệt: <b>再见</b></li>\n      </ul>\n    </div>\n    <div class=\"goal-item\">\n      <div class=\"num\">03</div>\n      <h4>Phát âm & Ngữ pháp</h4>\n      <ul>\n        <li>Làm quen với <b>Thanh nhẹ</b> (Không có dấu thanh).</li>\n        <li>Nắm quy tắc đánh dấu thanh điệu và viết giản lược Pinyin.</li>\n        <li>Quy tắc biến điệu của chữ <b>不 (bù)</b>.</li>\n      </ul>\n    </div>\n  </div>"},{"label":"Phát âm & Chữ Hán","html":"<h2 class=\"section-title\">Quy tắc Phát âm & Nét chữ Hán</h2>\n  <p class=\"section-sub\">Kiến thức quan trọng của Bài 2 giúp bạn đọc Pinyin chuẩn xác và viết chữ Hán đẹp hơn.</p>\n\n  <div class=\"card\">\n    <h3>1. Thanh Nhẹ (轻声)</h3>\n    <p>Ngoài 4 thanh điệu cơ bản (1, 2, 3, 4), tiếng Trung còn có một thanh được phát âm <b>rất ngắn và nhẹ</b>, gọi là Thanh Nhẹ. Âm mang thanh nhẹ sẽ <i>không có dấu thanh điệu</i> trên đầu.</p>\n    \n    <div class=\"goal-grid\" style=\"grid-template-columns: repeat(2, 1fr); margin-top: 16px;\">\n      <div class=\"goal-item\" style=\"padding: 18px; text-align: center;\">\n        <h4 style=\"color: var(--burgundy); font-family: 'Be Vietnam Pro', sans-serif; margin-bottom: 4px;\">mā<span style=\"color:var(--muted)\">ma</span></h4>\n        <div style=\"font-family:'Noto Sans SC',sans-serif;font-size:2rem;color:var(--ink);font-weight:600\">妈妈</div>\n        <p style=\"font-size: 0.9rem; margin-top: 8px;\">(mẹ) - Chữ thứ hai đọc lướt nhanh.</p>\n      </div>\n      <div class=\"goal-item\" style=\"padding: 18px; text-align: center;\">\n        <h4 style=\"color: var(--burgundy); font-family: 'Be Vietnam Pro', sans-serif; margin-bottom: 4px;\">xiè<span style=\"color:var(--muted)\">xie</span></h4>\n        <div style=\"font-family:'Noto Sans SC',sans-serif;font-size:2rem;color:var(--ink);font-weight:600\">谢谢</div>\n        <p style=\"font-size: 0.9rem; margin-top: 8px;\">(cảm ơn) - Chữ thứ hai hạ giọng nhẹ nhàng.</p>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"card\">\n    <h3>2. Quy tắc ghi dấu Thanh Điệu (标调法)</h3>\n    <p>Khi một vần (vận mẫu) có nhiều nguyên âm, ta phải đánh dấu thanh điệu lên chữ nào? Hãy nhớ khẩu quyết sau:</p>\n    \n    <div class=\"formula-box\">\n      <div class=\"formula-label\">Thứ tự ưu tiên đánh dấu</div>\n      <div class=\"formula\">a ➡ o ➡ e ➡ i ➡ u ➡ ü</div>\n    </div>\n    \n    <div class=\"tip-card\">\n      <h5>💡 Mẹo lưu ý cực kỳ quan trọng</h5>\n      <ul>\n        <li>Nếu có <b>a</b>, luôn đánh dấu trên <b>a</b> (ví dụ: h<b>ǎ</b>o).</li>\n        <li>Không có <b>a</b> thì tìm <b>o</b> hoặc <b>e</b> (ví dụ: x<b>ué</b>).</li>\n        <li>Nếu <b>i</b> và <b>u</b> đứng cạnh nhau (iu hoặc ui), dấu thanh luôn đánh ở <b>âm cuối cùng</b> (ví dụ: ji<b>ù</b>, gu<b>ì</b>).</li>\n      </ul>\n    </div>\n  </div>\n\n  <div class=\"card\">\n    <h3>3. Các Nét Chữ Hán Cơ Bản (Phần 2)</h3>\n    <p>Bài này giới thiệu 3 nét gấp khúc và móc rất phổ biến, cùng 4 chữ Hán độc thể cơ bản.</p>\n    \n    <div class=\"syn-grid\">\n      <div class=\"syn-card theme-burgundy\" style=\"margin-bottom: 0;\">\n        <table class=\"syn-table\">\n          <tr><th>Tên nét</th><th>Hướng viết</th><th>Ví dụ</th></tr>\n          <tr><td>Ngang gập (héngzhé)</td><td>Ngang rồi gập xuống</td><td><b class=\"zh\" style=\"color:var(--burgundy);font-size:1.2rem\">口</b> (kǒu - miệng)</td></tr>\n          <tr><td>Sổ gập (shùzhé)</td><td>Sổ xuống rồi gập ngang</td><td><b class=\"zh\" style=\"color:var(--burgundy);font-size:1.2rem\">山</b> (shān - núi)</td></tr>\n          <tr><td>Sổ móc (shùgōu)</td><td>Sổ xuống rồi hất móc lên</td><td><b class=\"zh\" style=\"color:var(--burgundy);font-size:1.2rem\">小</b> (xiǎo - nhỏ)</td></tr>\n        </table>\n      </div>\n      <div class=\"syn-card theme-gold\" style=\"margin-bottom: 0;\">\n        <div class=\"syn-icon\">👁️</div>\n        <h4 style=\"font-family:'Quicksand',sans-serif;font-size:1.2rem;font-weight:700\">Chiết tự chữ 见 (jiàn - gặp/thấy):</h4>\n        <p style=\"margin-top: 10px; font-size:.95rem; line-height: 1.6;\">\n          Phần trên là bộ <b>Mục</b> (目 - con mắt), phần dưới là bộ <b>Nhân</b> (儿 - người đi). Hình ảnh <i>một người đang mở to mắt để nhìn, để gặp gỡ</i>.\n        </p>\n      </div>\n    </div>\n  </div>"},{"label":"Lỗi sai","html":"<h2 class=\"section-title\">Lỗi sai thường gặp</h2>\n  <p class=\"section-sub\">Những lỗi người Việt hay mắc phải nhất khi học Bài 2.</p>\n  <div class=\"error-grid\">\n    <!-- Lỗi 1 -->\n    <div class=\"error-box\">\n      <div class=\"err-head wrong\">Lỗi 1 · Không đọc nhẹ chữ \"xie\" thứ hai</div>\n      <div class=\"err-body\">\n        <p style=\"margin-bottom:12px\">Người Việt thường có thói quen đọc hai chữ giống nhau với cùng một lực mạnh. Tuy nhiên, chữ \"谢谢\" có chữ thứ 2 mang thanh nhẹ.</p>\n        <p class=\"strike zh\">Xiè xiè! (Xiên xiên!)</p>\n      </div>\n      <div class=\"err-head correct\">Cách sửa</div>\n      <div class=\"err-body\">\n        <p class=\"correct-text zh\">Xièxie!</p>\n        <p style=\"font-size:.88rem;color:var(--muted);margin-top:6px\">Đọc chữ \"Xiè\" đầu tiên mạnh, chữ \"xie\" thứ hai hạ giọng xuống thật ngắn và nhẹ hều.</p>\n      </div>\n    </div>\n    <!-- Lỗi 2 -->\n    <div class=\"error-box\">\n      <div class=\"err-head wrong\">Lỗi 2 · Hiểu sai nghĩa \"不客气\"</div>\n      <div class=\"err-body\">\n        <p style=\"margin-bottom:12px\">Nhiều bạn dịch word-by-word \"不\" (không), \"客气\" (khách sáo/lịch sự) nên sợ dùng vì nghĩ nó nghĩa là \"Mày không lịch sự\".</p>\n        <p class=\"strike zh\">A: 谢谢！ B: 没关系。 (Dùng sai hoàn cảnh)</p>\n      </div>\n      <div class=\"err-head correct\">Cách sửa</div>\n      <div class=\"err-body\">\n        <p class=\"correct-text zh\">A: 谢谢！ B: 不客气。</p>\n        <p style=\"font-size:.88rem;color:var(--muted);margin-top:6px\">\"不客气\" là thành ngữ, nghĩa là \"Đừng khách sáo\", là cách đáp lại lời cảm ơn chuẩn mực nhất.</p>\n      </div>\n    </div>\n    <!-- Lỗi 3 -->\n    <div class=\"error-box\">\n      <div class=\"err-head wrong\">Lỗi 3 · Quên biến điệu chữ 不 (bù)</div>\n      <div class=\"err-body\">\n        <p style=\"margin-bottom:12px\">Chữ 不 gốc mang thanh 4 (bù). Tuy nhiên khi đứng trước chữ 客 (kè) hoặc 谢 (xiè) - cũng là thanh 4, nó phải đổi thành thanh 2 (bú).</p>\n        <p class=\"strike zh\">bù xiè, bù kè qi</p>\n      </div>\n      <div class=\"err-head correct\">Cách sửa</div>\n      <div class=\"err-body\">\n        <p class=\"correct-text zh\">bú xiè, bú kèqi</p>\n        <p style=\"font-size:.88rem;color:var(--muted);margin-top:6px\">Khi gặp 2 dấu huyền (thanh 4) đi liền nhau, dấu huyền đầu tiên tự động chuyển thành dấu sắc.</p>\n      </div>\n    </div>\n  </div>"},{"label":"Tổng hợp","html":"<h2 class=\"section-title\">Tổng hợp kiến thức</h2>\n  <p class=\"section-sub\">Sơ đồ cốt lõi giúp tóm tắt toàn bộ bài học số 2.</p>\n\n  <div class=\"syn-grid\">\n    <!-- Khối 1: Sơ đồ phản xạ Cảm ơn -->\n    <div class=\"syn-card theme-burgundy\">\n      <div class=\"syn-icon\">🙏</div>\n      <h3>Phản xạ Cảm ơn</h3>\n      <div class=\"syn-flow\">\n        <div class=\"step\"><span class=\"syn-keyhz\">谢谢 / 谢谢你</span><br><small>Cảm ơn / Cảm ơn bạn</small></div>\n        <span class=\"arrow\">→</span>\n        <div class=\"step\"><span class=\"syn-keyhz\">不客气 / 不谢</span><br><small>Đừng khách sáo / Không có gì</small></div>\n      </div>\n      <div class=\"syn-mnemonic\">Hễ ai nói <strong>Xièxie</strong> thì ngay lập tức phản xạ bằng <strong>Bú kèqi</strong> hoặc <strong>Bú xiè</strong>.</div>\n    </div>\n\n    <!-- Khối 2: Sơ đồ phản xạ Tạm biệt -->\n    <div class=\"syn-card theme-gold\">\n      <div class=\"syn-icon\">👋</div>\n      <h3>Phản xạ Tạm biệt</h3>\n      <div class=\"syn-flow\">\n        <div class=\"step\"><span class=\"syn-keyhz\">再见</span><br><small>Tạm biệt</small></div>\n        <span class=\"arrow\">→</span>\n        <div class=\"step\"><span class=\"syn-keyhz\">再见</span><br><small>Tạm biệt</small></div>\n      </div>\n      <div class=\"syn-mnemonic\">Khi chia tay ra về, cứ nói <strong>Zàijiàn</strong> qua lại với nhau là được.</div>\n    </div>\n\n    <!-- Khối 3: Bảng 5 Câu Thần Chú -->\n    <div class=\"syn-card theme-ink\" style=\"grid-column: 1 / -1;\">\n      <div class=\"syn-icon\">⚡</div>\n      <h3>Câu thần chú 5 mẫu</h3>\n      <table class=\"syn-table\">\n        <tr><th>Mẫu</th><th>Tình huống</th></tr>\n        <tr><td><span class=\"syn-keyhz\">谢谢！ (Xièxie!)</span></td><td>Khi nhận được sự giúp đỡ, nhận quà, được khen ngợi.</td></tr>\n        <tr><td><span class=\"syn-keyhz\">谢谢你！ (Xièxie nǐ!)</span></td><td>Nhấn mạnh lòng biết ơn trực tiếp đến đối phương (Cảm ơn bạn).</td></tr>\n        <tr><td><span class=\"syn-keyhz\">不客气！ (Bú kèqi!)</span></td><td>Khi người khác cảm ơn mình, đáp lại lịch sự \"Đừng khách sáo\".</td></tr>\n        <tr><td><span class=\"syn-keyhz\">不谢！ (Bú xiè!)</span></td><td>Cách nói ngắn gọn, xuề xòa hơn của \"Không có gì đâu\". Dùng với bạn bè.</td></tr>\n        <tr><td><span class=\"syn-keyhz\">再见！ (Zàijiàn!)</span></td><td>Khi rời đi, chào tạm biệt và hẹn gặp lại.</td></tr>\n      </table>\n      <div class=\"syn-mnemonic\"><strong>Thuộc 5 câu ngắn ngủn này là bạn đã xuất sắc vượt qua Bài 02.</strong></div>\n    </div>\n  </div>"}],"cssId":"c7fcf9643"},{"id":"k1v2-b03","courseId":"k1v2","order":3,"title":"Bạn tên là gì?","titleZh":"你叫什么名字？","vocab":[{"stt":1,"hanzi":"叫","pinyin":"jiào","hanviet":"Khiếu","pos":"Động từ","meaning":"gọi, tên là","comps":"叫什么 (tên là gì), 大叫 (kêu to)","example":{"zh":"你叫什么名字？","py":"Nǐ jiào shénme míngzi?","vi":"Bạn tên là gì?"}},{"stt":2,"hanzi":"什么","pinyin":"shénme","hanviet":"Thập ma","pos":"Đại từ","meaning":"cái gì, gì","comps":"什么人 (người nào), 什么书 (sách gì)","example":{"zh":"这是什么？","py":"Zhè shì shénme?","vi":"Đây là cái gì?"}},{"stt":3,"hanzi":"名字","pinyin":"míngzi","hanviet":"Danh tự","pos":"Danh từ","meaning":"tên (người, sự vật)","comps":"好名字 (tên hay)","example":{"zh":"我的名字叫大卫。","py":"Wǒ de míngzi jiào Dàwèi.","vi":"Tên của tôi là David."}},{"stt":4,"hanzi":"我","pinyin":"wǒ","hanviet":"Ngã","pos":"Đại từ","meaning":"tôi, ta, mình (ngôi thứ nhất)","comps":"我们 (chúng tôi), 我的 (của tôi)","example":{"zh":"我是学生。","py":"Wǒ shì xuésheng.","vi":"Tôi là học sinh."}},{"stt":5,"hanzi":"是","pinyin":"shì","hanviet":"Thị","pos":"Động từ","meaning":"là, vâng, đúng","comps":"不是 (không phải), 是否 (phải chăng)","example":{"zh":"他不是老师。","py":"Tā bú shì lǎoshī.","vi":"Anh ấy không phải là giáo viên."}},{"stt":6,"hanzi":"老师","pinyin":"lǎoshī","hanviet":"Lão sư","pos":"Danh từ","meaning":"thầy giáo, cô giáo","comps":"王老师 (thầy Vương)","example":{"zh":"李月是老师。","py":"Lǐ Yuè shì lǎoshī.","vi":"Lý Nguyệt là giáo viên."}},{"stt":7,"hanzi":"学生","pinyin":"xuésheng","hanviet":"Học sinh","pos":"Danh từ","meaning":"học sinh, sinh viên","comps":"小学生 (học sinh tiểu học)","example":{"zh":"你是学生吗？","py":"Nǐ shì xuésheng ma?","vi":"Bạn là học sinh phải không?"}},{"stt":8,"hanzi":"吗","pinyin":"ma","hanviet":"Ma","pos":"Trợ từ","meaning":"không, phải không (dùng để hỏi Yes/No)","comps":"好吗 (tốt không/khỏe không)","example":{"zh":"你是中国人吗？","py":"Nǐ shì Zhōngguó rén ma?","vi":"Bạn là người Trung Quốc phải không?"}},{"stt":9,"hanzi":"人","pinyin":"rén","hanviet":"Nhân","pos":"Danh từ","meaning":"người","comps":"什么人 (người nào), 好人 (người tốt)","example":{"zh":"他是美国人。","py":"Tā shì Měiguó rén.","vi":"Anh ấy là người Mỹ."}},{"stt":10,"hanzi":"中国","pinyin":"Zhōngguó","hanviet":"Trung Quốc","pos":"Danh từ riêng","meaning":"Trung Quốc","comps":"中国人 (người Trung Quốc)","example":{"zh":"我不是中国人。","py":"Wǒ bú shì Zhōngguó rén.","vi":"Tôi không phải người Trung Quốc."}}],"hanzi":[{"char":"叫","pinyin":"jiào","hanviet":"Khiếu","chars":["叫"],"story":"Phía bên trái là bộ Khẩu (口 - cái miệng), bên phải là số 4 (móc giống số 4). Dùng miệng để \"gọi\" ai đó 4 lần mới thưa."},{"char":"什么","pinyin":"shénme","hanviet":"Thập ma","chars":["什","么"],"story":"Chữ 什 có bộ Nhân đứng (亻) và chữ 十 (10). Chữ 么 là một biến thể của từ. \"什么\" là đại từ nghi vấn phổ biến nhất, luôn đứng TRƯỚC danh từ nó bổ nghĩa."},{"char":"名字","pinyin":"míngzi","hanviet":"Danh tự","chars":["名","字"],"story":"Chữ 名 (Danh) gồm bộ Tịch (夕 - buổi tối) và Khẩu (口 - miệng). Buổi tối trời tối thui, không thấy mặt nhau nên phải dùng miệng gọi \"Tên\" để nhận biết."},{"char":"我","pinyin":"wǒ","hanviet":"Ngã","chars":["我"],"story":"Bên trái giống bộ Thủ (tay), bên phải là bộ Qua (戈 - cây giáo mác). Hình ảnh người cầm vũ khí đứng bảo vệ chính bản ngã, cái tôi của mình."},{"char":"是","pinyin":"shì","hanviet":"Thị","chars":["是"],"story":"Phía trên là chữ Nhật (日 - mặt trời), dưới là chữ Chính (正 - ngay thẳng). Mặt trời thì luôn chiếu sáng đúng quy luật, mang ý nghĩa khẳng định \"Là, Đúng\"."},{"char":"老师","pinyin":"lǎoshī","hanviet":"Lão sư","chars":["老","师"],"story":"老 (Lão - già/kính trọng), 师 (Sư - người thầy). \"老师\" thể hiện sự tôn trọng dành cho những người truyền đạt kiến thức, bất kể tuổi tác."},{"char":"学生","pinyin":"xuésheng","hanviet":"Học sinh","chars":["学","生"],"story":"学 (Học - học tập), 生 (Sinh - người). \"学生\" là người làm nhiệm vụ học tập. Chữ 生 mang thanh nhẹ khi ghép trong từ này."},{"char":"吗","pinyin":"ma","hanviet":"Ma","chars":["吗"],"story":"Gồm bộ Khẩu (口 - miệng) để hỏi và chữ Mã (马 - con ngựa) gợi âm đọc. Đặt ở cuối câu trần thuật để biến nó thành câu hỏi nghi vấn."},{"char":"人","pinyin":"rén","hanviet":"Nhân","chars":["人"],"story":"Một trong những chữ tượng hình cổ nhất. Hình ảnh một người đang đứng giang hai chân bước đi thẳng lưng."},{"char":"中国","pinyin":"Zhōngguó","hanviet":"Trung Quốc","chars":["中","国"],"story":"中 (Trung - ở giữa), 国 (Quốc - đất nước). Nước nằm ở trung tâm. Chữ 国 có bộ Vi (囗 - biên giới) bao quanh bộ Ngọc (玉 - sự quý giá) bên trong."}],"grammar":[{"title":"Đại từ nghi vấn \"什么\" (shénme)","formula":"Chủ ngữ + Động từ + <span>什么</span> + (Danh từ)?","summary":"Đại từ \"什么\" (cái gì/ gì) được dùng để hỏi thông tin. Nó có thể đứng một mình làm tân ngữ, hoặc kết hợp với danh từ khác để làm rõ câu hỏi (VD: sách gì, người nào, tên gì).","note":"<strong>Lưu ý:</strong> Trật tự từ trong tiếng Trung: \"什么\" luôn đứng TRƯỚC danh từ mà nó bổ nghĩa. Khác hoàn toàn với tiếng Việt (Tên gì -> 什么名字).","examples":[{"zh":"这是什么？","py":"Zhè shì shénme?","vi":"Đây là cái gì?"},{"zh":"那是什么？","py":"Nà shì shénme?","vi":"Kia là cái gì?"},{"zh":"你叫什么名字？","py":"Nǐ jiào shénme míngzi?","vi":"Bạn tên là gì?"},{"zh":"你吃什么？","py":"Nǐ chī shénme?","vi":"Bạn ăn gì?"},{"zh":"你喝什么？","py":"Nǐ hē shénme?","vi":"Bạn uống gì?"},{"zh":"你看什么？","py":"Nǐ kàn shénme?","vi":"Bạn xem/nhìn cái gì?"},{"zh":"这是什么书？","py":"Zhè shì shénme shū?","vi":"Đây là sách gì?"},{"zh":"他是什么人？","py":"Tā shì shénme rén?","vi":"Anh ấy là người như thế nào?"}]},{"title":"Câu chữ \"是\" (shì)","formula":"A + <span>(不)是</span> + B","summary":"Câu chữ \"是\" (là) dùng để kết nối chủ ngữ và vị ngữ, nhằm xác định hoặc phán đoán A là B. Dùng để giới thiệu tên, nghề nghiệp, quốc tịch. Ở thể phủ định, ta dùng \"不是\" (bú shì).","note":"<strong>Lưu ý:</strong> Từ \"不\" (bù) khi đứng trước \"是\" (shì) phải đọc biến điệu thành thanh 2 (bú shì).","examples":[{"zh":"我是学生。","py":"Wǒ shì xuésheng.","vi":"Tôi là học sinh."},{"zh":"李月是老师。","py":"Lǐ Yuè shì lǎoshī.","vi":"Lý Nguyệt là giáo viên."},{"zh":"大卫是美国人。","py":"Dàwèi shì Měiguó rén.","vi":"David là người Mỹ."},{"zh":"我是越南人。","py":"Wǒ shì Yuènán rén.","vi":"Tôi là người Việt Nam."},{"zh":"我不是老师。","py":"Wǒ bú shì lǎoshī.","vi":"Tôi không phải là giáo viên."},{"zh":"他不是中国人。","py":"Tā bú shì Zhōngguó rén.","vi":"Anh ấy không phải người Trung Quốc."},{"zh":"这不是我的。","py":"Zhè bú shì wǒ de.","vi":"Đây không phải của tôi."},{"zh":"你是大卫吗？","py":"Nǐ shì Dàwèi ma?","vi":"Bạn là David phải không?"}]},{"title":"Câu hỏi Yes/No với \"吗\" (ma)","formula":"Câu khẳng định + <span>吗</span>?","summary":"Trợ từ nghi vấn \"吗\" (không, phải không) luôn được đặt ở CUỐI một câu trần thuật để biến câu đó thành câu hỏi đóng (Yes/No Question).","note":"<strong>Lưu ý cực kỳ quan trọng:</strong> Nếu trong câu đã có từ để hỏi (như 什么 - cái gì, 谁 - ai) thì TUYỆT ĐỐI không được dùng \"吗\" ở cuối câu nữa.","examples":[{"zh":"你是学生吗？","py":"Nǐ shì xuésheng ma?","vi":"Bạn là học sinh phải không?"},{"zh":"他是中国人吗？","py":"Tā shì Zhōngguó rén ma?","vi":"Anh ấy là người Trung Quốc phải không?"},{"zh":"你好吗？","py":"Nǐ hǎo ma?","vi":"Bạn khỏe không?"},{"zh":"这是你的书吗？","py":"Zhè shì nǐ de shū ma?","vi":"Đây là sách của bạn à?"},{"zh":"你是美国人吗？","py":"Nǐ shì Měiguó rén ma?","vi":"Bạn là người Mỹ phải không?"},{"zh":"他吃苹果吗？","py":"Tā chī píngguǒ ma?","vi":"Anh ấy ăn táo không?"},{"zh":"你喝茶吗？","py":"Nǐ hē chá ma?","vi":"Bạn uống trà không?"},{"zh":"他是老师吗？","py":"Tā shì lǎoshī ma?","vi":"Anh ấy là thầy giáo à?"}]}],"text":{"title":"课文 · Bài khoá","blocks":[{"titleZh":"在学校","titleVi":"Ở trường","icon":"🏫","lines":[{"speaker":"A","zh":"你叫什么名字？","py":"Nǐ jiào shénme míngzi?","vi":"Bạn tên là gì?"},{"speaker":"B","zh":"我叫李月。","py":"Wǒ jiào Lǐ Yuè.","vi":"Tôi tên là Lý Nguyệt."}]},{"titleZh":"在教室","titleVi":"Trong lớp học","icon":"👨‍🏫","lines":[{"speaker":"A","zh":"你是老师吗？","py":"Nǐ shì lǎoshī ma?","vi":"Cô là giáo viên phải không?"},{"speaker":"B","zh":"我不是老师，我是学生。","py":"Wǒ bú shì lǎoshī, wǒ shì xuésheng.","vi":"Tôi không phải là giáo viên, tôi là học sinh."}]},{"titleZh":"在学校","titleVi":"Ở trường","icon":"🌍","lines":[{"speaker":"A","zh":"你是中国人吗？","py":"Nǐ shì Zhōngguó rén ma?","vi":"Bạn là người Trung Quốc phải không?"},{"speaker":"B","zh":"我不是中国人，我是美国人。","py":"Wǒ bú shì Zhōngguó rén, wǒ shì Měiguó rén.","vi":"Tôi không phải người Trung Quốc, tôi là người Mỹ."}]}]},"extra":[{"label":"Mục tiêu","html":"<h2 class=\"section-title\">Mục tiêu bài học</h2>\n  <p class=\"section-sub\">Những kiến thức cốt lõi bạn cần nắm vững sau khi hoàn thành Bài 3.</p>\n  <div class=\"goal-grid\">\n    <div class=\"goal-item\">\n      <div class=\"num\">01</div>\n      <h4>Giao tiếp</h4>\n      <ul>\n        <li>Hỏi và trả lời về tên tuổi một cách tự nhiên.</li>\n        <li>Giới thiệu bản thân là học sinh hay giáo viên.</li>\n        <li>Hỏi và đáp về quốc tịch (bạn đến từ nước nào).</li>\n      </ul>\n    </div>\n    <div class=\"goal-item\">\n      <div class=\"num\">02</div>\n      <h4>Từ vựng</h4>\n      <ul>\n        <li>Đại từ nghi vấn: <b>什么</b> (cái gì)</li>\n        <li>Động từ quan trọng: <b>叫</b> (gọi/tên là), <b>是</b> (là)</li>\n        <li>Danh từ: <b>名字, 老师, 学生, 中国, 美国</b></li>\n      </ul>\n    </div>\n    <div class=\"goal-item\">\n      <div class=\"num\">03</div>\n      <h4>Ngữ pháp & Phát âm</h4>\n      <ul>\n        <li>Nắm cấu trúc câu phán đoán với <b>是</b>.</li>\n        <li>Sử dụng trợ từ <b>吗</b> để hỏi Yes/No.</li>\n        <li>Phân biệt nhóm âm <b>j, q, x</b> và quy tắc đi liền với <b>ü</b>.</li>\n      </ul>\n    </div>\n  </div>"},{"label":"Phát âm & Chữ Hán","html":"<h2 class=\"section-title\">Phát âm & Quy tắc Viết Chữ</h2>\n  <p class=\"section-sub\">Những lưu ý quan trọng để phân biệt nhóm âm khó và quy tắc vàng viết chữ Hán.</p>\n\n  <div class=\"card\">\n    <h3>1. Phân biệt âm: j, q, x và z, c, s</h3>\n    <p>Đây là 2 nhóm âm dễ gây nhầm lẫn nhất đối với người Việt học tiếng Trung.</p>\n    \n    <div class=\"goal-grid\" style=\"grid-template-columns: repeat(2, 1fr); margin-top: 16px;\">\n      <div class=\"goal-item\" style=\"padding: 18px; text-align: left;\">\n        <h4 style=\"color: var(--burgundy); font-family: 'Be Vietnam Pro', sans-serif;\">Nhóm mặt lưỡi (j, q, x)</h4>\n        <ul style=\"font-size: .9rem;\">\n          <li><b>j</b>: Đọc giống \"ch\" nhẹ trong tiếng Việt (chuối).</li>\n          <li><b>q</b>: Đọc giống \"j\" nhưng <b>bật hơi rất mạnh</b>. Răng cắn lại, đẩy gió ra.</li>\n          <li><b>x</b>: Đọc giống \"x\" nhẹ (xinh xắn).</li>\n        </ul>\n      </div>\n      <div class=\"goal-item\" style=\"padding: 18px; text-align: left;\">\n        <h4 style=\"color: var(--gold-dark); font-family: 'Be Vietnam Pro', sans-serif;\">Nhóm đầu lưỡi (z, c, s)</h4>\n        <ul style=\"font-size: .9rem;\">\n          <li><b>z</b>: Đọc giống \"tr\", đầu lưỡi chạm mặt sau răng cửa trên.</li>\n          <li><b>c</b>: Vị trí lưỡi như \"z\" nhưng <b>bật hơi mạnh</b> qua kẽ răng.</li>\n          <li><b>s</b>: Đọc giống \"s\" trong tiếng Việt (sách).</li>\n        </ul>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"card\">\n    <h3>2. Quy tắc vàng của \"U có mắt\" (ü)</h3>\n    <p>Vận mẫu <b>ü</b> (đọc tròn môi, lai giữa u và y) có một quy luật chính tả cực kỳ đặc biệt khi ghép với thanh mẫu.</p>\n    \n    <div class=\"formula-box\" style=\"background: linear-gradient(135deg, var(--ink) 0%, var(--ink-soft) 100%);\">\n      <div class=\"formula-label\" style=\"color: var(--ivory);\">Câu chuyện ghi nhớ</div>\n      <div class=\"formula\" style=\"font-size: 1.2rem; font-family: 'Be Vietnam Pro', sans-serif; font-weight: 500;\">\n        \"Cô nàng <b>ü</b> (đeo kính râm 2 chấm) khi gặp 3 anh chàng đẹp trai <b>j, q, x</b> thì phải bỏ kính ra (bỏ 2 chấm), biến thành <b>ju, qu, xu</b>\".\n      </div>\n    </div>\n    \n    <div class=\"tip-card\">\n      <h5>💡 Lưu ý sống còn:</h5>\n      <p>Nhóm <b>j, q, x</b> KHÔNG BAO GIỜ ghép với chữ \"u\" thường. Do đó, khi bạn nhìn thấy <b>ju, qu, xu</b> trên giấy, bạn PHẢI tự hiểu đó là <b>jü, qü, xü</b> và đọc tròn môi (chu, chyu, xu), tuyệt đối không đọc thành u.</p>\n    </div>\n  </div>\n\n  <div class=\"card\">\n    <h3>3. Các Nét Chữ Hán Cơ Bản (Phần 3) & Bút Thuận</h3>\n    \n    <div class=\"syn-grid\">\n      <div class=\"syn-card theme-burgundy\" style=\"margin-bottom: 0;\">\n        <table class=\"syn-table\">\n          <tr><th>Tên nét</th><th>Hướng viết</th><th>Ví dụ</th></tr>\n          <tr><td>Ngang gập móc (héngzhégōu)</td><td>Ngang, gập xuống, hất móc lên</td><td><b class=\"zh\" style=\"color:var(--burgundy);font-size:1.2rem\">月</b> (yuè - mặt trăng)</td></tr>\n          <tr><td>Nằm móc (wògōu)</td><td>Nằm cong như cái võng, móc lên</td><td><b class=\"zh\" style=\"color:var(--burgundy);font-size:1.2rem\">心</b> (xīn - trái tim)</td></tr>\n        </table>\n      </div>\n      <div class=\"syn-card theme-gold\" style=\"margin-bottom: 0;\">\n        <div class=\"syn-icon\">✍️</div>\n        <h4 style=\"font-family:'Quicksand',sans-serif;font-size:1.2rem;font-weight:700\">Quy tắc thứ tự nét (Bút thuận):</h4>\n        <ul style=\"margin-top: 10px;\">\n          <li><b>Ngang trước, sổ sau:</b> Chữ 十 (shí), chữ 工 (gōng). Viết nét ngang xong mới kéo nét sổ dọc cắt qua.</li>\n          <li><b>Phẩy trước, mác sau:</b> Chữ 八 (bā), chữ 人 (rén). Viết nét phẩy (trái) xong mới viết nét mác (phải).</li>\n        </ul>\n      </div>\n    </div>\n  </div>"},{"label":"Lỗi sai","html":"<h2 class=\"section-title\">Lỗi sai thường gặp</h2>\n  <p class=\"section-sub\">Những lỗi kinh điển người Việt hay mắc phải do bị ảnh hưởng bởi ngữ pháp tiếng Việt.</p>\n  <div class=\"error-grid\">\n    <!-- Lỗi 1 -->\n    <div class=\"error-box\">\n      <div class=\"err-head wrong\">Lỗi 1 · Dịch word-by-word câu hỏi Tên</div>\n      <div class=\"err-body\">\n        <p style=\"margin-bottom:12px\">Trong tiếng Việt, chúng ta hỏi \"Bạn tên là gì?\". Người mới học thường dịch y xì đúc thứ tự từ này sang tiếng Trung.</p>\n        <p class=\"strike zh\">你叫名字什么？ (Bạn - gọi - tên - gì)</p>\n      </div>\n      <div class=\"err-head correct\">Cách sửa</div>\n      <div class=\"err-body\">\n        <p class=\"correct-text zh\">你叫什么名字？</p>\n        <p style=\"font-size:.88rem;color:var(--muted);margin-top:6px\">Trong tiếng Trung, đại từ nghi vấn \"什么\" (cái gì) phải đứng <b>trước</b> danh từ \"名字\" (tên).</p>\n      </div>\n    </div>\n    <!-- Lỗi 2 -->\n    <div class=\"error-box\">\n      <div class=\"err-head wrong\">Lỗi 2 · Lạm dụng chữ \"吗\" (ma)</div>\n      <div class=\"err-body\">\n        <p style=\"margin-bottom:12px\">Nhiều bạn nghĩ rằng cứ câu hỏi là phải thêm \"吗\" (phải không) ở cuối câu, dẫn đến việc dùng sai khi câu đã có sẵn từ để hỏi.</p>\n        <p class=\"strike zh\">你叫什么名字吗？ (Bạn tên là gì phải không?)</p>\n      </div>\n      <div class=\"err-head correct\">Cách sửa</div>\n      <div class=\"err-body\">\n        <p class=\"correct-text zh\">你叫什么名字？</p>\n        <p style=\"font-size:.88rem;color:var(--muted);margin-top:6px\">Nếu trong câu đã có Đại từ nghi vấn (như 什么 - cái gì, 谁 - ai, 哪 - ở đâu), thì <b>TUYỆT ĐỐI KHÔNG</b> dùng 吗 ở cuối câu nữa.</p>\n      </div>\n    </div>\n    <!-- Lỗi 3 -->\n    <div class=\"error-box\">\n      <div class=\"err-head wrong\">Lỗi 3 · Đọc sai ju, qu, xu</div>\n      <div class=\"err-body\">\n        <p style=\"margin-bottom:12px\">Nhìn thấy chữ U, người Việt có thói quen đọc thành âm \"U\". Ví dụ: \"xu\" đọc là \"xu\" (trong đồng xu), \"ju\" đọc là \"chu\".</p>\n        <p class=\"strike zh\">xué sheng (xuể sâng) / jiào (chiao)</p>\n      </div>\n      <div class=\"err-head correct\">Cách sửa</div>\n      <div class=\"err-body\">\n        <p class=\"correct-text zh\">xué sheng (xuế sâng) / ju (chyu)</p>\n        <p style=\"font-size:.88rem;color:var(--muted);margin-top:6px\">Nhớ quy tắc: j, q, x đi với U thì U đó thực chất là Ü. Phải <b>tròn môi</b> khi đọc (chyu, xyu).</p>\n      </div>\n    </div>\n  </div>"},{"label":"Tổng hợp","html":"<h2 class=\"section-title\">Tổng hợp kiến thức</h2>\n  <p class=\"section-sub\">Sơ đồ cốt lõi giúp tóm tắt toàn bộ bài học số 3.</p>\n\n  <div class=\"syn-grid\">\n    <!-- Khối 1: Sơ đồ Giới thiệu bản thân -->\n    <div class=\"syn-card theme-burgundy\">\n      <div class=\"syn-icon\">🗣️</div>\n      <h3>Mạch giới thiệu bản thân</h3>\n      <div class=\"syn-flow\" style=\"flex-direction: column; align-items: stretch;\">\n        <div class=\"step\" style=\"margin-bottom: 8px;\"><span class=\"syn-keyhz\">我叫 + [Tên]</span><br><small>Tên tôi là...</small></div>\n        <div class=\"step\" style=\"margin-bottom: 8px;\"><span class=\"syn-keyhz\">我是 + [Quốc gia] + 人</span><br><small>Tôi là người [nước]...</small></div>\n        <div class=\"step\"><span class=\"syn-keyhz\">我是 + [Nghề nghiệp]</span><br><small>Tôi là [nghề]...</small></div>\n      </div>\n      <div class=\"syn-mnemonic\" style=\"margin-top: 14px;\">Ví dụ: 我叫李月，我是中国人，我是老师。</div>\n    </div>\n\n    <!-- Khối 2: Công thức Phủ định -->\n    <div class=\"syn-card theme-gold\">\n      <div class=\"syn-icon\">❌</div>\n      <h3>Công thức Phủ định với 是</h3>\n      <table class=\"syn-table\">\n        <tr><th>Khẳng định</th><th>Phủ định</th></tr>\n        <tr><td>我是学生</td><td>我<strong style=\"color:var(--burgundy)\">不是</strong>学生</td></tr>\n        <tr><td>她是老师</td><td>她<strong style=\"color:var(--burgundy)\">不是</strong>老师</td></tr>\n        <tr><td>你是美国人</td><td>你<strong style=\"color:var(--burgundy)\">不是</strong>美国人</td></tr>\n      </table>\n      <div class=\"syn-mnemonic\">Chú ý: <b>不 (bù)</b> đứng trước <b>是 (shì)</b> phải đọc biến điệu thành <b>不是 (bú shì)</b>.</div>\n    </div>\n\n    <!-- Khối 3: Bảng 5 Câu Thần Chú -->\n    <div class=\"syn-card theme-ink\" style=\"grid-column: 1 / -1;\">\n      <div class=\"syn-icon\">⚡</div>\n      <h3>Câu thần chú 5 mẫu</h3>\n      <table class=\"syn-table\">\n        <tr><th>Mẫu</th><th>Tình huống</th></tr>\n        <tr><td><span class=\"syn-keyhz\">你叫什么名字？</span></td><td>Dùng để hỏi tên người đối diện.</td></tr>\n        <tr><td><span class=\"syn-keyhz\">我叫李月。</span></td><td>Dùng để tự giới thiệu tên của mình.</td></tr>\n        <tr><td><span class=\"syn-keyhz\">你是老师吗？</span></td><td>Hỏi thăm nghề nghiệp (Dạng Yes/No).</td></tr>\n        <tr><td><span class=\"syn-keyhz\">我是学生。</span></td><td>Trả lời nghề nghiệp (Tôi là học sinh).</td></tr>\n        <tr><td><span class=\"syn-keyhz\">我是中国人。</span></td><td>Trả lời quốc tịch (Thêm chữ 人 sau tên nước).</td></tr>\n      </table>\n      <div class=\"syn-mnemonic\"><strong>Nắm vững 5 mẫu câu này, bạn đã có thể giao tiếp chào hỏi cơ bản cực kỳ lưu loát!</strong></div>\n    </div>\n  </div>"}],"cssId":"c7fcf9643"},{"id":"k1v2-b04","courseId":"k1v2","order":4,"title":"Cô ấy là giáo viên tiếng Trung của tôi","titleZh":"她是我的汉语老师","vocab":[{"stt":1,"hanzi":"她","pinyin":"tā","hanviet":"Tha","pos":"Đại từ","meaning":"cô ấy, chị ấy, bà ấy","comps":"她们 (các cô ấy)","example":{"zh":"她是谁？","py":"Tā shì shéi?","vi":"Cô ấy là ai?"}},{"stt":2,"hanzi":"谁","pinyin":"shéi / shuí","hanviet":"Thùy","pos":"Đại từ","meaning":"ai","comps":"是谁 (là ai), 谁的 (của ai)","example":{"zh":"那个老师是谁？","py":"Nà gè lǎoshī shì shéi?","vi":"Vị giáo viên kia là ai?"}},{"stt":3,"hanzi":"的","pinyin":"de","hanviet":"Đích","pos":"Trợ từ","meaning":"của (chỉ sự sở hữu)","comps":"我的 (của tôi), 好的 (được thôi)","example":{"zh":"这是我的书。","py":"Zhè shì wǒ de shū.","vi":"Đây là sách của tôi."}},{"stt":4,"hanzi":"汉语","pinyin":"Hànyǔ","hanviet":"Hán ngữ","pos":"Danh từ","meaning":"tiếng Trung Quốc (tiếng Hán)","comps":"汉语老师 (giáo viên tiếng Trung)","example":{"zh":"我学习汉语。","py":"Wǒ xuéxí Hànyǔ.","vi":"Tôi học tiếng Trung Quốc."}},{"stt":5,"hanzi":"哪","pinyin":"nǎ","hanviet":"Na","pos":"Đại từ","meaning":"nào, cái nào","comps":"哪个 (cái nào), 哪国人 (người nước nào)","example":{"zh":"你是哪国人？","py":"Nǐ shì nǎ guó rén?","vi":"Bạn là người nước nào?"}},{"stt":6,"hanzi":"国","pinyin":"guó","hanviet":"Quốc","pos":"Danh từ","meaning":"quốc gia, đất nước","comps":"中国 (Trung Quốc), 美国 (Nước Mỹ)","example":{"zh":"我去中国。","py":"Wǒ qù Zhōngguó.","vi":"Tôi đi Trung Quốc."}},{"stt":7,"hanzi":"呢","pinyin":"ne","hanviet":"Ni","pos":"Trợ từ","meaning":"còn... thì sao? (dùng cuối câu hỏi)","comps":"你呢 (còn bạn thì sao)","example":{"zh":"我是学生，你呢？","py":"Wǒ shì xuésheng, nǐ ne?","vi":"Tôi là học sinh, còn bạn thì sao?"}},{"stt":8,"hanzi":"他","pinyin":"tā","hanviet":"Tha","pos":"Đại từ","meaning":"anh ấy, ông ấy","comps":"他们 (bọn họ - nam/nam nữ chung)","example":{"zh":"他是我的好朋友。","py":"Tā shì wǒ de hǎo péngyou.","vi":"Anh ấy là bạn tốt của tôi."}},{"stt":9,"hanzi":"同学","pinyin":"tóngxué","hanviet":"Đồng học","pos":"Danh từ","meaning":"bạn cùng học, bạn cùng lớp","comps":"同学们 (các em học sinh/các bạn học)","example":{"zh":"他是我的同学。","py":"Tā shì wǒ de tóngxué.","vi":"Anh ấy là bạn cùng lớp của tôi."}},{"stt":10,"hanzi":"朋友","pinyin":"péngyou","hanviet":"Bằng hữu","pos":"Danh từ","meaning":"bạn bè","comps":"好朋友 (bạn tốt), 男朋友 (bạn trai)","example":{"zh":"我们是好朋友。","py":"Wǒmen shì hǎo péngyou.","vi":"Chúng tôi là bạn tốt."}}],"hanzi":[{"char":"她","pinyin":"tā","hanviet":"Tha","chars":["她"],"story":"Bộ Nữ (女 - phụ nữ) đứng trước chữ Dã (也 - cũng). Đại từ nhân xưng ngôi thứ 3, chuyên dùng để chỉ phái nữ."},{"char":"谁","pinyin":"shéi / shuí","hanviet":"Thùy","chars":["谁"],"story":"Bao gồm bộ Ngôn (讠- lời nói) và chữ Chuy (隹 - chim đuôi ngắn). Dùng lời nói để hỏi xem con chim bay qua (người đó) là ai."},{"char":"的","pinyin":"de","hanviet":"Đích","chars":["的"],"story":"Gồm chữ Bạch (白 - trắng) và chữ Bao (勺 - cái thìa). Đây là trợ từ kết cấu quan trọng nhất, dùng để kết nối định ngữ và trung tâm ngữ."},{"char":"汉语","pinyin":"Hànyǔ","hanviet":"Hán ngữ","chars":["汉","语"],"story":"汉 (Hán) - người Hán; 语 (Ngữ) - ngôn ngữ, được tạo bởi bộ Ngôn (讠) + Ngũ (五) + Khẩu (口). Ngôn ngữ của dân tộc Hán."},{"char":"哪","pinyin":"nǎ","hanviet":"Na","chars":["哪"],"story":"Phía trước là bộ Khẩu (口 - miệng), phía sau là chữ Na (那 - kia). Dùng miệng để hỏi sự lựa chọn \"Cái nào?\"."},{"char":"国","pinyin":"guó","hanviet":"Quốc","chars":["国"],"story":"Bên ngoài là bộ Vi (囗 - biên giới), bên trong là chữ Ngọc (玉 - viên ngọc). Quốc gia là nơi có biên giới bao bọc, bảo vệ viên ngọc quý."},{"char":"呢","pinyin":"ne","hanviet":"Ni","chars":["呢"],"story":"Bộ Khẩu (口 - miệng) + chữ Ni (尼). Thường đặt ở cuối câu để tạo thành câu hỏi tỉnh lược (hỏi lại cùng chủ đề vừa nhắc)."},{"char":"他","pinyin":"tā","hanviet":"Tha","chars":["他"],"story":"Giống chữ 她 nhưng dùng bộ Nhân đứng (亻- người) thay vì bộ Nữ (女). Dùng để chỉ phái nam hoặc ngôi thứ 3 nói chung."},{"char":"同学","pinyin":"tóngxué","hanviet":"Đồng học","chars":["同","学"],"story":"同 (Đồng - cùng nhau), 学 (Học). Những người \"cùng nhau học tập\" chung dưới một mái trường."},{"char":"朋友","pinyin":"péngyou","hanviet":"Bằng hữu","chars":["朋","友"],"story":"朋 gồm 2 bộ Nguyệt (月 - mặt trăng) đi cùng nhau. 友 là 2 bàn tay nắm lấy nhau (hữu). Tượng trưng cho tình bạn gắn bó, khăng khít."}],"grammar":[{"title":"Đại từ nghi vấn \"谁\" (shéi) và \"哪\" (nǎ)","formula":"Chủ ngữ + 是 + <span>谁</span> ? <br> <span>哪</span> + Danh từ ?","summary":"<b>谁</b> (ai) dùng để hỏi trực tiếp danh tính của một người. Nó đứng chính xác ở vị trí mà câu trả lời sẽ xuất hiện. <b>哪</b> (nào) dùng để yêu cầu chọn lựa, cấu trúc: 哪 + Lượng từ/Danh từ.","note":"<strong>Lưu ý:</strong> Khi dùng \"谁\" và \"哪\", tuyệt đối KHÔNG thêm \"吗\" ở cuối câu.","examples":[{"zh":"她是谁？","py":"Tā shì shéi?","vi":"Cô ấy là ai?"},{"zh":"谁是李月？","py":"Shéi shì Lǐ Yuè?","vi":"Ai là Lý Nguyệt?"},{"zh":"他是谁？","py":"Tā shì shéi?","vi":"Anh ấy là ai?"},{"zh":"你是哪国人？","py":"Nǐ shì nǎ guó rén?","vi":"Bạn là người nước nào?"},{"zh":"哪个人？","py":"Nǎ gè rén?","vi":"Người nào?"},{"zh":"哪本书？","py":"Nǎ běn shū?","vi":"Quyển sách nào?"},{"zh":"大卫是哪国人？","py":"Dàwèi shì nǎ guó rén?","vi":"David là người nước nào?"},{"zh":"谁是老师？","py":"Shéi shì lǎoshī?","vi":"Ai là giáo viên?"}]},{"title":"Trợ từ kết cấu \"的\" (de)","formula":"Chủ sở hữu + <span>的</span> + Vật/Người bị sở hữu","summary":"Chữ \"的\" dùng để nối định ngữ (thành phần bổ nghĩa) và trung tâm ngữ (danh từ chính), biểu thị quan hệ sở hữu. Dịch tiếng Việt là \"của\".","note":"<strong>Lưu ý:</strong> Nếu danh từ đằng sau là người thân trong gia đình hoặc bạn bè, hoặc biểu thị quan hệ rất gần gũi, ta CÓ THỂ LƯỢC BỎ \"的\" (Ví dụ: 我妈妈, 我同学).","examples":[{"zh":"我的老师","py":"Wǒ de lǎoshī","vi":"Giáo viên của tôi"},{"zh":"李月的书","py":"Lǐ Yuè de shū","vi":"Sách của Lý Nguyệt"},{"zh":"他的名字","py":"Tā de míngzi","vi":"Tên của anh ấy"},{"zh":"这是我的书。","py":"Zhè shì wǒ de shū.","vi":"Đây là sách của tôi."},{"zh":"她是我的汉语老师。","py":"Tā shì wǒ de Hànyǔ lǎoshī.","vi":"Cô ấy là giáo viên tiếng Trung của tôi."},{"zh":"我同学（我的同学）","py":"Wǒ tóngxué","vi":"Bạn cùng lớp của tôi (được lược bỏ 的)"},{"zh":"我朋友（我的朋友）","py":"Wǒ péngyou","vi":"Bạn của tôi (được lược bỏ 的)"},{"zh":"我的中国朋友","py":"Wǒ de Zhōngguó péngyou","vi":"Người bạn Trung Quốc của tôi"}]},{"title":"Trợ từ nghi vấn \"呢\" (ne)","formula":"A... (Thông tin). B + <span>呢</span> ?","summary":"Chữ \"呢\" được đặt ở cuối câu để tạo thành câu hỏi tỉnh lược (rút gọn), dùng để hỏi lại cùng một vấn đề vừa được đề cập ở câu trước đó. Tương đương với \"Còn... thì sao?\" trong tiếng Việt.","examples":[{"zh":"我是美国人。你呢？","py":"Wǒ shì Měiguó rén. Nǐ ne?","vi":"Tôi là người Mỹ. Còn bạn thì sao?"},{"zh":"我不是老师。你呢？","py":"Wǒ bú shì lǎoshī. Nǐ ne?","vi":"Tôi không phải giáo viên. Còn bạn?"},{"zh":"她叫李月。他呢？","py":"Tā jiào Lǐ Yuè. Tā ne?","vi":"Cô ấy tên Lý Nguyệt. Còn anh ấy?"},{"zh":"我很好。你呢？","py":"Wǒ hěn hǎo. Nǐ ne?","vi":"Tôi rất khỏe. Còn bạn?"},{"zh":"我是学生。她呢？","py":"Wǒ shì xuésheng. Tā ne?","vi":"Tôi là học sinh. Còn cô ấy?"},{"zh":"大卫是美国人，李月呢？","py":"Dàwèi shì Měiguó rén, Lǐ Yuè ne?","vi":"David là người Mỹ, còn Lý Nguyệt?"},{"zh":"这是我的书。你的呢？","py":"Zhè shì wǒ de shū. Nǐ de ne?","vi":"Đây là sách của tôi. Còn của bạn đâu?"},{"zh":"我去中国。你呢？","py":"Wǒ qù Zhōngguó. Nǐ ne?","vi":"Tôi đi Trung Quốc. Còn bạn?"}]}],"text":{"title":"课文 · Bài khoá","blocks":[{"titleZh":"在教室","titleVi":"Trong lớp học","icon":"👩‍🏫","lines":[{"speaker":"A","zh":"她是谁？","py":"Tā shì shéi?","vi":"Cô ấy là ai thế?"},{"speaker":"B","zh":"她是我的汉语老师，她叫李月。","py":"Tā shì wǒ de Hànyǔ lǎoshī, tā jiào Lǐ Yuè.","vi":"Cô ấy là giáo viên tiếng Trung của tôi, cô ấy tên là Lý Nguyệt."}]},{"titleZh":"在图书馆","titleVi":"Ở thư viện","icon":"📚","lines":[{"speaker":"A","zh":"你是哪国人？","py":"Nǐ shì nǎ guó rén?","vi":"Bạn là người nước nào?"},{"speaker":"B","zh":"我是美国人。你呢？","py":"Wǒ shì Měiguó rén. Nǐ ne?","vi":"Tôi là người Mỹ. Còn bạn?"},{"speaker":"A","zh":"我是中国人。","py":"Wǒ shì Zhōngguó rén.","vi":"Tôi là người Trung Quốc."}]},{"titleZh":"看照片","titleVi":"Xem ảnh","icon":"📸","lines":[{"speaker":"A","zh":"他是谁？","py":"Tā shì shéi?","vi":"Anh ấy là ai vậy?"},{"speaker":"B","zh":"他是我同学。","py":"Tā shì wǒ tóngxué.","vi":"Cậu ấy là bạn cùng lớp của tớ."},{"speaker":"A","zh":"她呢？她是你同学吗？","py":"Tā ne? Tā shì nǐ tóngxué ma?","vi":"Còn cô ấy? Cô ấy có phải bạn cùng lớp của cậu không?"},{"speaker":"B","zh":"她不是我同学，她是我朋友。","py":"Tā bú shì wǒ tóngxué, tā shì wǒ péngyou.","vi":"Cô ấy không phải bạn cùng lớp, cô ấy là bạn tớ."}]}]},"extra":[{"label":"Mục tiêu","html":"<h2 class=\"section-title\">Mục tiêu bài học</h2>\n  <p class=\"section-sub\">Những kiến thức cốt lõi bạn cần nắm vững sau khi hoàn thành Bài 4.</p>\n  <div class=\"goal-grid\">\n    <div class=\"goal-item\">\n      <div class=\"num\">01</div>\n      <h4>Giao tiếp</h4>\n      <ul>\n        <li>Hỏi xem một người thứ ba là ai (Anh ấy/Cô ấy là ai?).</li>\n        <li>Hỏi thông tin về quốc tịch một cách tự nhiên.</li>\n        <li>Giới thiệu các mối quan hệ (bạn bè, thầy cô giáo, bạn cùng lớp).</li>\n      </ul>\n    </div>\n    <div class=\"goal-item\">\n      <div class=\"num\">02</div>\n      <h4>Từ vựng</h4>\n      <ul>\n        <li>Đại từ nhân xưng: <b>她, 他</b></li>\n        <li>Đại từ nghi vấn: <b>谁, 哪</b></li>\n        <li>Danh từ chỉ người: <b>同学, 朋友</b></li>\n        <li>Trợ từ quan trọng: <b>的, 呢</b></li>\n      </ul>\n    </div>\n    <div class=\"goal-item\">\n      <div class=\"num\">03</div>\n      <h4>Ngữ pháp & Phát âm</h4>\n      <ul>\n        <li>Làm chủ trợ từ kết cấu <b>的</b> (chỉ sự sở hữu).</li>\n        <li>Biết dùng câu hỏi tỉnh lược với trợ từ <b>呢</b>.</li>\n        <li>Phát âm chuẩn xác nhóm âm uốn lưỡi <b>zh, ch, sh, r</b>.</li>\n      </ul>\n    </div>\n  </div>"},{"label":"Phát âm & Chữ Hán","html":"<h2 class=\"section-title\">Phát âm & Quy tắc Viết Chữ</h2>\n  <p class=\"section-sub\">Nhóm âm uốn lưỡi, biến điệu của \"一\" và các nét cong móc quan trọng.</p>\n\n  <div class=\"card\">\n    <h3>1. Nhóm âm uốn lưỡi: zh, ch, sh, r</h3>\n    <p>Đây là nhóm âm đòi hỏi bạn phải uốn đầu lưỡi cong lên chạm vào ngạc cứng (vòm miệng trên).</p>\n    \n    <div class=\"goal-grid\" style=\"grid-template-columns: repeat(2, 1fr); margin-top: 16px;\">\n      <div class=\"goal-item\" style=\"padding: 18px; text-align: left;\">\n        <h4 style=\"color: var(--burgundy); font-family: 'Be Vietnam Pro', sans-serif;\">Âm xát tắt (zh, ch)</h4>\n        <ul style=\"font-size: .9rem;\">\n          <li><b>zh</b>: Uốn cong lưỡi. Đọc giống chữ \"tr\" (con trâu) trong tiếng Việt nhưng không bật hơi.</li>\n          <li><b>ch</b>: Vị trí lưỡi như \"zh\" nhưng <b>bật hơi thật mạnh</b> đẩy gió ra ngoài.</li>\n        </ul>\n      </div>\n      <div class=\"goal-item\" style=\"padding: 18px; text-align: left;\">\n        <h4 style=\"color: var(--gold-dark); font-family: 'Be Vietnam Pro', sans-serif;\">Âm xát & Âm rung (sh, r)</h4>\n        <ul style=\"font-size: .9rem;\">\n          <li><b>sh</b>: Uốn lưỡi, tạo khe hở. Đọc giống chữ \"s\" (màu sắc) khi nói giọng chuẩn.</li>\n          <li><b>r</b>: Vị trí lưỡi giống \"sh\" nhưng thanh quản phải rung. Đọc gần giống chữ \"r\" (rá rổ).</li>\n        </ul>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"card\">\n    <h3>2. Quy tắc biến điệu của \"一\" (yī)</h3>\n    <p>Chữ \"一\" mang thanh 1, nhưng khi kết hợp với các từ khác, nó sẽ biến điệu để câu nói tự nhiên hơn.</p>\n    \n    <div class=\"formula-box\">\n      <div class=\"formula-label\">Nguyên tắc biến điệu</div>\n      <div class=\"formula\">一 + <span class=\"pop gold\">Thanh 1, 2, 3</span> ➡ Đọc thành <span class=\"pop gold\">Thanh 4 (yì)</span></div>\n      <div class=\"formula\" style=\"margin-top: 10px; font-size: 1.2rem;\">Ví dụ: yì zhāng (một tờ), yì tiáo (một sợi), yì běn (một quyển)</div>\n    </div>\n\n    <div class=\"formula-box\" style=\"background: linear-gradient(135deg, var(--ink) 0%, var(--ink-soft) 100%); margin-top: 10px;\">\n      <div class=\"formula\" style=\"color: var(--ivory);\">一 + <span class=\"pop gold\">Thanh 4</span> ➡ Đọc thành <span class=\"pop gold\">Thanh 2 (yí)</span></div>\n      <div class=\"formula\" style=\"margin-top: 10px; font-size: 1.2rem; color: var(--ivory);\">Ví dụ: yí dìng (nhất định), yí gè (một cái)</div>\n    </div>\n    \n    <div class=\"tip-card\">\n      <h5>💡 Mẹo lưu ý</h5>\n      <p>Khi \"一\" đứng một mình, đứng ở cuối từ, hoặc là số đếm (1, 2, 3...; thứ hai, thứ ba...), nó <b>GIỮ NGUYÊN</b> thanh 1 (yī). Ví dụ: 第一 (thứ nhất), 十一 (mười một).</p>\n    </div>\n  </div>\n\n  <div class=\"card\">\n    <h3>3. Các Nét Chữ Hán Cơ Bản (Phần 4)</h3>\n    \n    <div class=\"syn-grid\">\n      <div class=\"syn-card theme-burgundy\" style=\"margin-bottom: 0;\">\n        <table class=\"syn-table\">\n          <tr><th>Tên nét</th><th>Hình dáng</th><th>Ví dụ</th></tr>\n          <tr><td>Sổ cong móc (shùwāngōu)</td><td style=\"font-size:1.5rem; font-weight:bold; color:var(--burgundy)\">し</td><td><b class=\"zh\" style=\"color:var(--ink);font-size:1.2rem\">七</b> (qī - bảy)</td></tr>\n          <tr><td>Ngang gập cong móc (héngzhéwāngōu)</td><td style=\"font-size:1.5rem; font-weight:bold; color:var(--burgundy)\">㇈</td><td><b class=\"zh\" style=\"color:var(--ink);font-size:1.2rem\">几</b> (jǐ - mấy)</td></tr>\n        </table>\n      </div>\n      <div class=\"syn-card theme-gold\" style=\"margin-bottom: 0;\">\n        <div class=\"syn-icon\">✍️</div>\n        <h4 style=\"font-family:'Quicksand',sans-serif;font-size:1.2rem;font-weight:700\">Bộ thủ & Các chữ cần nhớ:</h4>\n        <ul style=\"margin-top: 10px;\">\n          <li><b>儿 (ér):</b> Gốc là đứa trẻ, nay chỉ con trai (儿子).</li>\n          <li><b>九 (jiǔ):</b> Số 9. Nét phẩy viết trước, ngang gập cong móc viết sau.</li>\n        </ul>\n      </div>\n    </div>\n  </div>"},{"label":"Lỗi sai","html":"<h2 class=\"section-title\">Lỗi sai thường gặp</h2>\n  <p class=\"section-sub\">Những lỗi người Việt hay mắc phải khi học bài này.</p>\n  <div class=\"error-grid\">\n    <!-- Lỗi 1 -->\n    <div class=\"error-box\">\n      <div class=\"err-head wrong\">Lỗi 1 · Dịch \"word-by-word\" cấu trúc sở hữu</div>\n      <div class=\"err-body\">\n        <p style=\"margin-bottom:12px\">Trong tiếng Việt ta nói \"Sách của tôi\" (A của B). Nhiều bạn dịch nguyên si sang tiếng Trung là 书的我 (Shū de wǒ), điều này hoàn toàn sai.</p>\n        <p class=\"strike zh\">书的我 / 老师我</p>\n      </div>\n      <div class=\"err-head correct\">Cách sửa</div>\n      <div class=\"err-body\">\n        <p class=\"correct-text zh\">我的书 / 我的老师</p>\n        <p style=\"font-size:.88rem;color:var(--muted);margin-top:6px\">Luôn nhớ: Chủ sở hữu đứng trước, đối tượng bị sở hữu đứng sau chữ 的. Tiếng Trung ngược lại hoàn toàn so với tiếng Việt.</p>\n      </div>\n    </div>\n    <!-- Lỗi 2 -->\n    <div class=\"error-box\">\n      <div class=\"err-head wrong\">Lỗi 2 · Lẫn lộn giữa 吗 (ma) và 呢 (ne)</div>\n      <div class=\"err-body\">\n        <p style=\"margin-bottom:12px\">Khi muốn hỏi phản vấn lại người khác (Ví dụ: Tôi là học sinh. Bạn phải không?), nhiều bạn dùng chữ 吗 thay vì 呢.</p>\n        <p class=\"strike zh\">我是学生，你吗？</p>\n      </div>\n      <div class=\"err-head correct\">Cách sửa</div>\n      <div class=\"err-body\">\n        <p class=\"correct-text zh\">我是学生，你呢？</p>\n        <p style=\"font-size:.88rem;color:var(--muted);margin-top:6px\">\"你吗\" là một cấu trúc sai. Để hỏi \"Còn bạn thì sao?\", bắt buộc dùng \"你呢？\".</p>\n      </div>\n    </div>\n    <!-- Lỗi 3 -->\n    <div class=\"error-box\">\n      <div class=\"err-head wrong\">Lỗi 3 · Đọc sai các âm uốn lưỡi (zh, ch, sh)</div>\n      <div class=\"err-body\">\n        <p style=\"margin-bottom:12px\">Do thói quen, nhiều bạn đọc \"shì\" (是 - là) giống y như \"sì\" (số 4 - 四), hoặc đọc \"zhōng\" (Trung) thành \"trông\".</p>\n        <p class=\"strike zh\">Wǒ sì Yuènán rén</p>\n      </div>\n      <div class=\"err-head correct\">Cách sửa</div>\n      <div class=\"err-body\">\n        <p class=\"correct-text zh\">Wǒ shì Yuènán rén</p>\n        <p style=\"font-size:.88rem;color:var(--muted);margin-top:6px\">Phải uốn cong đầu lưỡi lên ngạc cứng khi phát âm các chữ bắt đầu bằng zh, ch, sh, r.</p>\n      </div>\n    </div>\n  </div>"},{"label":"Tổng hợp","html":"<h2 class=\"section-title\">Tổng hợp kiến thức</h2>\n  <p class=\"section-sub\">Sơ đồ cốt lõi giúp tóm tắt toàn bộ bài học.</p>\n\n  <div class=\"syn-grid\">\n    <!-- Khối 1: Cấu trúc -->\n    <div class=\"syn-card theme-burgundy\">\n      <div class=\"syn-icon\">🔍</div>\n      <h3>Công thức Sở Hữu \"的\"</h3>\n      <table class=\"syn-table\">\n        <tr><th>Chủ sở hữu</th><th>Trợ từ</th><th>Vật bị sở hữu</th></tr>\n        <tr><td>我 (Tôi)</td><td>的 (de)</td><td>老师 (Giáo viên)</td></tr>\n        <tr><td>他 (Anh ấy)</td><td>的 (de)</td><td>名字 (Tên)</td></tr>\n      </table>\n      <div class=\"syn-mnemonic\">Mẹo: Công thức dịch ngược. Đọc là \"Tôi - của - Giáo viên\", nhưng dịch là \"Giáo viên của tôi\".</div>\n    </div>\n\n    <!-- Khối 2: Sơ đồ chuỗi (Flow) -->\n    <div class=\"syn-card theme-gold\">\n      <div class=\"syn-icon\">🗣️</div>\n      <h3>Hỏi thăm thông tin (Phản vấn)</h3>\n      <div class=\"syn-flow\">\n        <div class=\"step\"><span class=\"syn-keyhz\">我是中国人</span><br><small>Đưa ra thông tin A</small></div>\n        <span class=\"arrow\">→</span>\n        <div class=\"step\"><span class=\"syn-keyhz\">你呢？</span><br><small>Hỏi lại B về thông tin đó</small></div>\n      </div>\n      <div class=\"syn-mnemonic\">Mẹo: Dùng <strong>你呢？ (Nǐ ne?)</strong> ngay sau khi giới thiệu bản thân để hỏi đối phương câu tương tự.</div>\n    </div>\n\n    <!-- Khối 3: Bảng 5 Câu Thần Chú -->\n    <div class=\"syn-card theme-ink\" style=\"grid-column: 1 / -1;\">\n      <div class=\"syn-icon\">⚡</div>\n      <h3>Câu thần chú 5 mẫu</h3>\n      <table class=\"syn-table\">\n        <tr><th>Mẫu</th><th>Tình huống</th></tr>\n        <tr><td><span class=\"syn-keyhz\">她是谁？</span></td><td>Hỏi xem người phụ nữ kia/người thứ 3 là ai.</td></tr>\n        <tr><td><span class=\"syn-keyhz\">她是我的汉语老师。</span></td><td>Giới thiệu một người là giáo viên của mình.</td></tr>\n        <tr><td><span class=\"syn-keyhz\">你是哪国人？</span></td><td>Hỏi đối phương đến từ quốc gia nào.</td></tr>\n        <tr><td><span class=\"syn-keyhz\">我是中国人。你呢？</span></td><td>Trả lời quốc tịch, sau đó hỏi ngược lại người đối diện.</td></tr>\n        <tr><td><span class=\"syn-keyhz\">他不是我同学，他是我朋友。</span></td><td>Phủ định và khẳng định mối quan hệ của một người.</td></tr>\n      </table>\n      <div class=\"syn-mnemonic\"><strong>Thuộc lòng 5 mẫu này là bạn đã làm chủ hoàn toàn Bài 04.</strong></div>\n    </div>\n  </div>"}],"cssId":"c7fcf9643"},{"id":"k1v2-b05","courseId":"k1v2","order":5,"title":"Con gái của cô ấy năm nay 20 tuổi.","titleZh":"她女儿今年二十岁。","vocab":[{"stt":1,"hanzi":"家","pinyin":"jiā","hanviet":"Gia","pos":"Danh từ","meaning":"Nhà, gia đình","comps":"大家 (mọi người), 国家 (quốc gia)","example":{"zh":"这是我家。","py":"Zhè shì wǒ jiā.","vi":"Đây là nhà của tôi."}},{"stt":2,"hanzi":"有","pinyin":"yǒu","hanviet":"Hữu","pos":"Động từ","meaning":"Có","comps":"没有 (không có), 还有 (vẫn còn)","example":{"zh":"我家有三口人。","py":"Wǒ jiā yǒu sān kǒu rén.","vi":"Nhà tôi có ba người."}},{"stt":3,"hanzi":"口","pinyin":"kǒu","hanviet":"Khẩu","pos":"Lượng từ","meaning":"Lượng từ dùng cho người (nhân khẩu)","comps":"人口 (nhân khẩu), 户口 (hộ khẩu)","example":{"zh":"你家有几口人？","py":"Nǐ jiā yǒu jǐ kǒu rén?","vi":"Nhà bạn có mấy người?"}},{"stt":4,"hanzi":"女儿","pinyin":"nǚ'ér","hanviet":"Nữ nhi","pos":"Danh từ","meaning":"Con gái","comps":"儿子 (con trai), 她的女儿 (con gái cô ấy)","example":{"zh":"她女儿呢？","py":"Tā nǚ'ér ne?","vi":"Còn con gái cô ấy thì sao?"}},{"stt":5,"hanzi":"几","pinyin":"jǐ","hanviet":"Kỷ","pos":"Đại từ","meaning":"Mấy, vài (hỏi số lượng < 10)","comps":"几个 (mấy cái), 几岁 (mấy tuổi)","example":{"zh":"你女儿几岁了？","py":"Nǐ nǚ'ér jǐ suì le?","vi":"Con gái bạn mấy tuổi rồi?"}},{"stt":6,"hanzi":"岁","pinyin":"suì","hanviet":"Tuế","pos":"Lượng từ","meaning":"Tuổi","comps":"几岁 (mấy tuổi), 岁数 (số tuổi)","example":{"zh":"她今年四岁了。","py":"Tā jīnnián sì suì le.","vi":"Cô bé năm nay bốn tuổi rồi."}},{"stt":7,"hanzi":"了","pinyin":"le","hanviet":"Liễu","pos":"Trợ từ","meaning":"Rồi (chỉ sự thay đổi/hành động đã xảy ra)","comps":"来了 (đến rồi), 好了 (xong rồi)","example":{"zh":"李老师多大了？","py":"Lǐ lǎoshī duō dà le?","vi":"Cô Lý bao nhiêu tuổi rồi?"}},{"stt":8,"hanzi":"今年","pinyin":"jīnnián","hanviet":"Kim niên","pos":"Danh từ","meaning":"Năm nay","comps":"今天 (hôm nay), 明年 (sang năm)","example":{"zh":"她女儿今年二十岁。","py":"Tā nǚ'ér jīnnián èrshí suì.","vi":"Con gái cô ấy năm nay hai mươi tuổi."}},{"stt":9,"hanzi":"多","pinyin":"duō","hanviet":"Đa","pos":"Phó từ","meaning":"Bao nhiêu (chỉ mức độ); Nhiều","comps":"多少 (bao nhiêu), 很多 (rất nhiều)","example":{"zh":"你爸爸今年多大？","py":"Nǐ bàba jīnnián duō dà?","vi":"Ba của bạn năm nay bao nhiêu tuổi?"}},{"stt":10,"hanzi":"大","pinyin":"dà","hanviet":"Đại","pos":"Tính từ","meaning":"Lớn, già, to","comps":"大家 (mọi người), 很大 (rất lớn)","example":{"zh":"你今年多大了？","py":"Nǐ jīnnián duō dà le?","vi":"Năm nay bạn bao nhiêu tuổi rồi?"}}],"hanzi":[{"char":"家","pinyin":"jiā","hanviet":"Gia","chars":["家"],"story":"Chữ Nhà (家) gồm Bộ Miên (mái nhà 宀) ở trên và chữ Thỉ (con lợn 豕) ở dưới. Người xưa quan niệm có nhà ở và có lợn để chăn nuôi chính là biểu tượng của một gia đình ấm no, sung túc."},{"char":"有","pinyin":"yǒu","hanviet":"Hữu","chars":["有"],"story":"Bên trên là bộ Hựu/Thủ (bàn tay vươn ra 𠂇), bên dưới là bộ Nguyệt (mặt trăng 月). Bàn tay vươn ra trong đêm tối tóm được mặt trăng mang ý nghĩa là mình \"CÓ\" được thứ gì đó."},{"char":"口","pinyin":"kǒu","hanviet":"Khẩu","chars":["口"],"story":"Đây là chữ tượng hình, vẽ hình một cái miệng đang há ra vuông vức."},{"char":"女儿","pinyin":"nǚ'ér","hanviet":"Nữ nhi","chars":["女","儿"],"story":"Chữ 女 (Nữ) mô phỏng hình dáng một người phụ nữ đang quỳ chéo chân chắp tay trên mặt đất thời xưa. Chữ 儿 (Nhi) mượn hình ảnh đứa trẻ đang bước đi. \"Nữ nhi\" chính là bé gái hay con gái."},{"char":"几","pinyin":"jǐ","hanviet":"Kỷ","chars":["几"],"story":"Nét chữ trông giống hình một chiếc bàn kỷ nhỏ bằng gỗ thời xưa. Ở đây dùng mượn âm để hỏi số lượng \"mấy\"."},{"char":"岁","pinyin":"suì","hanviet":"Tuế","chars":["岁"],"story":"Phía trên là bộ Sơn (núi), phía dưới là bộ Tịch (chiều tối). Mặt trời lặn sau ngọn núi biểu thị 1 ngày đã qua, nhiều ngày như vậy gộp lại thành 1 năm, chỉ số \"Tuổi\"."},{"char":"了","pinyin":"le","hanviet":"Liễu","chars":["了"],"story":"Hình ảnh giống một đứa bé sơ sinh (chữ Tử 子) bị mất hai cánh tay, chỉ sự vật đã bị cắt đứt, hoàn tất, xong xuôi \"rồi\"."},{"char":"今年","pinyin":"jīnnián","hanviet":"Kim niên","chars":["今","年"],"story":"今 (Kim - hiện tại) ghép với 年 (Niên - năm). Kim niên chính là Năm nay. Chữ Niên có bộ Hòa (lúa) chỉ 1 vụ thu hoạch lúa tương đương 1 năm."},{"char":"多","pinyin":"duō","hanviet":"Đa","chars":["多"],"story":"Chữ 多 cấu tạo từ 2 bộ Tịch 夕 (chiều tối/mặt trăng) chồng lên nhau. Nghĩa là rất nhiều ngày, rất nhiều đêm."},{"char":"大","pinyin":"dà","hanviet":"Đại","chars":["大"],"story":"Hình ảnh một người (nhân 人) đang dang rộng hai tay và hai chân ra để vươn hết cỡ, tạo thành chữ Đại (To lớn)."}],"grammar":[{"title":"Đại từ nghi vấn chỉ số lượng \"几\" (jǐ)","formula":"Chủ ngữ + <span>几</span> + Lượng từ + Danh từ？","summary":"Dùng để hỏi số lượng nhỏ, thường là những con số dưới 10 (nghĩa là \"mấy\", \"vài\").","note":"<strong>Lưu ý:</strong> Khi dùng \"几\", bắt buộc phải có lượng từ đứng ngay đằng sau nó (như 个, 口, 本, v.v.).","examples":[{"zh":"你家有几口人？","py":"Nǐ jiā yǒu jǐ kǒu rén?","vi":"Nhà bạn có mấy người?"},{"zh":"你有几个汉语老师？","py":"Nǐ yǒu jǐ ge Hànyǔ lǎoshī?","vi":"Bạn có mấy giáo viên tiếng Trung?"},{"zh":"他有几个苹果？","py":"Tā yǒu jǐ ge píngguǒ?","vi":"Anh ấy có mấy quả táo?"},{"zh":"你想买几本书？","py":"Nǐ xiǎng mǎi jǐ běn shū?","vi":"Bạn muốn mua mấy cuốn sách?"},{"zh":"今天是几月几号？","py":"Jīntiān shì jǐ yuè jǐ hào?","vi":"Hôm nay là ngày mấy tháng mấy?"},{"zh":"明天星期几？","py":"Míngtiān xīngqī jǐ?","vi":"Ngày mai là thứ mấy?"},{"zh":"你们几点去学校？","py":"Nǐmen jǐ diǎn qù xuéxiào?","vi":"Các bạn mấy giờ đi đến trường?"},{"zh":"你女儿几岁了？","py":"Nǐ nǚ'ér jǐ suì le?","vi":"Con gái bạn mấy tuổi rồi?"}]},{"title":"Trợ từ \"了\" (le) chỉ sự thay đổi","formula":"Chủ ngữ + Vị ngữ + <span>了</span>。","summary":"Chữ \"了\" đặt ở cuối câu dùng để biểu thị một sự thay đổi đã xảy ra hoặc một tình huống mới đã xuất hiện.","note":"<strong>Lưu ý:</strong> Trong bài này, \"了\" kết hợp với mẫu câu tuổi tác để chỉ việc \"ai đó ĐÃ BƯỚC SANG một độ tuổi mới\". Thường dịch là \"...rồi\".","examples":[{"zh":"她今年四岁了。","py":"Tā jīnnián sì suì le.","vi":"Năm nay cháu 4 tuổi rồi."},{"zh":"李老师五十岁了。","py":"Lǐ lǎoshī wǔshí suì le.","vi":"Cô Lý 50 tuổi rồi."},{"zh":"我二十岁了。","py":"Wǒ èrshí suì le.","vi":"Tôi 20 tuổi rồi."},{"zh":"下雨了。","py":"Xià yǔ le.","vi":"Trời đổ mưa rồi."},{"zh":"昨天星期三，今天星期四了。","py":"Zuótiān xīngqīsān, jīntiān xīngqīsì le.","vi":"Hôm qua là thứ 4, hôm nay thứ 5 rồi."},{"zh":"不早了。","py":"Bù zǎo le.","vi":"Không còn sớm nữa rồi."},{"zh":"他回家了。","py":"Tā huí jiā le.","vi":"Anh ấy về nhà rồi."},{"zh":"苹果红了。","py":"Píngguǒ hóng le.","vi":"Quả táo chín đỏ rồi."}]},{"title":"Cấu trúc hỏi tuổi với \"多大\" (duō dà)","formula":"Chủ ngữ + (今年) + <span>多大</span> + (了)？","summary":"Khi muốn hỏi tuổi của người lớn (từ 10 tuổi trở lên), người Trung Quốc không dùng \"几岁\" mà dùng cấu trúc \"多大\" (bao lớn, bao nhiêu tuổi).","note":"<strong>Lưu ý:</strong> Với trẻ em dưới 10 tuổi ta dùng \"几岁\", từ 10 tuổi trở lên dùng \"多大\", và người già dùng \"多大年纪\" (bao nhiêu tuổi tác) để bày tỏ sự tôn trọng.","examples":[{"zh":"你今年多大了？","py":"Nǐ jīnnián duō dà le?","vi":"Năm nay bạn bao nhiêu tuổi rồi?"},{"zh":"李老师多大了？","py":"Lǐ lǎoshī duō dà le?","vi":"Cô Lý bao nhiêu tuổi rồi?"},{"zh":"你爸爸多大了？","py":"Nǐ bàba duō dà le?","vi":"Ba của bạn bao nhiêu tuổi rồi?"},{"zh":"那个学生多大了？","py":"Nà ge xuésheng duō dà le?","vi":"Học sinh kia bao nhiêu tuổi rồi?"},{"zh":"哥哥多大了？","py":"Gēge duō dà le?","vi":"Anh trai bao nhiêu tuổi rồi?"},{"zh":"你的中国朋友多大了？","py":"Nǐ de Zhōngguó péngyou duō dà le?","vi":"Người bạn Trung Quốc của bạn bao nhiêu tuổi?"},{"zh":"大卫今年多大了？","py":"Dàwèi jīnnián duō dà le?","vi":"David năm nay bao nhiêu tuổi?"},{"zh":"您今年多大年纪了？","py":"Nín jīnnián duō dà niánjì le?","vi":"Cụ năm nay bao nhiêu tuổi rồi ạ? (Người già)"}]}],"text":{"title":"课文 · Bài khoá","blocks":[{"titleZh":"在学校","titleVi":"Ở trường","icon":"🏫","lines":[{"speaker":"A","zh":"你家有几口人？","py":"Nǐ jiā yǒu jǐ kǒu rén?","vi":"Nhà anh có mấy người vậy?"},{"speaker":"B","zh":"我家有三口人。","py":"Wǒ jiā yǒu sān kǒu rén.","vi":"Nhà tôi có ba người."}]},{"titleZh":"在办公室","titleVi":"Trong văn phòng","icon":"🏢","lines":[{"speaker":"A","zh":"你女儿几岁了？","py":"Nǐ nǚ'ér jǐ suì le?","vi":"Con gái của cô mấy tuổi rồi?"},{"speaker":"B","zh":"她今年四岁了。","py":"Tā jīnnián sì suì le.","vi":"Năm nay cháu được bốn tuổi rồi."}]},{"titleZh":"在办公室","titleVi":"Trong văn phòng","icon":"🏢","lines":[{"speaker":"A","zh":"李老师多大了？","py":"Lǐ lǎoshī duō dà le?","vi":"Cô Lý bao nhiêu tuổi rồi?"},{"speaker":"B","zh":"她今年五十岁了。","py":"Tā jīnnián wǔshí suì le.","vi":"Năm nay cô ấy 50 tuổi rồi."},{"speaker":"A","zh":"她女儿呢？","py":"Tā nǚ'ér ne?","vi":"Còn con gái cô ấy?"},{"speaker":"B","zh":"她女儿今年二十岁。","py":"Tā nǚ'ér jīnnián èrshí suì.","vi":"Con gái cô ấy năm nay 20 tuổi."}]}]},"extra":[{"label":"Mục tiêu","html":"<h2 class=\"section-title\">Mục tiêu bài học</h2>\n  <p class=\"section-sub\">Nắm vững cách giới thiệu gia đình và hỏi tuổi tác trong giao tiếp hàng ngày.</p>\n  <div class=\"goal-grid\">\n    <div class=\"goal-item\">\n      <div class=\"num\">01</div>\n      <h4>Giao tiếp</h4>\n      <ul>\n        <li>Giới thiệu số lượng thành viên trong gia đình</li>\n        <li>Hỏi tuổi trẻ em dưới 10 tuổi</li>\n        <li>Hỏi tuổi người lớn và người cao tuổi một cách lịch sự</li>\n      </ul>\n    </div>\n    <div class=\"goal-item\">\n      <div class=\"num\">02</div>\n      <h4>Từ vựng</h4>\n      <ul>\n        <li>Chủ đề Đại từ: <b>几, 多</b></li>\n        <li>Chủ đề Gia đình: <b>家, 女儿</b></li>\n        <li>Chủ đề Tuổi tác: <b>岁, 今年, 大</b></li>\n      </ul>\n    </div>\n    <div class=\"goal-item\">\n      <div class=\"num\">03</div>\n      <h4>Ngữ pháp</h4>\n      <ul>\n        <li>Đại từ nghi vấn chỉ số lượng <b>\"几\"</b></li>\n        <li>Cấu trúc hỏi tuổi <b>\"多大\"</b></li>\n        <li>Trợ từ chỉ sự thay đổi <b>\"了\"</b> ở cuối câu</li>\n      </ul>\n    </div>\n  </div>"},{"label":"Chuyên đề Mở rộng","html":"<h2 class=\"section-title\">Văn hóa hỏi tuổi & Gia đình</h2>\n  <p class=\"section-sub\">Tìm hiểu cách người Trung Quốc xưng hô trong gia đình và sự khác biệt tinh tế khi hỏi tuổi ở từng độ tuổi khác nhau.</p>\n\n  <!-- Card 1: Gia đình -->\n  <div class=\"card\">\n    <h3>1. Từ vựng mở rộng: Các thành viên trong gia đình</h3>\n    <p>Người Trung Quốc rất coi trọng thứ bậc gia đình. Bài học bổ sung thêm cách gọi tên các thành viên thân thiết để bạn dễ dàng giới thiệu tổ ấm của mình.</p>\n    \n    <div class=\"formula-box\" style=\"background: linear-gradient(135deg, #3A2020 0%, #5C3A34 100%);\">\n      <div class=\"formula-label\">Thế hệ ông bà</div>\n      <div class=\"formula\"><span class=\"pop gold\" style=\"color: #FBF1E6;\">爷爷 (yéye - ông nội)</span> &nbsp;&amp;&nbsp; <span class=\"pop gold\" style=\"color: #FBF1E6;\">奶奶 (nǎinai - bà nội)</span></div>\n    </div>\n\n    <div class=\"formula-box\">\n      <div class=\"formula-label\">Thế hệ cha mẹ & Anh chị em</div>\n      <div class=\"formula\" style=\"font-size: 1.2rem; line-height: 1.8;\">\n        爸爸 (bàba - ba) &nbsp; 妈妈 (māma - mẹ)<br>\n        哥哥 (gēge - anh) &nbsp; 姐姐 (jiějie - chị)<br>\n        弟弟 (dìdi - em trai) &nbsp; 妹妹 (mèimei - em gái)\n      </div>\n    </div>\n    \n    <div class=\"tip-card\">\n      <h5>💡 Mẹo lưu ý</h5>\n      <p>Khi giới thiệu cả gia đình, người Trung Quốc thường liệt kê theo thứ tự từ lớn đến bé, ví dụ: <b>我家有爸爸，妈妈，哥哥，和我。</b> (Nhà tôi có ba, mẹ, anh trai, và tôi).</p>\n    </div>\n  </div>\n\n  <!-- Card 2: Văn hóa hỏi tuổi -->\n  <div class=\"card\">\n    <h3>2. Văn hóa: Cách hỏi tuổi của người Trung Quốc</h3>\n    <p>Trong văn hóa phương Tây, tuổi tác là vấn đề riêng tư. Nhưng ở Trung Quốc, hỏi tuổi là một cách thể hiện sự quan tâm. Tùy thuộc vào độ tuổi của người đối diện mà ta có cách hỏi khác nhau:</p>\n    \n    <ul style=\"margin-top: 14px; margin-bottom: 24px;\">\n      <li style=\"margin-bottom: 12px;\"><b>Với trẻ em (Dưới 10 tuổi):</b> Dùng \"几\" (mấy).<br> <span class=\"zh\" style=\"color:var(--burgundy); font-weight:600;\">你今年几岁了？</span> (Cháu năm nay mấy tuổi rồi?)</li>\n      <li style=\"margin-bottom: 12px;\"><b>Với thanh niên / Người trạc tuổi:</b> Dùng cấu trúc \"多大\" (bao nhiêu tuổi).<br> <span class=\"zh\" style=\"color:var(--burgundy); font-weight:600;\">你今年多大了？</span> (Bạn năm nay bao nhiêu tuổi rồi?)</li>\n      <li><b>Với người lớn tuổi / Bậc bề trên:</b> Phải thêm \"年纪\" (niánjì - tuổi tác) để thể hiện sự kính trọng cao nhất.<br> <span class=\"zh\" style=\"color:var(--burgundy); font-weight:600;\">您今年多大年纪了？</span> (Ông/bà năm nay bao nhiêu tuổi rồi ạ?)</li>\n    </ul>\n\n    <div class=\"tip-card\">\n      <h5>⚠️ Lưu ý sự khác biệt văn hoá</h5>\n      <p>Nếu bạn hỏi một ông cụ 70 tuổi là <b>你几岁了？</b>, người Trung Quốc sẽ cho rằng bạn đang hỏi ông cụ như hỏi một đứa trẻ 5 tuổi, điều này rất bất lịch sự! Hãy ghi nhớ kỹ 3 mẫu câu trên.</p>\n    </div>\n  </div>"},{"label":"Lỗi sai","html":"<h2 class=\"section-title\">Lỗi sai thường gặp</h2>\n  <p class=\"section-sub\">Những lỗi người Việt hay mắc phải khi học bài 5.</p>\n  <div class=\"error-grid\">\n    <!-- Lỗi 1 -->\n    <div class=\"error-box\">\n      <div class=\"err-head wrong\">Lỗi 1 · Dùng thừa, sai lượng từ cho người</div>\n      <div class=\"err-body\">\n        <p style=\"margin-bottom:12px\">Trong tiếng Việt ta nói \"3 cái miệng\" hoặc \"3 người\". Học sinh Việt Nam hay nhầm dùng lượng từ \"个\" cho người trong gia đình hoặc bê nguyên chữ \"口\" làm danh từ dẫn đến sai lầm.</p>\n        <p class=\"strike zh\">我家有三个口人。</p>\n        <p class=\"strike zh\" style=\"margin-top:4px;\">我家有三个人。</p>\n      </div>\n      <div class=\"err-head correct\">Cách sửa</div>\n      <div class=\"err-body\">\n        <p class=\"correct-text zh\">我家有三口人。</p>\n        <p style=\"font-size:.88rem;color:var(--muted);margin-top:6px\">Khi đếm thành viên trong gia đình, bắt buộc phải dùng lượng từ \"口\" (kǒu) đặt ngay trước chữ \"人\". Tuyệt đối không dùng \"个\" hay gộp \"个口\".</p>\n      </div>\n    </div>\n    <!-- Lỗi 2 -->\n    <div class=\"error-box\">\n      <div class=\"err-head wrong\">Lỗi 2 · Dùng \"几岁\" để hỏi người lớn</div>\n      <div class=\"err-body\">\n        <p style=\"margin-bottom:12px\">Chữ \"几\" (jǐ) chỉ dùng để hỏi số lượng nhỏ hơn 10. Do đó, nếu bạn hỏi người đã trưởng thành (trên 10 tuổi) bằng \"几岁\" là sai về mặt ngữ pháp và văn hóa.</p>\n        <p class=\"strike zh\">老师今年几岁了？</p>\n      </div>\n      <div class=\"err-head correct\">Cách sửa</div>\n      <div class=\"err-body\">\n        <p class=\"correct-text zh\">老师今年多大了？</p>\n        <p style=\"font-size:.88rem;color:var(--muted);margin-top:6px\">Với trẻ con &lt; 10 tuổi dùng \"几岁了\". Còn từ 10 tuổi trở lên phải dùng cụm từ \"多大了\".</p>\n      </div>\n    </div>\n    <!-- Lỗi 3 -->\n    <div class=\"error-box\">\n      <div class=\"err-head wrong\">Lỗi 3 · Nhầm trật tự từ của \"多大\"</div>\n      <div class=\"err-body\">\n        <p style=\"margin-bottom:12px\">Trong tiếng Việt, ta hỏi \"bao nhiêu tuổi\", có chữ \"tuổi\" ở cuối. Nhưng trong tiếng Trung, bản thân cụm \"多大\" đã bao hàm ý nghĩa hỏi tuổi tác mà không cần thêm chữ \"岁\".</p>\n        <p class=\"strike zh\">他今年大多了？</p>\n        <p class=\"strike zh\" style=\"margin-top:4px;\">他今年多大岁了？</p>\n      </div>\n      <div class=\"err-head correct\">Cách sửa</div>\n      <div class=\"err-body\">\n        <p class=\"correct-text zh\">他今年多大了？</p>\n        <p style=\"font-size:.88rem;color:var(--muted);margin-top:6px\">\"多大\" (bao lớn/bao nhiêu tuổi) luôn đi liền nhau. Đừng chèn thêm chữ \"岁\" vào phía sau câu hỏi \"多大\". Chữ \"岁\" chỉ xuất hiện ở câu TRẢ LỜI.</p>\n      </div>\n    </div>\n  </div>"},{"label":"Tổng hợp","html":"<h2 class=\"section-title\">Tổng hợp kiến thức</h2>\n  <p class=\"section-sub\">Sơ đồ cốt lõi giúp tóm tắt toàn bộ bài học.</p>\n\n  <div class=\"syn-grid\">\n    <!-- Khối 1: Cấu trúc -->\n    <div class=\"syn-card theme-burgundy\">\n      <div class=\"syn-icon\">🔍</div>\n      <h3>Cấu trúc nói về tuổi</h3>\n      <table class=\"syn-table\">\n        <tr><th>Loại</th><th>Cấu trúc</th></tr>\n        <tr><td>Khẳng định</td><td>Chủ ngữ + 今年 + Số tuổi + 岁 + 了。</td></tr>\n        <tr><td>Phủ định</td><td>Chủ ngữ + 今年 + Không dùng phủ định với tuổi.</td></tr>\n      </table>\n      <div class=\"syn-mnemonic\">Nhớ thêm chữ \"了\" ở cuối để chỉ sự thay đổi (đã bước sang tuổi mới).</div>\n    </div>\n\n    <!-- Khối 2: Sơ đồ chuỗi (Flow) -->\n    <div class=\"syn-card theme-gold\">\n      <div class=\"syn-icon\">📅</div>\n      <h3>Thứ tự hỏi - đáp Gia đình</h3>\n      <div class=\"syn-flow\">\n        <div class=\"step\"><span class=\"syn-keyhz\">你家</span><br><small>Nhà bạn</small></div>\n        <span class=\"arrow\">→</span>\n        <div class=\"step\"><span class=\"syn-keyhz\">有几口</span><br><small>có mấy</small></div>\n        <span class=\"arrow\">→</span>\n        <div class=\"step\"><span class=\"syn-keyhz\">人？</span><br><small>người?</small></div>\n      </div>\n      <div class=\"syn-mnemonic\">Nhớ dùng lượng từ <strong>口</strong> khi đếm nhân khẩu trong nhà!</div>\n    </div>\n\n    <!-- Khối 3: Bảng 5 Câu Thần Chú -->\n    <div class=\"syn-card theme-gold\" style=\"grid-column: 1 / -1;\">\n      <div class=\"syn-icon\">⚡</div>\n      <h3>Câu thần chú 5 mẫu</h3>\n      <table class=\"syn-table\">\n        <tr><th>Mẫu</th><th>Tình huống</th></tr>\n        <tr><td><span class=\"syn-keyhz\">我家有三口人。</span></td><td>Trả lời khi ai đó hỏi nhà bạn có mấy người (Nhà tôi có 3 người).</td></tr>\n        <tr><td><span class=\"syn-keyhz\">你家有几口人？</span></td><td>Hỏi thăm số lượng thành viên trong gia đình bạn bè.</td></tr>\n        <tr><td><span class=\"syn-keyhz\">你女儿几岁了？</span></td><td>Hỏi tuổi một đứa bé (trẻ em dưới 10 tuổi).</td></tr>\n        <tr><td><span class=\"syn-keyhz\">她今年四岁了。</span></td><td>Nói ra số tuổi hiện tại của một người (Cô ấy/bé ấy năm nay 4 tuổi rồi).</td></tr>\n        <tr><td><span class=\"syn-keyhz\">李老师多大了？</span></td><td>Hỏi tuổi một người trưởng thành (trên 10 tuổi) một cách lịch sự.</td></tr>\n      </table>\n      <div class=\"syn-mnemonic\"><strong>Thuộc 5 mẫu này là pass Bài 5.</strong></div>\n    </div>\n  </div>"}],"cssId":"c7fcf9643"},{"id":"k1v2-b06","courseId":"k1v2","order":6,"title":"Tôi biết nói tiếng Trung Quốc.","titleZh":"我会说汉语。","vocab":[{"stt":1,"hanzi":"会","pinyin":"huì","hanviet":"Hội","pos":"Động từ năng nguyện","meaning":"Biết (thông qua học tập)","comps":"开会 (họp), 不会 (không biết)","example":{"zh":"我会说汉语。","py":"Wǒ huì shuō Hànyǔ.","vi":"Tôi biết nói tiếng Trung."}},{"stt":2,"hanzi":"说","pinyin":"shuō","hanviet":"Thuyết","pos":"Động từ","meaning":"Nói","comps":"说话 (nói chuyện), 听说 (nghe nói)","example":{"zh":"她不会说汉语。","py":"Tā bú huì shuō Hànyǔ.","vi":"Cô ấy không biết nói tiếng Trung."}},{"stt":3,"hanzi":"妈妈","pinyin":"māma","hanviet":"Ma ma","pos":"Danh từ","meaning":"Mẹ","comps":"爸爸妈妈 (ba mẹ), 我妈妈 (mẹ tôi)","example":{"zh":"我妈妈不会做中国菜。","py":"Wǒ māma bú huì zuò Zhōngguó cài.","vi":"Mẹ tôi không biết nấu món Trung Quốc."}},{"stt":4,"hanzi":"菜","pinyin":"cài","hanviet":"Thái","pos":"Danh từ","meaning":"Món ăn, thức ăn, rau","comps":"做菜 (nấu ăn), 买菜 (mua thức ăn)","example":{"zh":"中国菜好吃吗？","py":"Zhōngguó cài hǎochī ma?","vi":"Món ăn Trung Quốc có ngon không?"}},{"stt":5,"hanzi":"很","pinyin":"hěn","hanviet":"Ngận","pos":"Phó từ","meaning":"Rất","comps":"很好 (rất tốt), 很大 (rất to)","example":{"zh":"中国菜很好吃。","py":"Zhōngguó cài hěn hǎochī.","vi":"Món ăn Trung Quốc rất ngon."}},{"stt":6,"hanzi":"好吃","pinyin":"hǎochī","hanviet":"Hảo cật","pos":"Tính từ","meaning":"Ngon","comps":"很好吃 (rất ngon), 不好吃 (không ngon)","example":{"zh":"这个菜很好吃。","py":"Zhège cài hěn hǎochī.","vi":"Món này rất ngon."}},{"stt":7,"hanzi":"做","pinyin":"zuò","hanviet":"Tác","pos":"Động từ","meaning":"Làm, nấu (ăn)","comps":"做菜 (nấu ăn), 做工作 (làm việc)","example":{"zh":"你会做中国菜吗？","py":"Nǐ huì zuò Zhōngguó cài ma?","vi":"Bạn biết nấu món Trung Quốc không?"}},{"stt":8,"hanzi":"写","pinyin":"xiě","hanviet":"Tả","pos":"Động từ","meaning":"Viết","comps":"写字 (viết chữ), 怎么写 (viết như thế nào)","example":{"zh":"你会写汉字吗？","py":"Nǐ huì xiě Hànzì ma?","vi":"Bạn biết viết chữ Hán không?"}},{"stt":9,"hanzi":"汉字","pinyin":"Hànzì","hanviet":"Hán tự","pos":"Danh từ","meaning":"Chữ Hán","comps":"写汉字 (viết chữ Hán), 读汉字 (đọc chữ Hán)","example":{"zh":"我不会写汉字。","py":"Wǒ bú huì xiě Hànzì.","vi":"Tôi không biết viết chữ Hán."}},{"stt":10,"hanzi":"字","pinyin":"zì","hanviet":"Tự","pos":"Danh từ","meaning":"Chữ","comps":"名字 (tên), 这个字 (chữ này)","example":{"zh":"这个字怎么读？","py":"Zhège zì zěnme dú?","vi":"Chữ này đọc như thế nào?"}},{"stt":11,"hanzi":"怎么","pinyin":"zěnme","hanviet":"Chẩm ma","pos":"Đại từ","meaning":"Như thế nào, sao","comps":"怎么做 (làm như thế nào), 怎么读 (đọc như thế nào)","example":{"zh":"你的汉语名字怎么写？","py":"Nǐ de Hànyǔ míngzi zěnme xiě?","vi":"Tên tiếng Trung của bạn viết thế nào?"}},{"stt":12,"hanzi":"读","pinyin":"dú","hanviet":"Độc","pos":"Động từ","meaning":"Đọc","comps":"读书 (đọc sách), 怎么读 (đọc thế nào)","example":{"zh":"这个字我会读，不会写。","py":"Zhège zì wǒ huì dú, bú huì xiě.","vi":"Chữ này tôi biết đọc, không biết viết."}}],"hanzi":[{"char":"会","pinyin":"huì","hanviet":"Hội","chars":["会"],"story":"Phía trên là chữ Nhân (人 - người) đội nón, phía dưới là chữ Vân (云 - mây). Người xưa cho rằng có thể hiểu được mây trời (thời tiết) là người có kỹ năng, sự hiểu biết."},{"char":"说","pinyin":"shuō","hanviet":"Thuyết","chars":["说"],"story":"Bên trái là bộ Ngôn (讠 - lời nói), bên phải là chữ Đoái (兑 - đổi chác, vui vẻ). Lời nói thốt ra để trao đổi ý kiến mang lại sự vui vẻ."},{"char":"妈妈","pinyin":"māma","hanviet":"Ma ma","chars":["妈","妈"],"story":"Chữ 妈 gồm bộ Nữ (女 - phụ nữ) chỉ ý nghĩa, và chữ Mã (马 - con ngựa) chỉ âm đọc. Mẹ là người phụ nữ vất vả như ngựa để nuôi con."},{"char":"菜","pinyin":"cài","hanviet":"Thái","chars":["菜"],"story":"Trên cùng là bộ Thảo (艹 - cỏ, cây cỏ), ở giữa là chữ Trảo (爫 - móng vuốt, bàn tay hái), dưới cùng là chữ Mộc (木 - cây). Tay hái cây cỏ để làm thức ăn (rau, món ăn)."},{"char":"很","pinyin":"hěn","hanviet":"Ngận","chars":["很"],"story":"Bên trái là bộ Xích (彳 - bước chân ngắn), bên phải là chữ Cấn (艮 - cứng rắn, quẻ Cấn). Bước đi một cách dứt khoát, mạnh mẽ thể hiện mức độ cao (Rất)."},{"char":"好吃","pinyin":"hǎochī","hanviet":"Hảo cật","chars":["好","吃"],"story":"好 (Hảo) là Tốt. 吃 (Cật) là Ăn (có bộ Khẩu 口 là cái miệng). Tốt để ăn thì có nghĩa là đồ ăn đó Ngon."},{"char":"做","pinyin":"zuò","hanviet":"Tác","chars":["做"],"story":"Bên trái là bộ Nhân đứng (亻), giữa là chữ Cổ (古 - xưa), phải là chữ Phác (攵 - đánh khẽ). Người thời xưa phải lao động bằng tay chân thì mới có ăn. Ở đây là hành động \"làm\"."},{"char":"写","pinyin":"xiě","hanviet":"Tả","chars":["写"],"story":"Bên trên là bộ Mịch (冖 - dải lụa trùm), bên dưới là một nét ngang gập và một nét ngang giống như chiếc bút. Trùm một tờ lụa lên bàn để dùng bút \"Viết\"."},{"char":"汉字","pinyin":"Hànzì","hanviet":"Hán tự","chars":["汉","字"],"story":"汉 (Hán) có bộ Thủy (氵) chỉ dòng sông Hán Thủy, nơi phát tích người Hán. 字 (Tự) có bộ Miên (宀 - mái nhà) và chữ Tử (子 - đứa trẻ), dưới mái nhà dạy trẻ học chữ. Chữ của người Hán là 汉字."},{"char":"字","pinyin":"zì","hanviet":"Tự","chars":["字"],"story":"Bao gồm bộ Miên (宀 - mái nhà) và chữ Tử (子 - con, đứa trẻ). Hình ảnh dưới mái nhà, đứa trẻ đang được dạy học \"chữ\"."},{"char":"怎么","pinyin":"zěnme","hanviet":"Chẩm ma","chars":["怎","么"],"story":"怎 (Chẩm) có chữ Tác (乍 - chợt) bên trên và bộ Tâm (心 - tim) bên dưới. Trái tim thình lình giật mình tự hỏi \"Thế nào? Sao lại thế?\"."},{"char":"读","pinyin":"dú","hanviet":"Độc","chars":["读"],"story":"Bên trái là bộ Ngôn (讠 - lời nói). Bên phải là chữ Mại (卖 - bán, âm đọc cổ gần giống Độc). Lời nói phát ra thành tiếng từ miệng là hành động \"Đọc\"."}],"grammar":[{"title":"Động từ năng nguyện \"会\" (huì)","formula":"Chủ ngữ + <span>(不)会</span> + Động từ + (Tân ngữ).","summary":"Động từ năng nguyện \"会\" được dùng trước động từ khác để diễn tả việc có được khả năng/kỹ năng nào đó thông qua quá trình học tập và rèn luyện. Dạng phủ định là \"不会\".","note":"<strong>Lưu ý:</strong> Khác với \"知道\" (zhīdào) là biết thông tin (biết nhà, biết tên), \"会\" luôn đi với một kỹ năng cần học như nói ngoại ngữ, nấu ăn, bơi lội, lái xe.","examples":[{"zh":"我会写汉字。","py":"Wǒ huì xiě Hànzì.","vi":"Tôi biết viết chữ Hán."},{"zh":"我不会做中国菜。","py":"Wǒ bú huì zuò Zhōngguó cài.","vi":"Tôi không biết nấu món ăn Trung Quốc."},{"zh":"你妈妈会说汉语吗？","py":"Nǐ māma huì shuō Hànyǔ ma?","vi":"Mẹ bạn có biết nói tiếng Trung Quốc không?"},{"zh":"大卫会做饭。","py":"Dàwèi huì zuò fàn.","vi":"David biết nấu ăn."},{"zh":"我的中国朋友会说英语。","py":"Wǒ de Zhōngguó péngyǒu huì shuō Yīngyǔ.","vi":"Bạn người Trung Quốc của tôi biết nói tiếng Anh."},{"zh":"他不会开车。","py":"Tā bú huì kāi chē.","vi":"Anh ấy không biết lái xe."},{"zh":"你们会做这个菜吗？","py":"Nǐmen huì zuò zhège cài ma?","vi":"Các bạn biết làm món này không?"},{"zh":"小明会游泳。","py":"Xiǎomíng huì yóuyǒng.","vi":"Tiểu Minh biết bơi."}]},{"title":"Câu có vị ngữ là Tính từ (với \"很\")","formula":"Chủ ngữ + <span>很 / 不</span> + Tính từ.","summary":"Tính từ được dùng để miêu tả tính chất, trạng thái của người hay sự vật. Trong câu khẳng định, nó thường đi cùng phó từ chỉ mức độ \"很\". Dạng phủ định không dùng \"很\" mà dùng \"不\".","note":"<strong>Lưu ý:</strong> Trong câu khẳng định \"汉语很难\", chữ \"很\" đóng vai trò liên kết ngữ pháp, đôi khi người Trung Quốc không dịch sát nghĩa là \"rất khó\" mà chỉ hiểu là \"tiếng Hán khó\". Không được nói \"汉语难\".","examples":[{"zh":"我很好。","py":"Wǒ hěn hǎo.","vi":"Tôi rất khoẻ / Tôi tốt."},{"zh":"我妈妈的汉语不好。","py":"Wǒ māma de Hànyǔ bù hǎo.","vi":"Tiếng Trung của mẹ tôi không tốt."},{"zh":"中国菜很好吃。","py":"Zhōngguó cài hěn hǎochī.","vi":"Món ăn Trung Quốc rất ngon."},{"zh":"这个菜不好吃。","py":"Zhège cài bù hǎochī.","vi":"Món này không ngon."},{"zh":"汉字很难。","py":"Hànzì hěn nán.","vi":"Chữ Hán rất khó."},{"zh":"那个苹果不大。","py":"Nàge píngguǒ bú dà.","vi":"Quả táo kia không to."},{"zh":"今天天气很好。","py":"Jīntiān tiānqì hěn hǎo.","vi":"Thời tiết hôm nay rất đẹp."},{"zh":"老师今天很高兴。","py":"Lǎoshī jīntiān hěn gāoxìng.","vi":"Hôm nay thầy giáo rất vui."}]},{"title":"Đại từ nghi vấn \"怎么\" (zěnme)","formula":"Chủ ngữ + <span>怎么</span> + Động từ + (Tân ngữ)？","summary":"Đại từ nghi vấn \"怎么\" (thế nào, làm sao, như thế nào) được dùng ngay trước động từ để hỏi về cách thức thực hiện của hành động đó.","note":"<strong>Lưu ý:</strong> Vị trí của \"怎么\" khác với tiếng Việt. Tiếng Việt nói động từ trước (Làm thế nào), tiếng Trung nói \"怎么\" trước (怎么做).","examples":[{"zh":"这个汉字怎么读？","py":"Zhège Hànzì zěnme dú?","vi":"Chữ Hán này đọc như thế nào?"},{"zh":"你的汉语名字怎么写？","py":"Nǐ de Hànyǔ míngzi zěnme xiě?","vi":"Tên tiếng Trung của bạn viết thế nào?"},{"zh":"这个菜怎么做？","py":"Zhège cài zěnme zuò?","vi":"Món này làm thế nào?"},{"zh":"你们怎么去北京？","py":"Nǐmen zěnme qù Běijīng?","vi":"Các bạn đi Bắc Kinh bằng cách nào?"},{"zh":"你怎么不高兴？","py":"Nǐ zěnme bù gāoxìng?","vi":"Sao bạn lại không vui?"},{"zh":"那个字怎么读？","py":"Nàge zì zěnme dú?","vi":"Chữ kia đọc sao?"},{"zh":"这个怎么卖？","py":"Zhège zěnme mài?","vi":"Cái này bán thế nào?"},{"zh":"你怎么去学校？","py":"Nǐ zěnme qù xuéxiào?","vi":"Bạn đến trường bằng cách nào? (đi xe gì)"}]}],"text":{"title":"课文 · Bài khoá","blocks":[{"titleZh":"在学校","titleVi":"Ở trường","icon":"🏫","lines":[{"speaker":"A","zh":"你会说汉语吗？","py":"Nǐ huì shuō Hànyǔ ma?","vi":"Em có biết nói tiếng Trung Quốc không?"},{"speaker":"B","zh":"我会说汉语。","py":"Wǒ huì shuō Hànyǔ.","vi":"Em có biết."},{"speaker":"A","zh":"你妈妈会说汉语吗？","py":"Nǐ māma huì shuō Hànyǔ ma?","vi":"Mẹ em biết nói tiếng Trung Quốc không?"},{"speaker":"B","zh":"她不会说。","py":"Tā bú huì shuō.","vi":"Mẹ em thì không."}]},{"titleZh":"在厨房","titleVi":"Trong nhà bếp","icon":"🍳","lines":[{"speaker":"A","zh":"中国菜好吃吗？","py":"Zhōngguó cài hǎochī ma?","vi":"Món ăn Trung Quốc có ngon không?"},{"speaker":"B","zh":"中国菜很好吃。","py":"Zhōngguó cài hěn hǎochī.","vi":"Rất ngon."},{"speaker":"A","zh":"你会做中国菜吗？","py":"Nǐ huì zuò Zhōngguó cài ma?","vi":"Anh có biết nấu món Trung Quốc không?"},{"speaker":"B","zh":"我不会做。","py":"Wǒ bú huì zuò.","vi":"Tôi không biết."}]},{"titleZh":"在图书馆","titleVi":"Ở thư viện","icon":"📚","lines":[{"speaker":"A","zh":"你会写汉字吗？","py":"Nǐ huì xiě Hànzì ma?","vi":"Anh có biết viết chữ Hán không?"},{"speaker":"B","zh":"我会写。","py":"Wǒ huì xiě.","vi":"Tôi có biết."},{"speaker":"A","zh":"这个字怎么写？","py":"Zhège zì zěnme xiě?","vi":"Vậy chữ này anh viết thế nào?"},{"speaker":"B","zh":"对不起，这个字我会读，不会写。","py":"Duìbuqǐ, zhège zì wǒ huì dú, bú huì xiě.","vi":"Xin lỗi, chữ này tôi biết đọc chứ không biết viết."}]}]},"extra":[{"label":"Mục tiêu","html":"<h2 class=\"section-title\">Mục tiêu bài học</h2>\n  <p class=\"section-sub\">Nắm vững cách diễn đạt khả năng và hỏi về cách thức thực hiện hành động.</p>\n  <div class=\"goal-grid\">\n    <div class=\"goal-item\">\n      <div class=\"num\">01</div>\n      <h4>Giao tiếp</h4>\n      <ul>\n        <li>Nói về khả năng/kỹ năng của bản thân (ngôn ngữ, nấu ăn...)</li>\n        <li>Hỏi cách làm một việc gì đó</li>\n        <li>Khen ngợi thức ăn ngon</li>\n      </ul>\n    </div>\n    <div class=\"goal-item\">\n      <div class=\"num\">02</div>\n      <h4>Từ vựng</h4>\n      <ul>\n        <li>Chủ đề Ngôn ngữ: <b>汉语, 字</b></li>\n        <li>Chủ đề Hành động: <b>说, 写, 读, 做</b></li>\n        <li>Chủ đề Đánh giá: <b>很, 好吃</b></li>\n      </ul>\n    </div>\n    <div class=\"goal-item\">\n      <div class=\"num\">03</div>\n      <h4>Ngữ pháp</h4>\n      <ul>\n        <li>Động từ <b>\"会\"</b> chỉ kỹ năng</li>\n        <li>Câu vị ngữ tính từ với <b>\"很\"</b></li>\n        <li>Đại từ nghi vấn <b>\"怎么\"</b></li>\n      </ul>\n    </div>\n  </div>"},{"label":"Chuyên đề Mở rộng","html":"<h2 class=\"section-title\">Ngôn ngữ & Kết cấu Chữ Hán</h2>\n  <p class=\"section-sub\">Mở rộng vốn từ vựng về các ngoại ngữ phổ biến và tìm hiểu kết cấu cơ bản của chữ Hán.</p>\n\n  <!-- Mẫu Card Cơ Bản -->\n  <div class=\"card\">\n    <h3>1. Từ vựng mở rộng: Các ngôn ngữ</h3>\n    <p>Ngoài 汉语 (Tiếng Hán), dưới đây là một số ngôn ngữ phổ biến trên thế giới. Điểm chung là chúng đều có đuôi <b>\"语\" (yǔ - ngữ)</b>.</p>\n    \n    <div class=\"formula-box\" style=\"background: linear-gradient(135deg, #3A2020 0%, #5C3A34 100%);\">\n      <div class=\"formula\" style=\"font-size: 1.3rem; line-height: 1.8;\">\n        英语 (Yīngyǔ - Tiếng Anh)<br>\n        法语 (Fǎyǔ - Tiếng Pháp)<br>\n        日语 (Rìyǔ - Tiếng Nhật)\n      </div>\n    </div>\n    \n    <div class=\"tip-card\">\n      <h5>💡 Ứng dụng</h5>\n      <p>Thử trả lời câu hỏi: <b>你会说英语吗？</b> (Bạn biết nói tiếng Anh không?)<br>\n        ➔ 我会说英语 / 我不会说英语。\n      </p>\n    </div>\n  </div>\n\n  <div class=\"card\">\n    <h3>2. Kết cấu chữ Hán: Độc thể và Hợp thể</h3>\n    <p>Về cơ bản, chữ Hán có hai loại kết cấu chính. Việc hiểu rõ điều này giúp bạn bóc tách và ghi nhớ chữ Hán dễ dàng hơn.</p>\n    \n    <ul style=\"margin-top: 14px; margin-bottom: 24px;\">\n      <li style=\"margin-bottom: 16px;\">\n        <b>Chữ Độc thể (独体结构):</b> Là chữ Hán chỉ có một bộ phận duy nhất, không thể tách rời thêm (nếu tách sẽ mất ý nghĩa).<br>\n        Ví dụ: \n        <span class=\"zh\" style=\"color:var(--burgundy); font-weight:600; font-size: 1.2rem;\">人</span> (rén - người), \n        <span class=\"zh\" style=\"color:var(--burgundy); font-weight:600; font-size: 1.2rem;\">我</span> (wǒ - tôi), \n        <span class=\"zh\" style=\"color:var(--burgundy); font-weight:600; font-size: 1.2rem;\">中</span> (zhōng - giữa).\n      </li>\n      <li>\n        <b>Chữ Hợp thể (合体结构):</b> Là chữ Hán được tạo thành bởi hai hoặc nhiều bộ phận (thường là các bộ thủ ghép lại với nhau).<br>\n        Ví dụ: \n        <span class=\"zh\" style=\"color:var(--burgundy); font-weight:600; font-size: 1.2rem;\">你</span> (nǐ) = 亻 + 尔.<br>\n        <span class=\"zh\" style=\"color:var(--burgundy); font-weight:600; font-size: 1.2rem;\">做</span> (zuò) = 亻 + 古 + 攵.\n      </li>\n    </ul>\n\n    <div class=\"tip-card\">\n      <h5>💡 Mẹo lưu ý</h5>\n      <p>Hầu hết các chữ Độc thể sau này sẽ trở thành <b>Bộ thủ</b> để ghép nên các chữ Hợp thể phức tạp hơn. Do đó, hãy học thật kỹ chữ Độc thể (như 口, 女, 人, 日, 月...).</p>\n    </div>\n  </div>"},{"label":"Lỗi sai","html":"<h2 class=\"section-title\">Lỗi sai thường gặp</h2>\n  <p class=\"section-sub\">Những lỗi người Việt hay mắc phải khi học bài này.</p>\n  <div class=\"error-grid\">\n    <!-- Lỗi 1 -->\n    <div class=\"error-box\">\n      <div class=\"err-head wrong\">Lỗi 1 · Thiếu \"很\" trong câu miêu tả</div>\n      <div class=\"err-body\">\n        <p style=\"margin-bottom:12px\">Trong tiếng Việt, chúng ta thường nói trực tiếp \"Tiếng Trung khó\", \"Món ăn ngon\". Học viên bê nguyên xi sang sẽ nói \"汉语难\", \"菜好吃\". Trong tiếng Trung, khi Tính từ làm vị ngữ khẳng định, bắt buộc phải có phó từ chỉ mức độ (thường là <b>很</b>) đi kèm, dù không mang nghĩa \"rất\".</p>\n        <p class=\"strike zh\">汉语难。</p>\n        <p class=\"strike zh\" style=\"margin-top:4px;\">中国菜好吃。</p>\n      </div>\n      <div class=\"err-head correct\">Cách sửa</div>\n      <div class=\"err-body\">\n        <p class=\"correct-text zh\">汉语很难。</p>\n        <p class=\"correct-text zh\" style=\"margin-top:4px;\">中国菜很好吃。</p>\n        <p style=\"font-size:.88rem;color:var(--muted);margin-top:6px\">Luôn nhớ công thức: Chủ ngữ + 很 + Tính từ.</p>\n      </div>\n    </div>\n    <!-- Lỗi 2 -->\n    <div class=\"error-box\">\n      <div class=\"err-head wrong\">Lỗi 2 · Đặt sai vị trí của \"怎么\"</div>\n      <div class=\"err-body\">\n        <p style=\"margin-bottom:12px\">Tiếng Việt nói \"Viết (đgt) thế nào\", \"Làm (đgt) thế nào\". Học viên hay dịch word-by-word (từng chữ một) thành \"写怎么\", \"做怎么\". Đây là lỗi sai trật tự từ cực kỳ phổ biến.</p>\n        <p class=\"strike zh\">这个字写怎么？</p>\n        <p class=\"strike zh\" style=\"margin-top:4px;\">中国菜做怎么？</p>\n      </div>\n      <div class=\"err-head correct\">Cách sửa</div>\n      <div class=\"err-body\">\n        <p class=\"correct-text zh\">这个字怎么写？</p>\n        <p class=\"correct-text zh\" style=\"margin-top:4px;\">中国菜怎么做？</p>\n        <p style=\"font-size:.88rem;color:var(--muted);margin-top:6px\">Trong tiếng Trung, \"怎么\" (như thế nào) phải đứng <b>TRƯỚC</b> Động từ.</p>\n      </div>\n    </div>\n    <!-- Lỗi 3 -->\n    <div class=\"error-box\">\n      <div class=\"err-head wrong\">Lỗi 3 · Nhầm lẫn giữa \"会\" và \"知道\"</div>\n      <div class=\"err-body\">\n        <p style=\"margin-bottom:12px\">Tiếng Việt đều dịch là \"Biết\" (Tôi biết bơi, Tôi biết địa chỉ của anh ấy). Tuy nhiên, tiếng Trung phân biệt rõ. \"会\" (huì) dùng cho kỹ năng phải HỌC mới biết (ngôn ngữ, bơi lội, lái xe...). \"知道\" (zhīdào) dùng cho việc biết thông tin, tin tức.</p>\n        <p class=\"strike zh\">我知道说汉语。</p>\n        <p class=\"strike zh\" style=\"margin-top:4px;\">我会他的名字。</p>\n      </div>\n      <div class=\"err-head correct\">Cách sửa</div>\n      <div class=\"err-body\">\n        <p class=\"correct-text zh\">我会说汉语。</p>\n        <p class=\"correct-text zh\" style=\"margin-top:4px;\">我知道他的名字。</p>\n        <p style=\"font-size:.88rem;color:var(--muted);margin-top:6px\">Nói ngoại ngữ là kỹ năng phải học ➔ Dùng 会. Tên người là thông tin ➔ Dùng 知道.</p>\n      </div>\n    </div>\n  </div>"},{"label":"Tổng hợp","html":"<h2 class=\"section-title\">Tổng hợp kiến thức</h2>\n  <p class=\"section-sub\">Sơ đồ cốt lõi giúp tóm tắt toàn bộ bài học.</p>\n\n  <div class=\"syn-grid\">\n    <!-- Khối 1: Cấu trúc -->\n    <div class=\"syn-card theme-burgundy\">\n      <div class=\"syn-icon\">🔍</div>\n      <h3>Biểu đạt khả năng (Kỹ năng)</h3>\n      <table class=\"syn-table\">\n        <tr><th>Loại</th><th>Cấu trúc</th></tr>\n        <tr><td>Khẳng định</td><td>Chủ ngữ + 会 + Động từ (Kỹ năng).</td></tr>\n        <tr><td>Phủ định</td><td>Chủ ngữ + 不会 + Động từ (Kỹ năng).</td></tr>\n      </table>\n      <div class=\"syn-mnemonic\">Học được mới biết thì dùng <strong>会</strong>. Dùng \"不会\" thay vì \"不怎么\".</div>\n    </div>\n\n    <!-- Khối 2: Sơ đồ chuỗi (Flow) -->\n    <div class=\"syn-card theme-gold\">\n      <div class=\"syn-icon\">📅</div>\n      <h3>Thứ tự hỏi cách thức</h3>\n      <div class=\"syn-flow\">\n        <div class=\"step\"><span class=\"syn-keyhz\">这个字</span><br><small>Chữ này</small></div>\n        <span class=\"arrow\">→</span>\n        <div class=\"step\"><span class=\"syn-keyhz\">怎么</span><br><small>như thế nào</small></div>\n        <span class=\"arrow\">→</span>\n        <div class=\"step\"><span class=\"syn-keyhz\">写？</span><br><small>viết?</small></div>\n      </div>\n      <div class=\"syn-mnemonic\">Luôn nhớ: <strong>怎么 + Động từ</strong> (Làm cái gì đó như thế nào).</div>\n    </div>\n\n    <!-- Khối 3: Bảng 5 Câu Thần Chú (Bắt buộc giữ form này ở cuối Tab 9) -->\n    <div class=\"syn-card theme-gold\" style=\"grid-column: 1 / -1;\">\n      <div class=\"syn-icon\">⚡</div>\n      <h3>Câu thần chú 5 mẫu</h3>\n      <table class=\"syn-table\">\n        <tr><th>Mẫu</th><th>Tình huống</th></tr>\n        <tr><td><span class=\"syn-keyhz\">我会说汉语。</span></td><td>Giới thiệu khả năng (Mình biết nói tiếng Trung).</td></tr>\n        <tr><td><span class=\"syn-keyhz\">中国菜很好吃。</span></td><td>Đưa ra lời nhận xét, khen ngợi (Món ăn TQ rất ngon).</td></tr>\n        <tr><td><span class=\"syn-keyhz\">你会做中国菜吗？</span></td><td>Hỏi xem ai đó có biết làm việc gì không (Bạn biết nấu món TQ không?).</td></tr>\n        <tr><td><span class=\"syn-keyhz\">这个字怎么写？</span></td><td>Hỏi cách thực hiện một hành động (Chữ này viết như thế nào?).</td></tr>\n        <tr><td><span class=\"syn-keyhz\">这个字我会读，不会写。</span></td><td>Nói rõ mức độ của kỹ năng (Chữ này tôi biết đọc, không biết viết).</td></tr>\n      </table>\n      <div class=\"syn-mnemonic\"><strong>Thuộc 5 mẫu này là pass Bài 6.</strong></div>\n    </div>\n  </div>"}],"cssId":"c7fcf9643"},{"id":"k1v2-b07","courseId":"k1v2","order":7,"title":"Hôm nay là ngày mấy?","titleZh":"今天几号？","vocab":[{"stt":1,"hanzi":"请","pinyin":"qǐng","hanviet":"Thỉnh","pos":"Động từ","meaning":"(lịch sự) Mời, xin","comps":"请问 (xin hỏi), 请坐 (mời ngồi)","example":{"zh":"请问，他叫什么名字？","py":"Qǐngwèn, tā jiào shénme míngzi?","vi":"Xin hỏi, anh ấy tên là gì?"}},{"stt":2,"hanzi":"问","pinyin":"wèn","hanviet":"Vấn","pos":"Động từ","meaning":"Hỏi","comps":"请问 (xin hỏi), 问题 (câu hỏi/vấn đề)","example":{"zh":"老师，我想问一个问题。","py":"Lǎoshī, wǒ xiǎng wèn yí ge wèntí.","vi":"Thưa thầy, em muốn hỏi một câu hỏi."}},{"stt":3,"hanzi":"今天","pinyin":"jīntiān","hanviet":"Kim thiên","pos":"Danh từ","meaning":"Hôm nay","comps":"今天几号 (hôm nay ngày mấy), 今天的菜 (món ăn hôm nay)","example":{"zh":"今天天气很好。","py":"Jīntiān tiānqì hěn hǎo.","vi":"Thời tiết hôm nay rất đẹp."}},{"stt":4,"hanzi":"号","pinyin":"hào","hanviet":"Hiệu","pos":"Danh/Lượng từ","meaning":"Ngày (trong văn nói), số hiệu","comps":"几号 (ngày mấy/số mấy), 三十一号 (ngày 31)","example":{"zh":"今天十月一号。","py":"Jīntiān shí yuè yī hào.","vi":"Hôm nay ngày 1 tháng 10."}},{"stt":5,"hanzi":"月","pinyin":"yuè","hanviet":"Nguyệt","pos":"Danh từ","meaning":"Tháng, mặt trăng","comps":"几个月 (mấy tháng), 九月 (tháng 9)","example":{"zh":"他是八月出生的。","py":"Tā shì bā yuè chūshēng de.","vi":"Anh ấy sinh vào tháng tám."}},{"stt":6,"hanzi":"星期","pinyin":"xīngqī","hanviet":"Tinh kỳ","pos":"Danh từ","meaning":"Tuần, thứ","comps":"星期几 (thứ mấy), 星期三 (thứ tư)","example":{"zh":"今天星期几？","py":"Jīntiān xīngqī jǐ?","vi":"Hôm nay là thứ mấy?"}},{"stt":7,"hanzi":"昨天","pinyin":"zuótiān","hanviet":"Tạc thiên","pos":"Danh từ","meaning":"Hôm qua","comps":"昨天下午 (chiều hôm qua), 昨天的天气 (thời tiết hôm qua)","example":{"zh":"昨天你去哪儿了？","py":"Zuótiān nǐ qù nǎr le?","vi":"Hôm qua bạn đi đâu rồi?"}},{"stt":8,"hanzi":"明天","pinyin":"míngtiān","hanviet":"Minh thiên","pos":"Danh từ","meaning":"Ngày mai","comps":"明天见 (ngày mai gặp), 明天的课 (bài học ngày mai)","example":{"zh":"明天我去学校。","py":"Míngtiān wǒ qù xuéxiào.","vi":"Ngày mai tôi đi đến trường."}},{"stt":9,"hanzi":"去","pinyin":"qù","hanviet":"Khứ","pos":"Động từ","meaning":"Đi (rời xa chỗ hiện tại)","comps":"去学校 (đi đến trường), 去年 (năm ngoái/năm đã đi qua)","example":{"zh":"我下午去买东西。","py":"Wǒ xiàwǔ qù mǎi dōngxi.","vi":"Buổi chiều tôi đi mua đồ."}},{"stt":10,"hanzi":"学校","pinyin":"xuéxiào","hanviet":"Học hiệu","pos":"Danh từ","meaning":"Trường học","comps":"去学校 (đến trường), 汉语学校 (trường tiếng Trung)","example":{"zh":"他的学校很大。","py":"Tā de xuéxiào hěn dà.","vi":"Trường học của anh ấy rất lớn."}},{"stt":11,"hanzi":"看","pinyin":"kàn","hanviet":"Khán","pos":"Động từ","meaning":"Nhìn, xem, đọc","comps":"看书 (đọc sách), 看看 (xem thử)","example":{"zh":"你在看什么？","py":"Nǐ zài kàn shénme?","vi":"Bạn đang xem gì vậy?"}},{"stt":12,"hanzi":"书","pinyin":"shū","hanviet":"Thư","pos":"Danh từ","meaning":"Sách","comps":"看书 (đọc sách), 买书 (mua sách)","example":{"zh":"这是一本好书。","py":"Zhè shì yì běn hǎo shū.","vi":"Đây là một cuốn sách hay."}}],"hanzi":[{"char":"请","pinyin":"qǐng","hanviet":"Thỉnh","chars":["请"],"story":"Bên trái là bộ Ngôn (讠 - lời nói), bên phải là chữ Thanh (青 - màu xanh/thanh tú). Dùng lời nói lịch sự, nhẹ nhàng như màu xanh thanh tao để mời người khác."},{"char":"问","pinyin":"wèn","hanviet":"Vấn","chars":["问"],"story":"Bên ngoài là bộ Môn (门 - cánh cửa), bên trong là bộ Khẩu (口 - cái miệng). Đến trước cửa nhà người khác, hé miệng ra gọi để \"hỏi\" thăm."},{"char":"今天","pinyin":"jīntiān","hanviet":"Kim thiên","chars":["今","天"],"story":"Kim (今 - hiện tại) ghép với Thiên (天 - bầu trời/ngày). Ngày hiện tại chính là \"Hôm nay\". Chữ Thiên vẽ hình một người dang tay, bên trên là đường nằm ngang (bầu trời ở trên đầu)."},{"char":"号","pinyin":"hào","hanviet":"Hiệu","chars":["号"],"story":"Bộ Khẩu (口) ở trên và nét ngang gập bên dưới giống cái còi. Dùng miệng thổi còi để phát ra âm thanh báo \"hiệu\" cho một \"ngày\" mới."},{"char":"月","pinyin":"yuè","hanviet":"Nguyệt","chars":["月"],"story":"Chữ tượng hình, vẽ hình mặt trăng khuyết. Mặt trăng xoay trọn một vòng khuyết/tròn tượng trưng cho một \"Tháng\"."},{"char":"星期","pinyin":"xīngqī","hanviet":"Tinh kỳ","chars":["星","期"],"story":"Tinh (星 - ngôi sao) có chữ Nhật (日 - mặt trời) ở trên và Sinh (生) ở dưới. Kỳ (期 - thời kỳ) có bộ Nguyệt (月 - mặt trăng). Sự vận động của mặt trời, mặt trăng và các vì sao được người xưa dùng để tính \"Tuần/Thứ\"."},{"char":"昨天","pinyin":"zuótiān","hanviet":"Tạc thiên","chars":["昨","天"],"story":"Chữ Tạc (昨) gồm bộ Nhật (日 - mặt trời) và chữ Trách (乍 - vừa mới). Chữ Trách chỉ quá khứ gần. Ngày vừa mới đi qua mặt trời lặn chính là \"Hôm qua\"."},{"char":"明天","pinyin":"míngtiān","hanviet":"Minh thiên","chars":["明","天"],"story":"Chữ Minh (明 - sáng sủa) ghép bởi Nhật (日 - mặt trời) và Nguyệt (月 - mặt trăng). Mặt trăng lặn, mặt trời ló rạng mang lại ánh sáng cho một \"Ngày mai\"."},{"char":"去","pinyin":"qù","hanviet":"Khứ","chars":["去"],"story":"Gồm bộ Thổ (土 - đất) ở trên và chữ Khư (厶 - riêng tư/giấu) ở dưới. Hình ảnh một người bước đi trên mặt đất, rời xa nơi mình đang đứng để \"đi\" đến một nơi khác."},{"char":"学校","pinyin":"xuéxiào","hanviet":"Học hiệu","chars":["学","校"],"story":"Chữ Học (学 - học) có đứa trẻ (子) đội nón đang ngồi học. Chữ Hiệu (校 - trường) có bộ Mộc (木 - cây gỗ) và Giao (交 - giao lưu). Ngôi nhà bằng gỗ nơi học sinh giao lưu kiến thức là \"trường học\"."},{"char":"看","pinyin":"kàn","hanviet":"Khán","chars":["看"],"story":"Phía trên là bộ Thủ (手 - bàn tay, bị biến thể chéo), phía dưới là bộ Mục (目 - con mắt). Hành động đưa tay che lên mắt để \"nhìn\" hoặc \"xem\" cho rõ."},{"char":"书","pinyin":"shū","hanviet":"Thư","chars":["书"],"story":"Ban đầu chữ 书 chỉ hành động chấm bút lông vào trong nghiên mực để viết, nét sổ ở giữa tượng trưng cho thân cây bút. Dần dần nghĩa mở rộng thành \"sách, thư từ\"."}],"grammar":[{"title":"Cách nói ngày, tháng, năm","formula":"<span>年 + 月 + 号/日 + 星期</span>","summary":"Trong tiếng Trung, thứ tự thời gian luôn đi từ đơn vị lớn đến đơn vị nhỏ: Năm (年) ➔ Tháng (月) ➔ Ngày (号/日) ➔ Thứ (星期). Trong văn nói, người ta thường dùng \"号\" thay cho \"日\".","note":"<strong>Lưu ý:</strong> Chữ số của Năm đọc tách từng số một (vd: 2023 ➔ 二零二三). Khi nói về ngày tháng, không cần dùng lượng từ.","examples":[{"zh":"九月一号。","py":"Jiǔ yuè yī hào.","vi":"Ngày 1 tháng 9."},{"zh":"九月二号，星期四。","py":"Jiǔ yuè èr hào, xīngqī sì.","vi":"Thứ Năm, ngày 2 tháng 9."},{"zh":"八月三十一号，星期二。","py":"Bā yuè sānshíyī hào, xīngqī èr.","vi":"Thứ Ba, ngày 31 tháng 8."},{"zh":"二零零八年八月八号。","py":"Èr líng líng bā nián bā yuè bā hào.","vi":"Ngày 8 tháng 8 năm 2008."},{"zh":"今天几月几号？","py":"Jīntiān jǐ yuè jǐ hào?","vi":"Hôm nay là ngày mấy tháng mấy?"},{"zh":"你的生日是几月几号？","py":"Nǐ de shēngrì shì jǐ yuè jǐ hào?","vi":"Sinh nhật của bạn là ngày mấy tháng mấy?"},{"zh":"明天星期几？","py":"Míngtiān xīngqī jǐ?","vi":"Ngày mai là thứ mấy?"},{"zh":"十月三十号星期天。","py":"Shí yuè sānshí hào xīngqī tiān.","vi":"Chủ Nhật, ngày 30 tháng 10."}]},{"title":"Câu có vị ngữ là Danh từ","formula":"Chủ ngữ + <span>Danh từ (Thời gian/Tuổi...)</span>","summary":"Là kiểu câu mà phần vị ngữ (tả về chủ ngữ) là một danh từ hoặc cụm danh từ. Thường dùng để chỉ thời gian, tuổi tác, quê quán hoặc giá cả. Trong câu khẳng định, không cần dùng động từ \"是\" (là).","note":"<strong>Lưu ý:</strong> Mặc dù tiếng Việt dịch có chữ \"là\" (Hôm nay LÀ thứ ba), nhưng tiếng Trung thì nói trực tiếp \"今天星期二\". Chỉ khi PHỦ ĐỊNH mới dùng \"不是\" (今天不是星期二).","examples":[{"zh":"今天九月一号。","py":"Jīntiān jiǔ yuè yī hào.","vi":"Hôm nay là ngày 1 tháng 9."},{"zh":"明天星期三。","py":"Míngtiān xīngqī sān.","vi":"Ngày mai là thứ Tư."},{"zh":"昨天星期二。","py":"Zuótiān xīngqī èr.","vi":"Hôm qua là thứ Ba."},{"zh":"我的老师三十三岁。","py":"Wǒ de lǎoshī sānshísān suì.","vi":"Giáo viên của tôi 33 tuổi."},{"zh":"我二十岁。","py":"Wǒ èrshí suì.","vi":"Tôi 20 tuổi."},{"zh":"他不是北京人。","py":"Tā bú shì Běijīng rén.","vi":"Anh ấy không phải người Bắc Kinh."},{"zh":"今天不是星期六。","py":"Jīntiān bú shì xīngqī liù.","vi":"Hôm nay không phải thứ Bảy."},{"zh":"明天十月一号。","py":"Míngtiān shí yuè yī hào.","vi":"Ngày mai là mùng 1 tháng 10."}]},{"title":"Câu liên động từ (去 + Nơi chốn + Làm gì)","formula":"Chủ ngữ + <span>去</span> + Địa điểm + <span>Động từ (Hành động)</span>","summary":"Câu liên động từ là câu có hai hoặc nhiều động từ. Trong đó, động từ thứ hai chỉ mục đích của động từ thứ nhất. Thường dùng nhất với chữ \"去\" (đi) để diễn tả việc di chuyển đến đâu đó để làm gì.","note":"<strong>Lưu ý:</strong> Có thể lược bỏ địa điểm nếu bối cảnh đã rõ ràng (vd: 我去看书 - Tôi đi đọc sách).","examples":[{"zh":"我去学校看书。","py":"Wǒ qù xuéxiào kàn shū.","vi":"Tôi đi đến trường đọc sách."},{"zh":"我们去饭馆吃中国菜。","py":"Wǒmen qù fànguǎn chī Zhōngguó cài.","vi":"Chúng tôi đi nhà hàng ăn đồ Trung Quốc."},{"zh":"你去学校做什么？","py":"Nǐ qù xuéxiào zuò shénme?","vi":"Bạn đi đến trường làm gì?"},{"zh":"明天我去中国。","py":"Míngtiān wǒ qù Zhōngguó.","vi":"Ngày mai tôi đi Trung Quốc."},{"zh":"他去中国学习汉语。","py":"Tā qù Zhōngguó xuéxí Hànyǔ.","vi":"Anh ấy đi Trung Quốc học tiếng Hán."},{"zh":"李老师去学校写字。","py":"Lǐ lǎoshī qù xuéxiào xiě zì.","vi":"Cô Lý đi đến trường viết chữ."},{"zh":"我去买书。","py":"Wǒ qù mǎi shū.","vi":"Tôi đi mua sách."},{"zh":"妈妈去超市买东西。","py":"Māma qù chāoshì mǎi dōngxi.","vi":"Mẹ đi siêu thị mua đồ."}]}],"text":{"title":"课文 · Bài khoá","blocks":[{"titleZh":"在银行","titleVi":"Ở ngân hàng","icon":"🏦","lines":[{"speaker":"A","zh":"请问，今天几号？","py":"Qǐngwèn, jīntiān jǐ hào?","vi":"Xin hỏi hôm nay là ngày mấy?"},{"speaker":"B","zh":"今天九月一号。","py":"Jīntiān jiǔ yuè yī hào.","vi":"Ngày 1 tháng 9."},{"speaker":"A","zh":"今天星期几？","py":"Jīntiān xīngqī jǐ?","vi":"Hôm nay là thứ mấy?"},{"speaker":"B","zh":"星期三。","py":"Xīngqī sān.","vi":"Thứ tư."}]},{"titleZh":"看日历","titleVi":"Xem lịch","icon":"📅","lines":[{"speaker":"A","zh":"昨天是几月几号？","py":"Zuótiān shì jǐ yuè jǐ hào?","vi":"Hôm qua là ngày mấy tháng mấy?"},{"speaker":"B","zh":"昨天是八月三十一号，星期二。","py":"Zuótiān shì bā yuè sānshíyī hào, xīngqī èr.","vi":"Hôm qua là thứ ba, ngày 31 tháng 8."},{"speaker":"A","zh":"明天呢？","py":"Míngtiān ne?","vi":"Còn ngày mai?"},{"speaker":"B","zh":"明天是九月二号，星期四。","py":"Míngtiān shì jiǔ yuè èr hào, xīngqī sì.","vi":"Ngày mai là thứ năm, ngày 2 tháng 9."}]},{"titleZh":"在咖啡馆儿","titleVi":"Ở quán cà phê","icon":"☕","lines":[{"speaker":"A","zh":"明天星期六，你去学校吗？","py":"Míngtiān xīngqī liù, nǐ qù xuéxiào ma?","vi":"Ngày mai là thứ bảy, bạn có đến trường không?"},{"speaker":"B","zh":"我去学校。","py":"Wǒ qù xuéxiào.","vi":"Có, tôi đến trường."},{"speaker":"A","zh":"你去学校做什么？","py":"Nǐ qù xuéxiào zuò shénme?","vi":"Bạn đến trường để làm gì?"},{"speaker":"B","zh":"我去学校看书。","py":"Wǒ qù xuéxiào kàn shū.","vi":"Để đọc sách."}]}]},"extra":[{"label":"Mục tiêu","html":"<h2 class=\"section-title\">Mục tiêu bài học</h2>\n  <p class=\"section-sub\">Hiểu và vận dụng cách nói thời gian, ngày tháng để hỏi đáp lịch trình hàng ngày.</p>\n  <div class=\"goal-grid\">\n    <div class=\"goal-item\">\n      <div class=\"num\">01</div>\n      <h4>Giao tiếp</h4>\n      <ul>\n        <li>Hỏi đáp về thứ, ngày, tháng.</li>\n        <li>Hỏi đáp về thời gian: Hôm qua, hôm nay, ngày mai.</li>\n        <li>Nói về lịch trình: Đi đâu? Làm gì?</li>\n      </ul>\n    </div>\n    <div class=\"goal-item\">\n      <div class=\"num\">02</div>\n      <h4>Từ vựng</h4>\n      <ul>\n        <li>Chủ đề Ngày/Tháng: <b>号, 月, 星期</b></li>\n        <li>Chủ đề Thời gian: <b>昨天, 今天, 明天</b></li>\n        <li>Chủ đề Hành động: <b>请问, 去, 看</b></li>\n      </ul>\n    </div>\n    <div class=\"goal-item\">\n      <div class=\"num\">03</div>\n      <h4>Ngữ pháp</h4>\n      <ul>\n        <li>Cách diễn tả ngày tháng (Từ lớn đến nhỏ).</li>\n        <li>Câu có vị ngữ là danh từ (Nói thời gian).</li>\n        <li>Câu liên động từ (去 + Nơi chốn + Làm gì).</li>\n      </ul>\n    </div>\n  </div>"},{"label":"Chuyên đề Mở rộng","html":"<h2 class=\"section-title\">Văn hóa thời gian và lịch Trung Quốc</h2>\n  <p class=\"section-sub\">Khám phá tư duy về thời gian của người Trung Quốc, cách đếm các thứ trong tuần và gọi tên các năm.</p>\n\n  <!-- Mẫu Card Cơ Bản -->\n  <div class=\"card\">\n    <h3>1. Tư duy \"Từ lớn đến nhỏ\"</h3>\n    <p>Khác với tiếng Việt (Ngày ➔ Tháng ➔ Năm), người Trung Quốc luôn xếp đơn vị thời gian theo tư duy tổng thể trước, chi tiết sau. Họ sẽ nói <b>Năm ➔ Tháng ➔ Ngày/Thứ</b>.</p>\n    \n    <div class=\"formula-box\">\n      <div class=\"formula-label\">Thứ tự thời gian chuẩn</div>\n      <div class=\"formula\">年 (Năm) + <span class=\"pop gold\">月 (Tháng)</span> + 号/日 (Ngày) + <span class=\"pop gold\">星期 (Thứ)</span></div>\n    </div>\n    \n    <div class=\"tip-card\">\n      <h5>💡 Ví dụ ứng dụng</h5>\n      <p>Hôm nay là Thứ Tư, ngày 1 tháng 9 năm 2023.<br>\n      ➔ <span class=\"zh\">2023年9月1号，星期三。</span></p>\n    </div>\n  </div>\n\n  <div class=\"card\">\n    <h3>2. \"Chủ Nhật\" không phải là \"Thứ Bảy\" hay \"Thứ Tám\"</h3>\n    <p>Trong tiếng Trung, các ngày trong tuần được đếm từ 星期一 (Thứ Hai) đến 星期六 (Thứ Bảy) theo số thứ tự từ 1 đến 6. Bạn cứ lấy số của tiếng Việt trừ đi 1 là ra tiếng Trung.</p>\n    <p>Tuy nhiên, <b>Chủ Nhật</b> không đếm bằng số (không có 星期七), mà dùng chữ <b>日 (rì - mặt trời)</b> hoặc <b>天 (tiān - bầu trời)</b>.</p>\n    \n    <ul style=\"margin-top: 14px; margin-bottom: 24px;\">\n      <li style=\"margin-bottom: 12px;\"><b>Thứ Hai:</b> 星期一 (xīngqī yī)</li>\n      <li style=\"margin-bottom: 12px;\"><b>Thứ Bảy:</b> 星期六 (xīngqī liù)</li>\n      <li><b>Chủ Nhật:</b> <span class=\"zh\" style=\"color:var(--burgundy); font-weight:600;\">星期日 (xīngqī rì)</span> hoặc <span class=\"zh\" style=\"color:var(--burgundy); font-weight:600;\">星期天 (xīngqī tiān)</span>. <i>Trong văn nói thường chuộng 星期天 hơn.</i></li>\n    </ul>\n\n    <div class=\"tip-card\">\n      <h5>💡 Đọc số năm</h5>\n      <p>Không giống đọc số thông thường (hai ngàn không trăm hai mươi ba), người Trung Quốc đọc năm bằng cách <b>đọc từng con số một</b>.<br>\n      Năm 2023 ➔ <span class=\"zh\">二零二三年</span> (èr líng èr sān nián).</p>\n    </div>\n  </div>"},{"label":"Lỗi sai","html":"<h2 class=\"section-title\">Lỗi sai thường gặp</h2>\n  <p class=\"section-sub\">Những lỗi người Việt hay mắc phải khi nói về ngày tháng và đi lại.</p>\n  <div class=\"error-grid\">\n    <!-- Lỗi 1 -->\n    <div class=\"error-box\">\n      <div class=\"err-head wrong\">Lỗi 1 · Xếp ngược thứ tự thời gian</div>\n      <div class=\"err-body\">\n        <p style=\"margin-bottom:12px\">Người Việt quen nói \"ngày 1 tháng 9\", \"tháng 9 năm 2023\". Nếu dịch từng chữ sang tiếng Trung sẽ bị sai trật tự từ cơ bản.</p>\n        <p class=\"strike zh\">一号九月</p>\n        <p class=\"strike zh\" style=\"margin-top:4px;\">九月二零二三年</p>\n      </div>\n      <div class=\"err-head correct\">Cách sửa</div>\n      <div class=\"err-body\">\n        <p class=\"correct-text zh\">九月一号 (Tháng 9 ngày 1)</p>\n        <p class=\"correct-text zh\" style=\"margin-top:4px;\">二零二三年九月 (Năm 2023 tháng 9)</p>\n        <p style=\"font-size:.88rem;color:var(--muted);margin-top:6px\">Luôn nhớ quy tắc: To (Năm) ➔ Vừa (Tháng) ➔ Nhỏ (Ngày/Thứ).</p>\n      </div>\n    </div>\n    <!-- Lỗi 2 -->\n    <div class=\"error-box\">\n      <div class=\"err-head wrong\">Lỗi 2 · Dùng sai đại từ nghi vấn hỏi thứ</div>\n      <div class=\"err-body\">\n        <p style=\"margin-bottom:12px\">Tiếng Việt hỏi \"Thứ MẤY\", nhiều bạn dùng từ hỏi \"多少\" (bao nhiêu) để hỏi. Cách hỏi này sai hoàn toàn.</p>\n        <p class=\"strike zh\">今天星期多少？</p>\n      </div>\n      <div class=\"err-head correct\">Cách sửa</div>\n      <div class=\"err-body\">\n        <p class=\"correct-text zh\">今天星期几？</p>\n        <p style=\"font-size:.88rem;color:var(--muted);margin-top:6px\">Để hỏi thứ (số lượng nhỏ hơn 10), bắt buộc phải dùng <b>几 (jǐ - mấy)</b>, ghép vào chữ 星期 thành 星期几.</p>\n      </div>\n    </div>\n    <!-- Lỗi 3 -->\n    <div class=\"error-box\">\n      <div class=\"err-head wrong\">Lỗi 3 · Bê nguyên cấu trúc \"Đi làm gì ở đâu\"</div>\n      <div class=\"err-body\">\n        <p style=\"margin-bottom:12px\">Trong tiếng Việt, chúng ta nói \"Tôi đi xem phim ở rạp chiếu phim\" (Động từ ➔ Nơi chốn). Nếu dịch sát nghĩa tiếng Việt sang sẽ bị sai ngữ pháp tiếng Trung.</p>\n        <p class=\"strike zh\">我去读书在学校。</p>\n        <p class=\"strike zh\" style=\"margin-top:4px;\">我去看书学校。</p>\n      </div>\n      <div class=\"err-head correct\">Cách sửa</div>\n      <div class=\"err-body\">\n        <p class=\"correct-text zh\">我去学校看书。</p>\n        <p style=\"font-size:.88rem;color:var(--muted);margin-top:6px\">Cấu trúc liên động từ bắt buộc: Chủ ngữ + <b>去 (Đi)</b> + Nơi chốn + <b>Động từ (Làm gì)</b>.</p>\n      </div>\n    </div>\n  </div>"},{"label":"Tổng hợp","html":"<h2 class=\"section-title\">Tổng hợp kiến thức</h2>\n  <p class=\"section-sub\">Sơ đồ cốt lõi giúp tóm tắt toàn bộ bài học.</p>\n\n  <div class=\"syn-grid\">\n    <!-- Khối 1: Cấu trúc -->\n    <div class=\"syn-card theme-burgundy\">\n      <div class=\"syn-icon\">🔍</div>\n      <h3>Cách nói thời gian</h3>\n      <table class=\"syn-table\">\n        <tr><th>Loại</th><th>Cấu trúc</th></tr>\n        <tr><td>Hỏi ngày</td><td>今天 + 几月几号？</td></tr>\n        <tr><td>Hỏi thứ</td><td>今天 + 星期几？</td></tr>\n        <tr><td>Trả lời</td><td>Hôm nay + Tháng + Ngày + Thứ.</td></tr>\n      </table>\n      <div class=\"syn-mnemonic\">Nhớ quy tắc phễu: Từ Đơn vị Lớn đến Đơn vị Nhỏ.</div>\n    </div>\n\n    <!-- Khối 2: Sơ đồ chuỗi (Flow) -->\n    <div class=\"syn-card theme-gold\">\n      <div class=\"syn-icon\">📅</div>\n      <h3>Hỏi đi đâu làm gì</h3>\n      <div class=\"syn-flow\">\n        <div class=\"step\"><span class=\"syn-keyhz\">你</span><br><small>Bạn</small></div>\n        <span class=\"arrow\">→</span>\n        <div class=\"step\"><span class=\"syn-keyhz\">去哪儿</span><br><small>đi đâu</small></div>\n        <span class=\"arrow\">→</span>\n        <div class=\"step\"><span class=\"syn-keyhz\">做什么？</span><br><small>làm gì?</small></div>\n      </div>\n      <div class=\"syn-mnemonic\">Cấu trúc <strong>去 + Địa điểm + Hành động</strong> là cấu trúc cực kỳ quan trọng!</div>\n    </div>\n\n    <!-- Khối 3: Bảng 5 Câu Thần Chú (Bắt buộc giữ form này ở cuối Tab 9) -->\n    <div class=\"syn-card theme-gold\" style=\"grid-column: 1 / -1;\">\n      <div class=\"syn-icon\">⚡</div>\n      <h3>Câu thần chú 5 mẫu</h3>\n      <table class=\"syn-table\">\n        <tr><th>Mẫu</th><th>Tình huống</th></tr>\n        <tr><td><span class=\"syn-keyhz\">请问，今天几号？</span></td><td>Hỏi thăm ngày một cách lịch sự.</td></tr>\n        <tr><td><span class=\"syn-keyhz\">今天九月一号，星期三。</span></td><td>Trả lời thông tin ngày tháng, thứ đầy đủ.</td></tr>\n        <tr><td><span class=\"syn-keyhz\">明天星期六，你去学校吗？</span></td><td>Hỏi dự định của người khác vào một ngày cụ thể.</td></tr>\n        <tr><td><span class=\"syn-keyhz\">你去学校做什么？</span></td><td>Hỏi mục đích đến một địa điểm nào đó.</td></tr>\n        <tr><td><span class=\"syn-keyhz\">我去学校看书。</span></td><td>Trả lời câu hỏi đi đâu, làm gì (Tôi đi trường học đọc sách).</td></tr>\n      </table>\n      <div class=\"syn-mnemonic\"><strong>Thuộc 5 mẫu này là pass Bài 7.</strong></div>\n    </div>\n  </div>"}],"cssId":"c7fcf9643"},{"id":"k1v2-b08","courseId":"k1v2","order":8,"title":"Tôi muốn uống trà.","titleZh":"我想喝茶。","vocab":[{"stt":1,"hanzi":"想","pinyin":"xiǎng","hanviet":"Tưởng","pos":"Động từ năng nguyện","meaning":"Muốn, nhớ, nghĩ","comps":"想要 (muốn có), 想家 (nhớ nhà)","example":{"zh":"我想喝茶。","py":"Wǒ xiǎng hē chá.","vi":"Tôi muốn uống trà."}},{"stt":2,"hanzi":"喝","pinyin":"hē","hanviet":"Hát","pos":"Động từ","meaning":"Uống","comps":"喝水 (uống nước), 喝茶 (uống trà)","example":{"zh":"你想喝什么？","py":"Nǐ xiǎng hē shénme?","vi":"Bạn muốn uống gì?"}},{"stt":3,"hanzi":"茶","pinyin":"chá","hanviet":"Trà","pos":"Danh từ","meaning":"Trà, chè","comps":"喝茶 (uống trà), 茶杯 (ly trà)","example":{"zh":"中国人喜欢喝茶。","py":"Zhōngguó rén xǐhuan hē chá.","vi":"Người Trung Quốc thích uống trà."}},{"stt":4,"hanzi":"吃","pinyin":"chī","hanviet":"Cật","pos":"Động từ","meaning":"Ăn","comps":"吃饭 (ăn cơm), 好吃 (ngon)","example":{"zh":"你想吃什么？","py":"Nǐ xiǎng chī shénme?","vi":"Bạn muốn ăn gì?"}},{"stt":5,"hanzi":"米饭","pinyin":"mǐfàn","hanviet":"Mễ phạn","pos":"Danh từ","meaning":"Cơm","comps":"吃米饭 (ăn cơm), 做米饭 (nấu cơm)","example":{"zh":"我中午吃米饭。","py":"Wǒ zhōngwǔ chī mǐfàn.","vi":"Buổi trưa tôi ăn cơm."}},{"stt":6,"hanzi":"下午","pinyin":"xiàwǔ","hanviet":"Hạ ngọ","pos":"Danh từ","meaning":"Buổi chiều","comps":"今天下午 (chiều nay), 下午好 (chào buổi chiều)","example":{"zh":"下午你想做什么？","py":"Xiàwǔ nǐ xiǎng zuò shénme?","vi":"Buổi chiều bạn muốn làm gì?"}},{"stt":7,"hanzi":"商店","pinyin":"shāngdiàn","hanviet":"Thương điếm","pos":"Danh từ","meaning":"Cửa hàng, tiệm","comps":"去商店 (đi cửa hàng), 买东西 (mua đồ)","example":{"zh":"我想去商店买水。","py":"Wǒ xiǎng qù shāngdiàn mǎi shuǐ.","vi":"Tôi muốn đến cửa hàng mua nước."}},{"stt":8,"hanzi":"买","pinyin":"mǎi","hanviet":"Mãi","pos":"Động từ","meaning":"Mua","comps":"买书 (mua sách), 买杯子 (mua ly)","example":{"zh":"你想买什么？","py":"Nǐ xiǎng mǎi shénme?","vi":"Bạn muốn mua gì?"}},{"stt":9,"hanzi":"个","pinyin":"gè","hanviet":"Cá","pos":"Lượng từ","meaning":"Cái, con, người (lượng từ phổ biến nhất)","comps":"一个人 (một người), 三个杯子 (ba cái ly)","example":{"zh":"我想买一个杯子。","py":"Wǒ xiǎng mǎi yí ge bēizi.","vi":"Tôi muốn mua một cái ly."}},{"stt":10,"hanzi":"杯子","pinyin":"bēizi","hanviet":"Bôi tử","pos":"Danh từ","meaning":"Cái ly, cốc, tách","comps":"一个杯子 (một cái ly), 买杯子 (mua ly)","example":{"zh":"这个杯子很大。","py":"Zhège bēizi hěn dà.","vi":"Cái ly này rất to."}},{"stt":11,"hanzi":"这","pinyin":"zhè","hanviet":"Giá","pos":"Đại từ","meaning":"Này, đây","comps":"这个 (cái này), 这里 (ở đây)","example":{"zh":"这个杯子多少钱？","py":"Zhège bēizi duōshao qián?","vi":"Cái ly này bao nhiêu tiền?"}},{"stt":12,"hanzi":"多少","pinyin":"duōshao","hanviet":"Đa thiếu","pos":"Đại từ","meaning":"Bao nhiêu (hỏi số lượng nhiều)","comps":"多少钱 (bao nhiêu tiền), 多少人 (bao nhiêu người)","example":{"zh":"你们学校有多少学生？","py":"Nǐmen xuéxiào yǒu duōshao xuésheng?","vi":"Trường các bạn có bao nhiêu học sinh?"}},{"stt":13,"hanzi":"钱","pinyin":"qián","hanviet":"Tiền","pos":"Danh từ","meaning":"Tiền","comps":"多少钱 (bao nhiêu tiền), 有钱 (có tiền)","example":{"zh":"我没有钱。","py":"Wǒ méiyǒu qián.","vi":"Tôi không có tiền."}},{"stt":14,"hanzi":"块","pinyin":"kuài","hanviet":"Khối","pos":"Lượng từ","meaning":"Đồng, cục, viên (đơn vị tiền tệ)","comps":"十块钱 (10 đồng), 一块 (một cục/đồng)","example":{"zh":"这个杯子十八块钱。","py":"Zhège bēizi shíbā kuài qián.","vi":"Cái ly này 18 đồng."}},{"stt":15,"hanzi":"那","pinyin":"nà","hanviet":"Na","pos":"Đại từ","meaning":"Kia, đó","comps":"那个 (cái kia), 那里 (ở đó)","example":{"zh":"那个杯子多少钱？","py":"Nàge bēizi duōshao qián?","vi":"Cái ly kia bao nhiêu tiền?"}}],"hanzi":[{"char":"想","pinyin":"xiǎng","hanviet":"Tưởng","chars":["想"],"story":"Phía trên là chữ Tướng (相 - hình dáng, xem xét), phía dưới là bộ Tâm (心 - trái tim). Trái tim đang suy xét, tơ tưởng đến một hình bóng nào đó. Nghĩa là muốn, hoặc nhớ."},{"char":"喝","pinyin":"hē","hanviet":"Hát","chars":["喝"],"story":"Bên trái là bộ Khẩu (口 - miệng). Bên phải là chữ Hạt (曷 - la mắng, khát). Dùng miệng để tu nước khi đang khát là hành động \"Uống\"."},{"char":"茶","pinyin":"chá","hanviet":"Trà","chars":["茶"],"story":"Trên cùng là bộ Thảo (艹 - cỏ, cây), ở giữa là chữ Nhân (人 - người), dưới cùng là bộ Mộc (木 - cây). Con người hái lá cây/cỏ thảo mộc để nấu thành \"Trà\"."},{"char":"吃","pinyin":"chī","hanviet":"Cật","chars":["吃"],"story":"Bên trái là bộ Khẩu (口 - miệng). Bên phải là chữ Khất (乞 - cầu xin). Hành động mở miệng ra xin đồ để \"Ăn\"."},{"char":"米饭","pinyin":"mǐfàn","hanviet":"Mễ phạn","chars":["米","饭"],"story":"米 (Mễ) là hình ảnh bông lúa trĩu hạt dạt ra 4 góc (chỉ gạo). 饭 (Phạn) gồm bộ Thực (飠- đồ ăn) và chữ Phản (反). Gạo (米) nấu chín thì thành Cơm (米饭)."},{"char":"下午","pinyin":"xiàwǔ","hanviet":"Hạ ngọ","chars":["下","午"],"story":"下 (Hạ - bên dưới, sau). 午 (Ngọ - giữa trưa). Khoảng thời gian sau lúc giữa trưa chính là Buổi chiều."},{"char":"商店","pinyin":"shāngdiàn","hanviet":"Thương điếm","chars":["商","店"],"story":"商 (Thương - buôn bán). 店 (Điếm) có bộ Quảng (广 - mái che rộng) và chữ Chiêm (占). Tòa nhà rộng rãi dùng để buôn bán là \"Cửa hàng\"."},{"char":"买","pinyin":"mǎi","hanviet":"Mãi","chars":["买"],"story":"Phía trên giống số 3/mũ miện gập lại, phía dưới là chữ Đầu (头 - cái đầu). Mang tiền/đồ đội trên đầu ra chợ để trao đổi \"Mua\" bán."},{"char":"个","pinyin":"gè","hanviet":"Cá","chars":["个"],"story":"Hình ảnh giống một mũi tên đâm vào gốc cây hoặc một cá thể đứng một mình. Là lượng từ chỉ một đơn vị độc lập."},{"char":"杯子","pinyin":"bēizi","hanviet":"Bôi tử","chars":["杯","子"],"story":"杯 (Bôi) gồm bộ Mộc (木 - gỗ) và chữ Bất (不). Cốc uống nước thời cổ đại thường được làm bằng gỗ."},{"char":"这","pinyin":"zhè","hanviet":"Giá","chars":["这"],"story":"Bên trong là chữ Văn (文 - văn vẻ), bên ngoài là bộ Xước (辶 - bước đi xa)."},{"char":"多少","pinyin":"duōshao","hanviet":"Đa thiếu","chars":["多","少"],"story":"多 (Đa - nhiều). 少 (Thiếu - ít). Ghép lại thành đại từ để hỏi về mức độ/số lượng: \"Bao nhiêu?\"."},{"char":"钱","pinyin":"qián","hanviet":"Tiền","chars":["钱"],"story":"Bên trái là bộ Kim (钅 - kim loại, vàng). Bên phải là chữ Qua (戋 - cây giáo/vũ khí). Tiền thời xưa được đúc bằng kim loại, quan trọng như vũ khí để phòng thân."},{"char":"块","pinyin":"kuài","hanviet":"Khối","chars":["块"],"story":"Bên trái là bộ Thổ (土 - đất). Phía phải là chữ Quái (夬). Ban đầu chỉ một khối đất (cục). Sau này dùng làm đơn vị đếm tiền (tương đương với chữ 元 - Nguyên)."},{"char":"那","pinyin":"nà","hanviet":"Na","chars":["那"],"story":"Đại từ chỉ định những vật ở xa người nói. Trái nghĩa với 这 (zhè - này)."}],"grammar":[{"title":"Động từ năng nguyện \"想\" (xiǎng)","formula":"Chủ ngữ + <span>想 / 不想</span> + Động từ + (Tân ngữ).","summary":"Động từ \"想\" (muốn) được dùng trước một động từ khác để diễn tả một mong muốn, dự định hoặc ý định làm việc gì đó. Dạng phủ định là \"不想\" (không muốn).","note":"<strong>Lưu ý:</strong> Mặc dù tiếng Việt nói \"Tôi muốn một cái ly\" (想 + Danh từ), tiếng Trung bắt buộc phải dùng \"我要一个杯子\" (要 + Danh từ). Còn \"想\" bắt buộc phải cộng với Động từ (我想买一个杯子).","examples":[{"zh":"我想学汉语。","py":"Wǒ xiǎng xué Hànyǔ.","vi":"Tôi muốn học tiếng Trung."},{"zh":"明天我想去学校。","py":"Míngtiān wǒ xiǎng qù xuéxiào.","vi":"Ngày mai tôi muốn đến trường."},{"zh":"我想买一个杯子。","py":"Wǒ xiǎng mǎi yí ge bēizi.","vi":"Tôi muốn mua một cái ly."},{"zh":"你想吃什么？","py":"Nǐ xiǎng chī shénme?","vi":"Bạn muốn ăn gì?"},{"zh":"我不想吃米饭。","py":"Wǒ bù xiǎng chī mǐfàn.","vi":"Tôi không muốn ăn cơm."},{"zh":"大卫想喝中国茶。","py":"Dàwèi xiǎng hē Zhōngguó chá.","vi":"David muốn uống trà Trung Quốc."},{"zh":"下午你想做什么？","py":"Xiàwǔ nǐ xiǎng zuò shénme?","vi":"Buổi chiều bạn muốn làm gì?"},{"zh":"他不想去商店。","py":"Tā bù xiǎng qù shāngdiàn.","vi":"Anh ấy không muốn đi cửa hàng."}]},{"title":"Đại từ nghi vấn \"多少\" (duōshao)","formula":"Chủ ngữ + 有 + <span>多少</span> + (Lượng từ) + Danh từ？","summary":"Dùng để hỏi số lượng lớn (thường là hơn 10). Khác với \"几\" (jǐ) bắt buộc phải có lượng từ theo sau, thì sau \"多少\" có thể dùng lượng từ hoặc LƯỢC BỎ lượng từ.","note":"<strong>Lưu ý:</strong> Khi hỏi giá cả, cấu trúc cố định là \"多少钱\" (Bao nhiêu tiền).","examples":[{"zh":"你们学校有多少（个）学生？","py":"Nǐmen xuéxiào yǒu duōshao (ge) xuésheng?","vi":"Trường các bạn có bao nhiêu học sinh?"},{"zh":"你有多少汉语老师？","py":"Nǐ yǒu duōshao Hànyǔ lǎoshī?","vi":"Bạn có bao nhiêu giáo viên tiếng Trung?"},{"zh":"这个杯子多少钱？","py":"Zhège bēizi duōshao qián?","vi":"Cái ly này bao nhiêu tiền?"},{"zh":"这本中国书多少钱？","py":"Zhè běn Zhōngguó shū duōshao qián?","vi":"Cuốn sách Trung Quốc này bao nhiêu tiền?"},{"zh":"你们班有多少人？","py":"Nǐmen bān yǒu duōshao rén?","vi":"Lớp các bạn có bao nhiêu người?"},{"zh":"那个大杯子多少钱？","py":"Nàge dà bēizi duōshao qián?","vi":"Cái ly to kia bao nhiêu tiền?"},{"zh":"你买多少苹果？","py":"Nǐ mǎi duōshao píngguǒ?","vi":"Bạn mua bao nhiêu quả táo?"},{"zh":"多少钱一个杯子？","py":"Duōshao qián yí ge bēizi?","vi":"Bao nhiêu tiền một cái ly? (Cách hỏi đảo ngữ)"}]},{"title":"Lượng từ \"个\" (gè)","formula":"Số từ / Đại từ chỉ định (这/那) + <span>个</span> + Danh từ.","summary":"\"个\" là lượng từ phổ biến và quan trọng nhất trong tiếng Trung. Khi bạn không biết phải dùng lượng từ gì cho một đồ vật, \"个\" là sự lựa chọn an toàn.","note":"<strong>Lưu ý:</strong> Tiếng Việt thường ghép chung (Cái này), tiếng Trung phải tách ra (这 + 个 + Danh từ = Này + cái + danh từ). Vd: 这个杯子 (Cái ly này).","examples":[{"zh":"三个老师。","py":"Sān ge lǎoshī.","vi":"Ba giáo viên."},{"zh":"五个学生。","py":"Wǔ ge xuésheng.","vi":"Năm học sinh."},{"zh":"一个杯子。","py":"Yí ge bēizi.","vi":"Một cái ly."},{"zh":"这个杯子。","py":"Zhège bēizi.","vi":"Cái ly này."},{"zh":"那个苹果。","py":"Nàge píngguǒ.","vi":"Quả táo kia."},{"zh":"你想买几个杯子？","py":"Nǐ xiǎng mǎi jǐ ge bēizi?","vi":"Bạn muốn mua mấy cái ly?"},{"zh":"我有一个中国朋友。","py":"Wǒ yǒu yí ge Zhōngguó péngyou.","vi":"Tôi có một người bạn Trung Quốc."},{"zh":"那个杯子是我的。","py":"Nàge bēizi shì wǒ de.","vi":"Cái ly kia là của tôi."}]}],"text":{"title":"课文 · Bài khoá","blocks":[{"titleZh":"在饭馆儿","titleVi":"Ở quán ăn","icon":"🍚","lines":[{"speaker":"A","zh":"你想喝什么？","py":"Nǐ xiǎng hē shénme?","vi":"Cô muốn uống gì?"},{"speaker":"B","zh":"我想喝茶。","py":"Wǒ xiǎng hē chá.","vi":"Tôi muốn uống trà."},{"speaker":"A","zh":"你想吃什么？","py":"Nǐ xiǎng chī shénme?","vi":"Cô muốn dùng món gì?"},{"speaker":"B","zh":"我想吃米饭。","py":"Wǒ xiǎng chī mǐfàn.","vi":"Tôi muốn ăn cơm."}]},{"titleZh":"在客厅","titleVi":"Trong phòng khách","icon":"🛋️","lines":[{"speaker":"A","zh":"下午你想做什么？","py":"Xiàwǔ nǐ xiǎng zuò shénme?","vi":"Buổi chiều bạn muốn làm gì?"},{"speaker":"B","zh":"下午我想去商店。","py":"Xiàwǔ wǒ xiǎng qù shāngdiàn.","vi":"Mình muốn đến cửa hàng."},{"speaker":"A","zh":"你想买什么？","py":"Nǐ xiǎng mǎi shénme?","vi":"Bạn muốn mua gì vậy?"},{"speaker":"B","zh":"我想买一个杯子。","py":"Wǒ xiǎng mǎi yí ge bēizi.","vi":"Mình muốn mua một cái ly."}]},{"titleZh":"在商店","titleVi":"Ở cửa hàng","icon":"🏪","lines":[{"speaker":"A","zh":"你好！这个杯子多少钱？","py":"Nǐ hǎo! Zhège bēizi duōshao qián?","vi":"Chào cô! Cái ly này bao nhiêu tiền?"},{"speaker":"B","zh":"二十八块。","py":"Èrshíbā kuài.","vi":"28 đồng."},{"speaker":"A","zh":"那个杯子多少钱？","py":"Nàge bēizi duōshao qián?","vi":"Còn cái ly đó?"},{"speaker":"B","zh":"那个杯子十八块钱。","py":"Nàge bēizi shíbā kuài qián.","vi":"Ly đó 18 đồng."}]}]},"extra":[{"label":"Mục tiêu","html":"<h2 class=\"section-title\">Mục tiêu bài học</h2>\n  <p class=\"section-sub\">Thành thạo kỹ năng nói lên mong muốn của bản thân và thực hiện giao dịch mua bán cơ bản.</p>\n  <div class=\"goal-grid\">\n    <div class=\"goal-item\">\n      <div class=\"num\">01</div>\n      <h4>Giao tiếp</h4>\n      <ul>\n        <li>Diễn đạt nhu cầu: Muốn ăn/uống gì.</li>\n        <li>Hỏi thăm dự định của người khác (Muốn làm gì/Đi đâu).</li>\n        <li>Hỏi giá cả và mua sắm đồ vật.</li>\n      </ul>\n    </div>\n    <div class=\"goal-item\">\n      <div class=\"num\">02</div>\n      <h4>Từ vựng</h4>\n      <ul>\n        <li>Chủ đề Ăn uống: <b>吃, 喝, 茶, 米饭</b></li>\n        <li>Chủ đề Mua bán: <b>买, 商店, 杯子, 多少, 钱, 块</b></li>\n        <li>Đại từ & Phó từ: <b>想, 这, 那</b></li>\n      </ul>\n    </div>\n    <div class=\"goal-item\">\n      <div class=\"num\">03</div>\n      <h4>Ngữ pháp</h4>\n      <ul>\n        <li>Động từ năng nguyện <b>\"想\"</b> chỉ ý muốn.</li>\n        <li>Đại từ nghi vấn <b>\"多少\"</b> hỏi số lượng lớn.</li>\n        <li>Lượng từ <b>\"个\"</b> và cách đọc giá tiền.</li>\n      </ul>\n    </div>\n  </div>"},{"label":"Chuyên đề Mở rộng","html":"<h2 class=\"section-title\">Tiền tệ Trung Quốc (Nhân dân tệ)</h2>\n  <p class=\"section-sub\">Tìm hiểu các mệnh giá và cách nói tiền tệ trong giao tiếp thực tế của người Trung Quốc.</p>\n\n  <div class=\"card\">\n    <h3>1. Đơn vị tiền tệ: 元 (yuán) vs 块 (kuài)</h3>\n    <p>Đơn vị cơ bản của Nhân dân tệ (RMB) viết trên giấy tờ là <b>元 (yuán - đồng/nguyên)</b>. Tuy nhiên, trong văn nói hàng ngày, người Trung Quốc hầu như luôn luôn sử dụng chữ <b>块 (kuài - cục/đồng)</b>.</p>\n    \n    <div class=\"formula-box\">\n      <div class=\"formula-label\">Văn viết (Giá niêm yết)</div>\n      <div class=\"formula\">100 <span class=\"pop gold\">元</span> (Yìbǎi yuán)</div>\n    </div>\n    \n    <div class=\"formula-box\" style=\"background: linear-gradient(135deg, #3A2020 0%, #5C3A34 100%);\">\n      <div class=\"formula-label\" style=\"color:var(--gold-soft)\">Văn nói (Thực tế giao tiếp)</div>\n      <div class=\"formula\" style=\"color:var(--ivory)\">100 <span class=\"pop gold\" style=\"color:var(--gold)\">块</span> (Yìbǎi kuài)</div>\n    </div>\n  </div>\n\n  <div class=\"card\">\n    <h3>2. Đọc các mệnh giá phổ biến</h3>\n    <p>Người Trung Quốc sử dụng các tờ tiền có mệnh giá: 1 đồng, 5 đồng, 10 đồng, 20 đồng, 50 đồng và cao nhất là 100 đồng (tờ màu đỏ in hình Mao Trạch Đông).</p>\n    \n    <ul style=\"margin-top: 14px; margin-bottom: 24px;\">\n      <li style=\"margin-bottom: 12px;\"><b>1 đồng:</b> 一块 (yí kuài)</li>\n      <li style=\"margin-bottom: 12px;\"><b>5 đồng:</b> 五块 (wǔ kuài)</li>\n      <li style=\"margin-bottom: 12px;\"><b>10 đồng:</b> 十块 (shí kuài)</li>\n      <li style=\"margin-bottom: 12px;\"><b>50 đồng:</b> 五十块 (wǔshí kuài)</li>\n      <li><b>100 đồng:</b> 一百块 (yìbǎi kuài)</li>\n    </ul>\n\n    <div class=\"tip-card\">\n      <h5>💡 Từ vựng bổ sung (Tiền hào/hào xu)</h5>\n      <p>Dưới \"đồng\" (块) là \"hào\" (毛 - máo) và \"xu\" (分 - fēn).<br>\n      1 đồng = 10 hào. (一块 = 十毛). Ví dụ mua cọng hành giá 5 hào: 五毛 (wǔ máo).</p>\n    </div>\n  </div>"},{"label":"Lỗi sai","html":"<h2 class=\"section-title\">Lỗi sai thường gặp</h2>\n  <p class=\"section-sub\">Những lỗi người Việt hay mắc phải khi dùng \"想\", \"几\" và \"多少\".</p>\n  <div class=\"error-grid\">\n    <!-- Lỗi 1 -->\n    <div class=\"error-box\">\n      <div class=\"err-head wrong\">Lỗi 1 · Dùng \"想\" (Muốn) thay cho \"要\" (Cần)</div>\n      <div class=\"err-body\">\n        <p style=\"margin-bottom:12px\">Tiếng Việt nói \"Tôi muốn một ly trà\" (động từ chính là 'muốn'). Nhưng trong tiếng Trung, \"想\" là động từ năng nguyện, sau nó phải là một ĐỘNG TỪ khác (Muốn UỐNG trà). Nếu chỉ có danh từ, phải dùng chữ \"要\" (Cần).</p>\n        <p class=\"strike zh\">我想一杯茶。</p>\n        <p class=\"strike zh\" style=\"margin-top:4px;\">我想一个杯子。</p>\n      </div>\n      <div class=\"err-head correct\">Cách sửa</div>\n      <div class=\"err-body\">\n        <p class=\"correct-text zh\">我想喝一杯茶。</p>\n        <p class=\"correct-text zh\" style=\"margin-top:4px;\">我要一个杯子。</p>\n        <p style=\"font-size:.88rem;color:var(--muted);margin-top:6px\">Quy tắc: 想 + Động từ. 要 + Danh từ.</p>\n      </div>\n    </div>\n    <!-- Lỗi 2 -->\n    <div class=\"error-box\">\n      <div class=\"err-head wrong\">Lỗi 2 · Thiếu lượng từ khi dùng \"个\"</div>\n      <div class=\"err-body\">\n        <p style=\"margin-bottom:12px\">Tiếng Việt nói \"Cái ly này\", học viên hay dịch từng chữ là \"这杯子\". Tiếng Trung bắt buộc phải có lượng từ đứng giữa đại từ chỉ định (这/那) và Danh từ.</p>\n        <p class=\"strike zh\">这杯子多少钱？</p>\n        <p class=\"strike zh\" style=\"margin-top:4px;\">那杯子很好。</p>\n      </div>\n      <div class=\"err-head correct\">Cách sửa</div>\n      <div class=\"err-body\">\n        <p class=\"correct-text zh\">这个杯子多少钱？</p>\n        <p class=\"correct-text zh\" style=\"margin-top:4px;\">那个杯子很好。</p>\n        <p style=\"font-size:.88rem;color:var(--muted);margin-top:6px\">Luôn nhớ: 这 (Này) / 那 (Kia) + Lượng từ (个) + Danh từ.</p>\n      </div>\n    </div>\n    <!-- Lỗi 3 -->\n    <div class=\"error-box\">\n      <div class=\"err-head wrong\">Lỗi 3 · Phân biệt 几 (Mấy) và 多少 (Bao nhiêu)</div>\n      <div class=\"err-body\">\n        <p style=\"margin-bottom:12px\">Nhiều bạn dùng \"几\" để hỏi giá tiền (Mấy tiền?). \"几\" chỉ dùng cho số lượng nhỏ hơn 10 và PHẢI có lượng từ đi kèm. Tiền nong thường lớn hơn 10 nên phải dùng \"多少\" và KHÔNG cần lượng từ (个) sau nó.</p>\n        <p class=\"strike zh\">这个杯子几钱？</p>\n        <p class=\"strike zh\" style=\"margin-top:4px;\">你们学校有几个老师？ (Nếu trường có hàng trăm giáo viên)</p>\n      </div>\n      <div class=\"err-head correct\">Cách sửa</div>\n      <div class=\"err-body\">\n        <p class=\"correct-text zh\">这个杯子多少钱？</p>\n        <p class=\"correct-text zh\" style=\"margin-top:4px;\">你们学校有多少老师？</p>\n        <p style=\"font-size:.88rem;color:var(--muted);margin-top:6px\">多少 + Danh từ (Hỏi số lượng lớn, không bắt buộc có lượng từ).</p>\n      </div>\n    </div>\n  </div>"},{"label":"Tổng hợp","html":"<h2 class=\"section-title\">Tổng hợp kiến thức</h2>\n  <p class=\"section-sub\">Sơ đồ cốt lõi giúp tóm tắt toàn bộ bài học.</p>\n\n  <div class=\"syn-grid\">\n    <!-- Khối 1: Cấu trúc -->\n    <div class=\"syn-card theme-burgundy\">\n      <div class=\"syn-icon\">🔍</div>\n      <h3>Biểu đạt ý muốn</h3>\n      <table class=\"syn-table\">\n        <tr><th>Loại</th><th>Cấu trúc</th></tr>\n        <tr><td>Khẳng định</td><td>Chủ ngữ + 想 + Động từ + (Tân ngữ).</td></tr>\n        <tr><td>Phủ định</td><td>Chủ ngữ + 不想 + Động từ + (Tân ngữ).</td></tr>\n      </table>\n      <div class=\"syn-mnemonic\">Nhớ: 想 (Xiǎng) = Trong LÒNG (心) mơ tưởng đến cành cây (木). Dùng để chỉ ý nghĩ, mong muốn.</div>\n    </div>\n\n    <!-- Khối 2: Sơ đồ chuỗi (Flow) -->\n    <div class=\"syn-card theme-gold\">\n      <div class=\"syn-icon\">📅</div>\n      <h3>Hỏi giá cả</h3>\n      <div class=\"syn-flow\">\n        <div class=\"step\"><span class=\"syn-keyhz\">这个</span><br><small>Cái này</small></div>\n        <span class=\"arrow\">→</span>\n        <div class=\"step\"><span class=\"syn-keyhz\">杯子</span><br><small>ly/tách</small></div>\n        <span class=\"arrow\">→</span>\n        <div class=\"step\"><span class=\"syn-keyhz\">多少钱？</span><br><small>bao nhiêu tiền?</small></div>\n      </div>\n      <div class=\"syn-mnemonic\">Thuộc lòng cụm <strong>多少钱</strong> (Duōshao qián) để đi mua sắm!</div>\n    </div>\n\n    <!-- Khối 3: Bảng 5 Câu Thần Chú -->\n    <div class=\"syn-card theme-gold\" style=\"grid-column: 1 / -1;\">\n      <div class=\"syn-icon\">⚡</div>\n      <h3>Câu thần chú 5 mẫu</h3>\n      <table class=\"syn-table\">\n        <tr><th>Mẫu</th><th>Tình huống</th></tr>\n        <tr><td><span class=\"syn-keyhz\">你想喝什么？</span></td><td>Hỏi xem đối phương muốn uống đồ uống gì.</td></tr>\n        <tr><td><span class=\"syn-keyhz\">我想吃米饭。</span></td><td>Trả lời về mong muốn ăn uống của bản thân.</td></tr>\n        <tr><td><span class=\"syn-keyhz\">下午你想做什么？</span></td><td>Hỏi dự định, kế hoạch của ai đó vào một thời điểm.</td></tr>\n        <tr><td><span class=\"syn-keyhz\">我想去商店买杯子。</span></td><td>Trả lời dự định (Muốn đi đâu, làm gì).</td></tr>\n        <tr><td><span class=\"syn-keyhz\">那个杯子多少钱？</span></td><td>Chỉ vào một món đồ ở xa và hỏi giá tiền.</td></tr>\n      </table>\n      <div class=\"syn-mnemonic\"><strong>Thuộc 5 mẫu này là pass Bài 8.</strong></div>\n    </div>\n  </div>"}],"cssId":"c7fcf9643"},{"id":"k1v2-b09","courseId":"k1v2","order":9,"title":"Con trai anh làm việc ở đâu?","titleZh":"你儿子在哪儿工作？","vocab":[{"stt":1,"hanzi":"小","pinyin":"xiǎo","hanviet":"Tiểu","pos":"Tính từ","meaning":"nhỏ, bé","comps":"小猫 · 小狗 · 小学","example":{"zh":"我家有一只小猫。","py":"Wǒ jiā yǒu yì zhī xiǎomāo.","vi":"Nhà tôi có một con mèo nhỏ."}},{"stt":2,"hanzi":"猫","pinyin":"māo","hanviet":"Miêu","pos":"Danh từ","meaning":"con mèo","comps":"小猫 · 大猫 · 熊猫","example":{"zh":"猫在椅子下面。","py":"Māo zài yǐzi xiàmiàn.","vi":"Mèo ở dưới ghế."}},{"stt":3,"hanzi":"在","pinyin":"zài","hanviet":"Tại","pos":"Động từ","meaning":"ở, tại","comps":"在家 · 在学校","example":{"zh":"我妈妈在家。","py":"Wǒ māma zài jiā.","vi":"Mẹ tôi ở nhà."}},{"stt":4,"hanzi":"那儿","pinyin":"nàr","hanviet":"Na nhi","pos":"Đại từ","meaning":"chỗ đó, ở đó/kia","comps":"在那儿 · 那儿很好","example":{"zh":"小猫在那儿。","py":"Xiǎomāo zài nàr.","vi":"Mèo ở chỗ đó."}},{"stt":5,"hanzi":"狗","pinyin":"gǒu","hanviet":"Cẩu","pos":"Danh từ","meaning":"con chó","comps":"小狗 · 大狗 · 热狗","example":{"zh":"小狗在椅子下面。","py":"Xiǎo gǒu zài yǐzi xiàmiàn.","vi":"Cún ở dưới ghế."}},{"stt":6,"hanzi":"椅子","pinyin":"yǐzi","hanviet":"Ỷ tử","pos":"Danh từ","meaning":"cái ghế (tựa)","comps":"小椅子 · 木椅子 · 椅子上","example":{"zh":"猫在椅子上。","py":"Māo zài yǐzi shàng.","vi":"Mèo ở trên ghế."}},{"stt":7,"hanzi":"下面","pinyin":"xiàmiàn","hanviet":"Hạ diện","pos":"Danh từ phương vị","meaning":"phía dưới, bên dưới","comps":"椅子下面 · 桌子下面 · 下面是","example":{"zh":"书在桌子下面。","py":"Shū zài zhuōzi xiàmiàn.","vi":"Sách ở dưới bàn."}},{"stt":8,"hanzi":"在","pinyin":"zài","hanviet":"Tại","pos":"Giới từ","meaning":"ở (giới thiệu nơi chốn)","comps":"在医院工作 · 在家吃饭","example":{"zh":"我在医院工作。","py":"Wǒ zài yīyuàn gōngzuò.","vi":"Tôi làm việc ở bệnh viện."}},{"stt":9,"hanzi":"哪儿","pinyin":"nǎr","hanviet":"Na nhi","pos":"Đại từ nghi vấn","meaning":"ở đâu?","comps":"在哪儿 · 去哪儿 · 哪儿都","example":{"zh":"你在哪儿？","py":"Nǐ zài nǎr?","vi":"Bạn ở đâu?"}},{"stt":10,"hanzi":"工作","pinyin":"gōngzuò","hanviet":"Công tác","pos":"Động từ / Danh từ","meaning":"làm việc; công việc","comps":"工作很忙 · 找工作 · 在医院工作","example":{"zh":"我爸爸在医院工作。","py":"Wǒ bàba zài yīyuàn gōngzuò.","vi":"Bố tôi làm việc ở bệnh viện."}},{"stt":11,"hanzi":"儿子","pinyin":"érzi","hanviet":"Nhi tử","pos":"Danh từ","meaning":"con trai","comps":"我儿子 · 大儿子 · 小儿子","example":{"zh":"你儿子在哪儿工作？","py":"Nǐ érzi zài nǎr gōngzuò?","vi":"Con trai bạn làm việc ở đâu?"}},{"stt":12,"hanzi":"医院","pinyin":"yīyuàn","hanviet":"Y viện","pos":"Danh từ","meaning":"bệnh viện","comps":"大医院 · 去医院 · 医院里","example":{"zh":"医院很大。","py":"Yīyuàn hěn dà.","vi":"Bệnh viện rất lớn."}},{"stt":13,"hanzi":"医生","pinyin":"yīshēng","hanviet":"Y sinh","pos":"Danh từ","meaning":"bác sĩ","comps":"好医生 · 男医生 · 女医生","example":{"zh":"我儿子是医生。","py":"Wǒ érzi shì yīshēng.","vi":"Con trai tôi là bác sĩ."}},{"stt":14,"hanzi":"爸爸","pinyin":"bàba","hanviet":"Bả bả","pos":"Danh từ","meaning":"bố, ba","comps":"我爸爸 · 爸爸妈妈 · 老爸","example":{"zh":"爸爸在家。","py":"Bàba zài jiā.","vi":"Bố ở nhà."}}],"hanzi":[{"char":"小","pinyin":"xiǎo","hanviet":"Tiểu","chars":["小"],"story":"小 — tượng hình ba chấm nhỏ, hai chấm hai bên + nét giữa → biểu thị sự nhỏ bé, ít."},{"char":"猫","pinyin":"māo","hanviet":"Miêu","chars":["猫"],"story":"猫 — bộ 犭(khuyển/động vật) + 苗 gợi âm 'māo'. Tiếng mèo kêu meo meo."},{"char":"在","pinyin":"zài","hanviet":"Tại","chars":["在"],"story":"在 — cây cỏ (才) đâm chồi trên đất (土) → tồn tại, hiện diện ở một nơi."},{"char":"那儿","pinyin":"nàr","hanviet":"Na nhi","chars":["那","儿"],"story":"那 (kia/đó) + 儿 (hậu tố 儿hoá Bắc Kinh) = chỗ kia. Thanh 4 — chỉ định."},{"char":"狗","pinyin":"gǒu","hanviet":"Cẩu","chars":["狗"],"story":"狗 — bộ 犭(khuyển) + 句 gợi âm 'gǒu'. Là con giáp Tuất."},{"char":"椅子","pinyin":"yǐzi","hanviet":"Ỷ tử","chars":["椅","子"],"story":"椅 — bộ 木 (gỗ) + 奇 (kỳ — gợi âm). 子 — hậu tố danh từ."},{"char":"下面","pinyin":"xiàmiàn","hanviet":"Hạ diện","chars":["下","面"],"story":"下 (dưới) + 面 (mặt/phía) = bề mặt phía dưới. Đối lập 上面 (phía trên)."},{"char":"在","pinyin":"zài","hanviet":"Tại","chars":["在"],"story":"Khi là giới từ, 在 đứng trước nơi chốn và trước động từ chính."},{"char":"哪儿","pinyin":"nǎr","hanviet":"Na nhi","chars":["哪","儿"],"story":"哪 (nào) + 儿 (儿hoá) = ở đâu. Thanh 3 — câu hỏi."},{"char":"工作","pinyin":"gōngzuò","hanviet":"Công tác","chars":["工","作"],"story":"工 (dụng cụ thợ) + 作 (làm/tạo) = hành động lao động có mục đích. Dùng cả N và V."},{"char":"儿子","pinyin":"érzi","hanviet":"Nhi tử","chars":["儿","子"],"story":"儿 (đứa trẻ — phồn 兒) + 子 (trẻ sơ sinh — hậu tố). Đối: 女儿 (con gái)."},{"char":"医院","pinyin":"yīyuàn","hanviet":"Y viện","chars":["医","院"],"story":"医 (y học — phồn 醫) + 院 (viện, khuôn viên) = nơi chữa bệnh có tổ chức."},{"char":"医生","pinyin":"yīshēng","hanviet":"Y sinh","chars":["医","生"],"story":"医 (y học) + 生 (người, người học) = người hành nghề y. Cùng cấu trúc: 学生."},{"char":"爸爸","pinyin":"bàba","hanviet":"Bả bả","chars":["爸","爸"],"story":"父 (cha) + 巴 (ba — gợi âm). Láy đôi 爸爸 tạo cảm giác thân mật."}],"grammar":[{"title":"Động từ \"在\" (zài) — chỉ vị trí","formula":"S + <span>在</span> + Nơi chốn / Phương hướng","summary":"<strong>在</strong> là động từ, sau nó là từ chỉ vị trí (nơi chốn/phương hướng) để làm vị ngữ, dùng để chỉ vị trí của người/vật. Lúc này 在 đứng <strong>một mình</strong>, không có động từ khác đi kèm.","note":"Phủ định: dùng <strong>不在</strong>. Câu hỏi có/không: thêm <strong>吗</strong> ở cuối.","examples":[{"zh":"我妈妈在家。","py":"Wǒ māma zài jiā.","vi":"Mẹ tôi ở nhà."},{"zh":"我朋友在学校。","py":"Wǒ péngyou zài xuéxiào.","vi":"Bạn tôi ở trường."},{"zh":"小狗在椅子下面。","py":"Xiǎo gǒu zài yǐzi xiàmiàn.","vi":"Cún ở dưới ghế."},{"zh":"爸爸在医院。","py":"Bàba zài yīyuàn.","vi":"Bố ở bệnh viện."},{"zh":"我的书在桌子上。","py":"Wǒ de shū zài zhuōzi shàng.","vi":"Sách của tôi ở trên bàn."},{"zh":"他不在家。","py":"Tā bú zài jiā.","vi":"Anh ấy không ở nhà."},{"zh":"你爸爸在家吗？","py":"Nǐ bàba zài jiā ma?","vi":"Bố bạn có ở nhà không?"},{"zh":"猫在那儿。","py":"Māo zài nàr.","vi":"Mèo ở chỗ đó."}]},{"title":"Đại từ nghi vấn \"哪儿\" (nǎr) — ở đâu?","formula":"S + 在 + <span>哪儿</span>？ &nbsp;|&nbsp; S + 在 + <span>哪儿</span> + V？","summary":"<strong>哪儿</strong> dùng trong câu hỏi để hỏi <strong>vị trí</strong> của người/vật. Đặt vào đúng vị trí mà câu trả lời sẽ điền nơi chốn vào.","note":"Trả lời: thay <strong>哪儿</strong> bằng tên nơi chốn cụ thể. <strong>哪儿</strong> (thanh 3) khác <strong>那儿</strong> (thanh 4 — chỗ đó).","examples":[{"zh":"我的杯子在哪儿？","py":"Wǒ de bēizi zài nǎr?","vi":"Cốc của tôi ở đâu?"},{"zh":"你的中国朋友在哪儿？","py":"Nǐ de Zhōngguó péngyou zài nǎr?","vi":"Bạn Trung Quốc của bạn ở đâu?"},{"zh":"小猫在哪儿？","py":"Xiǎo māo zài nǎr?","vi":"Mèo nhỏ ở đâu?"},{"zh":"你在哪儿？","py":"Nǐ zài nǎr?","vi":"Bạn ở đâu?"},{"zh":"他在哪儿工作？","py":"Tā zài nǎr gōngzuò?","vi":"Anh ấy làm việc ở đâu?"},{"zh":"你儿子在哪儿？","py":"Nǐ érzi zài nǎr?","vi":"Con trai bạn ở đâu?"},{"zh":"医院在哪儿？","py":"Yīyuàn zài nǎr?","vi":"Bệnh viện ở đâu?"},{"zh":"妈妈在哪儿？","py":"Māma zài nǎr?","vi":"Mẹ ở đâu?"}]},{"title":"Giới từ \"在\" (zài) — giới thiệu nơi xảy ra hành động","formula":"S + <span>在</span> + Nơi chốn + V + (O)","summary":"<strong>在</strong> còn là <strong>giới từ</strong>. Khi 在 làm giới từ, sau nó là từ chỉ vị trí, rồi đến <strong>động từ chính</strong>. Dùng để giới thiệu địa điểm/nơi chốn xảy ra hành động.","note":"Nhận biết: sau 在 + nơi chốn còn có <strong>động từ khác</strong> → 在 là giới từ (không phải động từ).","examples":[{"zh":"我在朋友家喝茶。","py":"Wǒ zài péngyou jiā hē chá.","vi":"Tôi uống trà ở nhà bạn."},{"zh":"他们在学校看书。","py":"Tāmen zài xuéxiào kàn shū.","vi":"Họ đọc sách ở trường."},{"zh":"我儿子在医院工作。","py":"Wǒ érzi zài yīyuàn gōngzuò.","vi":"Con trai tôi làm việc ở bệnh viện."},{"zh":"我在学校工作。","py":"Wǒ zài xuéxiào gōngzuò.","vi":"Tôi làm việc ở trường."},{"zh":"妈妈在饭馆吃饭。","py":"Māma zài fànguǎn chī fàn.","vi":"Mẹ ăn cơm ở quán ăn."},{"zh":"爸爸在家看电视。","py":"Bàba zài jiā kàn diànshì.","vi":"Bố xem TV ở nhà."},{"zh":"他在商店买东西。","py":"Tā zài shāngdiàn mǎi dōngxi.","vi":"Anh ấy mua đồ ở cửa hàng."},{"zh":"我们在公园跑步。","py":"Wǒmen zài gōngyuán pǎobù.","vi":"Chúng tôi chạy bộ ở công viên."}]},{"title":"Trợ từ nghi vấn \"呢\" (ne) — (2) hỏi vị trí","formula":"Người / Vật + <span>呢</span>？ &nbsp;|&nbsp; S + 在哪儿 + <span>呢</span>？","summary":"<strong>呢</strong> đặt cuối câu, tạo câu hỏi nhanh về <strong>vị trí</strong> của người/vật, hoặc hỏi \"còn ... thì sao?\" Khi đã có 哪儿 trong câu, thêm 呢 để câu hỏi mềm mại tự nhiên hơn.","note":"Lưu ý: <strong>không kết hợp</strong> với 吗. Câu đã có 呢 thì không thêm 吗.","examples":[{"zh":"我的小猫呢？","py":"Wǒ de xiǎo māo ne?","vi":"Mèo của tôi đâu rồi?"},{"zh":"我的杯子呢？","py":"Wǒ de bēizi ne?","vi":"Cốc của tôi đâu rồi?"},{"zh":"他在哪儿呢？","py":"Tā zài nǎr ne?","vi":"Anh ấy đang ở đâu vậy?"},{"zh":"你爸爸呢？","py":"Nǐ bàba ne?","vi":"Còn bố bạn thì sao?"},{"zh":"我儿子呢？","py":"Wǒ érzi ne?","vi":"Con trai tôi đâu rồi?"},{"zh":"你的书呢？","py":"Nǐ de shū ne?","vi":"Sách của bạn đâu?"},{"zh":"小狗在哪儿呢？","py":"Xiǎo gǒu zài nǎr ne?","vi":"Cún ở đâu vậy?"},{"zh":"妈妈在哪儿呢？","py":"Māma zài nǎr ne?","vi":"Mẹ ở đâu thế?"}]}],"text":{"title":"课文 · Bài khoá","blocks":[{"titleZh":"在家","titleVi":"Ở nhà","icon":"🏠","lines":[{"speaker":"A","zh":"小猫在哪儿？","py":"Xiǎo māo zài nǎr?","vi":"Con mèo đâu rồi?"},{"speaker":"B","zh":"小猫在那儿。","py":"Xiǎo māo zài nàr.","vi":"Nó ở chỗ kia kìa."},{"speaker":"A","zh":"小狗在哪儿？","py":"Xiǎo gǒu zài nǎr?","vi":"Còn con chó đâu?"},{"speaker":"B","zh":"小狗在椅子下面。","py":"Xiǎo gǒu zài yǐzi xiàmiàn.","vi":"Ở dưới ghế dựa."}]},{"titleZh":"在车站","titleVi":"Ở bến xe","icon":"🚏","lines":[{"speaker":"A","zh":"你在哪儿工作？","py":"Nǐ zài nǎr gōngzuò?","vi":"Anh làm việc ở đâu?"},{"speaker":"B","zh":"我在学校工作。","py":"Wǒ zài xuéxiào gōngzuò.","vi":"Tôi làm việc ở trường học."},{"speaker":"A","zh":"你儿子在哪儿工作？","py":"Nǐ érzi zài nǎr gōngzuò?","vi":"Vậy còn con trai anh?"},{"speaker":"B","zh":"我儿子在医院工作，他是医生。","py":"Wǒ érzi zài yīyuàn gōngzuò, tā shì yīshēng.","vi":"Con trai tôi làm việc ở bệnh viện, nó là bác sĩ."}]},{"titleZh":"打电话","titleVi":"Gọi điện thoại","icon":"📞","lines":[{"speaker":"A","zh":"你爸爸在家吗？","py":"Nǐ bàba zài jiā ma?","vi":"Cha cô có ở nhà không?"},{"speaker":"B","zh":"不在家。","py":"Bú zài jiā.","vi":"Không có."},{"speaker":"A","zh":"他在哪儿呢？","py":"Tā zài nǎr ne?","vi":"Ông ấy đâu rồi?"},{"speaker":"B","zh":"他在医院。","py":"Tā zài yīyuàn.","vi":"Ông ấy ở bệnh viện."}]}]},"extra":[{"label":"Mục tiêu","html":"<h2 class=\"section-title\">Mục tiêu bài học</h2>\n  <p class=\"section-sub\">Sau bài này, bạn có thể hỏi vị trí, nói nơi làm việc và nhận biết một số nghề nghiệp cơ bản.</p>\n  <div class=\"goals-grid\">\n    <div class=\"goal-card\">\n      <div class=\"goal-num\">01</div>\n      <div class=\"goal-title\">Giao tiếp</div>\n      <ul class=\"goal-list\">\n        <li>Hỏi vị trí người/vật: <b>... 在哪儿？</b></li>\n        <li>Trả lời vị trí: <b>... 在 + (nơi chốn)</b></li>\n        <li>Hỏi nơi làm việc: <b>你在哪儿工作？</b></li>\n        <li>Giới thiệu nghề: <b>他是医生</b>, <b>他在医院工作</b></li>\n        <li>Dùng <b>呢</b> để hỏi nhanh: <b>他在哪儿呢？</b></li>\n      </ul>\n    </div>\n    <div class=\"goal-card\">\n      <div class=\"goal-num\">02</div>\n      <div class=\"goal-title\">Từ vựng</div>\n      <ul class=\"goal-list\">\n        <li>14 từ trọng tâm bài 9</li>\n        <li>Con vật: <b>猫, 狗</b></li>\n        <li>Đồ vật & vị trí: <b>椅子, 下面, 那儿</b></li>\n        <li>Gia đình & nghề: <b>爸爸, 儿子, 医生</b></li>\n        <li>Nơi chốn & hành động: <b>医院, 工作</b></li>\n      </ul>\n    </div>\n    <div class=\"goal-card\">\n      <div class=\"goal-num\">03</div>\n      <div class=\"goal-title\">Ngữ pháp</div>\n      <ul class=\"goal-list\">\n        <li>Động từ <b>在</b> chỉ vị trí</li>\n        <li>Đại từ nghi vấn <b>哪儿</b></li>\n        <li>Giới từ <b>在</b> + nơi chốn + V</li>\n        <li>Trợ từ nghi vấn <b>呢</b> (2)</li>\n      </ul>\n    </div>\n  </div>"},{"label":"Vị trí & Nghề","html":"<h2 class=\"section-title\">Vị trí & Nghề nghiệp</h2>\n  <p class=\"section-sub\">Mở rộng vốn từ về địa điểm và nghề nghiệp — kết hợp cấu trúc \"在 + nơi chốn + 工作\".</p>\n\n  <div class=\"places-formula-box\">\n    <span class=\"label\">Cấu trúc lõi</span>\n    Chủ ngữ + <span>在</span> + Nơi chốn + <span>工作</span>\n  </div>\n  <div class=\"places-formula-box\" style=\"background:linear-gradient(135deg,var(--gold-dark) 0%, var(--gold) 100%);box-shadow:0 8px 22px -10px rgba(217,168,117,.5)\">\n    <span class=\"label\">Mở rộng — giới thiệu nghề</span>\n    Chủ ngữ + <span>是</span> + Nghề nghiệp, + 在 + Nơi + 工作\n  </div>\n\n  <h3 class=\"places-section-title\">📍 Nơi chốn thường gặp</h3>\n  <div class=\"places-grid\" id=\"placesGrid\"></div>\n\n  <h3 class=\"places-section-title\">💼 Nghề nghiệp cơ bản</h3>\n  <div class=\"places-grid\" id=\"jobsGrid\"></div>\n\n  <h3 class=\"places-section-title\">📐 Vị trí (phương vị)</h3>\n  <div class=\"places-grid\" id=\"posGrid\"></div>\n\n  <div class=\"tip-card\">\n    <h4>💡 Mẹo dùng \"在\"</h4>\n    <p><span class=\"zh\">在</span> là một chữ \"đa nhiệm\": vừa làm <strong>động từ</strong> (ở/tại) — đứng một mình (\"猫在椅子下面\"), vừa làm <strong>giới từ</strong> — đứng trước nơi chốn để dẫn vào động từ chính (\"在医院工作\"). Nhìn cấu trúc, nếu sau 在 còn có động từ khác → 在 là giới từ.</p>\n  </div>\n\n  <div class=\"mistake-card\">\n    <h4>⚠️ Lỗi thường gặp</h4>\n    <p style=\"font-size:14px;line-height:1.7\">\n      <span class=\"strike\">我工作在医院。</span> (Sai — không đảo trật tự)<br>\n      <span class=\"ok\">我在医院工作。</span> (Đúng — 在 + nơi chốn + V)\n    </p>\n  </div>"},{"label":"Lỗi sai","html":"<h2 class=\"section-title\">Lỗi sai thường gặp</h2>\n  <p class=\"section-sub\">5 lỗi điển hình khi học bài này — nhận diện sớm để tránh lặp lại.</p>\n  <div class=\"error-grid\">\n\n    <div class=\"error-box\">\n      <div class=\"err-head wrong\">Lỗi 1 · Đặt 在 + nơi chốn SAU động từ</div>\n      <div class=\"err-desc\">Khi 在 làm giới từ, \"在 + nơi chốn\" phải đứng <strong>trước</strong> động từ chính, không được đặt sau như tiếng Anh (\"work at hospital\").</div>\n      <ul class=\"err-list\">\n        <li class=\"strike zh\">我工作在医院。</li>\n        <li class=\"strike zh\">他学习在学校。</li>\n      </ul>\n      <div class=\"err-head correct\">Cách sửa</div>\n      <ul class=\"err-list\">\n        <li class=\"correct-text zh\">我在医院工作。</li>\n        <li class=\"correct-text zh\">他在学校学习。</li>\n      </ul>\n      <div class=\"err-note\">Quy tắc: S + 在 + Nơi chốn + V + (O)</div>\n    </div>\n\n    <div class=\"error-box\">\n      <div class=\"err-head wrong\">Lỗi 2 · Nhầm 哪儿 (nǎr) với 那儿 (nàr)</div>\n      <div class=\"err-desc\">Hai chữ rất giống nhưng <strong>khác hẳn nghĩa và thanh điệu</strong>: 哪儿 = đâu (nghi vấn, thanh 3); 那儿 = chỗ đó (chỉ định, thanh 4).</div>\n      <ul class=\"err-list\">\n        <li class=\"strike zh\">猫在那儿？ (ý \"ở đâu?\")</li>\n        <li class=\"strike zh\">猫在哪儿。(ý \"ở chỗ đó\")</li>\n      </ul>\n      <div class=\"err-head correct\">Cách sửa</div>\n      <ul class=\"err-list\">\n        <li class=\"correct-text zh\">猫在哪儿？ — Mèo ở đâu?</li>\n        <li class=\"correct-text zh\">猫在那儿。— Mèo ở chỗ đó.</li>\n      </ul>\n      <div class=\"err-note\">Mẹo nhớ: 哪 = thanh 3 (hỏi) ↔ 那 = thanh 4 (chỉ định).</div>\n    </div>\n\n    <div class=\"error-box\">\n      <div class=\"err-head wrong\">Lỗi 3 · Bỏ quên 在 khi nói vị trí</div>\n      <div class=\"err-desc\">Trong tiếng Việt nói \"Mèo dưới ghế\" hoặc \"Mẹ ở nhà\" có thể lược bớt; nhưng tiếng Trung <strong>bắt buộc</strong> có 在.</div>\n      <ul class=\"err-list\">\n        <li class=\"strike zh\">猫椅子下面。</li>\n        <li class=\"strike zh\">妈妈家。</li>\n      </ul>\n      <div class=\"err-head correct\">Cách sửa</div>\n      <ul class=\"err-list\">\n        <li class=\"correct-text zh\">猫在椅子下面。</li>\n        <li class=\"correct-text zh\">妈妈在家。</li>\n      </ul>\n    </div>\n\n    <div class=\"error-box\">\n      <div class=\"err-head wrong\">Lỗi 4 · Dùng sai 呢 và 吗</div>\n      <div class=\"err-desc\">Cả 2 đều là trợ từ nghi vấn nhưng dùng <strong>khác nhau</strong>: 吗 cuối câu trần thuật → câu hỏi có/không; 呢 cuối câu hỏi ngắn → hỏi lại vị trí/tình trạng.</div>\n      <ul class=\"err-list\">\n        <li class=\"strike zh\">爸爸在家呢？(ý \"Bố có ở nhà không?\")</li>\n        <li class=\"strike zh\">他在哪儿吗？(ý \"Anh ấy ở đâu?\")</li>\n      </ul>\n      <div class=\"err-head correct\">Cách sửa</div>\n      <ul class=\"err-list\">\n        <li class=\"correct-text zh\">爸爸在家吗？— Có ở nhà không?</li>\n        <li class=\"correct-text zh\">他在哪儿呢？— Anh ấy ở đâu vậy?</li>\n      </ul>\n      <div class=\"err-note\">呢 dùng với 哪儿 (có nghi vấn từ); 吗 dùng cho câu hỏi có/không (không có nghi vấn từ).</div>\n    </div>\n\n    <div class=\"error-box\">\n      <div class=\"err-head wrong\">Lỗi 5 · Đảo trật tự \"儿子\" và sở hữu</div>\n      <div class=\"err-desc\">Khi nói \"con trai của bạn\", tiếng Trung dùng <strong>người sở hữu trước</strong>: 你 + 儿子. Không thêm 的 sau đại từ nhân xưng cho quan hệ thân thiết.</div>\n      <ul class=\"err-list\">\n        <li class=\"strike zh\">儿子你在哪儿工作？</li>\n        <li class=\"strike zh\">你的儿子在哪儿工作？(không sai, nhưng kém tự nhiên)</li>\n      </ul>\n      <div class=\"err-head correct\">Cách sửa</div>\n      <ul class=\"err-list\">\n        <li class=\"correct-text zh\">你儿子在哪儿工作？</li>\n      </ul>\n      <div class=\"err-note\">Với quan hệ gia đình thân thiết, 的 thường được lược bỏ.</div>\n    </div>\n\n  </div>"},{"label":"Tổng hợp","html":"<h2 class=\"section-title\">Tổng hợp · Sơ đồ ghi nhớ</h2>\n  <p class=\"section-sub\">6 ô tổng hợp giúp khái quát toàn bài 9 — học một lần, nhớ lâu.</p>\n\n  <div class=\"syn-grid\">\n\n    <div class=\"syn-card theme-burgundy\">\n      <h3>🎯 3 tình huống giao tiếp</h3>\n      <div class=\"syn-flow\">\n        <div class=\"step burgundy\">Ở nhà</div>\n        <span class=\"arrow\">→</span>\n        <div class=\"step\">Tìm con vật</div>\n      </div>\n      <div class=\"syn-flow\">\n        <div class=\"step burgundy\">Ở bến xe</div>\n        <span class=\"arrow\">→</span>\n        <div class=\"step\">Hỏi nghề & nơi làm</div>\n      </div>\n      <div class=\"syn-flow\">\n        <div class=\"step burgundy\">Gọi điện</div>\n        <span class=\"arrow\">→</span>\n        <div class=\"step\">Hỏi người khác ở đâu</div>\n      </div>\n      <div class=\"syn-mnemonic\"><strong>Mẹo:</strong> Cứ thấy hỏi \"ở đâu?\" → trong đầu nghĩ ngay đến cấu trúc <strong>... 在哪儿？</strong></div>\n    </div>\n\n    <div class=\"syn-card theme-gold\">\n      <h3>🔑 Cấu trúc lõi nhất</h3>\n      <div class=\"syn-flow\">\n        <div class=\"step gold\">S</div>\n        <span class=\"arrow\">+</span>\n        <div class=\"step burgundy\">在</div>\n        <span class=\"arrow\">+</span>\n        <div class=\"step\">Nơi chốn</div>\n      </div>\n      <div class=\"syn-flow\">\n        <div class=\"step gold\">S</div>\n        <span class=\"arrow\">+</span>\n        <div class=\"step burgundy\">在</div>\n        <span class=\"arrow\">+</span>\n        <div class=\"step\">Nơi chốn</div>\n        <span class=\"arrow\">+</span>\n        <div class=\"step\">V</div>\n      </div>\n      <div class=\"syn-flow\">\n        <div class=\"step gold\">S</div>\n        <span class=\"arrow\">+</span>\n        <div class=\"step burgundy\">在哪儿</div>\n        <span class=\"arrow\">+</span>\n        <div class=\"step\">V (?)</div>\n      </div>\n      <div class=\"syn-mnemonic\"><strong>Quy tắc vàng:</strong> 在 đứng <strong>trước</strong> nơi chốn, không bao giờ đứng sau.</div>\n    </div>\n\n    <div class=\"syn-card theme-ink\">\n      <h3>💼 Nghề & Nơi làm việc</h3>\n      <table class=\"syn-table\">\n        <thead><tr><th>Nghề</th><th>Nơi làm</th><th>Mẫu câu</th></tr></thead>\n        <tbody>\n          <tr><td class=\"zh\">医生</td><td class=\"zh\">医院</td><td>他是医生，在医院工作。</td></tr>\n          <tr><td class=\"zh\">老师</td><td class=\"zh\">学校</td><td>她是老师，在学校工作。</td></tr>\n          <tr><td class=\"zh\">学生</td><td class=\"zh\">学校</td><td>我是学生，在学校学习。</td></tr>\n          <tr><td class=\"zh\">服务员</td><td class=\"zh\">饭馆</td><td>他在饭馆工作。</td></tr>\n        </tbody>\n      </table>\n      <div class=\"syn-mnemonic\"><strong>Lưu ý:</strong> Có thể nói 2 vế bằng dấu phẩy — nhanh và tự nhiên.</div>\n    </div>\n\n    <div class=\"syn-card theme-burgundy\">\n      <h3>📐 Phân biệt 哪儿 ↔ 那儿 ↔ 这儿</h3>\n      <table class=\"syn-table\">\n        <thead><tr><th>Chữ</th><th>Pinyin</th><th>Nghĩa</th></tr></thead>\n        <tbody>\n          <tr><td class=\"zh\">哪儿</td><td class=\"py\">nǎr</td><td>Ở đâu? (hỏi)</td></tr>\n          <tr><td class=\"zh\">那儿</td><td class=\"py\">nàr</td><td>Ở đó/kia</td></tr>\n          <tr><td class=\"zh\">这儿</td><td class=\"py\">zhèr</td><td>Ở đây</td></tr>\n        </tbody>\n      </table>\n      <div class=\"syn-mnemonic\"><strong>Mẹo:</strong> 3 chữ chỉ khác nhau ở thanh điệu và bộ thủ — đọc kỹ <strong>thanh 3 = hỏi</strong>, <strong>thanh 4 = chỉ định</strong>.</div>\n    </div>\n\n    <div class=\"syn-card theme-gold\">\n      <h3>📦 Tất cả 14 từ vựng</h3>\n      <table class=\"syn-table\">\n        <thead><tr><th>Nhóm</th><th>Từ</th></tr></thead>\n        <tbody>\n          <tr><td>Tính từ</td><td class=\"zh\">小</td></tr>\n          <tr><td>Con vật</td><td class=\"zh\">猫 · 狗</td></tr>\n          <tr><td>Vị trí</td><td class=\"zh\">在 · 哪儿 · 那儿 · 下面</td></tr>\n          <tr><td>Đồ vật</td><td class=\"zh\">椅子</td></tr>\n          <tr><td>Gia đình</td><td class=\"zh\">爸爸 · 儿子</td></tr>\n          <tr><td>Nghề/Nơi</td><td class=\"zh\">医生 · 医院 · 工作</td></tr>\n          <tr><td>Trợ từ</td><td class=\"zh\">呢</td></tr>\n        </tbody>\n      </table>\n      <div class=\"syn-mnemonic\"><strong>Học theo nhóm:</strong> 7 nhóm × 2 từ/nhóm = nhớ nhanh hơn học rời.</div>\n    </div>\n\n    <div class=\"syn-card theme-ink\">\n      <h3>⚡ 5 mẫu câu cần thuộc</h3>\n      <table class=\"syn-table\">\n        <thead><tr><th>#</th><th>Mẫu câu</th><th>Nghĩa</th></tr></thead>\n        <tbody>\n          <tr><td>1</td><td class=\"zh\">小猫在哪儿？</td><td>Mèo ở đâu?</td></tr>\n          <tr><td>2</td><td class=\"zh\">他在椅子下面。</td><td>Nó ở dưới ghế.</td></tr>\n          <tr><td>3</td><td class=\"zh\">你在哪儿工作？</td><td>Bạn làm việc ở đâu?</td></tr>\n          <tr><td>4</td><td class=\"zh\">我在医院工作，是医生。</td><td>Tôi làm ở bệnh viện, là bác sĩ.</td></tr>\n          <tr><td>5</td><td class=\"zh\">爸爸在家吗？</td><td>Bố có ở nhà không?</td></tr>\n        </tbody>\n      </table>\n      <div class=\"syn-mnemonic\"><strong>Thuộc 5 mẫu này = nắm trọn bài 9.</strong></div>\n    </div>\n\n  </div>"}],"cssId":"c7d43d0b3"},{"id":"k1v2-b10","courseId":"k1v2","order":10,"title":"Tôi có thể ngồi ở đây được không?","titleZh":"我能坐这儿吗？","vocab":[{"stt":1,"hanzi":"桌子","pinyin":"zhuōzi","hanviet":"Trác tử","pos":"Danh từ","meaning":"Bàn, cái bàn","comps":"一张桌子 · 桌子上 · 电脑桌","example":{"zh":"桌子上有什么？","py":"Zhuōzi shang yǒu shénme?","vi":"Trên bàn có gì?"}},{"stt":2,"hanzi":"上","pinyin":"shang","hanviet":"Thượng","pos":"Phương vị từ","meaning":"Trên, phía trên","comps":"上面 · 桌子上 · 上午","example":{"zh":"桌子上有一个电脑。","py":"Zhuōzi shang yǒu yí ge diànnǎo.","vi":"Trên bàn có một cái máy vi tính."}},{"stt":3,"hanzi":"电脑","pinyin":"diànnǎo","hanviet":"Điện não","pos":"Danh từ","meaning":"Máy vi tính","comps":"一台电脑 · 买电脑 · 玩电脑","example":{"zh":"我没有电脑。","py":"Wǒ méiyǒu diànnǎo.","vi":"Tôi không có máy tính."}},{"stt":4,"hanzi":"和","pinyin":"hé","hanviet":"Hòa","pos":"Liên từ","meaning":"Và, cùng","comps":"我和他 · 爸爸和妈妈","example":{"zh":"桌子上有一个电脑和一本书。","py":"Zhuōzi shang yǒu yí ge diànnǎo hé yì běn shū.","vi":"Trên bàn có một chiếc máy vi tính và một quyển sách."}},{"stt":5,"hanzi":"本","pinyin":"běn","hanviet":"Bản","pos":"Lượng từ","meaning":"Quyển, cuốn","comps":"一本书 · 两本 · 几本书","example":{"zh":"这是一本书。","py":"Zhè shì yì běn shū.","vi":"Đây là một quyển sách."}},{"stt":6,"hanzi":"里","pinyin":"li","hanviet":"Lý","pos":"Phương vị từ","meaning":"Trong, bên trong","comps":"里面 · 杯子里 · 家里","example":{"zh":"杯子在桌子里。","py":"Bēizi zài zhuōzi li.","vi":"Cái ly ở trong bàn."}},{"stt":7,"hanzi":"前面","pinyin":"qiánmiàn","hanviet":"Tiền diện","pos":"Phương vị từ","meaning":"Phía trước","comps":"前面的人 · 前天 · 前面","example":{"zh":"前面那个人叫什么名字？","py":"Qiánmiàn nàge rén jiào shénme míngzi?","vi":"Người phía trước tên là gì?"}},{"stt":8,"hanzi":"后面","pinyin":"hòumiàn","hanviet":"Hậu diện","pos":"Phương vị từ","meaning":"Phía sau","comps":"后来 · 后面的人","example":{"zh":"后面那个人在医院工作。","py":"Hòumiàn nàge rén zài yīyuàn gōngzuò.","vi":"Người phía sau làm việc ở bệnh viện."}},{"stt":9,"hanzi":"这儿","pinyin":"zhèr","hanviet":"Giá nhi","pos":"Đại từ","meaning":"Chỗ này, ở đây","comps":"来这儿 · 坐这儿","example":{"zh":"这儿有人吗？","py":"Zhèr yǒu rén ma?","vi":"Ở đây có người không?"}},{"stt":10,"hanzi":"没有","pinyin":"méiyǒu","hanviet":"Một hữu","pos":"Phó từ","meaning":"Không có, chưa","comps":"没有钱 · 没有人 · 没关系","example":{"zh":"这儿没有电脑。","py":"Zhèr méiyǒu diànnǎo.","vi":"Ở đây không có máy tính."}},{"stt":11,"hanzi":"能","pinyin":"néng","hanviet":"Năng","pos":"Động từ nn.","meaning":"Có thể, có năng lực","comps":"能够 · 不能 · 可能","example":{"zh":"我能坐这儿吗？","py":"Wǒ néng zuò zhèr ma?","vi":"Tôi có thể ngồi ở đây được không?"}},{"stt":12,"hanzi":"坐","pinyin":"zuò","hanviet":"Tọa","pos":"Động từ","meaning":"Ngồi, đi (xe)","comps":"坐下 · 请坐 · 坐车","example":{"zh":"请坐。","py":"Qǐng zuò.","vi":"Xin mời ngồi."}}],"hanzi":[{"char":"桌子","pinyin":"zhuōzi","hanviet":"Trác tử","chars":["桌","子"],"story":"Chữ 桌 (bàn) có bộ 木 (Mộc - gỗ) ở dưới, vì bàn ngày xưa làm bằng gỗ ghép lại."},{"char":"上","pinyin":"shang","hanviet":"Thượng","chars":["上"],"story":"Chữ chỉ sự (chỉ sự vật). Nét gạch ngang nhỏ nằm trên nét gạch ngang lớn, tượng trưng cho vị trí bên trên."},{"char":"电脑","pinyin":"diànnǎo","hanviet":"Điện não","chars":["电","脑"],"story":"电 (Điện) + 脑 (Não). Máy tính xử lý thông minh như bộ não con người nhờ năng lượng điện."},{"char":"和","pinyin":"hé","hanviet":"Hòa","chars":["和"],"story":"Bộ 禾 (Hòa - cây lúa) và 口 (Khẩu - miệng). Mọi người cùng chung miệng ăn lúa gạo thì sẽ hòa thuận."},{"char":"本","pinyin":"běn","hanviet":"Bản","chars":["本"],"story":"Một nét gạch ngang ở dưới bộ 木 (Mộc - gốc cây), vốn mang nghĩa là gốc rễ. Mở rộng làm lượng từ cho sách, tập."},{"char":"里","pinyin":"li","hanviet":"Lý","chars":["里"],"story":"Gồm bộ 田 (Điền - ruộng) và 土 (Thổ - đất). Nơi có ruộng đất là bên trong xóm làng."},{"char":"前面","pinyin":"qiánmiàn","hanviet":"Tiền diện","chars":["前","面"],"story":"Chữ 前 có bộ 刀 (Đao) ở trên 舟 (Chu). Cầm đao đứng trước mũi thuyền."},{"char":"后面","pinyin":"hòumiàn","hanviet":"Hậu diện","chars":["后","面"],"story":"Chữ 后 có bộ 彳 (Xích - bước đi nhỏ). Đi lùi, theo sau lưng người khác."},{"char":"这儿","pinyin":"zhèr","hanviet":"Giá nhi","chars":["这","儿"],"story":"这 (Này) kết hợp với âm cuốn lưỡi 儿 (nhi) tạo thành từ chỉ địa điểm \"Chỗ này\"."},{"char":"没有","pinyin":"méiyǒu","hanviet":"Một hữu","chars":["没","有"],"story":"Chữ 没 có bộ 氵(Thủy - nước). Đồ vật chìm xuống nước là coi như không còn (không có)."},{"char":"能","pinyin":"néng","hanviet":"Năng","chars":["能"],"story":"Hình ảnh con gấu (Hùng) to lớn, mạnh mẽ, biểu tượng cho năng lực (có thể làm được gì đó)."},{"char":"坐","pinyin":"zuò","hanviet":"Tọa","chars":["坐"],"story":"Gồm hai chữ 人 (Nhân) ngồi trên chữ 土 (Thổ - mặt đất). Hai người cùng ngồi trên đất."}],"grammar":[{"title":"Câu tồn tại với 有 (yǒu)","formula":"Địa điểm / Vị trí + <span>有 / 没有</span> + Người / Vật","summary":"Động từ 有 có thể dùng để diễn tả sự tồn tại, cho biết một người hoặc sự vật đang ở vị trí, địa điểm nào đó.","note":"<strong>Lưu ý:</strong> Dạng phủ định là <b>没有</b>. Khi dùng phủ định, phía trước Tân ngữ không dùng định ngữ chỉ số lượng.","examples":[{"zh":"桌子上有一个电脑和一本书。","py":"Zhuōzi shang yǒu yí ge diànnǎo hé yì běn shū.","vi":"Trên bàn có một máy tính và một quyển sách."},{"zh":"椅子下面有一只小狗。","py":"Yǐzi xiàmiàn yǒu yì zhī xiǎogǒu.","vi":"Dưới ghế có một con chó nhỏ."},{"zh":"学校里有一个商店。","py":"Xuéxiào li yǒu yí ge shāngdiàn.","vi":"Trong trường có một cửa hàng."},{"zh":"这儿有人吗？","py":"Zhèr yǒu rén ma?","vi":"Ở đây có người không?"},{"zh":"椅子下面没有小狗。","py":"Yǐzi xiàmiàn méiyǒu xiǎogǒu.","vi":"Dưới ghế không có chó nhỏ."},{"zh":"学校里没有商店。","py":"Xuéxiào li méiyǒu shāngdiàn.","vi":"Trong trường không có cửa hàng."},{"zh":"桌子上没有电脑和书。","py":"Zhuōzi shang méiyǒu diànnǎo hé shū.","vi":"Trên bàn không có máy tính và sách."},{"zh":"杯子里没有茶。","py":"Bēizi li méiyǒu chá.","vi":"Trong ly không có trà."}]},{"title":"Liên từ 和 (hé)","formula":"Danh từ 1 + <span>和</span> + Danh từ 2","summary":"Dùng để nối 2 hoặc nhiều thành phần ngang nhau (thường là danh từ/đại từ), thể hiện quan hệ song song.","note":"<strong>Tuyệt đối không dùng:</strong> 和 để nối 2 vế câu hoặc 2 hành động.","examples":[{"zh":"我有一个中国朋友和一个美国朋友。","py":"Wǒ yǒu yí ge Zhōngguó péngyǒu hé yí ge Měiguó péngyǒu.","vi":"Tôi có một người bạn Trung Quốc và một người bạn Mỹ."},{"zh":"我家有三口人，爸爸、妈妈和我。","py":"Wǒ jiā yǒu sān kǒu rén, bàba, māma hé wǒ.","vi":"Nhà tôi có 3 người, bố, mẹ và tôi."},{"zh":"桌子上有一个电脑和一本书。","py":"Zhuōzi shang yǒu yí ge diànnǎo hé yì běn shū.","vi":"Trên bàn có một cái máy tính và một quyển sách."},{"zh":"我和他都是老师。","py":"Wǒ hé tā dōu shì lǎoshī.","vi":"Tôi và anh ấy đều là giáo viên."},{"zh":"我喜欢吃苹果和香蕉。","py":"Wǒ xǐhuan chī píngguǒ hé xiāngjiāo.","vi":"Tôi thích ăn táo và chuối."},{"zh":"今天和明天都不下雨。","py":"Jīntiān hé míngtiān dōu bú xià yǔ.","vi":"Hôm nay và ngày mai đều không mưa."},{"zh":"你和她去商店吗？","py":"Nǐ hé tā qù shāngdiàn ma?","vi":"Bạn và cô ấy đi cửa hàng không?"},{"zh":"大卫和玛丽是学生。","py":"Dàwèi hé Mǎlì shì xuésheng.","vi":"David và Mary là học sinh."}]},{"title":"Động từ năng nguyện 能 (néng)","formula":"Chủ ngữ + <span>能</span> + Động từ + (吗?)","summary":"Đứng trước động từ khác để biểu thị năng lực, hoặc dùng trong câu hỏi \"能...吗？\" để diễn tả sự xin phép, thỉnh cầu.","note":"<strong>Trả lời:</strong> Đồng ý nói \"能\" hoặc \"可以\", từ chối nói \"不能\".","examples":[{"zh":"我能坐这儿吗？","py":"Wǒ néng zuò zhèr ma?","vi":"Tôi có thể ngồi ở đây được không?"},{"zh":"你能在这儿写你的名字吗？","py":"Nǐ néng zài zhèr xiě nǐ de míngzi ma?","vi":"Bạn có thể viết tên của bạn ở đây không?"},{"zh":"明天下午我能去商店。","py":"Míngtiān xiàwǔ wǒ néng qù shāngdiàn.","vi":"Chiều ngày mai tôi có thể đi cửa hàng."},{"zh":"你能听懂老师的话吗？","py":"Nǐ néng tīngdǒng lǎoshī de huà ma?","vi":"Bạn có thể nghe hiểu lời thầy giáo không?"},{"zh":"下午你能来我家吗？","py":"Xiàwǔ nǐ néng lái wǒ jiā ma?","vi":"Buổi chiều bạn có thể đến nhà tôi không?"},{"zh":"你能不能明天去？","py":"Nǐ néng bu néng míngtiān qù?","vi":"Bạn có thể đi vào ngày mai không?"},{"zh":"这儿不能看书。","py":"Zhèr bù néng kàn shū.","vi":"Ở đây không thể đọc sách."},{"zh":"我能吃一个苹果吗？","py":"Wǒ néng chī yí ge píngguǒ ma?","vi":"Tôi có thể ăn một quả táo được không?"}]}],"text":{"title":"课文 · Bài khoá","blocks":[{"titleZh":"在办公室","titleVi":"Trong văn phòng","icon":"🏢","lines":[{"speaker":"A","zh":"桌子上有什么？","py":"Zhuōzi shang yǒu shénme?","vi":"Trên bàn có gì vậy?"},{"speaker":"B","zh":"桌子上有一个电脑和一本书。","py":"Zhuōzi shang yǒu yí ge diànnǎo hé yì běn shū.","vi":"Trên bàn có một chiếc máy vi tính và một quyển sách."},{"speaker":"A","zh":"杯子在哪儿？","py":"Bēizi zài năr?","vi":"Vậy cái ly đâu?"},{"speaker":"B","zh":"杯子在桌子里。","py":"Bēizi zài zhuōzi li.","vi":"Cái ly ở trong bàn."}]},{"titleZh":"在健身房","titleVi":"Trong phòng tập thể dục","icon":"🏋️","lines":[{"speaker":"A","zh":"前面那个人叫什么名字？","py":"Qiánmiàn nàge rén jiào shénme míngzi?","vi":"Người ở phía trước tên gì vậy?"},{"speaker":"B","zh":"她叫王方，在医院工作。","py":"Tā jiào Wáng Fāng, zài yīyuàn gōngzuò.","vi":"Cô ấy tên là Vương Phương, làm việc ở bệnh viện."},{"speaker":"A","zh":"后面那个人呢？他叫什么名字？","py":"Hòumiàn nàge rén ne? Tā jiào shénme míngzi?","vi":"Còn người ở phía sau? Anh ấy tên gì?"},{"speaker":"B","zh":"他叫谢朋，在商店工作。","py":"Tā jiào Xiè Péng, zài shāngdiàn gōngzuò.","vi":"Anh ấy tên Tạ Bằng, làm việc ở cửa hàng."}]},{"titleZh":"在图书馆","titleVi":"Ở thư viện","icon":"📚","lines":[{"speaker":"A","zh":"这儿有人吗？","py":"Zhèr yǒu rén ma?","vi":"Chỗ này có ai ngồi chưa?"},{"speaker":"B","zh":"没有。","py":"Méiyǒu.","vi":"Chưa."},{"speaker":"A","zh":"我能坐这儿吗？","py":"Wǒ néng zuò zhèr ma?","vi":"Tôi có thể ngồi ở đây được không?"},{"speaker":"B","zh":"请坐。","py":"Qǐng zuò.","vi":"Được, xin mời."}]}]},"extra":[{"label":"Mục tiêu","html":"<h2 class=\"section-title\">Mục tiêu bài học</h2>\n  <p class=\"section-sub\">Bài 10 trang bị cho học viên kỹ năng miêu tả vị trí không gian, diễn tả sự tồn tại và cách xin phép lịch sự bằng tiếng Trung.</p>\n  <div class=\"goal-grid\">\n    <div class=\"goal-item\">\n      <div class=\"num\">01</div>\n      <h4>Giao tiếp</h4>\n      <ul>\n        <li>Diễn đạt <b>vị trí, phương hướng</b> của người và vật.</li>\n        <li>Miêu tả sự <b>tồn tại</b> ở một địa điểm nào đó.</li>\n        <li>Biết cách <b>xin phép</b> thực hiện một hành động (như xin ngồi).</li>\n      </ul>\n    </div>\n    <div class=\"goal-item\">\n      <div class=\"num\">02</div>\n      <h4>Từ vựng</h4>\n      <ul>\n        <li>Phương vị từ: <b>上, 里, 前面, 后面</b></li>\n        <li>Đồ vật: <b>桌子, 电脑, 本</b></li>\n        <li>Động từ: <b>能, 坐</b></li>\n        <li>Hư từ: <b>和, 没有, 这儿</b></li>\n      </ul>\n    </div>\n    <div class=\"goal-item\">\n      <div class=\"num\">03</div>\n      <h4>Ngữ pháp</h4>\n      <ul>\n        <li>Câu biểu đạt sự tồn tại với <b>有</b> (Có).</li>\n        <li>Liên từ <b>和</b> (Và) để nối các danh từ.</li>\n        <li>Động từ năng nguyện <b>能</b> (Có thể).</li>\n        <li>Câu cầu khiến với <b>请</b> (Xin mời).</li>\n      </ul>\n    </div>\n  </div>"},{"label":"Định vị & Văn hoá","html":"<h2 class=\"section-title\">Định vị Không gian &amp; Văn hoá</h2>\n  <p class=\"section-sub\">Tìm hiểu quy tắc diễn đạt phương hướng trong tiếng Trung và văn hoá gọi tên của người bản xứ.</p>\n\n  <div class=\"card\">\n    <h3>1. Phương vị từ cơ bản (Từ chỉ vị trí)</h3>\n    <p>Trong tiếng Trung, để chỉ vị trí, ta phải kết hợp: <b>Danh từ + Phương vị từ</b> (ngược lại so với tiếng Việt).</p>\n    \n    <div class=\"space-grid\">\n      <div class=\"space-item\">\n        <div class=\"space-hz\">上</div>\n        <div class=\"space-py\">shang</div>\n        <div class=\"space-vi\">Bên trên</div>\n        <div class=\"space-ex\">桌子上 (Trên bàn)</div>\n      </div>\n      <div class=\"space-item\">\n        <div class=\"space-hz\">里</div>\n        <div class=\"space-py\">li</div>\n        <div class=\"space-vi\">Bên trong</div>\n        <div class=\"space-ex\">杯子里 (Trong ly)</div>\n      </div>\n      <div class=\"space-item\">\n        <div class=\"space-hz\">前面</div>\n        <div class=\"space-py\">qiánmiàn</div>\n        <div class=\"space-vi\">Phía trước</div>\n        <div class=\"space-ex\">前面的人 (Người phía trước)</div>\n      </div>\n      <div class=\"space-item\">\n        <div class=\"space-hz\">后面</div>\n        <div class=\"space-py\">hòumiàn</div>\n        <div class=\"space-vi\">Phía sau</div>\n        <div class=\"space-ex\">后面的电脑 (Máy tính phía sau)</div>\n      </div>\n    </div>\n    \n    <div class=\"formula-box\">\n      <div class=\"formula-label\">Quy tắc vàng định vị</div>\n      <div class=\"formula\">Nơi chốn = Danh từ + <span class=\"pop gold\">Phương vị từ</span></div>\n    </div>\n    <p style=\"text-align:center; color:var(--muted); font-size:0.95rem;\"><em>Ví dụ:</em> Thay vì nói \"上桌子\" (sai), phải nói \"桌子上\" (đúng).</p>\n  </div>\n\n  <div class=\"card\">\n    <h3>2. Văn hoá: Họ tên người Trung Quốc</h3>\n    <p>Khác với phương Tây, tên người Trung Quốc tuân theo quy tắc: <b>Họ trước, Tên sau</b>.</p>\n    \n    <ul style=\"margin-top: 14px;\">\n      <li><b>Họ (姓氏):</b> Đa số là \"Họ đơn\" (单姓) gồm 1 chữ như 张 (Trương), 王 (Vương), 李 (Lý), 赵 (Triệu). Có khoảng hơn 5000 họ nhưng dùng phổ biến chỉ khoảng hơn 200.</li>\n      <li><b>Họ kép (复姓):</b> Gồm 2 chữ trở lên như 欧阳 (Âu Dương), 诸葛 (Gia Cát), 上官 (Thượng Quan).</li>\n    </ul>\n\n    <div class=\"tip-card\">\n      <h5>💡 Cách xưng hô lịch sự nơi công sở</h5>\n      <p>Khi gọi một người theo tính chất công việc hoặc để thể hiện sự tôn trọng, người Trung Quốc dùng cấu trúc:</p>\n      <p style=\"font-family:'Noto Sans SC',sans-serif; font-size:1.15rem; color:var(--burgundy); font-weight:600; margin: 8px 0; text-align:center;\">Họ + Chức danh / Nghề nghiệp</p>\n      <p><em>Ví dụ:</em></p>\n      <p>✔️ <b>李老师</b> (Lǐ lǎoshī - Cô Lý / Thầy Lý)</p>\n      <p>✔️ <b>王医生</b> (Wáng yīshēng - Bác sĩ Vương)</p>\n    </div>\n  </div>"},{"label":"Lỗi sai","html":"<h2 class=\"section-title\">Lỗi sai thường gặp</h2>\n  <p class=\"section-sub\">Ba lỗi điển hình của người Việt khi học Bài 10.</p>\n  <div class=\"error-grid\">\n    <div class=\"error-box\">\n      <div class=\"err-head wrong\">Lỗi 1 · Xếp sai vị trí Phương vị từ</div>\n      <div class=\"err-body\">\n        <p style=\"margin-bottom:12px\">Do thói quen tiếng Việt \"Trên bàn\", \"Trong phòng\", học viên thường đặt từ chỉ phương hướng lên trước Danh từ.</p>\n        <p class=\"strike zh\">上有电脑。</p>\n        <p class=\"strike zh\">里有没有人？</p>\n      </div>\n      <div class=\"err-head correct\">Cách sửa</div>\n      <div class=\"err-body\">\n        <p class=\"correct-text zh\">桌子上有电脑。</p>\n        <p class=\"correct-text zh\">杯子里没有茶。</p>\n        <p style=\"font-size:.88rem;color:var(--muted);margin-top:6px\">Luôn nhớ: Danh từ làm mốc + Phương vị từ (桌子 + 上).</p>\n      </div>\n    </div>\n    <div class=\"error-box\">\n      <div class=\"err-head wrong\">Lỗi 2 · Dùng sai dạng phủ định của 有</div>\n      <div class=\"err-body\">\n        <p style=\"margin-bottom:12px\">Phủ định của các động từ thông thường là 不, nhưng phủ định của 有 (Có) bắt buộc phải là 没 (Không có).</p>\n        <p class=\"strike zh\">我不用电脑。</p>\n        <p class=\"strike zh\">桌子上不有书。</p>\n      </div>\n      <div class=\"err-head correct\">Cách sửa</div>\n      <div class=\"err-body\">\n        <p class=\"correct-text zh\">我没有电脑。</p>\n        <p class=\"correct-text zh\">桌子上没有书。</p>\n      </div>\n    </div>\n    <div class=\"error-box\">\n      <div class=\"err-head wrong\">Lỗi 3 · Dùng 和 để nối câu</div>\n      <div class=\"err-body\">\n        <p style=\"margin-bottom:12px\">Liên từ 和 (Và) trong tiếng Trung chỉ dùng để nối <b>Danh từ</b> hoặc <b>Đại từ</b>, tuyệt đối không dùng để nối 2 câu hoặc 2 vế câu.</p>\n        <p class=\"strike zh\">他去商店和买杯子。</p>\n      </div>\n      <div class=\"err-head correct\">Cách sửa</div>\n      <div class=\"err-body\">\n        <p class=\"correct-text zh\">他去商店买杯子。</p>\n        <p style=\"font-size:.88rem;color:var(--muted);margin-top:6px\">Nối 2 hành động liên tiếp, ta dùng dấu phẩy hoặc không cần từ nối. \"我和他\" (Tôi và anh ấy) mới đúng.</p>\n      </div>\n    </div>\n  </div>"},{"label":"Tổng hợp","html":"<h2 class=\"section-title\">Tổng hợp kiến thức</h2>\n  <p class=\"section-sub\">Sơ đồ ngắn gọn, dễ nhớ nhất — gom toàn bộ Bài 10 theo cách giảng viên hay dùng trên lớp.</p>\n\n  <div class=\"syn-grid\">\n    <div class=\"syn-card theme-burgundy\">\n      <div class=\"syn-icon\">📍</div>\n      <h3>Định vị bằng 有</h3>\n      <p>Cấu trúc diễn tả sự tồn tại:</p>\n      <div class=\"syn-flow\">\n        <div class=\"step\">Vị trí<br><span class=\"syn-keyhz\">桌子上</span></div>\n        <span class=\"arrow\">+</span>\n        <div class=\"step\">Tồn tại<br><span class=\"syn-keyhz\">有 / 没有</span></div>\n        <span class=\"arrow\">+</span>\n        <div class=\"step\">Vật/Người<br><span class=\"syn-keyhz\">一本书</span></div>\n      </div>\n      <div class=\"syn-mnemonic\"><strong>Mẹo:</strong> \"Ở đâu đó\" + \"có\" + \"cái gì\". (Phủ định dùng <strong>没</strong>, không dùng 不).</div>\n    </div>\n\n    <div class=\"syn-card theme-gold\">\n      <div class=\"syn-icon\">🤝</div>\n      <h3>Chữ vàng: <span class=\"syn-keyhz\">能</span></h3>\n      <p>Dùng để biểu thị khả năng hoặc <b>xin phép</b> làm điều gì đó.</p>\n      <div class=\"syn-flow\">\n        <div class=\"step\">S + <span class=\"syn-keyhz\">能</span><br><small>Có thể</small></div>\n        <span class=\"arrow\">→</span>\n        <div class=\"step\">+ Động từ<br><small>坐</small></div>\n        <span class=\"arrow\">→</span>\n        <div class=\"step\">+ 吗?<br><small>được không?</small></div>\n      </div>\n      <div class=\"syn-mnemonic\"><strong>Ứng dụng:</strong> <span class=\"syn-keyhz\">我能坐这儿吗？</span> (Tôi có thể ngồi đây không?) - <span class=\"syn-keyhz\">请坐</span> (Mời ngồi).</div>\n    </div>\n\n    <div class=\"syn-card theme-ink\">\n      <div class=\"syn-icon\">🧭</div>\n      <h3>4 Phương vị từ lõi</h3>\n      <table class=\"syn-table\">\n        <tr><th>Chữ Hán</th><th>Vị trí</th></tr>\n        <tr><td><span class=\"syn-keyhz\">上</span> (shang)</td><td>Trên (桌子上 - Trên bàn)</td></tr>\n        <tr><td><span class=\"syn-keyhz\">里</span> (li)</td><td>Trong (杯子里 - Trong ly)</td></tr>\n        <tr><td><span class=\"syn-keyhz\">前面</span> (qiánmiàn)</td><td>Phía trước (前面的人)</td></tr>\n        <tr><td><span class=\"syn-keyhz\">后面</span> (hòumiàn)</td><td>Phía sau (那个人后面)</td></tr>\n      </table>\n      <div class=\"syn-mnemonic\"><strong>Luôn nhớ:</strong> Danh từ luôn đứng TRƯỚC từ chỉ phương hướng.</div>\n    </div>\n\n    <div class=\"syn-card theme-burgundy\">\n      <div class=\"syn-icon\">🔗</div>\n      <h3>Cái bẫy liên từ <span class=\"syn-keyhz\">和</span></h3>\n      <p>Tuyệt đối lưu ý về từ \"Và\" (和):</p>\n      <div class=\"syn-flow\">\n        <div class=\"step\">N1<br><span class=\"syn-keyhz\">我</span></div>\n        <span class=\"arrow\">+</span>\n        <div class=\"step\"><span class=\"syn-keyhz\">和</span><br><small>Và</small></div>\n        <span class=\"arrow\">+</span>\n        <div class=\"step\">N2<br><span class=\"syn-keyhz\">他</span></div>\n      </div>\n      <div class=\"syn-mnemonic\"><strong>Cấm kỵ:</strong> Không dùng 和 để nối 2 hành động (Không nói: 我吃饭和你喝茶 ✕).</div>\n    </div>\n\n    <div class=\"syn-card theme-gold\" style=\"grid-column: 1 / -1;\">\n      <div class=\"syn-icon\">⚡</div>\n      <h3>Câu thần chú 5 mẫu</h3>\n      <table class=\"syn-table\">\n        <tr><th>Mẫu</th><th>Tình huống</th></tr>\n        <tr><td><span class=\"syn-keyhz\">桌子上有什么？</span></td><td>Hỏi xem trên đó có gì</td></tr>\n        <tr><td><span class=\"syn-keyhz\">杯子在哪儿？</span></td><td>Hỏi vị trí đồ vật</td></tr>\n        <tr><td><span class=\"syn-keyhz\">前面那个人叫什么名字？</span></td><td>Hỏi tên người đang ở vị trí cụ thể</td></tr>\n        <tr><td><span class=\"syn-keyhz\">这儿有人吗？</span></td><td>Hỏi xem chỗ đã có người chưa</td></tr>\n        <tr><td><span class=\"syn-keyhz\">我能坐这儿吗？</span></td><td>Xin phép ngồi</td></tr>\n      </table>\n      <div class=\"syn-mnemonic\"><strong>Thuộc 5 mẫu này là pass Bài 10.</strong></div>\n    </div>\n  </div>"}],"cssId":"cabeb2241"},{"id":"k1v2-b11","courseId":"k1v2","order":11,"title":"Bây giờ là mấy giờ?","titleZh":"现在几点？","vocab":[{"stt":1,"hanzi":"现在","pinyin":"xiànzài","hanviet":"Hiện tại","pos":"Danh từ","meaning":"Bây giờ, hiện tại","comps":"现在几点 · 到现在","example":{"zh":"现在几点？","py":"Xiànzài jǐ diǎn?","vi":"Bây giờ là mấy giờ?"}},{"stt":2,"hanzi":"点","pinyin":"diǎn","hanviet":"Điểm","pos":"Lượng từ","meaning":"Giờ; chấm","comps":"几点 · 八点 · 一点儿","example":{"zh":"现在十点。","py":"Xiànzài shí diǎn.","vi":"Bây giờ là 10 giờ."}},{"stt":3,"hanzi":"分","pinyin":"fēn","hanviet":"Phân","pos":"Lượng từ","meaning":"Phút; chia ra","comps":"十分 · 五十分钟","example":{"zh":"现在十点十分。","py":"Xiànzài shí diǎn shí fēn.","vi":"Bây giờ là 10 giờ 10 phút."}},{"stt":4,"hanzi":"中午","pinyin":"zhōngwǔ","hanviet":"Trung ngọ","pos":"Danh từ","meaning":"Buổi trưa","comps":"中午好 · 今天中午","example":{"zh":"中午几点吃饭？","py":"Zhōngwǔ jǐ diǎn chī fàn?","vi":"Trưa mấy giờ ăn cơm?"}},{"stt":5,"hanzi":"吃饭","pinyin":"chī fàn","hanviet":"Cật phạn","pos":"Động từ","meaning":"Ăn cơm, dùng bữa","comps":"吃早饭 · 去吃饭","example":{"zh":"我们十二点吃饭。","py":"Wǒmen shí'èr diǎn chī fàn.","vi":"Chúng tôi 12 giờ ăn cơm."}},{"stt":6,"hanzi":"时候","pinyin":"shíhou","hanviet":"Thời hậu","pos":"Danh từ","meaning":"Lúc, khi, thời gian","comps":"什么时候 · 小时候","example":{"zh":"爸爸什么时候回家？","py":"Bàba shénme shíhou huí jiā?","vi":"Bố khi nào về nhà?"}},{"stt":7,"hanzi":"回","pinyin":"huí","hanviet":"Hồi","pos":"Động từ","meaning":"Về, trở về","comps":"回家 · 回国 · 回来","example":{"zh":"他下午五点回家。","py":"Tā xiàwǔ wǔ diǎn huí jiā.","vi":"Anh ấy 5 giờ chiều về nhà."}},{"stt":8,"hanzi":"我们","pinyin":"wǒmen","hanviet":"Ngã môn","pos":"Đại từ","meaning":"Chúng tôi, chúng ta","comps":"我们的 · 我们家","example":{"zh":"我们什么时候去？","py":"Wǒmen shénme shíhou qù?","vi":"Khi nào chúng ta đi?"}},{"stt":9,"hanzi":"电影","pinyin":"diànyǐng","hanviet":"Điện ảnh","pos":"Danh từ","meaning":"Phim, điện ảnh","comps":"看电影 · 好电影","example":{"zh":"我们去看电影。","py":"Wǒmen qù kàn diànyǐng.","vi":"Chúng ta đi xem phim."}},{"stt":10,"hanzi":"住","pinyin":"zhù","hanviet":"Trú","pos":"Động từ","meaning":"Ở, cư trú","comps":"住在 · 住房","example":{"zh":"你想在北京住几天？","py":"Nǐ xiǎng zài Běijīng zhù jǐ tiān?","vi":"Bạn muốn ở Bắc Kinh mấy ngày?"}},{"stt":11,"hanzi":"前","pinyin":"qián","hanviet":"Tiền","pos":"Danh từ","meaning":"Trước, phía trước","comps":"前面 · 三天前","example":{"zh":"星期五前能回家吗？","py":"Xīngqīwǔ qián néng huí jiā ma?","vi":"Trước thứ Sáu có thể về nhà không?"}},{"stt":12,"hanzi":"北京","pinyin":"Běijīng","hanviet":"Bắc Kinh","pos":"Danh từ riêng","meaning":"Bắc Kinh","comps":"去北京 · 北京人","example":{"zh":"我星期一去北京。","py":"Wǒ xīngqīyī qù Běijīng.","vi":"Thứ Hai tôi đi Bắc Kinh."}}],"hanzi":[{"char":"现在","pinyin":"xiànzài","hanviet":"Hiện tại","chars":["现","在"],"story":"现 (hiện ra) + 在 (tồn tại). Cái đang tồn tại, hiện diện ngay lúc này."},{"char":"点","pinyin":"diǎn","hanviet":"Điểm","chars":["点"],"story":"Bên dưới có 4 chấm hỏa (灬), tượng trưng cho những đốm lửa nhỏ. Dùng để chỉ một điểm thời gian (giờ)."},{"char":"分","pinyin":"fēn","hanviet":"Phân","chars":["分"],"story":"Bộ Bát (八 - chia cắt) ở trên, bộ Đao (刀 - con dao) ở dưới. Dùng dao chia nhỏ ra. Một giờ chia nhỏ thành các phút."},{"char":"中午","pinyin":"zhōngwǔ","hanviet":"Trung ngọ","chars":["中","午"],"story":"中 (giữa) + 午 (ngọ, lúc mặt trời đứng bóng). Điểm giữa của một ngày."},{"char":"吃饭","pinyin":"chī fàn","hanviet":"Cật phạn","chars":["吃","饭"],"story":"吃 (ăn) + 饭 (cơm). Hoạt động thiết yếu mỗi ngày."},{"char":"时候","pinyin":"shíhou","hanviet":"Thời hậu","chars":["时","候"],"story":"时 (thời gian, có bộ Nhật 日) + 候 (chờ đợi). Khoảng thời gian xảy ra sự việc."},{"char":"回","pinyin":"huí","hanviet":"Hồi","chars":["回"],"story":"Chữ tượng hình, vòng vuông nhỏ nằm trong vòng vuông lớn, tượng trưng cho sự quay vòng, trở lại điểm xuất phát."},{"char":"我们","pinyin":"wǒmen","hanviet":"Ngã môn","chars":["我","们"],"story":"我 (tôi) + 们 (hậu tố số nhiều cho người)."},{"char":"电影","pinyin":"diànyǐng","hanviet":"Điện ảnh","chars":["电","影"],"story":"电 (điện) + 影 (bóng). Hình bóng chuyển động nhờ điện năng tạo ra phim ảnh."},{"char":"住","pinyin":"zhù","hanviet":"Trú","chars":["住"],"story":"Bộ Nhân đứng (亻) và chữ Chủ (主). Người làm chủ một nơi nào đó thì sống/ở tại đó."},{"char":"前","pinyin":"qián","hanviet":"Tiền","chars":["前"],"story":"Hình ảnh chiếc thuyền (舟) tiến lên phía trước bằng mái chèo (刀)."},{"char":"北京","pinyin":"Běijīng","hanviet":"Bắc Kinh","chars":["北","京"],"story":"北 (phía Bắc) + 京 (kinh đô). Kinh đô nằm ở phía Bắc của Trung Quốc."}],"grammar":[{"title":"Cách diễn tả thời gian (Giờ / Phút)","formula":"(<span>上午 / 下午</span>) + Số + <span>点</span> + Số + <span>分</span>","summary":"Tiếng Trung dùng <b>点</b> (giờ) và <b>分</b> (phút) để nói giờ. Tuân thủ thứ tự từ lớn đến nhỏ.","note":"<strong>Chú ý:</strong> 2 giờ là <b>两点</b> (liǎng diǎn), KHÔNG nói <b>二点</b>.","examples":[{"zh":"现在九点。","py":"Xiànzài jiǔ diǎn.","vi":"Bây giờ là 9 giờ."},{"zh":"现在十一点十分。","py":"Xiànzài shíyī diǎn shí fēn.","vi":"Bây giờ là 11 giờ 10 phút."},{"zh":"现在下午两点。","py":"Xiànzài xiàwǔ liǎng diǎn.","vi":"Bây giờ là 2 giờ chiều."},{"zh":"上午八点","py":"shàngwǔ bā diǎn","vi":"8 giờ sáng"},{"zh":"下午五点三十分","py":"xiàwǔ wǔ diǎn sānshí fēn","vi":"5 giờ 30 phút chiều"},{"zh":"中午十二点","py":"zhōngwǔ shí'èr diǎn","vi":"12 giờ trưa"},{"zh":"现在几点？","py":"Xiànzài jǐ diǎn?","vi":"Bây giờ là mấy giờ?"},{"zh":"六点三十分","py":"liù diǎn sānshí fēn","vi":"6 giờ 30 phút"}]},{"title":"Từ chỉ thời gian làm Trạng ngữ","formula":"Chủ ngữ + <span>Thời gian</span> + Vị ngữ","summary":"Trong tiếng Trung, từ chỉ thời gian thường đứng <b>sau chủ ngữ</b> (hoặc có thể đứng trước chủ ngữ), nhưng luôn phải <b>trước động từ</b>.","note":"<strong>Lỗi tiếng Việt:</strong> Không để thời gian ở cuối câu. Sai: <span style=\"text-decoration:line-through;color:var(--burgundy)\">我吃饭六点。</span>","examples":[{"zh":"妈妈六点做饭。","py":"Māma liù diǎn zuò fàn.","vi":"Mẹ nấu cơm lúc 6 giờ."},{"zh":"李老师上午八点去学校。","py":"Lǐ lǎoshī shàngwǔ bā diǎn qù xuéxiào.","vi":"Thầy Lý 8 giờ sáng đi đến trường."},{"zh":"我星期一去北京。","py":"Wǒ xīngqīyī qù Běijīng.","vi":"Thứ Hai tôi đi Bắc Kinh."},{"zh":"我们中午十二点回家。","py":"Wǒmen zhōngwǔ shí'èr diǎn huí jiā.","vi":"Chúng tôi về nhà lúc 12 giờ trưa."},{"zh":"他们下午五点去看电影。","py":"Tāmen xiàwǔ wǔ diǎn qù kàn diànyǐng.","vi":"Bọn họ 5 giờ chiều đi xem phim."},{"zh":"爸爸什么时候回家？","py":"Bàba shénme shíhou huí jiā?","vi":"Bố khi nào về nhà?"},{"zh":"我们什么时候去？","py":"Wǒmen shénme shíhou qù?","vi":"Khi nào chúng ta đi?"},{"zh":"明天下午我能去商店。","py":"Míngtiān xiàwǔ wǒ néng qù shāngdiàn.","vi":"Chiều ngày mai tôi có thể đi cửa hàng."}]},{"title":"Danh từ 前 (Trước)","formula":"Thời gian + <span>前</span>","summary":"Dùng để chỉ thời điểm trước hiện tại hoặc trước một khoảng thời gian/mốc thời gian nào đó.","note":"<strong>So sánh:</strong> Tiếng Việt nói \"Trước 8 giờ\", Tiếng Trung nói \"8 giờ trước\" (八点前).","examples":[{"zh":"三天前","py":"sān tiān qián","vi":"3 ngày trước"},{"zh":"一个星期前","py":"yí ge xīngqī qián","vi":"1 tuần trước"},{"zh":"四点前","py":"sì diǎn qián","vi":"Trước 4 giờ"},{"zh":"星期五前","py":"xīngqīwǔ qián","vi":"Trước thứ Sáu"},{"zh":"你什么时候去学校？八点前。","py":"Nǐ shénme shíhou qù xuéxiào? Bā diǎn qián.","vi":"Bạn khi nào đi đến trường? Trước 8 giờ."},{"zh":"你什么时候回北京？星期六前。","py":"Nǐ shénme shíhou huí Běijīng? Xīngqīliù qián.","vi":"Bạn khi nào về Bắc Kinh? Trước thứ Bảy."},{"zh":"星期五前能回家吗？","py":"Xīngqīwǔ qián néng huí jiā ma?","vi":"Trước thứ Sáu có thể về nhà không?"},{"zh":"中午十二点前","py":"zhōngwǔ shí'èr diǎn qián","vi":"Trước 12 giờ trưa"}]}],"text":{"title":"课文 · Bài khoá","blocks":[{"titleZh":"在图书馆","titleVi":"Ở thư viện","icon":"📚","lines":[{"speaker":"A","zh":"现在几点？","py":"Xiànzài jǐ diǎn?","vi":"Bây giờ là mấy giờ?"},{"speaker":"B","zh":"现在十点十分。","py":"Xiànzài shí diǎn shí fēn.","vi":"Bây giờ là 10 giờ 10 phút."},{"speaker":"A","zh":"中午几点吃饭？","py":"Zhōngwǔ jǐ diǎn chī fàn?","vi":"Trưa mấy giờ ăn cơm?"},{"speaker":"B","zh":"十二点吃饭。","py":"Shí'èr diǎn chī fàn.","vi":"12 giờ ăn cơm."}]},{"titleZh":"在家","titleVi":"Ở nhà","icon":"🏠","lines":[{"speaker":"A","zh":"爸爸什么时候回家？","py":"Bàba shénme shíhou huí jiā?","vi":"Chừng nào cha mới về nhà?"},{"speaker":"B","zh":"下午五点。","py":"Xiàwǔ wǔ diǎn.","vi":"5 giờ chiều."},{"speaker":"A","zh":"我们什么时候去看电影？","py":"Wǒmen shénme shíhou qù kàn diànyǐng?","vi":"Khi nào chúng ta đi xem phim?"},{"speaker":"B","zh":"六点三十分。","py":"Liù diǎn sānshí fēn.","vi":"6 giờ rưỡi (6:30)."}]},{"titleZh":"在家","titleVi":"Ở nhà","icon":"🏠","lines":[{"speaker":"A","zh":"我星期一去北京。","py":"Wǒ xīngqīyī qù Běijīng.","vi":"Thứ Hai tôi đi Bắc Kinh."},{"speaker":"B","zh":"你想在北京住几天？","py":"Nǐ xiǎng zài Běijīng zhù jǐ tiān?","vi":"Bạn định ở Bắc Kinh mấy ngày?"},{"speaker":"A","zh":"住三天。","py":"Zhù sān tiān.","vi":"Ở 3 ngày."},{"speaker":"B","zh":"星期五前能回家吗？","py":"Xīngqīwǔ qián néng huí jiā ma?","vi":"Trước thứ Sáu có thể về nhà không?"},{"speaker":"A","zh":"能。","py":"Néng.","vi":"Được."}]}]},"extra":[{"label":"Mục tiêu","html":"<h2 class=\"section-title\">Mục tiêu bài học</h2>\n  <p class=\"section-sub\">Bài 11 giúp học viên làm chủ việc hỏi đáp về thời gian và diễn đạt các kế hoạch, thói quen sinh hoạt hàng ngày.</p>\n  <div class=\"goal-grid\">\n    <div class=\"goal-item\">\n      <div class=\"num\">01</div>\n      <h4>Giao tiếp</h4>\n      <ul>\n        <li>Hỏi và trả lời về <b>thời gian hiện tại</b>.</li>\n        <li>Hỏi đáp về <b>thời điểm</b> xảy ra một hành động.</li>\n        <li>Kể lại <b>lịch trình sinh hoạt</b> trong ngày.</li>\n      </ul>\n    </div>\n    <div class=\"goal-item\">\n      <div class=\"num\">02</div>\n      <h4>Từ vựng</h4>\n      <ul>\n        <li>Từ chỉ thời gian: <b>现在, 点, 分, 时候, 前, 中午</b></li>\n        <li>Hoạt động: <b>吃饭, 回, 住</b></li>\n        <li>Khác: <b>电影, 我们, 北京</b></li>\n      </ul>\n    </div>\n    <div class=\"goal-item\">\n      <div class=\"num\">03</div>\n      <h4>Ngữ pháp</h4>\n      <ul>\n        <li>Công thức nói giờ với <b>点</b> và <b>分</b>.</li>\n        <li>Vị trí của <b>Trạng ngữ chỉ thời gian</b> trong câu.</li>\n        <li>Cách sử dụng danh từ <b>前</b> (trước).</li>\n      </ul>\n    </div>\n  </div>"},{"label":"Chuyên đề Giờ","html":"<h2 class=\"section-title\">Cách nói giờ trong tiếng Trung</h2>\n  <p class=\"section-sub\">Nguyên tắc: Đi từ đơn vị lớn đến đơn vị nhỏ (Sáng/Chiều → Giờ → Phút).</p>\n\n  <div class=\"card\">\n    <h3>1. Công thức Đọc Giờ</h3>\n    <div class=\"formula-box\">\n      <div class=\"formula-label\">Cấu trúc chuẩn</div>\n      <div class=\"formula\">(<span class=\"gold\">上午 / 下午</span>) + Số + <span class=\"pop\">点</span> + Số + <span class=\"pop\">分</span></div>\n    </div>\n    <p style=\"margin-top:14px; text-align:center;\"><em>(Sáng / Chiều) + Giờ + Phút</em></p>\n\n    <div class=\"time-grid\">\n      <div class=\"time-card\">\n        <div class=\"t-clock\">09:00</div>\n        <div class=\"t-zh\">九点</div>\n        <div class=\"t-py\">jiǔ diǎn</div>\n      </div>\n      <div class=\"time-card\">\n        <div class=\"t-clock\">11:10</div>\n        <div class=\"t-zh\">十一点十分</div>\n        <div class=\"t-py\">shíyī diǎn shí fēn</div>\n      </div>\n      <div class=\"time-card\" style=\"border-color:var(--burgundy); background:var(--burgundy-soft);\">\n        <div class=\"t-clock\" style=\"color:var(--burgundy-dark);\">02:00</div>\n        <div class=\"t-zh\">两点</div>\n        <div class=\"t-py\">liǎng diǎn</div>\n        <div style=\"font-size:0.75rem; color:var(--burgundy); font-weight:bold; margin-top:4px;\">(Không dùng 二点)</div>\n      </div>\n      <div class=\"time-card\">\n        <div class=\"t-clock\">05:30</div>\n        <div class=\"t-zh\">五点三十分</div>\n        <div class=\"t-py\">wǔ diǎn sānshí fēn</div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"card\">\n    <h3>2. Các mốc thời gian trong ngày</h3>\n    <p>Để chỉ rõ thời gian, người Trung Quốc thường thêm các mốc thời gian lớn vào trước số giờ.</p>\n    <ul style=\"margin-top:10px;\">\n      <li><b>上午 (shàngwǔ):</b> Buổi sáng (Từ khoảng 8h - 11h). VD: <i>上午十点 (10h sáng)</i>.</li>\n      <li><b>中午 (zhōngwǔ):</b> Buổi trưa (Từ khoảng 11h - 1h chiều). VD: <i>中午十二点 (12h trưa)</i>.</li>\n      <li><b>下午 (xiàwǔ):</b> Buổi chiều (Từ khoảng 1h chiều - 6h tối). VD: <i>下午三点十分 (3h10 chiều)</i>.</li>\n    </ul>\n\n    <div class=\"tip-card\">\n      <h5>💡 Lưu ý khi nói số \"0\" ở số phút</h5>\n      <p>Khi số phút từ 1 đến 9, người ta thường thêm chữ 零 (líng - lẻ) vào trước số phút để nghe thuận tai hơn.</p>\n      <p style=\"margin-top:8px;\">Ví dụ: 02:05 -> <b>两点零五分</b> (liǎng diǎn líng wǔ fēn).</p>\n    </div>\n  </div>"},{"label":"Lỗi sai","html":"<h2 class=\"section-title\">Lỗi sai thường gặp</h2>\n  <p class=\"section-sub\">Ba lỗi kinh điển của người Việt khi học về thời gian trong tiếng Trung.</p>\n  <div class=\"error-grid\">\n    <div class=\"error-box\">\n      <div class=\"err-head wrong\">Lỗi 1 · Dùng \"二点\" thay vì \"两点\"</div>\n      <div class=\"err-body\">\n        <p style=\"margin-bottom:12px\">Khi nói 2 giờ, bắt buộc phải dùng \"两\" (liǎng), không dùng \"二\" (èr).</p>\n        <p class=\"strike zh\">现在二点。</p>\n      </div>\n      <div class=\"err-head correct\">Cách sửa</div>\n      <div class=\"err-body\">\n        <p class=\"correct-text zh\">现在两点。</p>\n        <p style=\"font-size:.88rem;color:var(--muted);margin-top:6px\">Tương tự, 2 giờ rưỡi là \"两点三十分\".</p>\n      </div>\n    </div>\n    <div class=\"error-box\">\n      <div class=\"err-head wrong\">Lỗi 2 · Đặt thời gian sai vị trí</div>\n      <div class=\"err-body\">\n        <p style=\"margin-bottom:12px\">Tiếng Việt thường để thời gian ở cuối câu (Tôi ăn cơm lúc 6 giờ). Tiếng Trung bắt buộc Thời gian phải đứng <b>TRƯỚC</b> Động từ.</p>\n        <p class=\"strike zh\">我吃饭六点。</p>\n        <p class=\"strike zh\">他回家下午五点。</p>\n      </div>\n      <div class=\"err-head correct\">Cách sửa</div>\n      <div class=\"err-body\">\n        <p class=\"correct-text zh\">我六点吃饭。</p>\n        <p class=\"correct-text zh\">他下午五点回家。</p>\n      </div>\n    </div>\n    <div class=\"error-box\">\n      <div class=\"err-head wrong\">Lỗi 3 · Hỏi \"Khi nào\" bằng \"几\"</div>\n      <div class=\"err-body\">\n        <p style=\"margin-bottom:12px\">Học viên hay nhầm lẫn và dịch word-by-word \"Mấy lúc\", \"Mấy khi\" bằng chữ \"几\".</p>\n        <p class=\"strike zh\">你几时候去？</p>\n      </div>\n      <div class=\"err-head correct\">Cách sửa</div>\n      <div class=\"err-body\">\n        <p class=\"correct-text zh\">你什么时候去？</p>\n        <p class=\"correct-text zh\">你几点去？</p>\n        <p style=\"font-size:.88rem;color:var(--muted);margin-top:6px\">\"什么时候\" hỏi chung chung (khi nào, ngày nào), còn \"几点\" hỏi cụ thể giờ giấc.</p>\n      </div>\n    </div>\n  </div>"},{"label":"Tổng hợp","html":"<h2 class=\"section-title\">Tổng hợp kiến thức</h2>\n  <p class=\"section-sub\">Sơ đồ cốt lõi giúp tóm tắt toàn bộ Bài 11.</p>\n\n  <div class=\"syn-grid\">\n    <div class=\"syn-card theme-burgundy\">\n      <div class=\"syn-icon\">⏰</div>\n      <h3>Công thức đọc giờ</h3>\n      <div class=\"syn-flow\">\n        <div class=\"step\">Thời điểm<br><span class=\"syn-keyhz\">下午</span></div>\n        <span class=\"arrow\">+</span>\n        <div class=\"step\">Giờ<br><span class=\"syn-keyhz\">五点</span></div>\n        <span class=\"arrow\">+</span>\n        <div class=\"step\">Phút<br><span class=\"syn-keyhz\">三十分</span></div>\n      </div>\n      <div class=\"syn-mnemonic\"><strong>Ngoại lệ:</strong> 2:00 đọc là <strong>两点</strong>. 02:05 đọc là 两点<strong>零</strong>五分.</div>\n    </div>\n\n    <div class=\"syn-card theme-gold\">\n      <div class=\"syn-icon\">🚂</div>\n      <h3>Vị trí của Thời gian</h3>\n      <p>Thời gian làm Trạng ngữ, luôn phải đứng <b>trước động từ</b>.</p>\n      <div class=\"syn-flow\">\n        <div class=\"step\">Chủ ngữ<br><span class=\"syn-keyhz\">妈妈</span></div>\n        <span class=\"arrow\">+</span>\n        <div class=\"step\">Thời gian<br><span class=\"syn-keyhz\">六点</span></div>\n        <span class=\"arrow\">+</span>\n        <div class=\"step\">Hành động<br><span class=\"syn-keyhz\">做饭</span></div>\n      </div>\n      <div class=\"syn-mnemonic\"><strong>Linh hoạt:</strong> Thời gian có thể đứng đầu câu: <span class=\"syn-keyhz\">六点妈妈做饭。</span></div>\n    </div>\n\n    <div class=\"syn-card theme-ink\">\n      <div class=\"syn-icon\">⏳</div>\n      <h3>Từ chỉ mốc thời gian: 前</h3>\n      <table class=\"syn-table\">\n        <tr><th>Cấu trúc</th><th>Ví dụ</th></tr>\n        <tr><td>Khoảng thời gian + 前</td><td>三天前 (3 ngày trước)</td></tr>\n        <tr><td>Mốc thời gian + 前</td><td>星期五前 (Trước thứ Sáu)</td></tr>\n        <tr><td>Giờ + 前</td><td>八点前 (Trước 8 giờ)</td></tr>\n      </table>\n      <div class=\"syn-mnemonic\">Từ 前 luôn đứng <strong>sau</strong> từ chỉ thời gian.</div>\n    </div>\n\n    <div class=\"syn-card theme-burgundy\">\n      <div class=\"syn-icon\">❓</div>\n      <h3>Hỏi: 几点 vs 什么时候</h3>\n      <p>Phân biệt hai cách hỏi thời gian:</p>\n      <ul style=\"font-size:0.95rem; line-height:1.6; margin-top:10px; color:var(--ink-soft); padding-left:18px;\">\n        <li><span class=\"syn-keyhz\">几点？</span> (Mấy giờ?): Cần câu trả lời chính xác số giờ. VD: 你几点吃饭？ -> 12点。</li>\n        <li><span class=\"syn-keyhz\">什么时候？</span> (Khi nào?): Hỏi chung chung về thời điểm (ngày, tháng, năm, lúc). VD: 你什么时候去？ -> 下午 / 明天。</li>\n      </ul>\n    </div>\n\n    <div class=\"syn-card theme-gold\" style=\"grid-column: 1 / -1;\">\n      <div class=\"syn-icon\">⚡</div>\n      <h3>Câu thần chú 5 mẫu</h3>\n      <table class=\"syn-table\">\n        <tr><th>Mẫu</th><th>Tình huống</th></tr>\n        <tr><td><span class=\"syn-keyhz\">现在几点？</span></td><td>Hỏi giờ hiện tại.</td></tr>\n        <tr><td><span class=\"syn-keyhz\">中午几点吃饭？</span></td><td>Hỏi giờ thực hiện một thói quen.</td></tr>\n        <tr><td><span class=\"syn-keyhz\">爸爸什么时候回家？</span></td><td>Hỏi thời điểm ai đó làm việc gì.</td></tr>\n        <tr><td><span class=\"syn-keyhz\">你想在北京住几天？</span></td><td>Hỏi dự định ở lại bao lâu.</td></tr>\n        <tr><td><span class=\"syn-keyhz\">星期五前能回家吗？</span></td><td>Hỏi xem có hoàn thành việc gì trước một thời hạn không.</td></tr>\n      </table>\n      <div class=\"syn-mnemonic\"><strong>Thuộc 5 mẫu này là pass Bài 11.</strong></div>\n    </div>\n  </div>"}],"cssId":"c84c13dfb"},{"id":"k1v2-b12","courseId":"k1v2","order":12,"title":"Ngày mai thời tiết thế nào?","titleZh":"明天天气怎么样？","vocab":[{"stt":1,"hanzi":"天气","pinyin":"tiānqì","hanviet":"Thiên khí","pos":"Danh từ","meaning":"Thời tiết","comps":"天气好 · 今天天气","example":{"zh":"今天天气怎么样？","py":"Jīntiān tiānqì zěnmeyàng?","vi":"Thời tiết hôm nay thế nào?"}},{"stt":2,"hanzi":"怎么样","pinyin":"zěnmeyàng","hanviet":"Chẩm ma dạng","pos":"Đại từ","meaning":"Như thế nào, ra sao","comps":"天气怎么样 · 身体怎么样","example":{"zh":"你的身体怎么样？","py":"Nǐ de shēntǐ zěnmeyàng?","vi":"Sức khoẻ của bạn thế nào?"}},{"stt":3,"hanzi":"太","pinyin":"tài","hanviet":"Thái","pos":"Phó từ","meaning":"Quá, lắm","comps":"太热了 · 太好了","example":{"zh":"今天太热了。","py":"Jīntiān tài rè le.","vi":"Hôm nay nóng quá."}},{"stt":4,"hanzi":"热","pinyin":"rè","hanviet":"Nhiệt","pos":"Tính từ","meaning":"Nóng","comps":"很热 · 热水","example":{"zh":"明天不冷不热。","py":"Míngtiān bù lěng bú rè.","vi":"Ngày mai không lạnh không nóng."}},{"stt":5,"hanzi":"冷","pinyin":"lěng","hanviet":"Lãnh","pos":"Tính từ","meaning":"Lạnh","comps":"很冷 · 不太冷","example":{"zh":"今天太冷了。","py":"Jīntiān tài lěng le.","vi":"Hôm nay lạnh quá."}},{"stt":6,"hanzi":"下雨","pinyin":"xià yǔ","hanviet":"Hạ vũ","pos":"Động từ","meaning":"Mưa, có mưa","comps":"会下雨 · 下大雨","example":{"zh":"今天不会下雨。","py":"Jīntiān bú huì xià yǔ.","vi":"Hôm nay sẽ không mưa."}},{"stt":7,"hanzi":"小姐","pinyin":"xiǎojiě","hanviet":"Tiểu thư","pos":"Danh từ","meaning":"Cô, tiểu thư (tiếng gọi tôn trọng phụ nữ trẻ)","comps":"王小姐 · 李小姐","example":{"zh":"王小姐今天会来吗？","py":"Wáng xiǎojiě jīntiān huì lái ma?","vi":"Hôm nay cô Vương có đến không?"}},{"stt":8,"hanzi":"来","pinyin":"lái","hanviet":"Lai","pos":"Động từ","meaning":"Đến, tới","comps":"来学校 · 回来","example":{"zh":"他不会来。","py":"Tā bú huì lái.","vi":"Anh ấy sẽ không đến."}},{"stt":9,"hanzi":"身体","pinyin":"shēntǐ","hanviet":"Thân thể","pos":"Danh từ","meaning":"Sức khỏe, cơ thể","comps":"身体好 · 身体不好","example":{"zh":"我身体不太好。","py":"Wǒ shēntǐ bú tài hǎo.","vi":"Sức khoẻ tôi không tốt lắm."}},{"stt":10,"hanzi":"爱","pinyin":"ài","hanviet":"Ái","pos":"Động từ","meaning":"Yêu, thích, hay (làm gì)","comps":"爱吃 · 不爱喝水","example":{"zh":"天气太热了，不爱吃饭。","py":"Tiānqì tài rè le, bú ài chī fàn.","vi":"Trời nóng quá, chẳng thích ăn cơm."}},{"stt":11,"hanzi":"些","pinyin":"xiē","hanviet":"Ta","pos":"Lượng từ","meaning":"Một ít, một vài","comps":"一些 · 这些 · 那些","example":{"zh":"你多吃些水果。","py":"Nǐ duō chī xiē shuǐguǒ.","vi":"Bạn ăn nhiều trái cây một chút."}},{"stt":12,"hanzi":"水果","pinyin":"shuǐguǒ","hanviet":"Thủy quả","pos":"Danh từ","meaning":"Trái cây, hoa quả","comps":"吃水果 · 买水果","example":{"zh":"我想买些水果。","py":"Wǒ xiǎng mǎi xiē shuǐguǒ.","vi":"Tôi muốn mua một ít trái cây."}},{"stt":13,"hanzi":"水","pinyin":"shuǐ","hanviet":"Thủy","pos":"Danh từ","meaning":"Nước","comps":"喝水 · 热水","example":{"zh":"你多喝水。","py":"Nǐ duō hē shuǐ.","vi":"Bạn uống nhiều nước nhé."}}],"hanzi":[{"char":"天气","pinyin":"tiānqì","hanviet":"Thiên khí","chars":["天","气"],"story":"天 (bầu trời) + 气 (khí). Khí tượng trên bầu trời chính là thời tiết."},{"char":"怎么样","pinyin":"zěnmeyàng","hanviet":"Chẩm ma dạng","chars":["怎","么","样"],"story":"Dùng để hỏi tính chất, trạng thái của sự vật hay con người."},{"char":"太","pinyin":"tài","hanviet":"Thái","chars":["太"],"story":"Chữ 大 (to lớn) thêm một chấm. Ý chỉ mức độ vượt qua sự bình thường, thái quá."},{"char":"热","pinyin":"rè","hanviet":"Nhiệt","chars":["热"],"story":"Bên dưới có 4 chấm hoả (灬 - lửa), thể hiện sự nóng bức."},{"char":"冷","pinyin":"lěng","hanviet":"Lãnh","chars":["冷"],"story":"Bên trái có bộ Băng (冫- nước đá), thể hiện sự lạnh lẽo."},{"char":"下雨","pinyin":"xià yǔ","hanviet":"Hạ vũ","chars":["下","雨"],"story":"下 (rơi xuống) + 雨 (mưa). Chữ 雨 có hình 4 giọt nước rơi từ đám mây."},{"char":"小姐","pinyin":"xiǎojiě","hanviet":"Tiểu thư","chars":["小","姐"],"story":"Chữ 姐 có bộ Nữ (女) bên trái. Thường ghép với họ của người phụ nữ."},{"char":"来","pinyin":"lái","hanviet":"Lai","chars":["来"],"story":"Ngược lại với 去 (đi). Chỉ hướng di chuyển về phía người nói."},{"char":"身体","pinyin":"shēntǐ","hanviet":"Thân thể","chars":["身","体"],"story":"Thân (cơ thể) và Thể (cốt cách). Thường dùng để hỏi thăm sức khỏe."},{"char":"爱","pinyin":"ài","hanviet":"Ái","chars":["爱"],"story":"Trong chữ có bộ Tâm (心 - trái tim) ở giữa, thể hiện tình cảm từ trong tim."},{"char":"些","pinyin":"xiē","hanviet":"Ta","chars":["些"],"story":"Thường dùng chỉ số lượng không xác định, nhỏ hơn nhiều."},{"char":"水果","pinyin":"shuǐguǒ","hanviet":"Thủy quả","chars":["水","果"],"story":"水 (nước) + 果 (quả). Trái cây thường chứa nhiều nước."},{"char":"水","pinyin":"shuǐ","hanviet":"Thủy","chars":["水"],"story":"Chữ tượng hình, mô phỏng dòng nước chảy uốn lượn."}],"grammar":[{"title":"Đại từ nghi vấn 怎么样","formula":"S / Cụm Danh Từ + <span>怎么样？</span>","summary":"Dùng để hỏi tính chất, tình trạng của người, sự vật hoặc sự việc.","note":"<strong>Trả lời:</strong> Dùng tính từ (như 好, 热, 冷...).","examples":[{"zh":"你的汉语怎么样？","py":"Nǐ de Hànyǔ zěnmeyàng?","vi":"Tiếng Trung của bạn thế nào?"},{"zh":"你妈妈身体怎么样？","py":"Nǐ māma shēntǐ zěnmeyàng?","vi":"Sức khỏe của mẹ bạn thế nào?"},{"zh":"明天天气怎么样？","py":"Míngtiān tiānqì zěnmeyàng?","vi":"Thời tiết ngày mai thế nào?"},{"zh":"这个电影怎么样？","py":"Zhège diànyǐng zěnmeyàng?","vi":"Bộ phim này thế nào?"},{"zh":"这个商店怎么样？","py":"Zhège shāngdiàn zěnmeyàng?","vi":"Cửa hàng này thế nào?"},{"zh":"北京的天气怎么样？","py":"Běijīng de tiānqì zěnmeyàng?","vi":"Thời tiết ở Bắc Kinh thế nào?"},{"zh":"这本书怎么样？","py":"Zhè běn shū zěnmeyàng?","vi":"Quyển sách này thế nào?"},{"zh":"你爸爸怎么样？","py":"Nǐ bàba zěnmeyàng?","vi":"Bố bạn dạo này thế nào?"}]},{"title":"Câu Vị ngữ là kết cấu Chủ - Vị","formula":"Chủ ngữ (Lớn) + [ <span>Chủ ngữ (nhỏ) + Vị ngữ (nhỏ)</span> ]","summary":"Loại câu có vị ngữ bản thân nó lại là một cụm Chủ-Vị. Thường dùng để miêu tả một đặc điểm, bộ phận của chủ ngữ lớn.","note":"<strong>Chú ý:</strong> Không cần thêm \"的\" (de) giữa Chủ ngữ lớn và Chủ ngữ nhỏ.","examples":[{"zh":"我身体不太好。","py":"Wǒ shēntǐ bú tài hǎo.","vi":"Tôi sức khỏe không tốt lắm."},{"zh":"明天天气很好。","py":"Míngtiān tiānqì hěn hǎo.","vi":"Ngày mai thời tiết rất đẹp."},{"zh":"你身体怎么样？","py":"Nǐ shēntǐ zěnmeyàng?","vi":"Bạn sức khoẻ thế nào?"},{"zh":"他工作很忙。","py":"Tā gōngzuò hěn máng.","vi":"Anh ấy công việc rất bận."},{"zh":"大卫汉语很好。","py":"Dàwèi Hànyǔ hěn hǎo.","vi":"David tiếng Trung rất tốt."},{"zh":"北京天气很冷。","py":"Běijīng tiānqì hěn lěng.","vi":"Bắc Kinh thời tiết rất lạnh."},{"zh":"妈妈工作很多。","py":"Māma gōngzuò hěn duō.","vi":"Mẹ công việc rất nhiều."},{"zh":"老师名字很好听。","py":"Lǎoshī míngzi hěn hǎo tīng.","vi":"Thầy giáo tên rất hay."}]},{"title":"Cấu trúc mức độ 太...了","formula":"Khẳng định: <span>太 + Adj + 了</span><br>Phủ định: <span>不太 + Adj</span>","summary":"Biểu thị mức độ cao (quá, lắm).","note":"<strong>Cực kỳ quan trọng:</strong> Khi dùng phủ định \"不太\", tuyệt đối không dùng \"了\" ở cuối câu.","examples":[{"zh":"太热了。","py":"Tài rè le.","vi":"Nóng quá."},{"zh":"天气太冷了。","py":"Tiānqì tài lěng le.","vi":"Thời tiết lạnh quá."},{"zh":"我身体不太好。","py":"Wǒ shēntǐ bú tài hǎo.","vi":"Sức khoẻ tôi không tốt lắm."},{"zh":"这个杯子太大了。","py":"Zhège bēizi tài dà le.","vi":"Cái ly này to quá."},{"zh":"那个电脑太小了。","py":"Nàge diànnǎo tài xiǎo le.","vi":"Máy tính kia nhỏ quá."},{"zh":"今天不太热。","py":"Jīntiān bú tài rè.","vi":"Hôm nay không nóng lắm."},{"zh":"这个菜不太好吃。","py":"Zhège cài bú tài hǎochī.","vi":"Món này không ngon lắm."},{"zh":"他不太高兴。","py":"Tā bú tài gāoxìng.","vi":"Anh ấy không vui lắm."}]},{"title":"Động từ năng nguyện 会","formula":"S + <span>会 / 不会</span> + V","summary":"\"会\" (huì) trong bài này được dùng để dự đoán một khả năng, một tình huống có thể xảy ra trong tương lai (Sẽ).","examples":[{"zh":"今天会下雨吗？","py":"Jīntiān huì xià yǔ ma?","vi":"Hôm nay sẽ mưa không?"},{"zh":"今天不会下雨。","py":"Jīntiān bú huì xià yǔ.","vi":"Hôm nay sẽ không mưa."},{"zh":"王小姐今天会来吗？","py":"Wáng xiǎojiě jīntiān huì lái ma?","vi":"Cô Vương hôm nay sẽ đến chứ?"},{"zh":"她不会来。","py":"Tā bú huì lái.","vi":"Cô ấy sẽ không đến."},{"zh":"爸爸八点前会回家吗？","py":"Bàba bā diǎn qián huì huí jiā ma?","vi":"Bố trước 8 giờ sẽ về nhà chứ?"},{"zh":"明天他会去北京。","py":"Míngtiān tā huì qù Běijīng.","vi":"Ngày mai anh ấy sẽ đi Bắc Kinh."},{"zh":"下午会很热。","py":"Xiàwǔ huì hěn rè.","vi":"Buổi chiều sẽ rất nóng."},{"zh":"明天不会冷。","py":"Míngtiān bú huì lěng.","vi":"Ngày mai sẽ không lạnh."}]}],"text":{"title":"课文 · Bài khoá","blocks":[{"titleZh":"在路上","titleVi":"Trên đường","icon":"🚶","lines":[{"speaker":"A","zh":"昨天北京的天气怎么样？","py":"Zuótiān Běijīng de tiānqì zěnmeyàng?","vi":"Hôm qua thời tiết ở Bắc Kinh thế nào?"},{"speaker":"B","zh":"太热了。","py":"Tài rè le.","vi":"Nóng lắm (Quá nóng)."},{"speaker":"A","zh":"明天呢？明天天气怎么样？","py":"Míngtiān ne? Míngtiān tiānqì zěnmeyàng?","vi":"Còn ngày mai thì sao? Thời tiết ngày mai thế nào?"},{"speaker":"B","zh":"明天天气很好，不冷不热。","py":"Míngtiān tiānqì hěn hǎo, bù lěng bú rè.","vi":"Ngày mai thời tiết rất đẹp, không lạnh cũng không nóng."}]},{"titleZh":"在健身房","titleVi":"Ở phòng tập thể dục","icon":"🏋️","lines":[{"speaker":"A","zh":"今天会下雨吗？","py":"Jīntiān huì xià yǔ ma?","vi":"Hôm nay có mưa không nhỉ?"},{"speaker":"B","zh":"今天不会下雨。","py":"Jīntiān bú huì xià yǔ.","vi":"Hôm nay sẽ không mưa đâu."},{"speaker":"A","zh":"王小姐今天会来吗？","py":"Wáng xiǎojiě jīntiān huì lái ma?","vi":"Hôm nay cô Vương có đến không nhỉ?"},{"speaker":"B","zh":"不会来，天气太冷了。","py":"Bú huì lái, tiānqì tài lěng le.","vi":"Không đến đâu, trời lạnh quá mà."}]},{"titleZh":"在病房","titleVi":"Trong phòng bệnh","icon":"🏥","lines":[{"speaker":"A","zh":"你身体怎么样？","py":"Nǐ shēntǐ zěnmeyàng?","vi":"Sức khỏe của anh thế nào?"},{"speaker":"B","zh":"我身体不太好。天气太热了，不爱吃饭。","py":"Wǒ shēntǐ bú tài hǎo. Tiānqì tài rè le, bú ài chī fàn.","vi":"Tôi không được khỏe lắm. Trời nóng quá, tôi chẳng muốn ăn cơm."},{"speaker":"A","zh":"你多吃些水果，多喝水。","py":"Nǐ duō chī xiē shuǐguǒ, duō hē shuǐ.","vi":"Anh hãy ăn thêm một ít trái cây và uống nhiều nước vào nhé."},{"speaker":"B","zh":"谢谢你，医生。","py":"Xièxie nǐ, yīshēng.","vi":"Cảm ơn bác sĩ."}]}]},"extra":[{"label":"Mục tiêu","html":"<h2 class=\"section-title\">Mục tiêu bài học</h2>\n  <p class=\"section-sub\">Bài 12 giúp học viên có khả năng bàn luận về thời tiết, hỏi thăm sức khoẻ cơ bản và đưa ra những lời khuyên phù hợp.</p>\n  <div class=\"goal-grid\">\n    <div class=\"goal-item\">\n      <div class=\"num\">01</div>\n      <h4>Giao tiếp</h4>\n      <ul>\n        <li>Hỏi và miêu tả <b>tình hình thời tiết</b> (nóng, lạnh, mưa).</li>\n        <li>Hỏi thăm <b>tình trạng sức khoẻ</b> (tốt/không tốt).</li>\n        <li>Đưa ra <b>lời khuyên</b> (nên làm gì nhiều hơn).</li>\n      </ul>\n    </div>\n    <div class=\"goal-item\">\n      <div class=\"num\">02</div>\n      <h4>Từ vựng</h4>\n      <ul>\n        <li>Thời tiết: <b>天气, 怎么样, 热, 冷, 下雨</b></li>\n        <li>Sức khỏe: <b>身体, 医生</b></li>\n        <li>Ăn uống: <b>水果, 水</b></li>\n        <li>Phó/Đại từ: <b>太, 会, 些</b></li>\n      </ul>\n    </div>\n    <div class=\"goal-item\">\n      <div class=\"num\">03</div>\n      <h4>Ngữ pháp</h4>\n      <ul>\n        <li>Đại từ nghi vấn <b>怎么样</b>.</li>\n        <li>Câu có vị ngữ là <b>kết cấu Chủ - Vị</b>.</li>\n        <li>Cấu trúc mức độ <b>太...了</b> (quá, lắm).</li>\n        <li>Động từ năng nguyện <b>会</b> (sẽ, có khả năng).</li>\n      </ul>\n    </div>\n  </div>"},{"label":"Dự báo Thời tiết","html":"<h2 class=\"section-title\">Dự báo Thời tiết &amp; Sức khoẻ</h2>\n  <p class=\"section-sub\">Mở rộng vốn từ về các hiện tượng thời tiết phổ biến và cách đưa ra lời khuyên chăm sóc sức khoẻ.</p>\n\n  <div class=\"card\">\n    <h3>1. Từ vựng mở rộng: Hiện tượng Thời tiết</h3>\n    <div class=\"weather-grid\">\n      <div class=\"weather-card\">\n        <div class=\"w-icon\">☀️</div>\n        <div class=\"w-zh\">晴天</div>\n        <div class=\"w-py\">qíng tiān</div>\n        <div class=\"w-vi\">Trời nắng</div>\n      </div>\n      <div class=\"weather-card\">\n        <div class=\"w-icon\">☁️</div>\n        <div class=\"w-zh\">阴天</div>\n        <div class=\"w-py\">yīn tiān</div>\n        <div class=\"w-vi\">Trời râm, nhiều mây</div>\n      </div>\n      <div class=\"weather-card\">\n        <div class=\"w-icon\">🌧️</div>\n        <div class=\"w-zh\">下雨</div>\n        <div class=\"w-py\">xià yǔ</div>\n        <div class=\"w-vi\">Trời mưa</div>\n      </div>\n      <div class=\"weather-card\">\n        <div class=\"w-icon\">❄️</div>\n        <div class=\"w-zh\">下雪</div>\n        <div class=\"w-py\">xià xuě</div>\n        <div class=\"w-vi\">Tuyết rơi</div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"card\">\n    <h3>2. Mẫu câu quan tâm Sức khoẻ</h3>\n    <p>Khi hỏi thăm sức khoẻ, dùng mẫu câu: <b>\"S + 身体怎么样？\"</b></p>\n    <p>Để khuyên ai đó nên làm việc gì nhiều hơn để tốt cho sức khoẻ, dùng cấu trúc: <b>多 (Nhiều) + Động từ + (Danh từ)</b></p>\n    \n    <div class=\"health-grid\">\n      <div class=\"health-item\">\n        <div class=\"h-zh\">多喝水</div>\n        <div class=\"h-py\">duō hē shuǐ</div>\n        <div class=\"h-vi\">Uống nhiều nước</div>\n      </div>\n      <div class=\"health-item\">\n        <div class=\"h-zh\">多吃水果</div>\n        <div class=\"h-py\">duō chī shuǐguǒ</div>\n        <div class=\"h-vi\">Ăn nhiều trái cây</div>\n      </div>\n      <div class=\"health-item\">\n        <div class=\"h-zh\">多休息</div>\n        <div class=\"h-py\">duō xiūxi</div>\n        <div class=\"h-vi\">Nghỉ ngơi nhiều hơn</div>\n      </div>\n      <div class=\"health-item\">\n        <div class=\"h-zh\">少说话</div>\n        <div class=\"h-py\">shǎo shuōhuà</div>\n        <div class=\"h-vi\">Ít nói chuyện lại (ngược lại với 多 là 少 - shǎo: Ít)</div>\n      </div>\n    </div>\n  </div>"},{"label":"Lỗi sai","html":"<h2 class=\"section-title\">Lỗi sai thường gặp</h2>\n  <p class=\"section-sub\">Những lỗi người học tiếng Trung hay nhầm lẫn khi áp dụng cấu trúc Bài 12.</p>\n  <div class=\"error-grid\">\n    <div class=\"error-box\">\n      <div class=\"err-head wrong\">Lỗi 1 · Dùng sai cấu trúc \"Nhiều/Ít làm gì\"</div>\n      <div class=\"err-body\">\n        <p style=\"margin-bottom:12px\">Tiếng Việt nói \"Ăn nhiều\", \"Uống nhiều\". Nhưng tiếng Trung bắt buộc \"多\" (Nhiều) phải đứng <b>TRƯỚC</b> động từ.</p>\n        <p class=\"strike zh\">吃多水果。</p>\n        <p class=\"strike zh\">喝多水。</p>\n      </div>\n      <div class=\"err-head correct\">Cách sửa</div>\n      <div class=\"err-body\">\n        <p class=\"correct-text zh\">多吃水果。</p>\n        <p class=\"correct-text zh\">多喝水。</p>\n      </div>\n    </div>\n    <div class=\"error-box\">\n      <div class=\"err-head wrong\">Lỗi 2 · Lạm dụng chữ \"了\" trong câu phủ định của \"太\"</div>\n      <div class=\"err-body\">\n        <p style=\"margin-bottom:12px\">Cấu trúc khẳng định là \"太...了\" (quá...), nhưng khi phủ định \"不太...\" (không... lắm) thì tuyệt đối <b>KHÔNG</b> dùng \"了\".</p>\n        <p class=\"strike zh\">今天不太热了。</p>\n      </div>\n      <div class=\"err-head correct\">Cách sửa</div>\n      <div class=\"err-body\">\n        <p class=\"correct-text zh\">今天不太热。</p>\n      </div>\n    </div>\n    <div class=\"error-box\">\n      <div class=\"err-head wrong\">Lỗi 3 · Dùng 怎么样 để hỏi \"cái gì\"</div>\n      <div class=\"err-body\">\n        <p style=\"margin-bottom:12px\">\"怎么样\" dùng để hỏi về tính chất, tình trạng (như thế nào), không dùng để hỏi sự vật, sự việc (cái gì/ai).</p>\n        <p class=\"strike zh\">你买怎么样？</p>\n      </div>\n      <div class=\"err-head correct\">Cách sửa</div>\n      <div class=\"err-body\">\n        <p class=\"correct-text zh\">你买什么？(Bạn mua gì?)</p>\n        <p class=\"correct-text zh\">这个怎么样？(Cái này như thế nào?)</p>\n      </div>\n    </div>\n  </div>"},{"label":"Tổng hợp","html":"<h2 class=\"section-title\">Tổng hợp kiến thức</h2>\n  <p class=\"section-sub\">Sơ đồ cốt lõi giúp tóm tắt toàn bộ Bài 12.</p>\n\n  <div class=\"syn-grid\">\n    <div class=\"syn-card theme-burgundy\">\n      <div class=\"syn-icon\">🌡️</div>\n      <h3>Hỏi tình trạng: 怎么样？</h3>\n      <p>Dùng để hỏi về tính chất của 1 sự vật / hiện tượng.</p>\n      <div class=\"syn-flow\">\n        <div class=\"step\">Chủ thể<br><span class=\"syn-keyhz\">明天天气</span></div>\n        <span class=\"arrow\">+</span>\n        <div class=\"step\">Hỏi<br><span class=\"syn-keyhz\">怎么样？</span></div>\n      </div>\n      <div class=\"syn-mnemonic\"><strong>Trả lời:</strong> Dùng tính từ để trả lời: <span class=\"syn-keyhz\">很好 / 很热 / 不冷</span>.</div>\n    </div>\n\n    <div class=\"syn-card theme-gold\">\n      <div class=\"syn-icon\">📈</div>\n      <h3>Mức độ: 太...了</h3>\n      <table class=\"syn-table\">\n        <tr><th>Dạng</th><th>Công thức</th><th>Ví dụ</th></tr>\n        <tr><td>Khẳng định</td><td><span class=\"syn-keyhz\">太 + Tính từ + 了</span></td><td>太热了 (Nóng quá)</td></tr>\n        <tr><td>Phủ định</td><td><span class=\"syn-keyhz\">不太 + Tính từ</span></td><td>不太冷 (Không lạnh lắm)</td></tr>\n      </table>\n      <div class=\"syn-mnemonic\"><strong>Lưu ý vàng:</strong> Phủ định KHÔNG CÓ 了.</div>\n    </div>\n\n    <div class=\"syn-card theme-ink\">\n      <div class=\"syn-icon\">🔮</div>\n      <h3>Dự đoán: 会</h3>\n      <p>Dùng để dự đoán một việc có khả năng xảy ra trong tương lai.</p>\n      <div class=\"syn-flow\">\n        <div class=\"step\">Thời gian<br><span class=\"syn-keyhz\">明天</span></div>\n        <span class=\"arrow\">+</span>\n        <div class=\"step\">Dự đoán<br><span class=\"syn-keyhz\">会 / 不会</span></div>\n        <span class=\"arrow\">+</span>\n        <div class=\"step\">Hành động<br><span class=\"syn-keyhz\">下雨</span></div>\n      </div>\n      <div class=\"syn-mnemonic\"><strong>Dịch nghĩa:</strong> Sẽ / Không sẽ (có khả năng).</div>\n    </div>\n\n    <div class=\"syn-card theme-burgundy\">\n      <div class=\"syn-icon\">🪆</div>\n      <h3>Câu Chủ - Vị</h3>\n      <p>Cấu trúc: Chủ ngữ lớn + (Chủ ngữ nhỏ + Vị ngữ nhỏ).</p>\n      <div class=\"syn-flow\">\n        <div class=\"step\">C.Ngữ lớn<br><span class=\"syn-keyhz\">我</span></div>\n        <span class=\"arrow\">+</span>\n        <div class=\"step\">[ C.Ngữ nhỏ<br><span class=\"syn-keyhz\">身体</span></div>\n        <span class=\"arrow\">+</span>\n        <div class=\"step\">V.Ngữ nhỏ ]<br><span class=\"syn-keyhz\">不太好</span></div>\n      </div>\n      <div class=\"syn-mnemonic\">Chủ ngữ nhỏ thường là một bộ phận thuộc sở hữu của chủ ngữ lớn.</div>\n    </div>\n\n    <div class=\"syn-card theme-gold\" style=\"grid-column: 1 / -1;\">\n      <div class=\"syn-icon\">⚡</div>\n      <h3>Câu thần chú 5 mẫu</h3>\n      <table class=\"syn-table\">\n        <tr><th>Mẫu</th><th>Tình huống</th></tr>\n        <tr><td><span class=\"syn-keyhz\">明天天气怎么样？</span></td><td>Hỏi thời tiết.</td></tr>\n        <tr><td><span class=\"syn-keyhz\">天气太热了。</span></td><td>Than vãn về thời tiết cực đoan.</td></tr>\n        <tr><td><span class=\"syn-keyhz\">今天会下雨吗？</span></td><td>Hỏi xem trời có sắp mưa không.</td></tr>\n        <tr><td><span class=\"syn-keyhz\">你身体怎么样？</span></td><td>Hỏi thăm sức khỏe.</td></tr>\n        <tr><td><span class=\"syn-keyhz\">多吃些水果，多喝水。</span></td><td>Khuyên bảo ai đó chăm sóc sức khoẻ.</td></tr>\n      </table>\n      <div class=\"syn-mnemonic\"><strong>Thuộc 5 mẫu này là pass Bài 12.</strong></div>\n    </div>\n  </div>"}],"cssId":"ca097f820"},{"id":"k1v2-b13","courseId":"k1v2","order":13,"title":"Anh ấy đang học nấu món ăn Trung Quốc","titleZh":"他在学做中国菜呢","vocab":[{"stt":1,"hanzi":"喂","pinyin":"wèi","hanviet":"Uy","pos":"Thán từ","meaning":"A lô, này","comps":"喂，你好","example":{"zh":"喂，你在做什么呢？","py":"Wèi, nǐ zài zuò shénme ne?","vi":"A lô, bạn đang làm gì thế?"}},{"stt":2,"hanzi":"也","pinyin":"yě","hanviet":"Dã","pos":"Phó từ","meaning":"Cũng","comps":"也是 · 也有 · 我也去","example":{"zh":"大卫也在看书吗？","py":"Dàwèi yě zài kàn shū ma?","vi":"David cũng đang đọc sách à?"}},{"stt":3,"hanzi":"学习","pinyin":"xuéxí","hanviet":"Học tập","pos":"Động từ","meaning":"Học, học tập","comps":"学习汉语 · 学习做菜","example":{"zh":"他在学做中国菜呢。","py":"Tā zài xué zuò Zhōngguó cài ne.","vi":"Anh ấy đang học nấu món ăn Trung Quốc."}},{"stt":4,"hanzi":"上午","pinyin":"shàngwǔ","hanviet":"Thượng ngọ","pos":"Danh từ","meaning":"Buổi sáng","comps":"今天上午 · 昨天上午","example":{"zh":"昨天上午你在做什么呢？","py":"Zuótiān shàngwǔ nǐ zài zuò shénme ne?","vi":"Sáng hôm qua bạn đang làm gì vậy?"}},{"stt":5,"hanzi":"睡觉","pinyin":"shuì jiào","hanviet":"Thụy giác","pos":"Động từ","meaning":"Ngủ","comps":"在睡觉 · 想睡觉","example":{"zh":"我在睡觉呢。","py":"Wǒ zài shuì jiào ne.","vi":"Tôi đang ngủ."}},{"stt":6,"hanzi":"电视","pinyin":"diànshì","hanviet":"Điện thị","pos":"Danh từ","meaning":"Tivi","comps":"看电视 · 买电视","example":{"zh":"我在家看电视呢。","py":"Wǒ zài jiā kàn diànshì ne.","vi":"Tôi đang ở nhà xem tivi."}},{"stt":7,"hanzi":"喜欢","pinyin":"xǐhuan","hanviet":"Hỷ hoan","pos":"Động từ","meaning":"Thích","comps":"喜欢看书 · 不喜欢","example":{"zh":"你喜欢看电视吗？","py":"Nǐ xǐhuan kàn diànshì ma?","vi":"Bạn có thích xem tivi không?"}},{"stt":8,"hanzi":"给","pinyin":"gěi","hanviet":"Cấp","pos":"Giới/Động từ","meaning":"Cho, đưa cho","comps":"给谁 · 给他打电话","example":{"zh":"我现在给她打电话。","py":"Wǒ xiànzài gěi tā dǎ diànhuà.","vi":"Tôi bây giờ gọi điện thoại cho cô ấy."}},{"stt":9,"hanzi":"打电话","pinyin":"dǎ diànhuà","hanviet":"Đả điện thoại","pos":"Động từ","meaning":"Gọi điện thoại","comps":"给我打电话 · 打错电话","example":{"zh":"你在给谁打电话？","py":"Nǐ zài gěi shéi dǎ diànhuà?","vi":"Bạn đang gọi điện cho ai thế?"}},{"stt":10,"hanzi":"吧","pinyin":"ba","hanviet":"Ba","pos":"Trợ từ","meaning":"Nhé, đi, thôi","comps":"走吧 · 吃饭吧","example":{"zh":"你下午打吧。","py":"Nǐ xiàwǔ dǎ ba.","vi":"Bạn buổi chiều gọi nhé."}},{"stt":11,"hanzi":"看书","pinyin":"kàn shū","hanviet":"Khán thư","pos":"Động từ","meaning":"Đọc sách","comps":"喜欢看书 · 在看书","example":{"zh":"我在看书呢。","py":"Wǒ zài kàn shū ne.","vi":"Tôi đang đọc sách."}},{"stt":12,"hanzi":"做饭","pinyin":"zuò fàn","hanviet":"Tố phạn","pos":"Động từ","meaning":"Nấu ăn","comps":"学做饭 · 妈妈在做饭","example":{"zh":"妈妈在做饭呢。","py":"Māma zài zuò fàn ne.","vi":"Mẹ đang nấu ăn."}}],"hanzi":[{"char":"喂","pinyin":"wèi","hanviet":"Uy","chars":["喂"],"story":"Bộ 口 (Khẩu - cái miệng) ở bên trái. Từ dùng cửa miệng để gọi hoặc nghe máy."},{"char":"也","pinyin":"yě","hanviet":"Dã","chars":["也"],"story":"Chữ tượng hình, nét móc dài diễn tả sự kéo dài, thêm vào -> cũng."},{"char":"学习","pinyin":"xuéxí","hanviet":"Học tập","chars":["学","习"],"story":"学 (học) + 习 (tập - luyện tập nhiều lần). Học và luyện tập đi đôi."},{"char":"上午","pinyin":"shàngwǔ","hanviet":"Thượng ngọ","chars":["上","午"],"story":"上 (trên/trước) + 午 (ngọ - giữa trưa). Khoảng thời gian trước buổi trưa."},{"char":"睡觉","pinyin":"shuì jiào","hanviet":"Thụy giác","chars":["睡","觉"],"story":"睡 có bộ 目 (Mục - mắt), khi ngủ thì mắt nhắm lại."},{"char":"电视","pinyin":"diànshì","hanviet":"Điện thị","chars":["电","视"],"story":"电 (điện) + 视 (nhìn - bộ Kiến 见). Đồ vật dùng điện để nhìn thấy hình ảnh."},{"char":"喜欢","pinyin":"xǐhuan","hanviet":"Hỷ hoan","chars":["喜","欢"],"story":"喜 (vui vẻ - có chữ Khẩu 口) + 欢 (vui sướng). Thể hiện sự yêu thích trong lòng."},{"char":"给","pinyin":"gěi","hanviet":"Cấp","chars":["给"],"story":"Bộ 纟(Mịch - tơ lụa) kết hợp với 合 (hợp). Ý nghĩa đem đồ đạc cung cấp cho người khác."},{"char":"打电话","pinyin":"dǎ diànhuà","hanviet":"Đả điện thoại","chars":["打","电","话"],"story":"打 (đánh/gọi - bộ Tài gảy 扌) + 电话 (điện thoại)."},{"char":"吧","pinyin":"ba","hanviet":"Ba","chars":["吧"],"story":"Bộ 口 (Khẩu) và 巴 (Ba - âm thanh). Dùng ở cuối câu để đề nghị hoặc thỉnh cầu."},{"char":"看书","pinyin":"kàn shū","hanviet":"Khán thư","chars":["看","书"],"story":"看 (nhìn - tay 扌 che trên mắt 目) + 书 (sách)."},{"char":"做饭","pinyin":"zuò fàn","hanviet":"Tố phạn","chars":["做","饭"],"story":"做 (làm - bộ Nhân 亻) + 饭 (cơm). Làm ra bữa cơm."}],"grammar":[{"title":"Từ cảm thán 喂 (wèi)","formula":"<span>喂</span>，... ?","summary":"Đây là từ thường được dùng để mở đầu khi gọi điện thoại hay trả lời điện thoại (A lô).","note":"<strong>Ứng dụng:</strong> Thường kết hợp với \"请问...\" (Xin hỏi...) để tỏ sự lịch sự.","examples":[{"zh":"喂，你在做什么呢？","py":"Wèi, nǐ zài zuò shénme ne?","vi":"A lô, bạn đang làm gì vậy?"},{"zh":"喂，李老师在家吗？","py":"Wèi, Lǐ lǎoshī zài jiā ma?","vi":"A lô, cô Lý có ở nhà không?"},{"zh":"喂，你是张小姐吗？","py":"Wèi, nǐ shì Zhāng xiǎojiě ma?","vi":"A lô, chị là cô Trương phải không?"},{"zh":"喂，请问大卫在吗？","py":"Wèi, qǐng wèn Dàwèi zài ma?","vi":"A lô, xin hỏi David có đó không?"},{"zh":"喂，这是李老师的电话吗？","py":"Wèi, zhè shì Lǐ lǎoshī de diànhuà ma?","vi":"A lô, đây là số điện thoại của cô Lý phải không?"},{"zh":"喂，你明天去学校吗？","py":"Wèi, nǐ míngtiān qù xuéxiào ma?","vi":"A lô, ngày mai bạn đến trường không?"},{"zh":"喂，我下午去你家。","py":"Wèi, wǒ xiàwǔ qù nǐ jiā.","vi":"A lô, buổi chiều tôi đến nhà bạn nhé."},{"zh":"喂，你是谁？","py":"Wèi, nǐ shì shéi?","vi":"A lô, bạn là ai thế?"}]},{"title":"Hành động đang tiếp diễn: 在...呢","formula":"Khẳng định: S + <span>在</span> + V + O + <span>(呢)</span><br>Phủ định: S + <span>没(在)</span> + V + O","summary":"Kết cấu <b>在 + Động từ + (呢)</b> dùng để diễn tả một hành động đang diễn ra tại một thời điểm (Đang...).","note":"<strong>Tuyệt đối tránh:</strong> Khi dùng phủ định (没/没在), <b>KHÔNG</b> được dùng 呢 ở cuối câu.","examples":[{"zh":"我在看书呢。","py":"Wǒ zài kàn shū ne.","vi":"Tôi đang đọc sách."},{"zh":"他在学做中国菜呢。","py":"Tā zài xué zuò Zhōngguó cài ne.","vi":"Anh ấy đang học nấu món ăn Trung Quốc."},{"zh":"昨天上午你在做什么呢？","py":"Zuótiān shàngwǔ nǐ zài zuò shénme ne?","vi":"Sáng hôm qua bạn đang làm gì vậy?"},{"zh":"我在睡觉呢。","py":"Wǒ zài shuì jiào ne.","vi":"Tôi đang ngủ."},{"zh":"妈妈在做饭。","py":"Māma zài zuò fàn.","vi":"Mẹ đang nấu ăn."},{"zh":"我没在看电视。","py":"Wǒ méi zài kàn diànshì.","vi":"Tôi không đang xem tivi. (Phủ định)"},{"zh":"他没看书。","py":"Tā méi kàn shū.","vi":"Anh ấy không đọc sách. (Phủ định)"},{"zh":"他们没在工作。","py":"Tāmen méi zài gōngzuò.","vi":"Họ không đang làm việc. (Phủ định)"}]},{"title":"Cách đọc Số điện thoại","formula":"Đọc từng số: 1 -> <span>幺 (yāo)</span>, 2 -> <span>二 (èr)</span> (Không đọc 两).","summary":"Khác với tiếng Việt, số điện thoại trong tiếng Trung phải đọc tách rời từng chữ số. Chữ số 1 đọc là <b>yāo (幺)</b>.","note":"<strong>Nhắc nhở:</strong> Việc đổi 1 thành \"yāo\" giúp tránh nghe nhầm với số 7 (qī) qua điện thoại.","examples":[{"zh":"82304155","py":"bā èr sān líng sì yāo wǔ wǔ","vi":"Tám hai ba không bốn một năm năm."},{"zh":"13851897623","py":"yāo sān bā wǔ yāo bā jiǔ qī liù èr sān","vi":"(Số di động Trung Quốc)"},{"zh":"110","py":"yāo yāo líng","vi":"(Số điện thoại cảnh sát Trung Quốc)"},{"zh":"119","py":"yāo yāo jiǔ","vi":"(Số điện thoại cứu hỏa Trung Quốc)"},{"zh":"120","py":"yāo èr líng","vi":"(Số điện thoại cấp cứu Trung Quốc)"},{"zh":"李老师的电话是 82304156。","py":"Lǐ lǎoshī de diànhuà shì bā èr sān líng sì yāo wǔ liù.","vi":"Điện thoại cô Lý là 82304156."},{"zh":"我的电话是 135...。","py":"Wǒ de diànhuà shì yāo sān wǔ...","vi":"Điện thoại tôi là 135..."},{"zh":"你的电话号码是多少？","py":"Nǐ de diànhuà hàomǎ shì duōshao?","vi":"Số điện thoại của bạn là bao nhiêu?"}]},{"title":"Trợ từ ngữ khí 吧 (ba)","formula":"Cụm câu + <span>吧</span>","summary":"Đứng ở cuối câu cầu khiến để diễn tả sự đề nghị, yêu cầu hoặc mệnh lệnh nhẹ nhàng.","note":"<strong>Dịch nghĩa:</strong> ...nhé, ...đi, ...thôi.","examples":[{"zh":"你下午打吧。","py":"Nǐ xiàwǔ dǎ ba.","vi":"Buổi chiều bạn gọi lại nhé."},{"zh":"这儿没有人，请坐吧。","py":"Zhèr méi yǒu rén, qǐng zuò ba.","vi":"Ở đây không có ai, mời ngồi đi."},{"zh":"今天我们在家吃饭吧。","py":"Jīntiān wǒmen zài jiā chī fàn ba.","vi":"Hôm nay chúng ta ăn cơm ở nhà nhé."},{"zh":"我们去买书吧。","py":"Wǒmen qù mǎi shū ba.","vi":"Chúng ta đi mua sách đi."},{"zh":"你喝茶吧。","py":"Nǐ hē chá ba.","vi":"Bạn uống trà nhé."},{"zh":"明天下午去吧。","py":"Míngtiān xiàwǔ qù ba.","vi":"Chiều ngày mai đi nhé."},{"zh":"太晚了，睡觉吧。","py":"Tài wǎn le, shuì jiào ba.","vi":"Muộn quá rồi, ngủ thôi."},{"zh":"给我打电话吧。","py":"Gěi wǒ dǎ diànhuà ba.","vi":"Gọi điện thoại cho tôi nhé."}]}],"text":{"title":"课文 · Bài khoá","blocks":[{"titleZh":"打电话","titleVi":"Gọi điện thoại","icon":"📞","lines":[{"speaker":"A","zh":"喂，你在做什么呢？","py":"Wèi, nǐ zài zuò shénme ne?","vi":"A lô, bạn đang làm gì vậy?"},{"speaker":"B","zh":"我在看书呢。","py":"Wǒ zài kàn shū ne.","vi":"Tôi đang đọc sách."},{"speaker":"A","zh":"大卫也在看书吗？","py":"Dàwèi yě zài kàn shū ma?","vi":"David cũng đang đọc sách à?"},{"speaker":"B","zh":"他没看书，他在学做中国菜呢。","py":"Tā méi kàn shū, tā zài xué zuò Zhōngguó cài ne.","vi":"Không phải, anh ấy đang học nấu món ăn Trung Quốc."}]},{"titleZh":"在咖啡馆儿","titleVi":"Ở quán cà phê","icon":"☕","lines":[{"speaker":"A","zh":"昨天上午你在做什么呢？","py":"Zuótiān shàngwǔ nǐ zài zuò shénme ne?","vi":"Sáng hôm qua bạn đang làm gì vậy?"},{"speaker":"B","zh":"我在睡觉呢。你呢？","py":"Wǒ zài shuì jiào ne. Nǐ ne?","vi":"Tôi đang ngủ. Còn bạn thì sao?"},{"speaker":"A","zh":"我在家看电视呢。你喜欢看电视吗？","py":"Wǒ zài jiā kàn diànshì ne. Nǐ xǐhuan kàn diànshì ma?","vi":"Tôi xem tivi ở nhà. Bạn có thích xem tivi không?"},{"speaker":"B","zh":"我不喜欢看电视，我喜欢看电影。","py":"Wǒ bù xǐhuan kàn diànshì, wǒ xǐhuan kàn diànyǐng.","vi":"Tôi không thích xem tivi, tôi thích xem phim."}]},{"titleZh":"在学校办公室","titleVi":"Trong văn phòng trường","icon":"🏫","lines":[{"speaker":"A","zh":"82304155，这是李老师的电话吗？","py":"Bā èr sān líng sì yāo wǔ wǔ, zhè shì Lǐ lǎoshī de diànhuà ma?","vi":"82304155, đây là số điện thoại của cô Lý phải không?"},{"speaker":"B","zh":"不是。她的电话是 82304156。","py":"Bú shì. Tā de diànhuà shì bā èr sān líng sì yāo wǔ liù.","vi":"Không phải. Số của cô ấy là 82304156."},{"speaker":"A","zh":"好，我现在给她打电话。","py":"Hǎo, wǒ xiànzài gěi tā dǎ diànhuà.","vi":"Được, bây giờ tôi gọi điện cho cô ấy đây."},{"speaker":"B","zh":"她在工作呢，你下午打吧。","py":"Tā zài gōngzuò ne, nǐ xiàwǔ dǎ ba.","vi":"Cô ấy đang làm việc, buổi chiều bạn hãy gọi nhé."}]}]},"extra":[{"label":"Mục tiêu","html":"<h2 class=\"section-title\">Mục tiêu bài học</h2>\n  <p class=\"section-sub\">Bài 13 hướng dẫn cách diễn đạt một hành động đang xảy ra tại một thời điểm và những kỹ năng giao tiếp qua điện thoại.</p>\n  <div class=\"goal-grid\">\n    <div class=\"goal-item\">\n      <div class=\"num\">01</div>\n      <h4>Giao tiếp</h4>\n      <ul>\n        <li>Hỏi và nói về <b>những việc đang làm</b>.</li>\n        <li>Bắt đầu và kết thúc một <b>cuộc gọi điện thoại</b>.</li>\n        <li>Hỏi đáp về <b>sở thích</b> cá nhân (xem tivi, đọc sách).</li>\n      </ul>\n    </div>\n    <div class=\"goal-item\">\n      <div class=\"num\">02</div>\n      <h4>Từ vựng</h4>\n      <ul>\n        <li>Hành động: <b>学习, 睡觉, 打电话, 看书, 做饭</b>.</li>\n        <li>Giao tiếp ĐT: <b>喂, 给, 吧</b>.</li>\n        <li>Danh từ: <b>上午, 电视</b>.</li>\n        <li>Phó từ/Động từ: <b>也, 喜欢</b>.</li>\n      </ul>\n    </div>\n    <div class=\"goal-item\">\n      <div class=\"num\">03</div>\n      <h4>Ngữ pháp</h4>\n      <ul>\n        <li>Cấu trúc tiếp diễn: <b>在...呢</b> (đang).</li>\n        <li>Cách <b>đọc số điện thoại</b> trong tiếng Trung (số 1 đọc là yāo).</li>\n        <li>Từ cảm thán <b>喂</b>.</li>\n        <li>Trợ từ ngữ khí <b>吧</b>.</li>\n      </ul>\n    </div>\n  </div>"},{"label":"Điện thoại & Đang diễn ra","html":"<h2 class=\"section-title\">Giao tiếp Điện thoại &amp; Đang diễn ra</h2>\n  <p class=\"section-sub\">Nắm vững cách đọc số điện thoại chuẩn xác của người bản xứ và vận dụng cấu trúc tiếp diễn.</p>\n\n  <div class=\"card\">\n    <h3>1. Văn hoá đọc Số điện thoại</h3>\n    <p>Khác với tiếng Việt có thể gộp số để đọc (VD: Một trăm mười ba), trong tiếng Trung, <b>số điện thoại phải đọc tách rời từng chữ số một</b>.</p>\n    \n    <div class=\"formula-box\">\n      <div class=\"formula-label\">Quy tắc Vàng</div>\n      <div class=\"formula\">Số 1 trong số điện thoại, số phòng... luôn đọc là <span class=\"pop gold\">yāo</span> (幺) thay vì <span class=\"gold\">yī</span> (一)</div>\n    </div>\n    \n    <p style=\"margin-top: 14px; color: var(--muted); font-size: 0.95rem;\"><em>Nguyên nhân: Âm \"yī\" (1) và \"qī\" (7) rất dễ nghe nhầm qua điện thoại, nên người ta đổi 1 thành \"yāo\" để dễ phân biệt.</em></p>\n\n    <div class=\"phone-grid\">\n      <div class=\"phone-card\">\n        <div class=\"p-num\">110</div>\n        <div class=\"p-zh\">幺 幺 零</div>\n        <div class=\"p-py\">yāo yāo líng</div>\n        <div style=\"font-size:0.8rem; color:var(--ink-soft); margin-top:4px;\">(Cảnh sát TQ)</div>\n      </div>\n      <div class=\"phone-card\">\n        <div class=\"p-num\">138 5189 7623</div>\n        <div class=\"p-zh\">幺三八 五幺八九 七六二三</div>\n        <div class=\"p-py\">yāo sān bā wǔ yāo bā jiǔ qī liù èr sān</div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"card\">\n    <h3>2. Mẫu câu gọi điện thường dùng</h3>\n    <ul style=\"margin-top: 14px;\">\n      <li><b>Bắt máy:</b> 喂？(Wèi? - A lô?)</li>\n      <li><b>Hỏi thăm người nhận:</b> 喂，请问是李老师吗？(Wèi, qǐng wèn shì Lǐ lǎoshī ma? - A lô, xin hỏi là cô Lý phải không?)</li>\n      <li><b>Xác nhận số ĐT:</b> 这是李老师的电话吗？(Zhè shì Lǐ lǎoshī de diànhuà ma? - Đây là số điện thoại của cô Lý phải không?)</li>\n    </ul>\n\n    <div class=\"tip-card\">\n      <h5>💡 Cấu trúc \"在...呢\" (Đang...)</h5>\n      <p>Khi hỏi \"Bạn đang làm gì thế?\" qua điện thoại, người Trung Quốc thường xuyên thêm trợ từ <b>呢 (ne)</b> ở cuối câu để làm mềm giọng điệu.</p>\n      <p style=\"margin-top:8px;\">Hỏi: 你<b>在</b>做什么<b>呢</b>？(Nǐ zài zuò shénme ne?)</p>\n      <p>Đáp: 我<b>在</b>看书<b>呢</b>。(Wǒ zài kàn shū ne.)</p>\n    </div>\n  </div>"},{"label":"Lỗi sai","html":"<h2 class=\"section-title\">Lỗi sai thường gặp</h2>\n  <p class=\"section-sub\">Những lỗi người học tiếng Trung hay nhầm lẫn khi áp dụng cấu trúc Bài 13.</p>\n  <div class=\"error-grid\">\n    <div class=\"error-box\">\n      <div class=\"err-head wrong\">Lỗi 1 · Dùng \"呢\" trong câu phủ định của \"在\"</div>\n      <div class=\"err-body\">\n        <p style=\"margin-bottom:12px\">Câu khẳng định là \"在...呢\" (đang làm gì), nhưng khi phủ định \"没在...\" (không đang làm gì), ta tuyệt đối <b>KHÔNG</b> dùng \"呢\" ở cuối câu.</p>\n        <p class=\"strike zh\">我没在看书呢。</p>\n      </div>\n      <div class=\"err-head correct\">Cách sửa</div>\n      <div class=\"err-body\">\n        <p class=\"correct-text zh\">我没看书。</p>\n        <p class=\"correct-text zh\">我没在看书。</p>\n      </div>\n    </div>\n    <div class=\"error-box\">\n      <div class=\"err-head wrong\">Lỗi 2 · Vị trí của giới từ \"给\"</div>\n      <div class=\"err-body\">\n        <p style=\"margin-bottom:12px\">Người Việt quen nói \"Gọi điện thoại <b>cho tôi</b>\" (Động từ + Giới từ). Tiếng Trung bắt buộc Giới từ + Tân ngữ phải đứng <b>TRƯỚC</b> Động từ.</p>\n        <p class=\"strike zh\">打电话给我。</p>\n      </div>\n      <div class=\"err-head correct\">Cách sửa</div>\n      <div class=\"err-body\">\n        <p class=\"correct-text zh\">给我打电话。</p>\n        <p style=\"font-size:.88rem;color:var(--muted);margin-top:6px\">Cấu trúc chung: A + 给 + B + Động từ (A làm gì cho B).</p>\n      </div>\n    </div>\n    <div class=\"error-box\">\n      <div class=\"err-head wrong\">Lỗi 3 · Đọc \"1\" là \"yī\" trong số điện thoại</div>\n      <div class=\"err-body\">\n        <p style=\"margin-bottom:12px\">Thói quen đọc số đếm áp dụng vào việc đọc mã số, biển số xe, số phòng, số điện thoại.</p>\n        <p class=\"strike zh\">113 -> yī yī sān</p>\n      </div>\n      <div class=\"err-head correct\">Cách sửa</div>\n      <div class=\"err-body\">\n        <p class=\"correct-text zh\">113 -> 幺 幺 三 (yāo yāo sān)</p>\n        <p style=\"font-size:.88rem;color:var(--muted);margin-top:6px\">Luôn nhớ chuyển 1 thành 幺 (yāo) trong các dãy mã số.</p>\n      </div>\n    </div>\n  </div>"},{"label":"Tổng hợp","html":"<h2 class=\"section-title\">Tổng hợp kiến thức</h2>\n  <p class=\"section-sub\">Sơ đồ cốt lõi giúp tóm tắt toàn bộ Bài 13.</p>\n\n  <div class=\"syn-grid\">\n    <div class=\"syn-card theme-burgundy\">\n      <div class=\"syn-icon\">⏳</div>\n      <h3>Hành động Đang diễn ra</h3>\n      <table class=\"syn-table\">\n        <tr><th>Dạng</th><th>Công thức</th></tr>\n        <tr><td>Khẳng định</td><td>S + <span class=\"syn-keyhz\">在</span> + V + O + <span class=\"syn-keyhz\">呢</span></td></tr>\n        <tr><td>Phủ định</td><td>S + <span class=\"syn-keyhz\">没(在)</span> + V + O (Không 呢)</td></tr>\n      </table>\n      <div class=\"syn-mnemonic\">Ví dụ: 我<strong>在</strong>看书<strong>呢</strong>。(Đang đọc sách) / 他<strong>没</strong>看书。(Không đọc sách).</div>\n    </div>\n\n    <div class=\"syn-card theme-gold\">\n      <div class=\"syn-icon\">📞</div>\n      <h3>Gọi điện: 给我...</h3>\n      <p>Cấu trúc: <b>Cho ai đó làm gì</b>.</p>\n      <div class=\"syn-flow\">\n        <div class=\"step\">Chủ ngữ<br><span class=\"syn-keyhz\">我</span></div>\n        <span class=\"arrow\">+</span>\n        <div class=\"step\">Cho ai<br><span class=\"syn-keyhz\">给他</span></div>\n        <span class=\"arrow\">+</span>\n        <div class=\"step\">Làm gì<br><span class=\"syn-keyhz\">打电话</span></div>\n      </div>\n      <div class=\"syn-mnemonic\"><strong>Nhớ:</strong> Đưa đối tượng tiếp nhận lên trước hành động.</div>\n    </div>\n\n    <div class=\"syn-card theme-ink\">\n      <div class=\"syn-icon\">🔢</div>\n      <h3>Quy tắc số điện thoại</h3>\n      <ul style=\"font-size:0.95rem; line-height:1.6; margin-top:10px; color:var(--ink-soft); padding-left:18px;\">\n        <li>Đọc tách rời từng chữ số.</li>\n        <li>Tuyệt đối <b>không dùng 两</b> cho số 2. Vẫn đọc là 二 (èr).</li>\n        <li>Số 1 đọc là <span class=\"syn-keyhz\">幺 (yāo)</span>.</li>\n      </ul>\n    </div>\n\n    <div class=\"syn-card theme-burgundy\">\n      <div class=\"syn-icon\">💁</div>\n      <h3>Trợ từ 吧 (ba)</h3>\n      <p>Đứng cuối câu, biểu thị sự đề nghị, thỉnh cầu, mệnh lệnh nhẹ nhàng.</p>\n      <div class=\"syn-flow\">\n        <div class=\"step\">Hành động<br><span class=\"syn-keyhz\">你下午打</span></div>\n        <span class=\"arrow\">+</span>\n        <div class=\"step\">Trợ từ<br><span class=\"syn-keyhz\">吧</span></div>\n      </div>\n      <div class=\"syn-mnemonic\">Dịch là: <strong>...nhé, ...đi, ...thôi</strong>. (VD: 我们去吃饭吧 - Đi ăn thôi).</div>\n    </div>\n\n    <div class=\"syn-card theme-gold\" style=\"grid-column: 1 / -1;\">\n      <div class=\"syn-icon\">⚡</div>\n      <h3>Câu thần chú 5 mẫu</h3>\n      <table class=\"syn-table\">\n        <tr><th>Mẫu</th><th>Tình huống</th></tr>\n        <tr><td><span class=\"syn-keyhz\">喂，你在做什么呢？</span></td><td>Hỏi thăm qua điện thoại xem đối phương đang làm gì.</td></tr>\n        <tr><td><span class=\"syn-keyhz\">我在学习呢。</span></td><td>Trả lời về hành động đang diễn ra.</td></tr>\n        <tr><td><span class=\"syn-keyhz\">你喜欢看电影吗？</span></td><td>Hỏi về sở thích.</td></tr>\n        <tr><td><span class=\"syn-keyhz\">这是李老师的电话吗？</span></td><td>Xác nhận số điện thoại.</td></tr>\n        <tr><td><span class=\"syn-keyhz\">我现在给她打电话。</span></td><td>Nói dự định sẽ gọi điện cho ai.</td></tr>\n      </table>\n      <div class=\"syn-mnemonic\"><strong>Thuộc 5 mẫu này là pass Bài 13.</strong></div>\n    </div>\n  </div>"}],"cssId":"ce40c3e49"},{"id":"k1v2-b14","courseId":"k1v2","order":14,"title":"Cô ấy đã mua nhiều quần áo.","titleZh":"她买了不少衣服。","vocab":[{"stt":1,"hanzi":"东西","pinyin":"dōngxi","hanviet":"Đông tây","pos":"Danh từ","meaning":"Đồ, đồ đạc, đồ vật","comps":"买东西 · 吃东西","example":{"zh":"我去商店买东西了。","py":"Wǒ qù shāngdiàn mǎi dōngxi le.","vi":"Tôi đến cửa hàng mua đồ rồi."}},{"stt":2,"hanzi":"一点儿","pinyin":"yìdiǎnr","hanviet":"Nhất điểm nhi","pos":"Số lượng","meaning":"Một ít, một chút","comps":"喝一点儿水 · 一点儿东西","example":{"zh":"我买了一点儿苹果。","py":"Wǒ mǎi le yìdiǎnr píngguǒ.","vi":"Tôi đã mua một ít táo."}},{"stt":3,"hanzi":"苹果","pinyin":"píngguǒ","hanviet":"Bình quả","pos":"Danh từ","meaning":"Quả táo","comps":"吃苹果 · 买苹果","example":{"zh":"桌子上有一点儿苹果。","py":"Zhuōzi shang yǒu yìdiǎnr píngguǒ.","vi":"Trên bàn có một ít táo."}},{"stt":4,"hanzi":"看见","pinyin":"kànjiàn","hanviet":"Khán kiến","pos":"Động từ","meaning":"Nhìn thấy","comps":"看见他了 · 没看见","example":{"zh":"你看见张先生了吗？","py":"Nǐ kànjiàn Zhāng xiānsheng le ma?","vi":"Bạn có thấy ông Trương không?"}},{"stt":5,"hanzi":"先生","pinyin":"xiānsheng","hanviet":"Tiên sinh","pos":"Danh từ","meaning":"Ông, ngài, thầy","comps":"张先生 · 李先生","example":{"zh":"张先生去学开车了。","py":"Zhāng xiānsheng qù xué kāi chē le.","vi":"Ông Trương đi học lái xe rồi."}},{"stt":6,"hanzi":"开","pinyin":"kāi","hanviet":"Khai","pos":"Động từ","meaning":"Lái (xe), mở","comps":"开车 · 开门","example":{"zh":"他去学开车了。","py":"Tā qù xué kāi chē le.","vi":"Anh ấy đi học lái xe rồi."}},{"stt":7,"hanzi":"车","pinyin":"chē","hanviet":"Xa","pos":"Danh từ","meaning":"Xe, xe cộ","comps":"开车 · 坐车 · 火车","example":{"zh":"爸爸在开车呢。","py":"Bàba zài kāi chē ne.","vi":"Bố đang lái xe."}},{"stt":8,"hanzi":"回来","pinyin":"huílai","hanviet":"Hồi lai","pos":"Động từ","meaning":"Về, trở lại","comps":"回家 · 他回来了","example":{"zh":"他什么时候能回来？","py":"Tā shénme shíhou néng huílai?","vi":"Khi nào ông ấy có thể quay lại?"}},{"stt":9,"hanzi":"分钟","pinyin":"fēnzhōng","hanviet":"Phân chung","pos":"Danh từ","meaning":"Phút (khoảng thời gian)","comps":"十分钟 · 几分钟","example":{"zh":"四十分钟后回来。","py":"Sìshí fēnzhōng hòu huílai.","vi":"40 phút sau sẽ quay lại."}},{"stt":10,"hanzi":"后","pinyin":"hòu","hanviet":"Hậu","pos":"Danh từ","meaning":"Sau, sau khi","comps":"后来 · 星期五后","example":{"zh":"他五点后回家。","py":"Tā wǔ diǎn hòu huí jiā.","vi":"Sau 5 giờ anh ấy về nhà."}},{"stt":11,"hanzi":"衣服","pinyin":"yīfu","hanviet":"Y phục","pos":"Danh từ","meaning":"Quần áo","comps":"买衣服 · 洗衣服","example":{"zh":"王方的衣服太漂亮了！","py":"Wáng Fāng de yīfu tài piàoliang le!","vi":"Quần áo của Vương Phương đẹp quá!"}},{"stt":12,"hanzi":"漂亮","pinyin":"piàoliang","hanviet":"Phiêu lượng","pos":"Tính từ","meaning":"Đẹp, xinh đẹp","comps":"很漂亮 · 漂亮衣服","example":{"zh":"这件衣服很漂亮。","py":"Zhè jiàn yīfu hěn piàoliang.","vi":"Bộ quần áo này rất đẹp."}},{"stt":13,"hanzi":"少","pinyin":"shǎo","hanviet":"Thiểu","pos":"Tính từ","meaning":"Ít","comps":"多少 · 不少 (Nhiều)","example":{"zh":"她买了不少衣服。","py":"Tā mǎi le bùshǎo yīfu.","vi":"Cô ấy đã mua khá nhiều quần áo."}},{"stt":14,"hanzi":"这些","pinyin":"zhèxiē","hanviet":"Giá ta","pos":"Đại từ","meaning":"Những (cái) này","comps":"这些人 · 这些书","example":{"zh":"这些都是王方的东西。","py":"Zhèxiē dōu shì Wáng Fāng de dōngxi.","vi":"Những thứ này đều là đồ của Vương Phương."}},{"stt":15,"hanzi":"都","pinyin":"dōu","hanviet":"Đô","pos":"Phó từ","meaning":"Đều, tất cả","comps":"都是 · 都有","example":{"zh":"他们都喜欢喝茶。","py":"Tāmen dōu xǐhuan hē chá.","vi":"Bọn họ đều thích uống trà."}}],"hanzi":[{"char":"东西","pinyin":"dōngxi","hanviet":"Đông tây","chars":["东","西"],"story":"Đông và Tây. Người xưa mua hàng hóa ở chợ phía Đông và phía Tây, nên ghép lại thành \"Đồ đạc\". (Lưu ý chữ xi thanh nhẹ)."},{"char":"一点儿","pinyin":"yìdiǎnr","hanviet":"Nhất điểm nhi","chars":["一","点","儿"],"story":"Thường đứng trước danh từ không đếm được hoặc để giảm nhẹ ngữ khí."},{"char":"苹果","pinyin":"píngguǒ","hanviet":"Bình quả","chars":["苹","果"],"story":"果 (quả - có bộ Mộc 木 chỉ cây cối). 苹 là tên một loại cây."},{"char":"看见","pinyin":"kànjiàn","hanviet":"Khán kiến","chars":["看","见"],"story":"看 (nhìn) + 见 (thấy). Biểu thị kết quả của hành động nhìn là đã thấy được."},{"char":"先生","pinyin":"xiānsheng","hanviet":"Tiên sinh","chars":["先","生"],"story":"先 (trước) + 生 (sinh ra). Người sinh ra trước thường có kiến thức, được tôn trọng, gọi là Tiên sinh."},{"char":"开","pinyin":"kāi","hanviet":"Khai","chars":["开"],"story":"Hình ảnh hai tay đang rút chốt cửa ra để mở."},{"char":"车","pinyin":"chē","hanviet":"Xa","chars":["车"],"story":"Chữ tượng hình, mô phỏng chiếc xe có hai bánh hai bên và trục ở giữa."},{"char":"回来","pinyin":"huílai","hanviet":"Hồi lai","chars":["回","来"],"story":"回 (quay về) + 来 (hướng về phía người nói)."},{"char":"分钟","pinyin":"fēnzhōng","hanviet":"Phân chung","chars":["分","钟"],"story":"Phân biệt với 分 (dùng để nói mốc giờ 10:10). 分钟 dùng để chỉ khoảng/lượng thời gian."},{"char":"后","pinyin":"hòu","hanviet":"Hậu","chars":["后"],"story":"Chỉ thời gian tương lai, hoặc phía sau."},{"char":"衣服","pinyin":"yīfu","hanviet":"Y phục","chars":["衣","服"],"story":"Chữ 衣 mô phỏng cổ áo và tà áo đan chéo nhau."},{"char":"漂亮","pinyin":"piàoliang","hanviet":"Phiêu lượng","chars":["漂","亮"],"story":"Thường dùng khen ngợi ngoại hình phụ nữ, quần áo, cảnh vật."},{"char":"少","pinyin":"shǎo","hanviet":"Thiểu","chars":["少"],"story":"Ngược lại với 多 (Nhiều). Khi kết hợp thành 不少 thì nghĩa là \"Không ít -> Rất nhiều\"."},{"char":"这些","pinyin":"zhèxiē","hanviet":"Giá ta","chars":["这","些"],"story":"这 (Này) + 些 (Vài/những). Số nhiều của 这个."},{"char":"都","pinyin":"dōu","hanviet":"Đô","chars":["都"],"story":"Bao quát tất cả những đối tượng đã được nhắc đến ở trước."}],"grammar":[{"title":"Trợ từ động thái 了 (Hoàn thành)","formula":"Cuối câu: S + V + O + <span>了</span><br>Giữa câu: S + V + <span>了</span> + [Số lượng] + O","summary":"Trợ từ \"了\" đứng ở cuối câu hoặc sau động từ, biểu thị một hành động đã xảy ra hoặc đã hoàn thành.","note":"<strong>Phủ định:</strong> Dùng \"没\" trước động từ và TUYỆT ĐỐI bỏ chữ \"了\". (VD: 我没买).","examples":[{"zh":"我去商店买东西了。","py":"Wǒ qù shāngdiàn mǎi dōngxi le.","vi":"Tôi đã đến cửa hàng mua đồ."},{"zh":"他去学开车了。","py":"Tā qù xué kāi chē le.","vi":"Anh ấy đã đi học lái xe rồi."},{"zh":"你买什么了？","py":"Nǐ mǎi shénme le?","vi":"Bạn đã mua gì thế?"},{"zh":"我买了一点儿苹果。","py":"Wǒ mǎi le yìdiǎnr píngguǒ.","vi":"Tôi đã mua một ít táo."},{"zh":"她买了不少衣服。","py":"Tā mǎi le bùshǎo yīfu.","vi":"Cô ấy đã mua khá nhiều quần áo."},{"zh":"你看见了几个人？","py":"Nǐ kànjiàn le jǐ ge rén?","vi":"Bạn đã nhìn thấy mấy người?"},{"zh":"她没去商店。","py":"Tā méi qù shāngdiàn.","vi":"Cô ấy đã không đến cửa hàng. (Phủ định)"},{"zh":"我没看见张先生。","py":"Wǒ méi kànjiàn Zhāng xiānsheng.","vi":"Tôi không nhìn thấy ông Trương. (Phủ định)"}]},{"title":"Danh từ chỉ thời gian 后 (Sau)","formula":"Mốc thời gian / Khoảng thời gian + <span>后</span>","summary":"Chỉ khoảng thời gian sau thời điểm hiện tại hoặc sau khoảng thời gian được đề cập.","note":"<strong>Khác tiếng Việt:</strong> Tiếng Việt nói \"Sau 40 phút\", Tiếng Trung nói \"40 phút sau\" (40分钟后).","examples":[{"zh":"四十分钟后回来。","py":"Sìshí fēnzhōng hòu huílai.","vi":"40 phút sau sẽ quay lại."},{"zh":"他五点后回家。","py":"Tā wǔ diǎn hòu huí jiā.","vi":"Anh ấy về nhà sau 5 giờ."},{"zh":"星期三后","py":"xīngqīsān hòu","vi":"Sau thứ Tư"},{"zh":"三天后","py":"sān tiān hòu","vi":"3 ngày sau"},{"zh":"你几点去工作？八点后。","py":"Nǐ jǐ diǎn qù gōngzuò? Bā diǎn hòu.","vi":"Bạn mấy giờ đi làm? Sau 8 giờ."},{"zh":"你什么时候回家？五点后。","py":"Nǐ shénme shíhou huí jiā? Wǔ diǎn hòu.","vi":"Khi nào bạn về nhà? Sau 5 giờ."},{"zh":"他什么时候能回来？","py":"Tā shénme shíhou néng huílai?","vi":"Khi nào anh ấy có thể quay lại?"},{"zh":"我十分钟后去学校。","py":"Wǒ shí fēnzhōng hòu qù xuéxiào.","vi":"10 phút sau tôi đến trường."}]},{"title":"Trợ từ ngữ khí 啊 (a)","formula":"... <span>啊</span>","summary":"Dùng ở cuối câu trần thuật để biểu đạt cảm xúc (như ngạc nhiên, khen ngợi, hoặc khẳng định chắc chắn).","note":"<strong>Biến âm:</strong> Tùy âm tiết trước nó mà \"啊\" có thể đọc thành wa, ya, na... nhưng chữ viết vẫn là 啊.","examples":[{"zh":"王方的衣服太漂亮了！","py":"Wáng Fāng de yīfu tài piàoliang le!","vi":"Quần áo của Vương Phương đẹp quá!"},{"zh":"是啊，她买了不少衣服。","py":"Shì a, tā mǎi le bùshǎo yīfu.","vi":"Đúng thế, cô ấy mua nhiều quần áo lắm."},{"zh":"你是王小姐吗？是啊。","py":"Nǐ shì Wáng xiǎojiě ma? Shì a.","vi":"Chị là cô Vương phải không? Đúng vậy."},{"zh":"你想去吃中国菜吗？好啊。","py":"Nǐ xiǎng qù chī Zhōngguó cài ma? Hǎo a.","vi":"Bạn muốn đi ăn món Trung Quốc không? Được thôi."},{"zh":"太好吃了啊！","py":"Tài hǎochī le a!","vi":"Ngon quá đi mất!"},{"zh":"对啊！","py":"Duì a!","vi":"Đúng á!"},{"zh":"他没来啊。","py":"Tā méi lái a.","vi":"Anh ấy không đến đâu."},{"zh":"真多啊。","py":"Zhēn duō a.","vi":"Thật nhiều quá."}]},{"title":"Phó từ 都 (Đều / Tất cả)","formula":"S (Số nhiều) + <span>都</span> + V / Adj","summary":"Dùng để bao quát lại toàn bộ những đối tượng đã nhắc đến ở phía trước. Đứng TRƯỚC động từ/tính từ.","note":"<strong>Bắt buộc:</strong> Đối tượng được nhắc đến phải đặt TRƯỚC từ \"都\".","examples":[{"zh":"这些都是王方的东西。","py":"Zhèxiē dōu shì Wáng Fāng de dōngxi.","vi":"Những thứ này đều là đồ của Vương Phương."},{"zh":"我们都是中国人。","py":"Wǒmen dōu shì Zhōngguó rén.","vi":"Chúng tôi đều là người Trung Quốc."},{"zh":"他们都喜欢喝茶。","py":"Tāmen dōu xǐhuan hē chá.","vi":"Bọn họ đều thích uống trà."},{"zh":"这些衣服都很漂亮。","py":"Zhèxiē yīfu dōu hěn piàoliang.","vi":"Những bộ quần áo này đều rất đẹp."},{"zh":"苹果和水，我都喜欢。","py":"Píngguǒ hé shuǐ, wǒ dōu xǐhuan.","vi":"Táo và nước, tôi đều thích."},{"zh":"我们都没买东西。","py":"Wǒmen dōu méi mǎi dōngxi.","vi":"Chúng tôi đều không mua đồ."},{"zh":"爸爸妈妈都在家。","py":"Bàba māma dōu zài jiā.","vi":"Bố mẹ đều ở nhà."},{"zh":"他们都去医院了。","py":"Tāmen dōu qù yīyuàn le.","vi":"Bọn họ đều đi bệnh viện rồi."}]}],"text":{"title":"课文 · Bài khoá","blocks":[{"titleZh":"在宿舍","titleVi":"Ở ký túc xá","icon":"🏢","lines":[{"speaker":"A","zh":"昨天上午你去哪儿了？","py":"Zuótiān shàngwǔ nǐ qù nǎr le?","vi":"Sáng hôm qua bạn đi đâu vậy?"},{"speaker":"B","zh":"我去商店买东西了。","py":"Wǒ qù shāngdiàn mǎi dōngxi le.","vi":"Mình đến cửa hàng để mua đồ."},{"speaker":"A","zh":"你买什么了？","py":"Nǐ mǎi shénme le?","vi":"Bạn mua gì vậy?"},{"speaker":"B","zh":"我买了一点儿苹果。","py":"Wǒ mǎi le yìdiǎnr píngguǒ.","vi":"Mình mua một ít táo."}]},{"titleZh":"在公司","titleVi":"Trong công ty","icon":"💼","lines":[{"speaker":"A","zh":"你看见张先生了吗？","py":"Nǐ kànjiàn Zhāng xiānsheng le ma?","vi":"Anh có thấy ông Trương không?"},{"speaker":"B","zh":"看见了，他去学开车了。","py":"Kànjiàn le, tā qù xué kāi chē le.","vi":"Thấy rồi, ông ấy đi học lái xe rồi."},{"speaker":"A","zh":"他什么时候能回来？","py":"Tā shénme shíhou néng huílai?","vi":"Khi nào ông ấy quay lại?"},{"speaker":"B","zh":"40分钟后回来。","py":"Sìshí fēnzhōng hòu huílai.","vi":"40 phút nữa (sẽ quay lại)."}]},{"titleZh":"在商店门口","titleVi":"Trước cửa hàng","icon":"🛒","lines":[{"speaker":"A","zh":"王方的衣服太漂亮了！","py":"Wáng Fāng de yīfu tài piàoliang le!","vi":"Quần áo của Vương Phương đẹp quá!"},{"speaker":"B","zh":"是啊，她买了不少衣服。","py":"Shì a, tā mǎi le bùshǎo yīfu.","vi":"Đúng vậy. Cô ấy mua nhiều quần áo lắm."},{"speaker":"A","zh":"你买什么了？","py":"Nǐ mǎi shénme le?","vi":"Còn bạn mua những gì?"},{"speaker":"B","zh":"我没买，这些都是王方的东西。","py":"Wǒ méi mǎi, zhèxiē dōu shì Wáng Fāng de dōngxi.","vi":"Mình không mua gì cả, những thứ này đều là đồ của Vương Phương."}]}]},"extra":[{"label":"Mục tiêu","html":"<h2 class=\"section-title\">Mục tiêu bài học</h2>\n  <p class=\"section-sub\">Bài 14 hướng dẫn cách kể lại những việc đã làm, đi mua sắm và ước lượng thời gian một người sẽ quay lại.</p>\n  <div class=\"goal-grid\">\n    <div class=\"goal-item\">\n      <div class=\"num\">01</div>\n      <h4>Giao tiếp</h4>\n      <ul>\n        <li>Kể lại một <b>hành động đã xảy ra</b> (đi đâu, làm gì).</li>\n        <li>Hỏi đáp về <b>kết quả mua sắm</b> (mua bao nhiêu, mua gì).</li>\n        <li>Ước lượng <b>thời gian</b> ai đó sẽ quay lại (sau bao lâu).</li>\n      </ul>\n    </div>\n    <div class=\"goal-item\">\n      <div class=\"num\">02</div>\n      <h4>Từ vựng</h4>\n      <ul>\n        <li>Đồ vật: <b>东西, 苹果, 衣服, 车</b>.</li>\n        <li>Định lượng: <b>一点儿, 这些, 少, 不少, 都</b>.</li>\n        <li>Thời gian: <b>分钟, 后</b>.</li>\n        <li>Động từ: <b>看见, 开, 回来</b>.</li>\n      </ul>\n    </div>\n    <div class=\"goal-item\">\n      <div class=\"num\">03</div>\n      <h4>Ngữ pháp</h4>\n      <ul>\n        <li>Trợ từ động thái <b>了</b> (sự việc đã hoàn thành).</li>\n        <li>Danh từ thời gian <b>后</b> (Sau khi).</li>\n        <li>Trợ từ ngữ khí <b>啊</b>.</li>\n        <li>Phó từ <b>都</b> (Đều / Tất cả).</li>\n      </ul>\n    </div>\n  </div>"},{"label":"Định lượng & Mua sắm","html":"<h2 class=\"section-title\">Định lượng &amp; Mua sắm</h2>\n  <p class=\"section-sub\">Phân biệt sự khác nhau giữa các từ chỉ số lượng không xác định để dùng chuẩn như người bản xứ khi đi mua sắm.</p>\n\n  <div class=\"card\">\n    <h3>1. Từ chỉ số lượng không xác định</h3>\n    \n    <div class=\"quant-grid\">\n      <div class=\"quant-card\">\n        <div class=\"q-zh\">一点儿</div>\n        <div class=\"q-py\">yìdiǎnr</div>\n        <div class=\"q-vi\">Một ít, một chút</div>\n        <div class=\"q-ex\">Thường dùng với danh từ không đếm được (nước, trà) hoặc muốn nhấn mạnh sự nhỏ lẻ. <br><br><b>买了一点儿苹果。</b></div>\n      </div>\n      <div class=\"quant-card\" style=\"border-top-color: var(--gold);\">\n        <div class=\"q-zh\">些 / 这些</div>\n        <div class=\"q-py\">xiē / zhèxiē</div>\n        <div class=\"q-vi\">Vài / Những cái này</div>\n        <div class=\"q-ex\">Lượng từ số nhiều, thay thế cho \"个\" khi số lượng > 1. <br><br><b>这些衣服很漂亮。</b></div>\n      </div>\n      <div class=\"quant-card\" style=\"border-top-color: var(--ink);\">\n        <div class=\"q-zh\">不少</div>\n        <div class=\"q-py\">bùshǎo</div>\n        <div class=\"q-vi\">Nhiều (Không ít)</div>\n        <div class=\"q-ex\">Dùng để cảm thán, nhấn mạnh số lượng thực tế mua rất nhiều. <br><br><b>她买了不少衣服。</b></div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"card\">\n    <h3>2. Trợ từ \"了\" trong bối cảnh mua sắm</h3>\n    <p>Khi đi mua sắm, hành động \"đã mua xong\" được diễn đạt bằng trợ từ <b>了 (le)</b>.</p>\n    \n    <div class=\"formula-box\">\n      <div class=\"formula-label\">Vị trí của chữ 了</div>\n      <div class=\"formula\">Động từ + <span class=\"pop gold\">了</span> + Số lượng + Danh từ</div>\n    </div>\n    \n    <p style=\"margin-top: 14px;\"><em>Ví dụ:</em></p>\n    <ul style=\"color:var(--ink-soft); line-height: 1.8;\">\n      <li>我买<b>了</b>一点儿苹果。(Tôi đã mua một ít táo.)</li>\n      <li>她买<b>了</b>不少衣服。(Cô ấy đã mua khá nhiều quần áo.)</li>\n      <li>大卫买<b>了</b>一个杯子。(David đã mua một cái ly.)</li>\n    </ul>\n\n    <div class=\"tip-card\" style=\"margin-top:16px;\">\n      <h5>💡 Phủ định của \"了\"</h5>\n      <p>Khi bạn <b>chưa</b> mua hoặc <b>không</b> mua, ta dùng <b>没 (méi)</b> trước động từ, và tuyệt đối <b>bỏ chữ 了</b> đi.</p>\n      <p>✔️ 我没买东西。(Tôi không mua đồ.)</p>\n    </div>\n  </div>"},{"label":"Lỗi sai","html":"<h2 class=\"section-title\">Lỗi sai thường gặp</h2>\n  <p class=\"section-sub\">Những lỗi người học tiếng Trung hay mắc phải khi nói về hành động đã xảy ra.</p>\n  <div class=\"error-grid\">\n    <div class=\"error-box\">\n      <div class=\"err-head wrong\">Lỗi 1 · Dùng \"了\" trong câu phủ định</div>\n      <div class=\"err-body\">\n        <p style=\"margin-bottom:12px\">Nhiều bạn nghĩ \"了\" là thì quá khứ nên câu nào ở quá khứ cũng gắn \"了\". Thực tế, nếu dùng \"没\" (không/chưa) thì hành động đó chưa xảy ra, nên <b>không có \"了\"</b>.</p>\n        <p class=\"strike zh\">昨天我没去商店了。</p>\n        <p class=\"strike zh\">我没买了。</p>\n      </div>\n      <div class=\"err-head correct\">Cách sửa</div>\n      <div class=\"err-body\">\n        <p class=\"correct-text zh\">昨天我没去商店。</p>\n        <p class=\"correct-text zh\">我没买。</p>\n      </div>\n    </div>\n    <div class=\"error-box\">\n      <div class=\"err-head wrong\">Lỗi 2 · Vị trí của phó từ 都 (Đều)</div>\n      <div class=\"err-body\">\n        <p style=\"margin-bottom:12px\">Theo thói quen tiếng Việt \"Đều là họ\", học viên thường đặt \"都\" lên trước chủ ngữ. Trong tiếng Trung, \"都\" là phó từ, phải đứng <b>SAU chủ ngữ, TRƯỚC động từ</b>.</p>\n        <p class=\"strike zh\">都是王方的东西。</p>\n        <p class=\"strike zh\">都他们喜欢喝茶。</p>\n      </div>\n      <div class=\"err-head correct\">Cách sửa</div>\n      <div class=\"err-body\">\n        <p class=\"correct-text zh\">这些都是王方的东西。</p>\n        <p class=\"correct-text zh\">他们都喜欢喝茶。</p>\n      </div>\n    </div>\n    <div class=\"error-box\">\n      <div class=\"err-head wrong\">Lỗi 3 · Dịch word-by-word \"Sau 40 phút\"</div>\n      <div class=\"err-body\">\n        <p style=\"margin-bottom:12px\">Tiếng Việt nói \"Sau + [Thời gian]\". Tiếng Trung thì ngược lại, danh từ <b>后</b> phải đứng <b>SAU</b> khoảng thời gian.</p>\n        <p class=\"strike zh\">他后40分钟回来。</p>\n      </div>\n      <div class=\"err-head correct\">Cách sửa</div>\n      <div class=\"err-body\">\n        <p class=\"correct-text zh\">他40分钟后回来。</p>\n        <p style=\"font-size:.88rem;color:var(--muted);margin-top:6px\">Tương tự: \"Sau 5 giờ\" là 五点后, \"Sau thứ Tư\" là 星期三后.</p>\n      </div>\n    </div>\n  </div>"},{"label":"Tổng hợp","html":"<h2 class=\"section-title\">Tổng hợp kiến thức</h2>\n  <p class=\"section-sub\">Sơ đồ cốt lõi giúp tóm tắt toàn bộ Bài 14.</p>\n\n  <div class=\"syn-grid\">\n    <div class=\"syn-card theme-burgundy\">\n      <div class=\"syn-icon\">✅</div>\n      <h3>Trợ từ 了 (Hoàn thành)</h3>\n      <table class=\"syn-table\">\n        <tr><th>Loại</th><th>Cấu trúc</th></tr>\n        <tr><td>Cuối câu</td><td>S + V + O + <span class=\"syn-keyhz\">了</span> (我去商店了)</td></tr>\n        <tr><td>Giữa câu</td><td>S + V + <span class=\"syn-keyhz\">了</span> + Số lượng + O (买了苹果)</td></tr>\n        <tr><td>Phủ định</td><td>S + <span class=\"syn-keyhz\">没</span> + V + O (我没买)</td></tr>\n      </table>\n      <div class=\"syn-mnemonic\">Cứ có \"没\" là mất \"了\".</div>\n    </div>\n\n    <div class=\"syn-card theme-gold\">\n      <div class=\"syn-icon\">⏳</div>\n      <h3>Từ chỉ thời gian: 后</h3>\n      <p>Biểu thị thời điểm sau hiện tại hoặc sau một mốc nào đó.</p>\n      <div class=\"syn-flow\">\n        <div class=\"step\">Thời gian<br><span class=\"syn-keyhz\">四十分钟</span></div>\n        <span class=\"arrow\">+</span>\n        <div class=\"step\">Danh từ<br><span class=\"syn-keyhz\">后</span></div>\n        <span class=\"arrow\">+</span>\n        <div class=\"step\">Hành động<br><span class=\"syn-keyhz\">回来</span></div>\n      </div>\n      <div class=\"syn-mnemonic\">Ngược với tiếng Việt (Sau 40 phút -> 40 phút sau).</div>\n    </div>\n\n    <div class=\"syn-card theme-ink\">\n      <div class=\"syn-icon\">🛍️</div>\n      <h3>Từ chỉ Định lượng</h3>\n      <ul style=\"font-size:0.95rem; line-height:1.6; margin-top:10px; color:var(--ink-soft); padding-left:18px;\">\n        <li><span class=\"syn-keyhz\">一点儿</span>: Một ít, một chút.</li>\n        <li><span class=\"syn-keyhz\">些 (这些)</span>: Vài, những (dùng cho số nhiều).</li>\n        <li><span class=\"syn-keyhz\">不少</span>: Không ít -> Rất nhiều.</li>\n      </ul>\n      <div class=\"syn-mnemonic\">Đều đứng trước Danh từ. (买了一点儿苹果).</div>\n    </div>\n\n    <div class=\"syn-card theme-burgundy\">\n      <div class=\"syn-icon\">👥</div>\n      <h3>Phó từ 都 (Đều)</h3>\n      <p>Gộp toàn bộ chủ thể, luôn đứng sau Chủ ngữ, trước Động từ.</p>\n      <div class=\"syn-flow\">\n        <div class=\"step\">S (Nhiều)<br><span class=\"syn-keyhz\">这些东西</span></div>\n        <span class=\"arrow\">+</span>\n        <div class=\"step\">Phó từ<br><span class=\"syn-keyhz\">都</span></div>\n        <span class=\"arrow\">+</span>\n        <div class=\"step\">Động từ<br><span class=\"syn-keyhz\">是</span></div>\n      </div>\n      <div class=\"syn-mnemonic\"><strong>Cấm kỵ:</strong> Không để 都 lên đầu câu.</div>\n    </div>\n\n    <div class=\"syn-card theme-gold\" style=\"grid-column: 1 / -1;\">\n      <div class=\"syn-icon\">⚡</div>\n      <h3>Câu thần chú 5 mẫu</h3>\n      <table class=\"syn-table\">\n        <tr><th>Mẫu</th><th>Tình huống</th></tr>\n        <tr><td><span class=\"syn-keyhz\">昨天上午你去哪儿了？</span></td><td>Hỏi xem ai đó đã đi đâu.</td></tr>\n        <tr><td><span class=\"syn-keyhz\">我买了一点儿苹果。</span></td><td>Kể lại mình đã mua được gì (số lượng ít).</td></tr>\n        <tr><td><span class=\"syn-keyhz\">你看见张先生了吗？</span></td><td>Hỏi xem có nhìn thấy ai đó không.</td></tr>\n        <tr><td><span class=\"syn-keyhz\">他40分钟后回来。</span></td><td>Hẹn thời gian một người sẽ quay lại.</td></tr>\n        <tr><td><span class=\"syn-keyhz\">这些都是王方的东西。</span></td><td>Xác nhận tất cả đồ đạc thuộc về ai.</td></tr>\n      </table>\n      <div class=\"syn-mnemonic\"><strong>Thuộc 5 mẫu này là pass Bài 14.</strong></div>\n    </div>\n  </div>"}],"cssId":"cee1abbca"},{"id":"k1v2-b15","courseId":"k1v2","order":15,"title":"Tôi đáp máy bay đến đây","titleZh":"我是坐飞机来的","vocab":[{"stt":1,"hanzi":"认识","pinyin":"rènshi","hanviet":"Nhận thức","pos":"Động từ","meaning":"Quen, quen biết","comps":"很高兴认识你 · 不认识","example":{"zh":"很高兴认识您！","py":"Hěn gāoxìng rènshi nín!","vi":"Rất vui được quen biết ngài!"}},{"stt":2,"hanzi":"年","pinyin":"nián","hanviet":"Niên","pos":"Danh từ","meaning":"Năm","comps":"今年 · 明年 · 2011年","example":{"zh":"我们是2011年认识的。","py":"Wǒmen shì èr líng yī yī nián rènshi de.","vi":"Chúng tôi quen nhau vào năm 2011."}},{"stt":3,"hanzi":"大学","pinyin":"dàxué","hanviet":"Đại học","pos":"Danh từ","meaning":"Đại học","comps":"上大学 · 大学同学","example":{"zh":"她是我大学同学。","py":"Tā shì wǒ dàxué tóngxué.","vi":"Cô ấy là bạn học đại học của tôi."}},{"stt":4,"hanzi":"饭店","pinyin":"fàndiàn","hanviet":"Phạn điếm","pos":"Danh từ","meaning":"Khách sạn, nhà hàng","comps":"来饭店 · 去饭店","example":{"zh":"你们是怎么来饭店的？","py":"Nǐmen shì zěnme lái fàndiàn de?","vi":"Các bạn đến nhà hàng bằng cách nào?"}},{"stt":5,"hanzi":"出租车","pinyin":"chūzūchē","hanviet":"Xuất tô xa","pos":"Danh từ","meaning":"Xe taxi","comps":"坐出租车 · 叫出租车","example":{"zh":"我们是坐出租车来的。","py":"Wǒmen shì zuò chūzūchē lái de.","vi":"Chúng tôi đáp taxi đến đây."}},{"stt":6,"hanzi":"一起","pinyin":"yìqǐ","hanviet":"Nhất khởi","pos":"Phó từ","meaning":"Cùng, cùng nhau","comps":"一起去 · 两个人一起","example":{"zh":"他和朋友一起开车来的。","py":"Tā hé péngyou yìqǐ kāi chē lái de.","vi":"Anh ấy và bạn cùng lái xe đến đây."}},{"stt":7,"hanzi":"高兴","pinyin":"gāoxìng","hanviet":"Cao hứng","pos":"Tính từ","meaning":"Vui, phấn khởi","comps":"很高兴 · 不高兴","example":{"zh":"认识你我也很高兴！","py":"Rènshi nǐ wǒ yě hěn gāoxìng!","vi":"Tôi cũng rất vui được quen biết bạn!"}},{"stt":8,"hanzi":"听","pinyin":"tīng","hanviet":"Thính","pos":"Động từ","meaning":"Nghe","comps":"听他说 · 好听","example":{"zh":"听张先生说...","py":"Tīng Zhāng xiānsheng shuō...","vi":"Nghe ông Trương nói..."}},{"stt":9,"hanzi":"飞机","pinyin":"fēijī","hanviet":"Phi cơ","pos":"Danh từ","meaning":"Máy bay","comps":"坐飞机 · 飞机票","example":{"zh":"您是坐飞机来北京的？","py":"Nín shì zuò fēijī lái Běijīng de?","vi":"Ngài đáp máy bay đến Bắc Kinh phải không?"}},{"stt":10,"hanzi":"坐","pinyin":"zuò","hanviet":"Tọa","pos":"Động từ","meaning":"Ngồi, đáp (xe, tàu)","comps":"坐车 · 坐飞机","example":{"zh":"我是坐飞机来的。","py":"Wǒ shì zuò fēijī lái de.","vi":"Tôi đáp máy bay đến đây."}},{"stt":11,"hanzi":"怎么","pinyin":"zěnme","hanviet":"Chẩm ma","pos":"Đại từ","meaning":"Thế nào, bằng cách nào","comps":"怎么去 · 怎么写","example":{"zh":"你们是怎么来饭店的？","py":"Nǐmen shì zěnme lái fàndiàn de?","vi":"Các bạn đến khách sạn bằng phương tiện gì?"}},{"stt":12,"hanzi":"开车","pinyin":"kāi chē","hanviet":"Khai xa","pos":"Động từ","meaning":"Lái xe","comps":"去开车 · 会开车","example":{"zh":"他是开车来的。","py":"Tā shì kāi chē lái de.","vi":"Anh ấy tự lái xe đến đây."}}],"hanzi":[{"char":"认识","pinyin":"rènshi","hanviet":"Nhận thức","chars":["认","识"],"story":"Cả hai chữ đều có bộ 言 (Ngôn - lời nói). Phải dùng lời nói giao tiếp mới có thể quen biết nhau."},{"char":"年","pinyin":"nián","hanviet":"Niên","chars":["年"],"story":"Hình ảnh người vác lúa về nhà báo hiệu một năm thu hoạch. Chữ này dùng chỉ đơn vị thời gian (Năm)."},{"char":"大学","pinyin":"dàxué","hanviet":"Đại học","chars":["大","学"],"story":"大 (lớn) + 学 (học). Nơi đào tạo bậc học cao, rộng lớn."},{"char":"饭店","pinyin":"fàndiàn","hanviet":"Phạn điếm","chars":["饭","店"],"story":"饭 (cơm/bữa ăn) + 店 (cửa tiệm). Nơi bán đồ ăn lớn hoặc nơi lưu trú."},{"char":"出租车","pinyin":"chūzūchē","hanviet":"Xuất tô xa","chars":["出","租","车"],"story":"出 (đưa ra) + 租 (thuê) + 车 (xe). Xe cho thuê để di chuyển."},{"char":"一起","pinyin":"yìqǐ","hanviet":"Nhất khởi","chars":["一","起"],"story":"Thường đứng trước động từ để chỉ hành động được thực hiện cùng nhau bởi nhiều người."},{"char":"高兴","pinyin":"gāoxìng","hanviet":"Cao hứng","chars":["高","兴"],"story":"Tâm trạng vui vẻ, phấn khích dâng cao."},{"char":"听","pinyin":"tīng","hanviet":"Thính","chars":["听"],"story":"Bộ 口 (Khẩu - miệng) và bộ 斤 (Cân - cái búa). Dùng để chỉ hành động lắng nghe."},{"char":"飞机","pinyin":"fēijī","hanviet":"Phi cơ","chars":["飞","机"],"story":"飞 (bay) + 机 (máy móc). Cỗ máy có thể bay lượn trên trời."},{"char":"坐","pinyin":"zuò","hanviet":"Tọa","chars":["坐"],"story":"Hai chữ 人 (Nhân - người) ngồi trên chữ 土 (Thổ - đất)."},{"char":"怎么","pinyin":"zěnme","hanviet":"Chẩm ma","chars":["怎","么"],"story":"Dùng để hỏi về cách thức, phương pháp tiến hành một hành động."},{"char":"开车","pinyin":"kāi chē","hanviet":"Khai xa","chars":["开","车"],"story":"开 (mở/điều khiển) + 车 (xe). Tự mình điều khiển phương tiện."}],"grammar":[{"title":"Cấu trúc nhấn mạnh quá khứ: 是...的","formula":"S + <span>(是)</span> + [T.gian/Đ.điểm/Cách thức] + V + <span>的</span>","summary":"Khi một sự việc <strong>đã xảy ra</strong>, người ta dùng cấu trúc này để <strong>nhấn mạnh</strong> thời gian, địa điểm, hoặc phương thức của hành động đó.","note":"<strong>Chú ý:</strong> Trong câu khẳng định và nghi vấn, chữ <b>是</b> có thể lược bỏ, nhưng <b>的</b> bắt buộc phải có.","examples":[{"zh":"我们是在学校认识的。","py":"Wǒmen shì zài xuéxiào rènshi de.","vi":"Chúng tôi quen nhau ở trường. (Nhấn mạnh địa điểm)"},{"zh":"我是坐飞机来的。","py":"Wǒ shì zuò fēijī lái de.","vi":"Tôi đến đây bằng máy bay. (Nhấn mạnh phương thức)"},{"zh":"你们是怎么来饭店的？","py":"Nǐmen shì zěnme lái fàndiàn de?","vi":"Các bạn đến nhà hàng bằng cách nào? (Hỏi phương thức)"},{"zh":"他是昨天来的。","py":"Tā shì zuótiān lái de.","vi":"Anh ấy đến vào ngày hôm qua. (Nhấn mạnh thời gian)"},{"zh":"这件衣服是在哪儿买的？","py":"Zhè jiàn yīfu shì zài nǎr mǎi de?","vi":"Bộ đồ này mua ở đâu vậy? (Hỏi địa điểm)"},{"zh":"大卫是坐出租车去北京的。","py":"Dàwèi shì zuò chūzūchē qù Běijīng de.","vi":"David đi Bắc Kinh bằng xe taxi."},{"zh":"我们是2011年9月认识的。","py":"Wǒmen shì èr líng yī yī nián jiǔ yuè rènshi de.","vi":"Chúng tôi quen nhau vào tháng 9 năm 2011."},{"zh":"他是和朋友一起开车来的。","py":"Tā shì hé péngyou yìqǐ kāi chē lái de.","vi":"Anh ấy cùng lái xe với bạn đến đây."}]},{"title":"Phủ định của cấu trúc 是...的","formula":"S + <span>不是</span> + [T.gian/Đ.điểm/Cách thức] + V + <span>的</span>","summary":"Để phủ định một chi tiết nào đó (không phải vào lúc đó, không phải ở đó...), ta dùng <b>不是 (bú shì)</b>.","note":"<strong>Quan trọng:</strong> Trong câu phủ định, <b>KHÔNG</b> được lược bỏ chữ <b>是</b>.","examples":[{"zh":"我不是昨天来的。","py":"Wǒ bú shì zuótiān lái de.","vi":"Tôi không phải đến vào hôm qua."},{"zh":"我们不是在学校认识的。","py":"Wǒmen bú shì zài xuéxiào rènshi de.","vi":"Chúng tôi không phải quen nhau ở trường."},{"zh":"他不是坐出租车来的。","py":"Tā bú shì zuò chūzūchē lái de.","vi":"Anh ấy không phải đi taxi đến."},{"zh":"这本书不是在书店买的。","py":"Zhè běn shū bú shì zài shūdiàn mǎi de.","vi":"Quyển sách này không phải mua ở nhà sách."},{"zh":"爸爸不是坐飞机去北京的。","py":"Bàba bú shì zuò fēijī qù Běijīng de.","vi":"Bố không phải đi Bắc Kinh bằng máy bay."},{"zh":"她不是今天早上回来的。","py":"Tā bú shì jīntiān zǎoshang huílai de.","vi":"Cô ấy không phải trở về vào sáng nay."},{"zh":"这个不是我做的。","py":"Zhège bú shì wǒ zuò de.","vi":"Cái này không phải tôi làm đâu."},{"zh":"我们不是2011年认识的。","py":"Wǒmen bú shì èr líng yī yī nián rènshi de.","vi":"Chúng tôi không phải quen nhau năm 2011."}]},{"title":"Cách nói Ngày Tháng Năm","formula":"Năm(<span>年</span>) + Tháng(<span>月</span>) + Ngày(<span>日/号</span>) + Thứ(<span>星期...</span>)","summary":"Người Trung Quốc diễn đạt thời gian theo nguyên tắc <strong>Từ Đơn Vị Lớn Đến Đơn Vị Nhỏ</strong>.","note":"<strong>Cách đọc năm:</strong> Đọc tách rời từng con số một. Ví dụ: 2011 đọc là 二零一一 (èr líng yī yī).","examples":[{"zh":"今天是2014年5月11号。","py":"Jīntiān shì èr líng yī sì nián wǔ yuè shíyī hào.","vi":"Hôm nay là ngày 11 tháng 5 năm 2014."},{"zh":"今天9月10号，星期三。","py":"Jīntiān jiǔ yuè shí hào, xīngqīsān.","vi":"Hôm nay ngày 10 tháng 9, thứ Tư."},{"zh":"我的生日是8月8号。","py":"Wǒ de shēngrì shì bā yuè bā hào.","vi":"Sinh nhật của tôi là ngày 8 tháng 8."},{"zh":"我们是2011年9月认识的。","py":"Wǒmen shì èr líng yī yī nián jiǔ yuè rènshi de.","vi":"Chúng tôi quen nhau vào tháng 9 năm 2011."},{"zh":"昨天是星期一。","py":"Zuótiān shì xīngqīyī.","vi":"Hôm qua là thứ Hai."},{"zh":"2008年8月8号星期五。","py":"Èr líng líng bā nián bā yuè bā hào xīngqīwǔ.","vi":"Thứ Sáu, ngày 8 tháng 8 năm 2008."},{"zh":"他是2015年去北京的。","py":"Tā shì èr líng yī wǔ nián qù Běijīng de.","vi":"Anh ấy đi Bắc Kinh vào năm 2015."},{"zh":"你们是哪年认识的？","py":"Nǐmen shì nǎ nián rènshi de?","vi":"Các bạn quen nhau vào năm nào?"}]}],"text":{"title":"课文 · Bài khoá","blocks":[{"titleZh":"在餐桌旁","titleVi":"Bên bàn ăn","icon":"🍴","lines":[{"speaker":"A","zh":"你和李小姐是什么时候认识的？","py":"Nǐ hé Lǐ xiǎojiě shì shénme shíhou rènshi de?","vi":"Anh và cô Lý quen nhau khi nào vậy?"},{"speaker":"B","zh":"我们是2011年9月认识的。","py":"Wǒmen shì èr líng yī yī nián jiǔ yuè rènshi de.","vi":"Chúng tôi quen nhau vào tháng 9 năm 2011."},{"speaker":"A","zh":"你们在哪儿认识的？","py":"Nǐmen zài nǎr rènshi de?","vi":"Các bạn quen nhau ở đâu?"},{"speaker":"B","zh":"我们是在学校认识的，她是我大学同学。","py":"Wǒmen shì zài xuéxiào rènshi de, tā shì wǒ dàxué tóngxué.","vi":"Ở trường đại học. Cô ấy học cùng trường với tôi."}]},{"titleZh":"在饭店门口","titleVi":"Trước cửa khách sạn","icon":"🏨","lines":[{"speaker":"A","zh":"你们是怎么来饭店的？","py":"Nǐmen shì zěnme lái fàndiàn de?","vi":"Các anh đến khách sạn bằng cách nào vậy?"},{"speaker":"B","zh":"我们是坐出租车来的。","py":"Wǒmen shì zuò chūzūchē lái de.","vi":"Chúng tôi đáp taxi đến đây."},{"speaker":"A","zh":"李先生呢？","py":"Lǐ xiānsheng ne?","vi":"Còn ông Lý thì sao?"},{"speaker":"B","zh":"他是和朋友一起开车来的。","py":"Tā shì hé péngyou yìqǐ kāi chē lái de.","vi":"Ông ấy và bạn cùng lái xe đến đây."}]},{"titleZh":"在公司","titleVi":"Trong công ty","icon":"🏢","lines":[{"speaker":"A","zh":"很高兴认识您！李小姐。","py":"Hěn gāoxìng rènshi nín! Lǐ xiǎojiě.","vi":"Rất vui được quen biết cô, cô Lý."},{"speaker":"B","zh":"认识你我也很高兴！","py":"Rènshi nǐ wǒ yě hěn gāoxìng!","vi":"Tôi cũng rất vui được quen biết anh!"},{"speaker":"A","zh":"听张先生说，您是坐飞机来北京的？","py":"Tīng Zhāng xiānsheng shuō, nín shì zuò fēijī lái Běijīng de?","vi":"Nghe ông Trương nói, cô đáp máy bay đến Bắc Kinh phải không?"},{"speaker":"B","zh":"是的。","py":"Shì de.","vi":"Đúng vậy."}]}]},"extra":[{"label":"Mục tiêu","html":"<h2 class=\"section-title\">Mục tiêu bài học</h2>\n  <p class=\"section-sub\">Bài 15 giúp học viên nhấn mạnh các chi tiết quan trọng (thời gian, địa điểm, cách thức) của một sự việc đã diễn ra trong quá khứ.</p>\n  <div class=\"goal-grid\">\n    <div class=\"goal-item\">\n      <div class=\"num\">01</div>\n      <h4>Giao tiếp</h4>\n      <ul>\n        <li>Hỏi đáp về việc <b>quen biết ai đó</b> ở đâu, khi nào.</li>\n        <li>Hỏi và nói về <b>phương tiện</b> di chuyển đã sử dụng.</li>\n        <li>Kể lại chi tiết <b>thời gian, địa điểm</b> của một sự việc đã qua.</li>\n      </ul>\n    </div>\n    <div class=\"goal-item\">\n      <div class=\"num\">02</div>\n      <h4>Từ vựng</h4>\n      <ul>\n        <li>Phương tiện: <b>飞机, 出租车, 坐, 开车</b>.</li>\n        <li>Thời gian/Nơi chốn: <b>年, 大学, 饭店</b>.</li>\n        <li>Động từ: <b>认识, 听, 来</b>.</li>\n        <li>Từ khác: <b>怎么, 一起, 高兴</b>.</li>\n      </ul>\n    </div>\n    <div class=\"goal-item\">\n      <div class=\"num\">03</div>\n      <h4>Ngữ pháp</h4>\n      <ul>\n        <li>Cấu trúc nhấn mạnh quá khứ <b>是...的</b>.</li>\n        <li>Quy tắc đọc <b>Ngày tháng năm</b> (Từ Lớn đến Nhỏ).</li>\n        <li>Câu hỏi phương thức với <b>怎么</b> (như thế nào).</li>\n      </ul>\n    </div>\n  </div>"},{"label":"Giao thông & Ngày tháng","html":"<h2 class=\"section-title\">Giao thông &amp; Ngày tháng</h2>\n  <p class=\"section-sub\">Mở rộng từ vựng về các phương tiện đi lại và sơ đồ quy tắc diễn đạt thời gian trong tiếng Trung.</p>\n\n  <div class=\"card\">\n    <h3>1. Phương tiện Giao thông</h3>\n    <p>Để diễn đạt việc di chuyển bằng phương tiện, ta thường dùng động từ <b>坐 (Ngồi / Đáp)</b> hoặc <b>开 (Lái)</b> kết hợp với Danh từ phương tiện.</p>\n    <div class=\"transport-grid\">\n      <div class=\"transport-card\">\n        <div class=\"t-icon\">✈️</div>\n        <div class=\"t-zh\">飞机</div>\n        <div class=\"t-py\">fēijī</div>\n        <div class=\"t-vi\">Máy bay</div>\n      </div>\n      <div class=\"transport-card\">\n        <div class=\"t-icon\">🚕</div>\n        <div class=\"t-zh\">出租车</div>\n        <div class=\"t-py\">chūzūchē</div>\n        <div class=\"t-vi\">Xe taxi</div>\n      </div>\n      <div class=\"transport-card\">\n        <div class=\"t-icon\">🚗</div>\n        <div class=\"t-zh\">开车</div>\n        <div class=\"t-py\">kāi chē</div>\n        <div class=\"t-vi\">Lái xe (hơi)</div>\n      </div>\n      <div class=\"transport-card\">\n        <div class=\"t-icon\">🚆</div>\n        <div class=\"t-zh\">火车</div>\n        <div class=\"t-py\">huǒchē</div>\n        <div class=\"t-vi\">Tàu hỏa (Mở rộng)</div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"card\">\n    <h3>2. Quy tắc Thời gian (Từ Lớn đến Nhỏ)</h3>\n    <p>Khác với tiếng Việt (Ngày -> Tháng -> Năm), người Trung Quốc tư duy từ cái lớn bao trùm cái nhỏ. Vì vậy, mốc thời gian bắt buộc phải đi từ <b>Năm -> Tháng -> Ngày -> Thứ</b>.</p>\n    \n    <div class=\"time-flow-box\">\n      <div class=\"tf-items\">\n        <div class=\"tf-item\">Năm<br><span style=\"font-size:1.4rem; color:var(--burgundy-dark)\">年</span></div>\n        <div class=\"tf-arrow\">→</div>\n        <div class=\"tf-item\">Tháng<br><span style=\"font-size:1.4rem; color:var(--burgundy-dark)\">月</span></div>\n        <div class=\"tf-arrow\">→</div>\n        <div class=\"tf-item\">Ngày<br><span style=\"font-size:1.4rem; color:var(--burgundy-dark)\">日 / 号</span></div>\n        <div class=\"tf-arrow\">→</div>\n        <div class=\"tf-item\">Thứ<br><span style=\"font-size:1.4rem; color:var(--burgundy-dark)\">星期</span></div>\n      </div>\n      <p style=\"margin-top:20px; font-family:'Noto Sans SC',sans-serif; font-size:1.25rem; font-weight:600; color:var(--ink);\">2011年9月10号，星期三</p>\n      <p style=\"font-style:italic; color:var(--muted); font-size:0.95rem;\">(Thứ Tư, ngày 10 tháng 9 năm 2011)</p>\n    </div>\n  </div>"},{"label":"Lỗi sai","html":"<h2 class=\"section-title\">Lỗi sai thường gặp</h2>\n  <p class=\"section-sub\">Những lỗi người học tiếng Trung hay mắc phải khi nói về phương tiện và thời gian trong quá khứ.</p>\n  <div class=\"error-grid\">\n    <div class=\"error-box\">\n      <div class=\"err-head wrong\">Lỗi 1 · Xếp ngược thứ tự Ngày Tháng Năm</div>\n      <div class=\"err-body\">\n        <p style=\"margin-bottom:12px\">Tiếng Việt nói \"Tháng 9 năm 2011\". Nếu dịch thẳng sang tiếng Trung sẽ bị sai hoàn toàn nguyên tắc \"Từ Lớn Đến Nhỏ\".</p>\n        <p class=\"strike zh\">9月2011年</p>\n        <p class=\"strike zh\">10号9月</p>\n      </div>\n      <div class=\"err-head correct\">Cách sửa</div>\n      <div class=\"err-body\">\n        <p class=\"correct-text zh\">2011年9月</p>\n        <p class=\"correct-text zh\">9月10号</p>\n      </div>\n    </div>\n    <div class=\"error-box\">\n      <div class=\"err-head wrong\">Lỗi 2 · Thiếu \"的\" trong cấu trúc \"是...的\"</div>\n      <div class=\"err-body\">\n        <p style=\"margin-bottom:12px\">Cấu trúc nhấn mạnh bắt buộc phải có cặp bài trùng <b>是</b> và <b>的</b>. Học viên hay quen miệng lược bỏ mất chữ \"的\" ở cuối câu.</p>\n        <p class=\"strike zh\">我是坐飞机来。</p>\n        <p class=\"strike zh\">我们是在学校认识。</p>\n      </div>\n      <div class=\"err-head correct\">Cách sửa</div>\n      <div class=\"err-body\">\n        <p class=\"correct-text zh\">我是坐飞机来的。</p>\n        <p class=\"correct-text zh\">我们是在学校认识的。</p>\n      </div>\n    </div>\n    <div class=\"error-box\">\n      <div class=\"err-head wrong\">Lỗi 3 · Dùng sai động từ với Phương tiện</div>\n      <div class=\"err-body\">\n        <p style=\"margin-bottom:12px\">Học viên thường ghép từ \"去\" (đi) trực tiếp với phương tiện (ví dụ: đi máy bay -> 去飞机).</p>\n        <p class=\"strike zh\">他去飞机来北京。</p>\n      </div>\n      <div class=\"err-head correct\">Cách sửa</div>\n      <div class=\"err-body\">\n        <p class=\"correct-text zh\">他坐飞机来北京。</p>\n        <p style=\"font-size:.88rem;color:var(--muted);margin-top:6px\">Phải dùng 坐 (ngồi/đáp) hoặc 开 (lái) trước phương tiện.</p>\n      </div>\n    </div>\n  </div>"},{"label":"Tổng hợp","html":"<h2 class=\"section-title\">Tổng hợp kiến thức</h2>\n  <p class=\"section-sub\">Sơ đồ cốt lõi giúp tóm tắt toàn bộ Bài 15.</p>\n\n  <div class=\"syn-grid\">\n    <div class=\"syn-card theme-burgundy\">\n      <div class=\"syn-icon\">🔍</div>\n      <h3>Nhấn mạnh: 是...的</h3>\n      <p>Khi sự việc ĐÃ XẢY RA, dùng cấu trúc này để nhấn mạnh chi tiết (Thời gian / Địa điểm / Phương thức).</p>\n      <table class=\"syn-table\">\n        <tr><th>Loại</th><th>Cấu trúc</th></tr>\n        <tr><td>Khẳng định</td><td>S + <span class=\"syn-keyhz\">是</span> + [Thời gian/Nơi/Cách] + V + <span class=\"syn-keyhz\">的</span></td></tr>\n        <tr><td>Phủ định</td><td>S + <span class=\"syn-keyhz\">不是</span> + [Thời gian/Nơi/Cách] + V + <span class=\"syn-keyhz\">的</span></td></tr>\n      </table>\n      <div class=\"syn-mnemonic\">Chữ \"是\" có thể bỏ trong câu khẳng định, nhưng \"的\" thì không thể bỏ. Phủ định KHÔNG dùng 没.</div>\n    </div>\n\n    <div class=\"syn-card theme-gold\">\n      <div class=\"syn-icon\">📅</div>\n      <h3>Quy tắc Thời gian</h3>\n      <p>Luôn đi từ đơn vị lớn nhất đến nhỏ nhất.</p>\n      <div class=\"syn-flow\">\n        <div class=\"step\"><span class=\"syn-keyhz\">年</span><br><small>Năm</small></div>\n        <span class=\"arrow\">→</span>\n        <div class=\"step\"><span class=\"syn-keyhz\">月</span><br><small>Tháng</small></div>\n        <span class=\"arrow\">→</span>\n        <div class=\"step\"><span class=\"syn-keyhz\">日/号</span><br><small>Ngày</small></div>\n        <span class=\"arrow\">→</span>\n        <div class=\"step\"><span class=\"syn-keyhz\">星期</span><br><small>Thứ</small></div>\n      </div>\n      <div class=\"syn-mnemonic\">Năm đọc tách từng số: 2011 = 二零一 一 (èr líng yī yī).</div>\n    </div>\n\n    <div class=\"syn-card theme-ink\">\n      <div class=\"syn-icon\">✈️</div>\n      <h3>Động từ Phương tiện</h3>\n      <ul style=\"font-size:0.95rem; line-height:1.6; margin-top:10px; color:var(--ink-soft); padding-left:18px;\">\n        <li><span class=\"syn-keyhz\">坐</span> (Ngồi/Đáp): 坐飞机 (đáp máy bay), 坐出租车 (đi taxi).</li>\n        <li><span class=\"syn-keyhz\">开</span> (Lái): 开车 (lái xe).</li>\n      </ul>\n      <div class=\"syn-mnemonic\">Cách hỏi phương thức: <strong>怎么</strong> + V ? (怎么来 / 怎么去).</div>\n    </div>\n\n    <div class=\"syn-card theme-burgundy\">\n      <div class=\"syn-icon\">🤝</div>\n      <h3>Cùng nhau: 一起</h3>\n      <p>Dùng để chỉ hành động làm cùng nhau.</p>\n      <div class=\"syn-flow\">\n        <div class=\"step\">Đối tượng<br><span class=\"syn-keyhz\">和朋友</span></div>\n        <span class=\"arrow\">+</span>\n        <div class=\"step\">Phó từ<br><span class=\"syn-keyhz\">一起</span></div>\n        <span class=\"arrow\">+</span>\n        <div class=\"step\">Hành động<br><span class=\"syn-keyhz\">来</span></div>\n      </div>\n      <div class=\"syn-mnemonic\">和 + [Ai đó] + 一起 + [Làm gì].</div>\n    </div>\n\n    <div class=\"syn-card theme-gold\" style=\"grid-column: 1 / -1;\">\n      <div class=\"syn-icon\">⚡</div>\n      <h3>Câu thần chú 5 mẫu</h3>\n      <table class=\"syn-table\">\n        <tr><th>Mẫu</th><th>Tình huống</th></tr>\n        <tr><td><span class=\"syn-keyhz\">你们是什么时候认识的？</span></td><td>Hỏi thời gian quen biết.</td></tr>\n        <tr><td><span class=\"syn-keyhz\">我们是在学校认识的。</span></td><td>Nhấn mạnh địa điểm quen biết.</td></tr>\n        <tr><td><span class=\"syn-keyhz\">你们是怎么来饭店的？</span></td><td>Hỏi phương thức di chuyển đến đâu đó.</td></tr>\n        <tr><td><span class=\"syn-keyhz\">我是坐出租车来的。</span></td><td>Nhấn mạnh phương tiện đã sử dụng.</td></tr>\n        <tr><td><span class=\"syn-keyhz\">很高兴认识您！</span></td><td>Câu chào khi mới quen biết ai đó.</td></tr>\n      </table>\n      <div class=\"syn-mnemonic\"><strong>Thuộc 5 mẫu này là pass Bài 15.</strong></div>\n    </div>\n  </div>"}],"cssId":"c04d4c28c"}];